-- ============================================================================
-- MASTER CLIENT HANDOVER RESET SCRIPT (Enterprise Edition - Production Ready)
-- ============================================================================
-- هذا السكربت يقوم بتنظيف وتصفير قاعدة البيانات بالكامل للاستعداد لتسليم العميل
-- يجمع جميع عمليات التنظيف، إعادة التهيئة، وتوليد البيانات المرجعية في Transaction واحدة
-- آمن 100%: إذا حدث أي خطأ يتم التراجع تلقائياً (Rollback)
-- متوافق 100% مع Multi-Tenancy وأنواع البيانات المختلفة (UUID/TEXT/INTEGER)
-- ============================================================================
-- المتطلبات المحققة:
-- 1. إزالة جميع القيود والحركات المحاسبية والتشغيلية بالكامل (Transactions = 0)
-- 2. الحفاظ على شجرة الحسابات القياسية كاملة (28+ حساب رسمي) وضمان وجودها وربطها بالشركة
-- 3. تنظيف حسابات الكيانات الفرعية القديمة دون لمس الحسابات الأب (1020, 2000, 2103, 2104, 3101)
-- 4. إعداد الخزينة الرئيسية والـ 4 عملات وربطها بحسابات GL الرسمية (11101-11104)
-- 5. إعداد حسابات البنوك الأربعة الرسمية (11201-11204) والمخازن الرسمية
-- 6. تهيئة كافة البيانات المرجعية (العملات، التصنيفات، الوحدات، إعدادات النظام، السنة المالية)
-- 7. تفعيل التريجرز التلقائية لتوليد حسابات العملاء والموردين وشركات الشحن مستقبلاً
-- 8. تصفير الـ Sequences والأرصدة لتبدأ من 1
-- 9. فحص وتحقق شامل (Verification) قبل الـ Commit
-- ============================================================================

BEGIN;

-- تعطيل triggers الحذف والتحقق مؤقتاً أثناء عملية الـ Reset
SET LOCAL session_replication_role = 'replica';

-- ============================================================================
-- المرحلة 0: ضمان وجود الكيانات الأساسية وأعمدة الهيكلية للشركات وشجرة الحسابات
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.sys_companies (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ
);

INSERT INTO public.sys_companies (id, name, is_active, created_at, updated_at)
VALUES ('a0000000-0000-0000-0000-000000000001'::uuid, 'الشركة الافتراضية', true, now(), now())
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.sys_companies (id, name, is_active, created_at, updated_at)
SELECT id, name, COALESCE(is_active, true), COALESCE(created_at, now()), now() 
FROM public.tenants
ON CONFLICT (id) DO UPDATE SET 
    name = EXCLUDED.name, 
    is_active = EXCLUDED.is_active, 
    updated_at = now();

CREATE OR REPLACE FUNCTION public.fn_sync_tenant_to_sys_companies()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    INSERT INTO public.sys_companies (id, name, is_active, created_at, updated_at)
    VALUES (NEW.id, NEW.name, COALESCE(NEW.is_active, true), COALESCE(NEW.created_at, now()), now())
    ON CONFLICT (id) DO UPDATE SET 
        name = EXCLUDED.name, 
        is_active = EXCLUDED.is_active, 
        updated_at = now();
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_tenant_to_sys_companies ON public.tenants;
CREATE TRIGGER trg_sync_tenant_to_sys_companies
AFTER INSERT OR UPDATE ON public.tenants
FOR EACH ROW EXECUTE FUNCTION public.fn_sync_tenant_to_sys_companies();

-- 1. جدول القيود اليومية الأساسي (Unified Journal Entries)
CREATE TABLE IF NOT EXISTS public.journal_entries (
    id BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    entry_number TEXT NOT NULL,
    entry_date DATE DEFAULT CURRENT_DATE NOT NULL,
    description TEXT NOT NULL,
    status TEXT DEFAULT 'posted' NOT NULL,
    is_auto_generated BOOLEAN DEFAULT true NOT NULL,
    source_type TEXT,
    source_id TEXT,
    created_by UUID,
    created_at TIMESTAMPTZ DEFAULT now() NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT now(),
    posted_at TIMESTAMPTZ DEFAULT now(),
    company_id UUID REFERENCES public.sys_companies(id),
    currency_snapshot JSONB DEFAULT '{}'::jsonb,
    idempotency_key TEXT,
    deleted_at TIMESTAMPTZ
);

ALTER TABLE IF EXISTS public.journal_entries 
    ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT now();

-- 2. جدول قيود الأستاذ العام (General Ledger Entries)
CREATE TABLE IF NOT EXISTS public.account_ledger_entries (
    id BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    journal_entry_id BIGINT NOT NULL REFERENCES public.journal_entries(id) ON DELETE CASCADE,
    account_id BIGINT NOT NULL,
    debit NUMERIC DEFAULT 0 NOT NULL,
    credit NUMERIC DEFAULT 0 NOT NULL,
    currency TEXT DEFAULT 'EGP' NOT NULL,
    amount_in_base_currency NUMERIC DEFAULT 0 NOT NULL,
    description TEXT,
    created_at TIMESTAMPTZ DEFAULT now() NOT NULL,
    company_id UUID REFERENCES public.sys_companies(id),
    cost_center_id TEXT,
    entity_type TEXT,
    entity_id TEXT,
    deleted_at TIMESTAMPTZ
);

ALTER TABLE IF EXISTS public.account_ledger_entries 
    ADD COLUMN IF NOT EXISTS cost_center_id TEXT,
    ADD COLUMN IF NOT EXISTS entity_type TEXT,
    ADD COLUMN IF NOT EXISTS entity_id TEXT;

CREATE INDEX IF NOT EXISTS idx_account_ledger_entries_entity 
ON public.account_ledger_entries (entity_type, entity_id);

CREATE OR REPLACE FUNCTION public.fn_auto_set_ledger_entry_entity()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_cust_id text;
    v_supp_id text;
    v_source_id text;
    v_source_type text;
BEGIN
    IF NEW.entity_id IS NOT NULL AND NEW.entity_id <> '' THEN
        IF NEW.entity_type IS NULL OR NEW.entity_type = '' THEN
            NEW.entity_type := 'customer';
        END IF;
        RETURN NEW;
    END IF;

    SELECT id INTO v_cust_id
    FROM public.customers
    WHERE account_id = NEW.account_id
    LIMIT 1;

    IF v_cust_id IS NOT NULL THEN
        NEW.entity_type := 'customer';
        NEW.entity_id := v_cust_id::text;
        RETURN NEW;
    END IF;

    SELECT id INTO v_supp_id
    FROM public.suppliers
    WHERE account_id = NEW.account_id
    LIMIT 1;

    IF v_supp_id IS NOT NULL THEN
        NEW.entity_type := 'supplier';
        NEW.entity_id := v_supp_id::text;
        RETURN NEW;
    END IF;

    SELECT source_id, source_type INTO v_source_id, v_source_type
    FROM public.journal_entries
    WHERE id = NEW.journal_entry_id;

    IF v_source_id IS NOT NULL AND v_source_id <> '' THEN
        IF v_source_id LIKE 'customers_%' THEN
            NEW.entity_type := 'customer';
            NEW.entity_id := REPLACE(v_source_id, 'customers_', '');
            RETURN NEW;
        ELSIF v_source_id LIKE 'suppliers_%' THEN
            NEW.entity_type := 'supplier';
            NEW.entity_id := REPLACE(v_source_id, 'suppliers_', '');
            RETURN NEW;
        ELSIF v_source_type IN ('cash_receipt', 'customer_payment', 'receipt', 'sale_sorting', 'sorting_sale') THEN
            NEW.entity_type := 'customer';
            NEW.entity_id := v_source_id;
            RETURN NEW;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_auto_set_ledger_entry_entity ON public.account_ledger_entries;
CREATE TRIGGER trg_auto_set_ledger_entry_entity
BEFORE INSERT OR UPDATE ON public.account_ledger_entries
FOR EACH ROW
EXECUTE FUNCTION public.fn_auto_set_ledger_entry_entity();

-- 3. جدول أبعاد القيود (Journal Entry Dimensions)
CREATE TABLE IF NOT EXISTS public.journal_entry_dimensions (
    id BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    company_id UUID REFERENCES public.sys_companies(id),
    journal_entry_id BIGINT NOT NULL REFERENCES public.journal_entries(id) ON DELETE CASCADE,
    dimension_key TEXT NOT NULL,
    dimension_value TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT now() NOT NULL
);

-- 4. جدول أنواع المستندات
CREATE TABLE IF NOT EXISTS public.sys_document_types (
    code TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    prefix TEXT NOT NULL,
    description TEXT,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    deleted_at TIMESTAMPTZ
);

-- 5. جدول ترقيم المستندات (Sequences)
CREATE TABLE IF NOT EXISTS public.sys_sequences (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id UUID REFERENCES public.sys_companies(id),
    document_type_code TEXT REFERENCES public.sys_document_types(code),
    fiscal_year_id INTEGER,
    current_value BIGINT DEFAULT 0,
    prefix TEXT,
    padding_length INTEGER DEFAULT 5,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

