('purchase', 'Purchase Invoice', 'PURC', true),
('purchase_invoice', 'Purchase Invoice', 'PINV', true),
('lot_receipt', 'شراء محصول', 'LOT', true),
('lot_return', 'مردودات محصول', 'LRET', true),
