CREATE OR REPLACE FUNCTION public.fn_get_next_sequence(
    p_company_id UUID,
    p_document_type_code TEXT,
    p_fiscal_year_id INT DEFAULT NULL,
    p_branch_id UUID DEFAULT NULL
)
RETURNS TEXT AS
$func$
DECLARE
    v_prefix TEXT;
    v_fiscal_year_name TEXT := '';
    v_current_value BIGINT;
    v_padding INT := 5;
    v_next_val BIGINT;
    v_generated_number TEXT;
BEGIN
    -- 1. Ensure company exists in sys_companies to satisfy foreign key
    IF p_company_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.sys_companies WHERE id = p_company_id) THEN
        BEGIN
            INSERT INTO public.sys_companies (id, name, is_active, created_at, updated_at)
            VALUES (p_company_id, 'شركة النظام', true, now(), now())
            ON CONFLICT (id) DO UPDATE SET is_active = true, updated_at = now();
        EXCEPTION WHEN OTHERS THEN
            SELECT id INTO p_company_id FROM public.sys_companies WHERE deleted_at IS NULL ORDER BY created_at ASC LIMIT 1;
        END;
    END IF;

    SELECT prefix INTO v_prefix 
    FROM public.sys_document_types 
    WHERE code = p_document_type_code;

    IF v_prefix IS NULL OR v_prefix = '' THEN
        v_prefix := UPPER(SUBSTRING(COALESCE(p_document_type_code, 'DOC') FROM 1 FOR 3));
    END IF;

    -- 2. Ensure document type exists in sys_document_types to satisfy foreign key
    IF NOT EXISTS (SELECT 1 FROM public.sys_document_types WHERE code = p_document_type_code) THEN
        INSERT INTO public.sys_document_types (code, name, prefix, is_active)
        VALUES (
            p_document_type_code,
            INITCAP(REPLACE(p_document_type_code, '_', ' ')),
            v_prefix,
            true
        )
        ON CONFLICT (code) DO NOTHING;
    END IF;

    IF p_fiscal_year_id IS NOT NULL THEN
        BEGIN
            SELECT name INTO v_fiscal_year_name
            FROM public.fiscal_years
            WHERE id = p_fiscal_year_id;
        EXCEPTION WHEN OTHERS THEN
            v_fiscal_year_name := '';
        END;
    END IF;

    UPDATE public.sys_sequences
    SET current_value = current_value + 1,
        updated_at = now()
    WHERE id = (
        SELECT id FROM public.sys_sequences
        WHERE (company_id = p_company_id OR (company_id IS NULL AND p_company_id IS NULL))
          AND document_type_code = p_document_type_code
          AND (fiscal_year_id = p_fiscal_year_id OR (fiscal_year_id IS NULL AND p_fiscal_year_id IS NULL))
        ORDER BY id ASC
        LIMIT 1
        FOR UPDATE
    )
    RETURNING current_value, padding_length INTO v_next_val, v_padding;

    IF NOT FOUND THEN
        INSERT INTO public.sys_sequences (
            company_id, document_type_code, fiscal_year_id, current_value, padding_length
        ) VALUES (
            p_company_id, p_document_type_code, p_fiscal_year_id, 1, 5
        ) RETURNING current_value, padding_length INTO v_next_val, v_padding;
    END IF;

    v_padding := COALESCE(v_padding, 5);

    IF v_fiscal_year_name IS NOT NULL AND v_fiscal_year_name != '' THEN
        v_generated_number := v_prefix || '-' || v_fiscal_year_name || '-' || LPAD(v_next_val::TEXT, v_padding, '0');
    ELSE
        v_generated_number := v_prefix || '-' || LPAD(v_next_val::TEXT, v_padding, '0');
    END IF;

    RETURN v_generated_number;
END;
$func$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION public.fn_get_next_sequence(
    p_company_id TEXT,
    p_document_type_code TEXT,
    p_fiscal_year_id INT DEFAULT NULL,
    p_branch_id UUID DEFAULT NULL
)
RETURNS TEXT AS $$
BEGIN
    RETURN public.fn_get_next_sequence(
        CASE WHEN p_company_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' 
             THEN p_company_id::UUID ELSE NULL END,
        p_document_type_code,
        p_fiscal_year_id,
        p_branch_id
    );
END;
$$ LANGUAGE plpgsql;

GRANT EXECUTE ON FUNCTION public.fn_get_next_sequence(UUID, TEXT, INT, UUID) TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.fn_get_next_sequence(TEXT, TEXT, INT, UUID) TO authenticated, anon, service_role;

-- 6. جدول مراكز التكلفة
CREATE TABLE IF NOT EXISTS public.cost_centers (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    name_ar TEXT,
    name_en TEXT,
    cost_center_type TEXT,
    color TEXT,
    icon TEXT,
    is_active BOOLEAN DEFAULT true,
    company_id UUID REFERENCES public.sys_companies(id),
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    deleted_at TIMESTAMPTZ
);

-- Season Locking column
ALTER TABLE IF EXISTS public.cost_centers
  ADD COLUMN IF NOT EXISTS is_closed BOOLEAN GENERATED ALWAYS AS (
    NOT is_active 
    OR season_status IN ('closed', 'permanently_closed') 
    OR status IN ('closed', 'permanently_closed')
  ) STORED;

-- Ensure fruit_types and raw_materials columns & triggers are aligned
ALTER TABLE IF EXISTS public.fruit_types 
    ADD COLUMN IF NOT EXISTS cost_center_id TEXT,
    ADD COLUMN IF NOT EXISTS purchase_mode TEXT;

ALTER TABLE IF EXISTS public.fruit_types 
    ALTER COLUMN cost_center_id TYPE TEXT USING cost_center_id::TEXT;

ALTER TABLE IF EXISTS public.raw_materials 
    ADD COLUMN IF NOT EXISTS cost_center_id TEXT;

ALTER TABLE IF EXISTS public.raw_materials 
    ALTER COLUMN cost_center_id TYPE TEXT USING cost_center_id::TEXT;

DROP TRIGGER IF EXISTS trg_fruit_types_cost_center ON public.fruit_types;
DROP FUNCTION IF EXISTS public.fn_sync_fruit_type_cost_center();

GRANT ALL ON TABLE public.fruit_types TO authenticated, anon, service_role;
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_sequences WHERE schemaname = 'public' AND sequencename = 'fruit_types_id_seq') THEN
        EXECUTE 'GRANT ALL ON SEQUENCE public.fruit_types_id_seq TO authenticated, anon, service_role';
    END IF;
    IF EXISTS (SELECT 1 FROM pg_sequences WHERE schemaname = 'public' AND sequencename = 'fruit_type_code_seq') THEN
        EXECUTE 'GRANT ALL ON SEQUENCE public.fruit_type_code_seq TO authenticated, anon, service_role';
    END IF;
END $$;


-- 7. جدول حركات مراكز التكلفة
CREATE TABLE IF NOT EXISTS public.cost_center_transactions (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cost_center_id BIGINT REFERENCES public.cost_centers(id) ON DELETE SET NULL,
    cost_center_code TEXT,
    account_id BIGINT,
    journal_entry_id BIGINT REFERENCES public.journal_entries(id) ON DELETE SET NULL,
    amount NUMERIC DEFAULT 0,
    amount_in_base_currency NUMERIC DEFAULT 0,
    currency TEXT DEFAULT 'EGP',
    transaction_date DATE DEFAULT CURRENT_DATE,
    description TEXT,
    source_type TEXT,
    source_id TEXT,
    company_id UUID REFERENCES public.sys_companies(id),
    created_by UUID,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 8. جدول حركات البنوك (للتوافق مع الـ RPCs)
CREATE TABLE IF NOT EXISTS public.bank_transactions (
    id SERIAL PRIMARY KEY,
    bank_account_id INTEGER REFERENCES public.bank_accounts(id) ON DELETE CASCADE,
    type TEXT,
    transaction_type TEXT,
    amount NUMERIC(18,2) NOT NULL DEFAULT 0.00,
    balance_before NUMERIC(18,2),
    balance_after NUMERIC(18,2),
    currency TEXT DEFAULT 'EGP',
    description TEXT,
    notes TEXT,
    counterparty_name TEXT,
    reference_type TEXT,
    reference_id TEXT,
    transaction_date DATE DEFAULT CURRENT_DATE,
    created_by UUID,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    journal_entry_id BIGINT REFERENCES public.journal_entries(id) ON DELETE SET NULL,
    expense_account_id BIGINT,
    exchange_rate NUMERIC(15,6) DEFAULT 1.0,
    amount_in_base_currency NUMERIC(18,2),
    currency_snapshot JSONB DEFAULT '{}'::jsonb,
    company_id UUID REFERENCES public.sys_companies(id),
    deleted_at TIMESTAMPTZ
);

-- 9. جدول توزيعات سداد الموردين
CREATE TABLE IF NOT EXISTS public.supplier_payment_allocations (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    payment_id BIGINT,
    invoice_id UUID,
    allocated_amount NUMERIC(15,2),
    amount NUMERIC(15,2),
    currency TEXT,
    entity_type TEXT,
    entity_id TEXT,
    source_type TEXT,
    source_id BIGINT,
    purchase_invoice_id INTEGER,
    lot_receipt_id BIGINT,
    packing_order_cost_item_id BIGINT,
    shipment_cost_item_id BIGINT,
    supplier_id UUID,
    allocation_type TEXT,
    created_at TIMESTAMPTZ DEFAULT now()
);

ALTER TABLE IF EXISTS public.supplier_payment_allocations 
    ADD COLUMN IF NOT EXISTS currency TEXT,
    ADD COLUMN IF NOT EXISTS entity_type TEXT,
    ADD COLUMN IF NOT EXISTS entity_id TEXT;

-- 10. جدول أسطر أوامر التعبئة
CREATE TABLE IF NOT EXISTS public.packing_order_lines (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    packing_order_id BIGINT NOT NULL REFERENCES public.packing_orders(id) ON DELETE CASCADE,
    product_id BIGINT,
    variety_id BIGINT,
    grade TEXT,
    planned_cartons INT DEFAULT 0,
    actual_cartons INT DEFAULT 0,
    gross_weight_kg NUMERIC DEFAULT 0,
    net_weight_kg NUMERIC DEFAULT 0,
    fruit_cost_base NUMERIC DEFAULT 0,
    material_cost_base NUMERIC DEFAULT 0,
    allocated_cost_items NUMERIC DEFAULT 0,
    total_line_cost NUMERIC DEFAULT 0,
    unit_cost_per_carton NUMERIC DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- 11. جدول هوالك التعبئة
CREATE TABLE IF NOT EXISTS public.packing_wastes (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    packing_order_id BIGINT NOT NULL,
    waste_type TEXT,
    quantity NUMERIC DEFAULT 0,
    unit TEXT,
    cost_impact NUMERIC DEFAULT 0,
    notes TEXT,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 12. جدول أكواد الحسابات المحذوفة
CREATE TABLE IF NOT EXISTS public.deleted_account_codes (
    code TEXT PRIMARY KEY,
    deleted_at TIMESTAMPTZ DEFAULT now()
);

-- 13. جدول موردي النقل (Transport Suppliers)
CREATE TABLE IF NOT EXISTS public.transport_suppliers (
    id SERIAL PRIMARY KEY,
    code TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    phone TEXT,
    email TEXT,
    account_id BIGINT REFERENCES public.accounts(id),
    initial_balance NUMERIC(15,2) DEFAULT 0,
    initial_balance_direction TEXT DEFAULT 'CREDIT' CHECK (initial_balance_direction IN ('CREDIT', 'DEBIT')),
    balance NUMERIC(15,2) DEFAULT 0,
    current_balance NUMERIC(15,2) DEFAULT 0,
    notes TEXT,
    company_id UUID REFERENCES public.sys_companies(id),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    deleted_at TIMESTAMPTZ
);

-- 14. جدول حركات موردي النقل (Transport Transactions)
CREATE TABLE IF NOT EXISTS public.transport_transactions (
    id SERIAL PRIMARY KEY,
    supplier_id INTEGER NOT NULL REFERENCES public.transport_suppliers(id) ON DELETE CASCADE,
    type TEXT NOT NULL,
    amount NUMERIC(15,2) NOT NULL,
    currency TEXT DEFAULT 'EGP',
    reference_id TEXT,
    description TEXT,
    truck_count NUMERIC(12,2) DEFAULT 1,
    notes TEXT,
    journal_entry_id BIGINT REFERENCES public.journal_entries(id),
    date DATE NOT NULL DEFAULT (NOW() AT TIME ZONE 'Africa/Cairo')::date,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    created_by UUID
);

-- 15. جدول الفترات المحاسبية (Accounting Periods)
CREATE TABLE IF NOT EXISTS public.accounting_periods (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id UUID REFERENCES public.sys_companies(id),
    fiscal_year_id INTEGER,
    period_name TEXT NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    status TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN', 'CLOSED', 'ADJUSTMENT')),
    period_number INTEGER,
    name TEXT,
    is_closed BOOLEAN DEFAULT false,
    closed_at TIMESTAMPTZ,
    closed_by UUID,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    deleted_at TIMESTAMPTZ
);

-- 16. جداول إعدادات التوجيه المحاسبي والضرائب (Enterprise Posting Config)
CREATE TABLE IF NOT EXISTS public.posting_account_roles (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    description TEXT,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.posting_profiles (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id UUID REFERENCES public.sys_companies(id),
    code TEXT NOT NULL,
    name TEXT NOT NULL,
    description TEXT,
    is_default BOOLEAN DEFAULT false,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.posting_profile_rules (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id UUID REFERENCES public.sys_companies(id),
    profile_id UUID REFERENCES public.posting_profiles(id) ON DELETE CASCADE,
    role_id UUID REFERENCES public.posting_account_roles(id) ON DELETE CASCADE,
    account_id BIGINT REFERENCES public.accounts(id) ON DELETE CASCADE,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.document_posting_templates (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    document_type_code TEXT REFERENCES public.sys_document_types(code),
    line_key TEXT NOT NULL,
    role_code TEXT,
    entry_side TEXT NOT NULL,
    description_template TEXT,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.posting_validation_rules (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    rule_type TEXT NOT NULL,
    severity TEXT DEFAULT 'ERROR',
