    '12111', '12112', '12113', '12114', '12121',
    '12211', '12212', '12213', '12214',
    '12311', '12312', '12313', '12314',
    '12411', '12412', '12413', '12414',
    '12511', '12512',
    '12611', '12612', '12613', '12614', '12615', '12616',
    
    -- 2. الخصوم وحقوق الملكية (Roots, Groups & Official Level 5)
    '2', '21', '22', '23',
    '211', '212', '213', '221', '231', '232', '233', '234', '235',
    '2111', '2112',
    '21111', '21112', '21113', '21114', '21115', '21116', '21117', '21118', '21121',
    '2121', '2122',
    '21211', '21212', '21213', '21214', '21215', '21216',
    '21221', '21222',
    '2131',
    '21311', '21312',
    '2211', '2212',
    '22111',
    '22121', '22122', '22123', '22124', '22125', '22126',
    '2311',
    '23111', '23112',
    '2321',
    '23211', '23212', '23213',
    '2331',
    '23311',
    '2341',
    '23411',
    '2342',
    '23421',
    '2351',
    '23511',
    
    -- 3. المصروفات والتكاليف (Roots, Groups & Official Accounts)
    '3', '31', '32', '33', '34', '341',
    '311', '312', '313', '314', '315',
    '3111', '3112', '3113', '3114', '3115', '3116',
    '3122', '3124', '3125',
    '3131', '3132', '3133', '3134',
    '3141',
    '3151', '3152', '3153', '3154', '3155', '3156', '3157', '3158',
    '321', '322', '323',
    '3211', '3213', '3214', '3215', '3216', '3217', '3218', '3219', '3220',
    '3221',
    '3231', '3232',
    '331', '332',
    '3310', '3311', '3312', '3321',
    '3411', '34111', '34112', '34113', '34114', '34115', '34116', '34117', '34118', '34119', '34110',
    
    -- 4. الإيرادات (Roots, Groups & Official Accounts)
    '4', '41', '42',
    '411', '412', '413',
    '4111', '4112', '4113', '4114', '4115', '4116', '4117', '4118',
    '4121', '4122', '4131',
    '421', '422', '423',
    '4211', '4212', '4221', '4231', '4232',
    
    -- 9. الحسابات الوسيطة والنظامية
    '9', '91', '911', '912',
    '9111', '9112', '9121', '9122', '9123', '9124',
    
    -- حسابات الجذور القديمة الاحتياطية (Legacy Root Placeholders)
    '1000', '1010', '1020', '1030', '1031', '1032', '1040',
    '11101', '11102', '11103', '11104',
    '11201', '11202', '11203', '11204',
    '2000', '2100', '2101', '2102', '2103', '2104', '2105', '2106', '2107', '2200', '2300',
    '3000', '3100', '3101', '3200', '3300',
    '3900', '3901', '3902', '3903', '3904',
    '4000', '41101', '4200', '4300', '4310', '4320',
    '5000', '6000', '6001', '6002', '6110', '6130', '6150', '6151', '6152'
)
AND (
    -- أ. كافة حسابات الترحيل الفرعية للكيانات المكونة من 6 أرقام أو أكثر (1251xx, 2111xx..2117xx, 2321xx)
    account_code ~ '^(1251|2111|2112|2113|2114|2115|2116|2117|2321)[0-9]{2,}$'
    
    -- ب. كافة الحسابات الفرعية التابعة مباشرة لأي من حسابات الكيانات الأب (خارج القائمة المعتمدة أعلاه)
    OR parent_id IN (
        SELECT id FROM public.accounts 
        WHERE account_code IN ('1251', '2111', '2112', '2113', '2114', '2115', '2116', '2117', '2321')
    )
    
    -- ج. حسابات الكيانات القديمة التراكمية (Legacy Entity Codes)
    OR account_code ~ '^(1020|2000|2100|2101|2102|2103|2104|2105|2106|2107|2315|3101)[0-9]+'
    
    -- د. مطابقة أسماء الحسابات التشغيلية بجميع بادئاتها وتصنيفاتها
    OR account_name LIKE 'عميل%' OR name LIKE 'Customer%'
    OR account_name LIKE 'مورد%' OR name LIKE 'Supplier%'
    OR account_name LIKE 'مورد تعبئة%' OR name LIKE 'Packaging Supplier%'
    OR account_name LIKE 'مورد مشترك%' OR name LIKE 'Shared Supplier%'
    OR account_name LIKE 'مورد نقل%' OR name LIKE 'Transport Supplier%' OR name LIKE 'Transporter%'
    OR account_name LIKE 'شركة شحن%' OR name LIKE 'Shipping%'
    OR account_name LIKE 'مخلص%' OR name LIKE 'Clearing%'
    OR account_name LIKE 'مساهم%' OR name LIKE 'Shareholder%'
    OR account_name LIKE 'عهدة%' OR name LIKE 'Custody%'
    
    -- هـ. أكواد تجريبية أو شاذة سابقة
    OR account_code IN ('1050', '1568', '112001', '211200', '124101', '124102', '2132', '2133', '2134', '2135', '2136', '2137', '2138', '222', '2221', '2222', '2223', '2224', '2225', '2226', '2227', '2310', '2312', '2313', '2314', '2322', '2330', '2332', '2333', '2334', '2342', '3121', '3123', '3212', '3222', '3223', '3224')
)
AND NOT EXISTS (SELECT 1 FROM public.shareholders sh WHERE sh.account_id = public.accounts.id)
AND NOT EXISTS (SELECT 1 FROM public.suppliers sp WHERE sp.account_id = public.accounts.id)
AND NOT EXISTS (SELECT 1 FROM public.customers cs WHERE cs.account_id = public.accounts.id)
AND NOT EXISTS (SELECT 1 FROM public.account_ledger_entries ale WHERE ale.account_id = public.accounts.id);

-- حذف الحسابات الزائدة المستبعدة نهائياً من شجرة الحسابات (فقط إذا لم تكن مرتبطة بكيانات أو قيود)
DELETE FROM public.accounts a 
WHERE a.account_code IN ('3121', '3123', '3212', '3222', '3223', '3224')
  AND NOT EXISTS (SELECT 1 FROM public.shareholders sh WHERE sh.account_id = a.id)
  AND NOT EXISTS (SELECT 1 FROM public.suppliers sp WHERE sp.account_id = a.id)
  AND NOT EXISTS (SELECT 1 FROM public.customers cs WHERE cs.account_id = a.id)
  AND NOT EXISTS (SELECT 1 FROM public.account_ledger_entries ale WHERE ale.account_id = a.id);

-- تصحيح مسميات حسابات جاري المساهمين واستبدال أي خطأ طباعي (جائز -> جاري)
UPDATE public.accounts 
SET account_name = REPLACE(account_name, 'جائز', 'جاري'),
    name = REPLACE(name, 'جائز', 'جاري')
WHERE account_name LIKE '%جائز%' OR name LIKE '%جائز%';

UPDATE public.accounts SET account_name = 'جاري مساهمين' WHERE account_code IN ('232', '2321');
UPDATE public.accounts SET account_name = 'جاري / عماد' WHERE account_code = '23211';
UPDATE public.accounts SET account_name = 'جاري / عبد الباطن' WHERE account_code = '23212';
UPDATE public.accounts SET account_name = 'جاري / إسلام' WHERE account_code = '23213';

-- حذف أي حسابات قديمة أخر لها نفس أسماء الحسابات القياسية الجديدة (بأكواد مختلفة)
DELETE FROM public.accounts a
WHERE EXISTS (
    SELECT 1 FROM public.accounts b
    WHERE b.account_code IN (
        '1000', '1010', '1020', '1030', '1031', '1032', '1040',
        '11101', '11102', '11103', '11104',
        '11201', '11202', '11203', '11204',
        '2000', '2100', '2101', '2102', '2103', '2104', '2105', '2106', '2107', '2200', '2300',
        '3000', '3001', '3002', '3003', '3004', '3100', '3101', '3200', '3300',
        '3900', '3901', '3902', '3903', '3904',
        '4000', '41101', '4200', '4300', '4310', '4320',
        '5000', '6001', '51102', '51104', '5110', '5210', '6002', '6000', '6110', '51101', '6130', '6150', '6151', '6152'
    )
      AND b.account_name = a.account_name
      AND b.id != a.id
)
AND a.account_code NOT IN (
    '1000', '1010', '1020', '1030', '1031', '1032', '1040',
    '11101', '11102', '11103', '11104',
    '11201', '11202', '11203', '11204',
    '2000', '2100', '2101', '2102', '2103', '2104', '2105', '2106', '2107', '2200', '2300',
    '3000', '3001', '3002', '3003', '3004', '3100', '3101', '3200', '3300',
    '3900', '3901', '3902', '3903', '3904',
    '4000', '41101', '4200', '4300', '4310', '4320',
    '5000', '6001', '51102', '51104', '5110', '5210', '6002', '6000', '6110', '51101', '6130', '6150', '6151', '6152'
);

-- حذف أي حسابات قديمة شاذة أو يتيمة بلا أب ولا تتبع الجذور القياسية الخمسة (1, 2, 3, 4, 9)
DELETE FROM public.accounts
WHERE parent_id IS NULL 
  AND account_code NOT IN ('1', '2', '3', '4', '9');


-- ============================================================================
-- المرحلة 5: غرس وضمان وجود الدليل المحاسبي القياسي الموحد (Chart of Accounts)
-- ============================================================================
-- ملاحظة مهمة: account_code فيه UNIQUE constraint عالمي (مش per-company)
-- لذلك نضيف الحسابات مرة واحدة فقط ونربطها بأول شركة
DO $$
DECLARE
    v_has_company BOOLEAN;
    v_acct_col_type TEXT;
    v_first_company_id TEXT;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'accounts' AND column_name = 'company_id'
    ) INTO v_has_company;

    IF v_has_company THEN
        SELECT udt_name INTO v_acct_col_type
        FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'accounts' AND column_name = 'company_id';

        -- التأكد من وجود شركة واحدة على الأقل
        IF NOT EXISTS (SELECT 1 FROM public.sys_companies WHERE deleted_at IS NULL) THEN
            IF v_acct_col_type = 'uuid' THEN
                BEGIN
                    INSERT INTO public.sys_companies (id, name, is_active, created_at, updated_at)
                    VALUES ('a0000000-0000-0000-0000-000000000001'::uuid, 'الشركة الافتراضية', true, now(), now())
                    ON CONFLICT (id) DO NOTHING;
                EXCEPTION WHEN OTHERS THEN
                    NULL;
                END;
            ELSE
                BEGIN
                    INSERT INTO public.sys_companies (id, name, is_active, created_at, updated_at)
                    VALUES ('comp-main-001', 'الشركة الافتراضية', true, now(), now())
                    ON CONFLICT (id) DO NOTHING;
                EXCEPTION WHEN OTHERS THEN
                    NULL;
                END;
            END IF;
        END IF;

        -- الحصول على أول شركة
        SELECT id::text INTO v_first_company_id FROM public.sys_companies WHERE deleted_at IS NULL ORDER BY created_at ASC LIMIT 1;
    END IF;

    -- أرشفة واستبعاد أي حسابات أصول قديمة أو زائدة خارج شجرة الـ 40 حساباً المعيارية
    UPDATE public.accounts
    SET deleted_at = NOW(), is_active = false
    WHERE (account_code LIKE '1%' OR code LIKE '1%')
      AND COALESCE(account_code, code) NOT IN (
        '1', '11', '12',
        '111', '121', '122', '123', '124', '125', '126',
        '1111', '1211', '1212', '1221', '1231', '1241', '1251', '1261',
        '11111', '11112', '11113', '11114', '11115', '11116',
        '12111', '12112', '12113', '12114', '12121',
        '12211', '12212', '12213', '12214',
        '12311', '12312', '12313', '12314',
        '12411', '12412', '12413', '12414',
        '12511', '12512',
        '12611', '12612', '12613', '12614', '12615', '12616'
      );

    -- أرشفة واستبعاد أي حسابات خصوم قديمة أو زائدة خارج شجرة الـ 51 حساباً المعيارية
    UPDATE public.accounts
    SET deleted_at = NOW(), is_active = false
    WHERE (account_code LIKE '2%' OR code LIKE '2%')
      AND COALESCE(account_code, code) NOT IN (
        '2', '21', '22', '23',
        '211', '212', '213', '221', '231', '232', '233', '234', '235',
        '2111', '2112', '2121', '2122', '2131', '2211', '2212', '2311', '2321', '2331', '2341', '2342', '2351',
        '21111', '21112', '21113', '21114', '21115', '21116', '21117', '21118', '21121',
        '21211', '21212', '21213', '21214', '21215', '21216',
        '21221', '21222',
        '21311', '21312',
        '22111',
        '22121', '22122', '22123', '22124', '22125', '22126',
        '23111', '23112',
        '23211', '23212', '23213',
        '23311',
        '23411',
        '23421',
        '23511'
      );

    -- غرس وتحديث شجرة الحسابات القياسية المتزامنة حرفياً (COA Verbatim Synchronization)
    IF v_first_company_id IS NOT NULL THEN
        IF v_acct_col_type = 'uuid' THEN
            INSERT INTO public.accounts (account_code, name, account_name, account_type, normal_balance, is_active, is_leaf, allow_posting, sort_order, company_id)
            SELECT v.account_code, v.name, v.account_name, v.account_type, v.normal_balance, true, v.is_leaf, v.allow_posting, v.sort_order, v_first_company_id::uuid
            FROM (VALUES
                -- ──────────────────────────────────────────────────────────────────
        -- ROOT 1: ASSETS / الأصول (Natural Balance: Debit) - المستوى الأول (1)
        -- ──────────────────────────────────────────────────────────────────
        ('1', 'Assets', 'الأصول', 'asset', 'Debit', false, false, 1000),
        
        -- المستوى الثاني (2)
        ('11', 'Non-Current Assets', 'أصول طويله الأجل', 'asset', 'Debit', false, false, 1100),
        ('12', 'Current Assets', 'أصول متداوله', 'asset', 'Debit', false, false, 1200),
        
        -- المستوى الثالث (7)
        ('111', 'Fixed Assets', 'أصول ثابته', 'asset', 'Debit', false, false, 1110),
        ('121', 'Cash at Banks', 'النقديه بالبنوك', 'asset', 'Debit', false, false, 1210),
        ('122', 'Cash in Hand & Safes', 'النقديه بالصندوق', 'asset', 'Debit', false, false, 1220),
        ('123', 'Cash in Transit', 'النقديه بالطريق', 'asset', 'Debit', false, false, 1230),
        ('124', 'Inventory', 'المخزون', 'asset', 'Debit', false, false, 1240),
        ('125', 'Customers & Receivables', 'العملاء', 'asset', 'Debit', false, false, 1250),
        ('126', 'Other Debit Balances', 'أرصده مدينه أخرى', 'asset', 'Debit', false, false, 1260),

        -- المستوى الرابع (8)
        ('1111', 'Integrated Fixed Assets', 'أصول ثابته متكامله', 'asset', 'Debit', false, false, 1111),
        ('1211', 'Debit Banks', 'بنوك مدينه', 'asset', 'Debit', false, false, 1211),
        ('1212', 'Cheques Under Collection', 'شيكات برسم التحصيل', 'asset', 'Debit', false, false, 1212),
        ('1221', 'Main Safes', 'الخزن الاساسيه', 'asset', 'Debit', false, false, 1221),
        ('1231', 'Cash Transfers', 'تحويلات نقديه', 'asset', 'Debit', false, false, 1231),
        ('1241', 'Inventory Control', 'المخزون', 'asset', 'Debit', false, false, 1241),
        ('1251', 'Customers Control', 'العملاء', 'asset', 'Debit', false, false, 1251),
        ('1261', 'Other Debit Balances Control', 'أرصده مدينه أخرى', 'asset', 'Debit', false, false, 1261),

        -- المستوى الخامس (22 حساب ترحيل نهائي)
        -- 1. أصول ثابتة (تحت 1111):
        ('11111', 'Fixed Assets - Lands', 'أصول ثابته أراضى', 'asset', 'Debit', true, true, 11111),
        ('11112', 'Fixed Assets - Buildings', 'أصول ثابته مباني', 'asset', 'Debit', true, true, 11112),
        ('11113', 'Fixed Assets - Furniture & Office', 'أصول ثابته أثاث ومعدات مكتبيه', 'asset', 'Debit', true, true, 11113),
        ('11114', 'Fixed Assets - Computers & IT', 'أصول ثابته اجهزه كمبيوتر', 'asset', 'Debit', true, true, 11114),
        ('11115', 'Fixed Assets - Passenger Vehicles', 'أصول ثابته سيارات ملاكي', 'asset', 'Debit', true, true, 11115),
        ('11116', 'Fixed Assets - Produce Transport Vehicles', 'أصول ثابته وسائل نقل المحاصيل', 'asset', 'Debit', true, true, 11116),

        -- 2. بنوك مدينة (تحت 1211):
        ('12111', 'Commercial International Bank (CIB) - EGP', 'البنك التجاري الدولي CIB - جنيه مصري', 'asset', 'Debit', true, true, 12111),
        ('12112', 'Commercial International Bank (CIB) - USD', 'البنك التجاري الدولي CIB - دولار أمريكي', 'asset', 'Debit', true, true, 12112),
        ('12113', 'Commercial International Bank (CIB) - EUR', 'البنك التجاري الدولي CIB - يورو', 'asset', 'Debit', true, true, 12113),
        ('12114', 'Commercial International Bank (CIB) - GBP', 'البنك التجاري الدولي CIB - جنيه إسترليني', 'asset', 'Debit', true, true, 12114),

        -- 3. شيكات برسم التحصيل (تحت 1212):
        ('12121', 'Cheques Under Collection', 'شيكات برسم التحصيل', 'asset', 'Debit', true, true, 12121),

        -- 4. النقدية بالصندوق (تحت 1221):
        ('12211', 'Main Treasury - EGP', 'الخزينة الرئيسية - جنيه مصري', 'asset', 'Debit', true, true, 12211),
        ('12212', 'Main Treasury - USD', 'الخزينة الرئيسية - دولار أمريكي', 'asset', 'Debit', true, true, 12212),
        ('12213', 'Main Treasury - EUR', 'الخزينة الرئيسية - يورو', 'asset', 'Debit', true, true, 12213),
        ('12214', 'Main Treasury - GBP', 'الخزينة الرئيسية - جنيه إسترليني', 'asset', 'Debit', true, true, 12214),

        -- 5. النقدية بالطريق (تحت 1231):
        ('12311', 'Cash Transfers', 'تحويلات نقديه', 'asset', 'Debit', true, true, 12311),
        ('12312', 'Cheque Transfers', 'تحويلات شيكات', 'asset', 'Debit', true, true, 12312),
        ('12313', 'Foreign Currency Bank Transfers', 'تحويلات بنكيه عملات - خارجيه', 'asset', 'Debit', true, true, 12313),
        ('12314', 'Inter-Branch Bank Transfers', 'تحويلات بنكيه بين الفروع - داخليه', 'asset', 'Debit', true, true, 12314),

        -- 6. المخزون (تحت 1241):
        ('12411', 'Packaging Materials Warehouse', 'مخزن التعبئه والتغليف', 'asset', 'Debit', true, true, 12411),
        ('12412', 'Raw Materials Purchases Warehouse', 'مخزن مشتريات خام', 'asset', 'Debit', true, true, 12412),
        ('12413', 'Finished Goods Warehouse', 'مخزن الإنتاج التام', 'asset', 'Debit', true, true, 12413),
        ('12414', 'Sorting & Defective Warehouse', 'مخزن الفرز والتالف القابل للبيع', 'asset', 'Debit', true, true, 12414),

        -- 7. العملاء (تحت 1251):
        ('12511', 'Export Customers', 'عملاء تصدير', 'asset', 'Debit', true, true, 12511),
        ('12512', 'Local Customers', 'عملاء محلي', 'asset', 'Debit', true, true, 12512),

        -- 8. أرصدة مدينة أخرى (تحت 1261):
        ('12611', 'Cash Advances', 'سلف نقديه', 'asset', 'Debit', true, true, 12611),
        ('12612', 'Temporary Cash Custody', 'عهد نقديه مؤقته', 'asset', 'Debit', false, false, 12612),
        ('12613', 'Permanent Cash Custody', 'عهد نقديه مستديمه', 'asset', 'Debit', false, false, 12613),
        ('12614', 'Tax Authority - Withholding Tax', 'جاري مصلحه الضرائب - خصم منبع', 'asset', 'Debit', true, true, 12614),
        ('12615', 'Other Debtors - Under Collection', 'ارصده مدينه اخرى - ارصده تحت التحصيل', 'asset', 'Debit', true, true, 12615),
        ('12616', 'Other Debtors - Legal Auditor Office', 'ارصده مدينه اخرى - مكتب المحاسب القانوني', 'asset', 'Debit', true, true, 12616),

        -- ──────────────────────────────────────────────────────────────────
        -- ROOT 2: LIABILITIES & EQUITY / الخصوم (Natural Balance: Credit)
        -- ──────────────────────────────────────────────────────────────────
        ('2', 'Liabilities & Equity', 'الخصوم', 'liability', 'Credit', false, false, 2000),
        
        -- Level 2 (3)
        ('21', 'Current Liabilities', 'الخصوم المتداوله', 'liability', 'Credit', false, false, 2100),
        ('22', 'Long-Term Liabilities', 'الإلتزامات طويله الأجل', 'liability', 'Credit', false, false, 2200),
        ('23', 'Capital & Equity', 'راس المال وحقوق الملكيه', 'equity', 'Credit', false, false, 2300),

        -- Level 3 under 21 (Current Liabilities)
        ('211', 'Suppliers & Notes Payable', 'الموردين واوراق الدفع', 'liability', 'Credit', false, false, 2110),
        ('212', 'Liabilities to Government Entities', 'التزامات لجهات حكوميه', 'liability', 'Credit', false, false, 2120),
        ('213', 'Other Credit Balances', 'أرصده دائنه أخرى', 'liability', 'Credit', false, false, 2130),

        -- Level 4 under 211 (Suppliers & Notes Payable)
        ('2111', 'Suppliers Control', 'الموردين', 'liability', 'Credit', false, false, 21110),
        ('2112', 'Notes Payable', 'أوراق الدفع', 'liability', 'Credit', false, false, 21120),

        -- Level 5 under 2111 (Suppliers Control / الموردين)
        ('21111', 'Transport Suppliers Sub-ledger', 'موردي النقل والسيارات', 'liability', 'Credit', true, true, 21111),
        ('21112', 'Packaging Materials Suppliers Sub-ledger', 'موردي مواد التعبئة', 'liability', 'Credit', true, true, 21112),
        ('21113', 'Crop Purchase Suppliers Sub-ledger', 'موردي مشتريات محاصيل', 'liability', 'Credit', true, true, 21113),
        ('21114', 'Shared Suppliers Sub-ledger', 'موردين مشتركين', 'liability', 'Credit', true, true, 21114),
        ('21115', 'Shipping Companies Sub-ledger', 'شركات الشحن', 'liability', 'Credit', true, true, 21115),
        ('21116', 'Customs Clearance Sub-ledger', 'مخلصي الجمارك', 'liability', 'Credit', true, true, 21116),
        ('21117', 'Station Suppliers Sub-ledger', 'موردي المحطات', 'liability', 'Credit', true, true, 21117),
        ('21118', 'Deductions Suppliers Sub-ledger', 'موردي التخصيمات', 'liability', 'Credit', true, true, 21118),

        -- Level 5 under 2112 (Notes Payable)
        ('21121', 'Notes Payable - CIB', 'أوراق دفع البنك التجاري الدولي CIB', 'liability', 'Credit', true, true, 21121),

        -- Level 4 under 212 (Government Entities)
        ('2121', 'Taxes Control', 'الضرائب', 'liability', 'Credit', false, false, 2121),
        ('2122', 'Social Insurance & Labor Office Control', 'هيئه التامينات الإجتماعيه ومكتب العمل', 'liability', 'Credit', false, false, 2122),

        -- Level 5 under 2121 (Taxes)
        ('21211', 'Payroll Tax', 'ضريبه كسب العمل', 'liability', 'Credit', true, true, 21211),
        ('21212', 'Withholding Tax', 'ضريبه الخصم من الغير - الخصم والاضافه', 'liability', 'Credit', true, true, 21212),
        ('21213', 'VAT - Sales Tax', 'ضريبه القيمه المضافه - المبيعات', 'liability', 'Credit', true, true, 21213),
        ('21214', 'Corporate Income Tax', 'ضريبه الدخل', 'liability', 'Credit', true, true, 21214),
        ('21215', 'Stamp Duty Tax', 'ضريبه الدمغه', 'liability', 'Credit', true, true, 21215),
        ('21216', 'Prior Years Taxes', 'ضريبه سنوات سابقه', 'liability', 'Credit', true, true, 21216),

        -- Level 5 under 2122 (Social Insurance & Labor Office)
        ('21221', 'Social Insurance Authority', 'هيئه التامينات الإجتماعيه', 'liability', 'Credit', true, true, 21221),
        ('21222', 'Labor Office', 'مكتب العمل', 'liability', 'Credit', true, true, 21222),

        -- Level 4 under 213 (Other Credit Balances)
        ('2131', 'Other Credit Balances Control', 'أرصده دائنه أخرى', 'liability', 'Credit', false, false, 2131),

        -- Level 5 under 2131
        ('21311', 'Accrued Expenses - Salaries', 'مصروفات مستحقه - مرتبات', 'liability', 'Credit', true, true, 21311),
        ('21312', 'Third Party Deposits', 'تأمينات لصالح الغير', 'liability', 'Credit', true, true, 21312),

        -- Level 3 under 22 (Long-Term Liabilities)
        ('221', 'Long Term Liabilities', 'إلتزامات طويله الأجل', 'liability', 'Credit', false, false, 2210),

        -- Level 4 under 221
        ('2211', 'Long Term Liabilities - Taxes', 'التزمات طويله الأجل ضرائب', 'liability', 'Credit', false, false, 2211),
        ('2212', 'Accumulated Depreciation Control', 'مجمع الإهلاك', 'liability', 'Credit', false, false, 2212),

        -- Level 5 under 2211 (Deferred Taxes)
        ('22111', 'Deferred Taxes', 'ضرائب مؤجله', 'liability', 'Credit', true, true, 22111),

        -- Level 5 under 2212 (Accumulated Depreciation)
        ('22121', 'Acc. Depr. - Land Improvements', 'مجمع اهلاك أصول ثابته اراضي', 'liability', 'Credit', true, true, 22121),
        ('22122', 'Acc. Depr. - Buildings', 'مجمع اهلاك أصول ثابته مباني', 'liability', 'Credit', true, true, 22122),
        ('22123', 'Acc. Depr. - Furniture & Office Equipment', 'مجمع اهلاك أصول ثابته أثاث ومعدات مكتبيه', 'liability', 'Credit', true, true, 22123),
