        ('42', 'Other Revenues', 'إيرادات اخرى', 'revenue', 'Credit', false, false, 4200),

        -- Level 3 under 41 & 42
        ('411', 'Operating Revenues', 'إيرادات النشاط', 'revenue', 'Credit', false, false, 4110),
        ('421', 'Other Revenues', 'إيرادات اخرى', 'revenue', 'Credit', false, false, 4210),

        -- Level 4
        ('4111', 'Crop Sales', 'مبيعات محاصيل', 'revenue', 'Credit', false, false, 4111),
        ('4112', 'Other Sales', 'مبيعات اخرى', 'revenue', 'Credit', false, false, 4112),
        ('4113', 'Sales Discounts', 'خصم مسموح به', 'revenue', 'Debit', false, false, 4113),
        ('4211', 'Credit Interest', 'فوائد دائنه', 'revenue', 'Credit', false, false, 4211),
        ('4212', 'Commissions', 'عمولات', 'revenue', 'Credit', false, false, 4212),

        -- Level 5
        ('41111', 'Strawberry Sales', 'مبيعات فراوله', 'revenue', 'Credit', true, true, 41111),
        ('41112', 'Mango Sales', 'مبيعات مانجو', 'revenue', 'Credit', true, true, 41112),
        ('41113', 'Dates Sales', 'مبيعات بلح', 'revenue', 'Credit', true, true, 41113),
        ('41114', 'Blueberry Sales', 'مبيعات بلوبيرى', 'revenue', 'Credit', true, true, 41114),
        ('41121', 'Local Sorting Sales', 'مبيعات فرزه محلي', 'revenue', 'Credit', true, true, 41121),
        ('41131', 'Sales Discounts - Export', 'خصم مسموح به - مبيعات تصدير', 'revenue', 'Debit', true, true, 41131),
        ('42111', 'Credit Interest - CIB', 'فوائد دائنه - بنك التجارى الدولى CIB', 'revenue', 'Credit', true, true, 42111),
        ('42121', 'Commissions', 'عمولات', 'revenue', 'Credit', true, true, 42121),

        -- ──────────────────────────────────────────────────────────────────
        -- ROOT 9: SYSTEM & INTERMEDIARY ACCOUNTS / حسابات نظامية ووسيطة (Natural Balance: Debit)
        -- ──────────────────────────────────────────────────────────────────
        ('9', 'System & Intermediary Accounts', 'حسابات نظامية ووسيطة', 'system', 'Debit', false, false, 9000),

        -- Level 2
        ('91', 'Intermediary & Clearing Accounts', 'الحسابات الوسيطة والتسويات', 'system', 'Debit', false, false, 9100),

        -- Level 3
        ('911', 'Operational & Waste Intermediary', 'حسابات وسيطة للتشغيل والهالك', 'system', 'Debit', false, false, 9110),
        ('912', 'Tax & Expense Clearing', 'حسابات تسوية الضرائب والمصاريف', 'system', 'Debit', false, false, 9120),

        -- Level 4 under 911 & 912
        ('9111', 'Packaging Waste Intermediary', 'وسيط هالك مواد التعبئة', 'system', 'Debit', true, true, 9111),
        ('9112', 'Produce Waste Intermediary', 'وسيط هالك المحاصيل', 'system', 'Debit', true, true, 9112),
        ('9121', 'Tax Intermediary', 'وسيط ضرائب', 'system', 'Debit', true, true, 9121),
        ('9122', 'Allocated Taxes', 'ضرائب محملة', 'system', 'Debit', true, true, 9122),
        ('9123', 'Admin Expenses Provision', 'مخصص / وسيط مصروفات إدارية', 'system', 'Debit', true, true, 9123),
        ('9124', 'Allocated Admin Expenses', 'مصروفات إدارية محملة', 'system', 'Debit', true, true, 9124)
            ) AS v(account_code, name, account_name, account_type, normal_balance, is_leaf, allow_posting, sort_order)
            ON CONFLICT (account_code) DO UPDATE
            SET name = EXCLUDED.name,
                account_name = EXCLUDED.account_name,
                account_type = EXCLUDED.account_type,
                normal_balance = EXCLUDED.normal_balance,
                is_leaf = EXCLUDED.is_leaf,
                allow_posting = EXCLUDED.allow_posting,
                sort_order = EXCLUDED.sort_order,
                is_active = true;
        END IF;
    END IF;

    -- تفعيل وتأكيد خصائص الحسابات القياسية
    UPDATE public.accounts
    SET is_active = true;

    IF EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'accounts' AND column_name = 'deleted_at'
    ) THEN
        EXECUTE 'UPDATE public.accounts SET deleted_at = NULL';
    END IF;

    -- ── ضبط الهيكلية الشجرية الرسمية ذات الـ 4 مستويات ──
    -- 1. المستوى الأول: الجذور (Level 1 Roots)
    UPDATE public.accounts
    SET parent_id = NULL,
        level = 1,
        is_leaf = false,
        allow_posting = false
    WHERE account_code IN ('1', '2', '3', '4', '9');

    -- 2. المستوى الثاني: المجموعات الرئيسية (Level 2 Groups)
    UPDATE public.accounts a
    SET parent_id = p.id,
        level = 2,
        is_leaf = false,
        allow_posting = false
    FROM public.accounts p
    WHERE p.account_code = SUBSTRING(a.account_code FROM 1 FOR 1)
      AND a.account_code IN ('11', '12', '21', '22', '23', '31', '32', '33', '34', '41', '42', '91');

    -- 3. المستوى الثالث: المجموعات الفرعية (Level 3 Intermediate)
    UPDATE public.accounts a
    SET parent_id = p.id,
        level = 3,
        is_leaf = false,
        allow_posting = false
    FROM public.accounts p
    WHERE p.account_code = SUBSTRING(a.account_code FROM 1 FOR 2)
      AND a.account_code IN (
        '111', '121', '122', '123', '124', '125', '126',
        '211', '212', '213', '221', '222', '231', '232', '233', '234', '235',
        '311', '312', '313', '314', '315', '321', '322', '323', '331', '332', '341',
        '411', '412', '413', '421', '422', '423', '911', '912'
      );

    -- ضبط 341 تابعة للمجموعة 34 (تكاليف المبيعات)
    UPDATE public.accounts a
    SET parent_id = p.id,
        level = 3,
        is_leaf = false,
        allow_posting = false
    FROM public.accounts p
    WHERE p.account_code = '34'
      AND a.account_code = '341';

    -- ضبط 34 كحساب مجموعة رئيسي (Level 2)
    UPDATE public.accounts
    SET is_leaf = false,
        allow_posting = false,
        level = 2
    WHERE account_code = '34';

    -- ضبط 3411 كحساب تحليلي رقابي (Level 4)
    UPDATE public.accounts
    SET is_leaf = false,
        allow_posting = false,
        level = 4
    WHERE account_code = '3411';

    -- 4. المستوى الرابع: الحسابات التحليلية (Level 4 Analytical Accounts)
    UPDATE public.accounts a
    SET parent_id = p.id,
        level = 4,
        is_leaf = false,
        allow_posting = false
    FROM public.accounts p
    WHERE p.account_code = SUBSTRING(a.account_code FROM 1 FOR 3)
      AND LENGTH(a.account_code) = 4
      AND a.account_code NOT LIKE 'TMP_%';

    -- 4b. ضبط حسابات المستوى الرابع للأصول والخصوم كآباء رقابية
    UPDATE public.accounts
    SET is_leaf = false,
        allow_posting = false
    WHERE account_code IN (
      '1111', '1211', '1212', '1221', '1231', '1241', '1251', '1261',
      '2111', '2112', '2121', '2122', '2131', '2211', '2212', '2311', '2321', '2331', '2341', '2351'
    );

    -- 5. المستوى الخامس: حسابات الترحيل النهائية (Level 5 Leaf Accounts)
    UPDATE public.accounts a
    SET parent_id = p.id,
        level = 5,
        is_leaf = true,
        allow_posting = true
    FROM public.accounts p
    WHERE p.account_code = SUBSTRING(a.account_code FROM 1 FOR 4)
      AND (a.account_code LIKE '1%' OR a.account_code LIKE '2%' OR a.account_code LIKE '3%' OR a.account_code LIKE '4%')
      AND LENGTH(a.account_code) = 5;

    -- استبعاد وأرشفة العهد القديمة (124101، 124102)
    UPDATE public.accounts
    SET deleted_at = NOW(),
        is_active = false
    WHERE account_code IN ('124101', '124102') OR code IN ('124101', '124102');

    -- جاري المساهمين (تحت 2321)
    UPDATE public.accounts a
    SET parent_id = p.id,
        level = 5,
        is_leaf = true,
        allow_posting = true
    FROM public.accounts p
    WHERE p.account_code = '2321'
      AND (a.account_code ~ '^2321[0-9]+' OR a.account_code IN ('231501', '231502', '231503'));

    -- الحسابات التابعة لشركات النقل والموردين والعملاء
    UPDATE public.accounts a
    SET parent_id = p.id,
        level = 5,
        is_leaf = true,
        allow_posting = true
    FROM public.accounts p
    WHERE p.account_code = '2111'
      AND a.account_code ~ '^2111[0-9]{2,}$';

    UPDATE public.accounts a
    SET parent_id = p.id,
        level = 5,
        is_leaf = true,
        allow_posting = true
    FROM public.accounts p
    WHERE p.account_code = '2112'
      AND a.account_code ~ '^2112[0-9]{2,}$';

    UPDATE public.accounts a
    SET parent_id = p.id,
        level = 5,
        is_leaf = true,
        allow_posting = true
    FROM public.accounts p
    WHERE p.account_code = '1251'
      AND a.account_code ~ '^1251[0-9]{2,}$';

    UPDATE public.accounts a
    SET parent_id = p.id,
        level = 5,
        is_leaf = true,
        allow_posting = true
    FROM public.accounts p
    WHERE p.account_code = '1221'
      AND a.account_code ~ '^1221[0-9]{2,}$';

    -- خطوة وقائية تأكيدية: تنظيف أو ربط أي حساب يتيم خارج الجذور القياسية قبل الفحص
    UPDATE public.accounts a
    SET parent_id = p.id
    FROM public.accounts p
    WHERE a.parent_id IS NULL 
      AND a.account_code NOT IN ('1', '2', '3', '4', '9')
      AND p.account_code = (
          CASE 
              WHEN a.account_code ~ '^2321[0-9]+' THEN '2321'
              WHEN a.account_code ~ '^2315[0-9]+' THEN '2321'
              WHEN a.account_code ~ '^1251[0-9]+' THEN '1251'
              WHEN a.account_code ~ '^1221[0-9]+' THEN '1221'
              WHEN a.account_code ~ '^2111[0-9]+' THEN '2111'
              WHEN a.account_code ~ '^2112[0-9]+' THEN '2112'
              WHEN a.account_code = '1000' THEN '1'
              WHEN a.account_code = '2000' THEN '2'
              WHEN a.account_code = '3000' THEN '3'
              WHEN a.account_code = '4000' THEN '4'
              WHEN a.account_code IN ('5', '5000') THEN '32'
              WHEN a.account_code LIKE '5%' THEN '321'
              WHEN LENGTH(a.account_code) >= 5    THEN SUBSTRING(a.account_code FROM 1 FOR 4)
              WHEN LENGTH(a.account_code) = 4     THEN SUBSTRING(a.account_code FROM 1 FOR 3)
              WHEN LENGTH(a.account_code) = 3     THEN SUBSTRING(a.account_code FROM 1 FOR 2)
              WHEN LENGTH(a.account_code) = 2     THEN SUBSTRING(a.account_code FROM 1 FOR 1)
              ELSE NULL
          END
      );

    DELETE FROM public.accounts
    WHERE parent_id IS NULL AND account_code NOT IN ('1', '2', '3', '4', '9');

    -- 6. إعادة بناء مسارات الأكواد والمعرفات (path_codes & path_ids) بدقة
    WITH RECURSIVE account_tree AS (
        SELECT id, account_code, 1 AS depth, account_code::text AS path_c, id::text AS path_i
        FROM public.accounts
        WHERE parent_id IS NULL
        UNION ALL
        SELECT a.id, a.account_code, t.depth + 1, (t.path_c || '/' || a.account_code), (t.path_i || '/' || a.id::text)
        FROM public.accounts a
        JOIN account_tree t ON a.parent_id = t.id
    )
    UPDATE public.accounts a
    SET path_codes = t.path_c,
        path_ids = t.path_i,
        level = t.depth
    FROM account_tree t
    WHERE a.id = t.id;

    -- ضبط leaf / posting ديناميكياً
    UPDATE public.accounts a
    SET is_leaf = NOT EXISTS (SELECT 1 FROM public.accounts c WHERE c.parent_id = a.id),
        allow_posting = NOT EXISTS (SELECT 1 FROM public.accounts c WHERE c.parent_id = a.id);
END $$;

-- ── دالة إعادة بناء مسارات الهيكل المحاسبي الشجري مع الوقاية الذاتية ──
CREATE OR REPLACE FUNCTION public.rebuild_chart_of_accounts_hierarchy()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    -- أ. خطوة وقائية ذاتية: التأكد من أن الحسابات الجذرية 5 فقط ولا يوجد حساب فرعي بلا أب
    UPDATE public.accounts
    SET parent_id = (SELECT id FROM public.accounts WHERE account_code = '2321' LIMIT 1),
        level = 5,
        is_leaf = true,
        allow_posting = true
    WHERE parent_id IS NULL
      AND account_code NOT IN ('1', '2', '3', '4', '9')
      AND (
          account_code ~ '^2321[0-9]+'
          OR account_code ~ '^2315[0-9]+'
          OR account_name LIKE 'مساهم - %'
          OR account_name LIKE 'جارى أ / %'
          OR name LIKE 'Shareholder - %'
      );

    -- وقاية الحسابات التحليلية الأخرى
    UPDATE public.accounts
    SET parent_id = (SELECT id FROM public.accounts WHERE account_code = '1251' LIMIT 1),
        level = 5
    WHERE parent_id IS NULL
      AND account_code NOT IN ('1', '2', '3', '4', '9')
      AND (account_code ~ '^1251[0-9]+' OR account_name LIKE 'عميل - %' OR name LIKE 'Customer - %');

    UPDATE public.accounts
    SET parent_id = (SELECT id FROM public.accounts WHERE account_code = '1221' LIMIT 1),
        level = 5
    WHERE parent_id IS NULL
      AND account_code NOT IN ('1', '2', '3', '4', '9')
      AND account_code ~ '^1221[0-9]+'
      AND account_name NOT LIKE 'عميل - %'
      AND name NOT LIKE 'Customer - %';

    -- ربط حسابات موردي المحاصيل بـ 2111
    UPDATE public.accounts
    SET parent_id = (SELECT id FROM public.accounts WHERE account_code = '2111' LIMIT 1),
        level = 5
    WHERE parent_id IS NULL
      AND account_code NOT IN ('1', '2', '3', '4', '9')
      AND (
          account_code ~ '^2111[0-9]+'
          OR (
              (account_name LIKE 'مورد - %' OR name LIKE 'Supplier - %')
              AND account_name NOT LIKE 'مورد مشترك - %'
              AND account_name NOT LIKE 'مورد نقل - %'
              AND account_name NOT LIKE 'مورد تعبئة - %'
              AND name NOT LIKE 'Shared Supplier - %'
              AND name NOT LIKE 'Transporter - %'
              AND name NOT LIKE 'Packaging Supplier - %'
          )
      );

    -- ربط حسابات أوراق الدفع بـ 2112
    UPDATE public.accounts
    SET parent_id = (SELECT id FROM public.accounts WHERE account_code = '2112' LIMIT 1),
        level = 5
    WHERE parent_id IS NULL
      AND account_code NOT IN ('1', '2', '3', '4', '9')
      AND (
          account_code ~ '^2112[0-9]+'
          OR account_name LIKE 'أوراق دفع%'
          OR account_name LIKE 'اوراق دفع%'
      );

    -- تنظيف وحذف الحسابات غير المرغوبة (2113..2117, 21131..21171, 2123..2126, 2132..2138, 222, 2310..2314, 2322, 2330..2334)
    UPDATE public.accounts
    SET is_system = false,
        is_active = false,
        deleted_at = NOW()
    WHERE account_code IN ('2113', '2114', '2115', '2116', '2117', '21131', '21141', '21151', '21161', '21171', '2123', '2124', '2125', '2126', '2132', '2133', '2134', '2135', '2136', '2137', '2138', '222', '2221', '2222', '2223', '2224', '2225', '2226', '2227', '2310', '2312', '2313', '2314', '2322', '2330', '2332', '2333', '2334')
       OR code IN ('2113', '2114', '2115', '2116', '2117', '21131', '21141', '21151', '21161', '21171', '2123', '2124', '2125', '2126', '2132', '2133', '2134', '2135', '2136', '2137', '2138', '222', '2221', '2222', '2223', '2224', '2225', '2226', '2227', '2310', '2312', '2313', '2314', '2322', '2330', '2332', '2333', '2334');

    DELETE FROM public.accounts
    WHERE account_code IN ('2113', '2114', '2115', '2116', '2117', '21131', '21141', '21151', '21161', '21171', '2123', '2124', '2125', '2126', '2132', '2133', '2134', '2135', '2136', '2137', '2138', '222', '2221', '2222', '2223', '2224', '2225', '2226', '2227', '2310', '2312', '2313', '2314', '2322', '2330', '2332', '2333', '2334')
       OR code IN ('2113', '2114', '2115', '2116', '2117', '21131', '21141', '21151', '21161', '21171', '2123', '2124', '2125', '2126', '2132', '2133', '2134', '2135', '2136', '2137', '2138', '222', '2221', '2222', '2223', '2224', '2225', '2226', '2227', '2310', '2312', '2313', '2314', '2322', '2330', '2332', '2333', '2334');

    -- وقاية حسابات شركات الشحن والتخليص القديمة (2103, 2104) — ربطها بـ 211
    UPDATE public.accounts
    SET parent_id = (SELECT id FROM public.accounts WHERE account_code = '211' LIMIT 1),
        level = 4,
        is_leaf = false,
        allow_posting = false
    WHERE parent_id IS NULL
      AND account_code IN ('2103', '2104');

    -- وقاية الحسابات التابعة لـ 2103/2104
    UPDATE public.accounts
    SET parent_id = (SELECT id FROM public.accounts WHERE account_code = '2103' LIMIT 1),
        level = 5
    WHERE parent_id IS NULL
      AND account_code NOT IN ('1', '2', '3', '4', '9')
      AND account_code ~ '^2103[0-9]+';

    UPDATE public.accounts
    SET parent_id = (SELECT id FROM public.accounts WHERE account_code = '2104' LIMIT 1),
        level = 5
    WHERE parent_id IS NULL
      AND account_code NOT IN ('1', '2', '3', '4', '9')
      AND account_code ~ '^2104[0-9]+';

    -- ب. إعادة احتساب المسارات التكرارية للشجرة كاملة
    WITH RECURSIVE account_tree AS (
        SELECT 
            id, 
            account_code, 
            1 AS depth, 
            account_code::text AS path_c, 
            id::text AS path_i
        FROM public.accounts
        WHERE parent_id IS NULL
        
        UNION ALL
        
        SELECT 
            a.id, 
            a.account_code, 
            t.depth + 1, 
            (t.path_c || '/' || a.account_code), 
            (t.path_i || '/' || a.id::text)
        FROM public.accounts a
        JOIN account_tree t ON a.parent_id = t.id
    )
    UPDATE public.accounts a
    SET 
        path_codes = t.path_c,
        path_ids   = t.path_i,
        level      = t.depth
    FROM account_tree t
    WHERE a.id = t.id;
END;
$$;

-- ── دالة حل الحسابات الموحدة resolve_gl_account مع دعم التوافقية العكسية ──
DROP FUNCTION IF EXISTS public.resolve_gl_account(text, uuid);
CREATE OR REPLACE FUNCTION public.resolve_gl_account(
    p_account_code TEXT,
    p_company_id   UUID DEFAULT NULL
) RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_id BIGINT;
    v_target_code TEXT := p_account_code;
BEGIN
    IF v_target_code IS NULL OR v_target_code = '' THEN
        RETURN NULL;
    END IF;

    -- 1. مطابقة مباشرة بالكود والشركة
    SELECT id INTO v_id FROM public.accounts WHERE account_code = v_target_code AND company_id = p_company_id LIMIT 1;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;

    -- 2. مطابقة عامة بالكود
    SELECT id INTO v_id FROM public.accounts WHERE account_code = v_target_code LIMIT 1;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;

    -- 3. خريطة تحويل الأكواد القديمة والبديلة إلى الدليل القياسي الجديد ذو الـ 4 مستويات
    v_target_code := CASE p_account_code
        WHEN '1020' THEN '1221'
        WHEN '2000' THEN '2111'
        WHEN '21311' THEN '21111'
        WHEN '2101' THEN '9121'
        WHEN '9101' THEN '9121'
        WHEN '2102' THEN '9122'
        WHEN '9102' THEN '9122'
        WHEN '2103' THEN '21115'
        WHEN '2104' THEN '21116'
        WHEN '2105' THEN '9123'
        WHEN '9105' THEN '9123'
        WHEN '2106' THEN '9111'
        WHEN '9106' THEN '9111'
        WHEN '2107' THEN '9112'
        WHEN '9107' THEN '9112'
        WHEN '3000' THEN '23111'
        WHEN '3101' THEN '2321'
        WHEN '5000' THEN '3111'
        WHEN '1030' THEN '12412'
        WHEN '1031' THEN '12413'
        WHEN '1032' THEN '12414'
        WHEN '1040' THEN '12411'
        WHEN '4105' THEN '4131'
        WHEN '4200' THEN '4114'
        WHEN '4310' THEN '32211'
        WHEN '5210' THEN '9124'
        WHEN '9210' THEN '9124'
        WHEN '6151' THEN '32211'
        WHEN '51101' THEN '3211'
        WHEN '51102' THEN '3211'
        WHEN '51104' THEN '3213'
        WHEN '6000' THEN '3211'
        WHEN '6001' THEN '3211'
        WHEN '6002' THEN '3213'
        WHEN '11101' THEN '12121'
        WHEN '11102' THEN '12122'
        WHEN '11103' THEN '12123'
        WHEN '11104' THEN '12124'
        WHEN '11201' THEN '12111'
        WHEN '11202' THEN '12112'
        WHEN '11203' THEN '12113'
        WHEN '11204' THEN '12114'
        WHEN '3900' THEN '2330'
        WHEN '3901' THEN '2331'
        WHEN '3902' THEN '2332'
        WHEN '3903' THEN '2333'
        WHEN '3904' THEN '2334'
        ELSE p_account_code
    END;

    -- 4. البحث بعد التحويل
    SELECT id INTO v_id FROM public.accounts WHERE account_code = v_target_code AND company_id = p_company_id LIMIT 1;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;

    SELECT id INTO v_id FROM public.accounts WHERE account_code = v_target_code LIMIT 1;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;

    -- 5. بديل الخزينة الرئيسية إذا كان المطلوب خزينة أو بنك
    IF v_target_code LIKE '111%' OR v_target_code LIKE '121%' THEN
        SELECT t.account_id INTO v_id
        FROM public.treasuries t
        WHERE t.type = 'main' AND t.account_id IS NOT NULL
        LIMIT 1;
        IF v_id IS NOT NULL THEN RETURN v_id; END IF;
    END IF;

    RETURN v_id;
END;
$$;

-- Drop any conflicting TEXT overload to prevent PGRST203 ambiguous function errors
DROP FUNCTION IF EXISTS public.resolve_gl_account(text, text);

-- ── دالة حل حساب الأرصدة الافتتاحية لحقوق الملكية ──
CREATE OR REPLACE FUNCTION public.resolve_opening_balance_equity_account(
    p_currency TEXT,
    p_company_id UUID DEFAULT NULL
)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_acct BIGINT;
BEGIN
    -- 1. المحاولة بحساب فروق الأرصدة الافتتاحية المخصص (23421) أولاً
    SELECT id INTO v_acct
    FROM public.accounts
    WHERE account_code = '23421'
      AND (p_company_id IS NULL OR company_id = p_company_id OR company_id IS NULL OR company_id = 'a0000000-0000-0000-0000-000000000001'::uuid)
    ORDER BY (company_id IS NOT NULL AND company_id = p_company_id) DESC, id ASC
    LIMIT 1;

    -- 2. احتياطي في حال عدم وجوده: الأرباح والخسائر المرحلة (23411) أو الاحتياطي القانوني (23311)
    IF v_acct IS NULL THEN
        SELECT id INTO v_acct
        FROM public.accounts
        WHERE account_code IN ('23411', '23311', '23111', '2341', '2331', '2311')
          AND (p_company_id IS NULL OR company_id = p_company_id OR company_id IS NULL OR company_id = 'a0000000-0000-0000-0000-000000000001'::uuid)
        ORDER BY (company_id IS NOT NULL AND company_id = p_company_id) DESC, 
                 CASE account_code WHEN '23411' THEN 1 WHEN '23311' THEN 2 WHEN '23111' THEN 3 ELSE 4 END
        LIMIT 1;
    END IF;

    IF v_acct IS NULL THEN
        -- احتياطي: أي حساب حقوق ملكية نشط ويقبل الترحيل
        SELECT id INTO v_acct
        FROM public.accounts
        WHERE account_type = 'equity' AND (allow_posting = true OR is_leaf = true)
          AND (p_company_id IS NULL OR company_id = p_company_id OR company_id IS NULL OR company_id = 'a0000000-0000-0000-0000-000000000001'::uuid)
        ORDER BY (company_id IS NOT NULL AND company_id = p_company_id) DESC, id ASC
        LIMIT 1;
    END IF;

    -- 4. احتياطي مطلق: حساب 23421 دون تقييد على الشركة
    IF v_acct IS NULL THEN
        SELECT id INTO v_acct
        FROM public.accounts
        WHERE account_code IN ('23421', '2342', '2331', '3001')
        ORDER BY (account_code = '23421') DESC, id ASC
        LIMIT 1;
    END IF;

    RETURN v_acct;
END;
$$;

CREATE OR REPLACE FUNCTION public.resolve_opening_balance_equity_account(
    p_currency TEXT,
    p_company_id TEXT
)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    RETURN public.resolve_opening_balance_equity_account(p_currency, p_company_id::UUID);
END;
$$;


-- ── دالة حل حساب خسائر فروق العملة المحققة (32211 - فروق تقويم عمله) ──
CREATE OR REPLACE FUNCTION public.resolve_realized_fx_loss_account(p_company_id UUID DEFAULT NULL)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_acct BIGINT;
BEGIN
    -- 1. البحث عن حساب 32211 (فروق تقويم عمله) بتقييد الشركة
    SELECT id INTO v_acct
    FROM public.accounts
    WHERE account_code = '32211'
      AND (p_company_id IS NULL OR company_id = p_company_id OR company_id IS NULL)
    ORDER BY (company_id IS NOT NULL AND company_id = p_company_id) DESC, id ASC
    LIMIT 1;

    -- 2. احتياطي: حساب التحكم 3221 (فروق عمله)
    IF v_acct IS NULL THEN
        SELECT id INTO v_acct
        FROM public.accounts
        WHERE account_code = '3221'
          AND (p_company_id IS NULL OR company_id = p_company_id OR company_id IS NULL)
        ORDER BY (company_id IS NOT NULL AND company_id = p_company_id) DESC, id ASC
        LIMIT 1;
    END IF;

    -- 3. احتياطي مطلق بدون تقييد الشركة
    IF v_acct IS NULL THEN
        SELECT id INTO v_acct
        FROM public.accounts
        WHERE account_code = '32211'
        LIMIT 1;
    END IF;

    RETURN v_acct;
END;
$$;

-- ── دالة حل حساب أرباح فروق العملة المحققة (32211 - نفس حساب الخسائر) ──
CREATE OR REPLACE FUNCTION public.resolve_realized_fx_gain_account(p_company_id UUID DEFAULT NULL)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    -- في شجرة الحسابات الحالية، حساب 32211 يستقبل كلاً من الأرباح والخسائر
    -- الخسائر: مدين (Debit) / الأرباح: دائن (Credit)
    RETURN public.resolve_realized_fx_loss_account(p_company_id);
END;
$$;

GRANT EXECUTE ON FUNCTION public.resolve_realized_fx_loss_account(UUID) TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.resolve_realized_fx_gain_account(UUID) TO authenticated, anon, service_role;


-- ============================================================================
-- المرحلة 6: إعادة إنشاء الخزينة الرئيسية والبنوك والمخازن الرسمية
-- ============================================================================

DO $$
DECLARE
    v_has_company BOOLEAN;
    v_col_type TEXT;
    v_first_company_id TEXT;
    v_tid BIGINT;
    v_aid BIGINT;
    v_curr TEXT;
    v_acode TEXT;
    v_rate NUMERIC;
    v_comp RECORD;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'treasuries' AND column_name = 'company_id'
    ) INTO v_has_company;

    IF v_has_company THEN
        SELECT udt_name INTO v_col_type FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'treasuries' AND column_name = 'company_id';
        SELECT id::text INTO v_first_company_id FROM public.sys_companies WHERE deleted_at IS NULL ORDER BY created_at ASC LIMIT 1;
    END IF;

    -- 1. الخزينة الرئيسية (نضمن وجود خزينة رئيسية واحدة معتمدة للنظام مع معالجة التكرار)
    IF v_first_company_id IS NOT NULL THEN
        IF v_col_type = 'uuid' THEN
            EXECUTE 'INSERT INTO public.treasuries (name, type, notes, is_active, approval_status, company_id)
                     VALUES (''الخزينة الرئيسية'', ''main'', ''الخزينة الافتراضية للنظام'', true, ''approved'', ' || quote_literal(v_first_company_id) || '::uuid)
                     ON CONFLICT (name) DO UPDATE SET
                        type = ''main'',
                        is_active = true,
                        approval_status = ''approved'',
                        company_id = COALESCE(public.treasuries.company_id, EXCLUDED.company_id)';
        ELSE
            EXECUTE 'INSERT INTO public.treasuries (name, type, notes, is_active, approval_status, company_id)
                     VALUES (''الخزينة الرئيسية'', ''main'', ''الخزينة الافتراضية للنظام'', true, ''approved'', ' || quote_literal(v_first_company_id) || ')
                     ON CONFLICT (name) DO UPDATE SET
                        type = ''main'',
                        is_active = true,
                        approval_status = ''approved'',
                        company_id = COALESCE(public.treasuries.company_id, EXCLUDED.company_id)';
        END IF;
    ELSE
        INSERT INTO public.treasuries (name, type, notes, is_active, approval_status)
        VALUES ('الخزينة الرئيسية', 'main', 'الخزينة الافتراضية للنظام', true, 'approved')
        ON CONFLICT (name) DO UPDATE SET
            type = 'main',
            is_active = true,
            approval_status = 'approved';
    END IF;

    -- تحديث حالة الخزينة الرئيسية لتكون نشطة ومعتمدة دائماً
    UPDATE public.treasuries
    SET is_active = true, approval_status = 'approved', type = 'main'
    WHERE name = 'الخزينة الرئيسية' OR type = 'main';

    -- 2. ربط أرصدة الخزينة بالـ 4 عملات (EGP, USD, EUR, GBP) وحسابات GL
    FOR v_tid IN (SELECT id FROM public.treasuries WHERE type = 'main' OR name = 'الخزينة الرئيسية')
    LOOP
        FOR v_curr, v_acode, v_rate IN 
            SELECT * FROM (VALUES 
                ('EGP', '12211', 1.000000), 
                ('USD', '12212', 50.000000), 
                ('EUR', '12213', 54.000000), 
                ('GBP', '12214', 63.000000)
            ) AS v(c, a, r)
        LOOP
            -- البحث عن حساب الأستاذ العام (أولاً 12211..12214 ثم 12121..12124 ثم 11101..11104)
            SELECT id INTO v_aid FROM public.accounts WHERE account_code = v_acode AND is_active = true LIMIT 1;
            IF v_aid IS NULL THEN
                SELECT id INTO v_aid FROM public.accounts WHERE account_code = CASE v_curr WHEN 'EGP' THEN '12121' WHEN 'USD' THEN '12122' WHEN 'EUR' THEN '12123' WHEN 'GBP' THEN '12124' END AND is_active = true LIMIT 1;
            END IF;
            IF v_aid IS NULL THEN
                SELECT id INTO v_aid FROM public.accounts WHERE account_code = CASE v_curr WHEN 'EGP' THEN '11101' WHEN 'USD' THEN '11102' WHEN 'EUR' THEN '11103' WHEN 'GBP' THEN '11104' END AND is_active = true LIMIT 1;
            END IF;

            -- إذا لم يوجد، نربطه بأي حساب خزينة للأصل
            IF v_aid IS NULL THEN
                SELECT id INTO v_aid FROM public.accounts WHERE (account_name ILIKE '%خزينة%' OR name ILIKE '%treasury%') AND is_active = true LIMIT 1;
            END IF;

            -- غرس / تحديث رصيد العملة في treasury_balances دون أي شروط معطلة
            INSERT INTO public.treasury_balances (treasury_id, currency, balance, cost_base, book_rate, account_id)
            VALUES (v_tid, v_curr, 0.00, 0.00, v_rate, v_aid)
            ON CONFLICT (treasury_id, currency) DO UPDATE SET
                account_id = COALESCE(EXCLUDED.account_id, public.treasury_balances.account_id),
                book_rate = EXCLUDED.book_rate,
                updated_at = now();
        END LOOP;
    END LOOP;

    -- 2.1 ترقية حساب الإدارة الرئيسي المتبقي وتفعيل الصلاحيات الإدارية الكاملة
    UPDATE public.users SET is_admin = true;
    
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'user_roles') THEN
        UPDATE public.user_roles 
        SET allowed_pages = '["/owner-safe", "/accounts", "/treasury", "/general-ledger", "/reports", "/suppliers", "/customers", "/shipments"]'::jsonb,
            role = 'owner',
            can_manage_users = true;

        -- ضمان وجود دور المالك لحساب الإدارة في جدول user_roles دون الحاجة لقيد فريد
        INSERT INTO public.user_roles (user_id, role, allowed_pages, can_manage_users)
        SELECT u.id, 'owner', '["/owner-safe", "/accounts", "/treasury", "/general-ledger", "/reports", "/suppliers", "/customers", "/shipments"]'::jsonb, true
        FROM public.users u
        WHERE NOT EXISTS (
            SELECT 1 FROM public.user_roles ur WHERE ur.user_id = u.id
        );
    END IF;

    -- 3. الحسابات البنكية الأربعة (INSERT مرة واحدة فقط)
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'bank_accounts') THEN
        IF v_first_company_id IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'bank_accounts' AND column_name = 'company_id') THEN
            IF v_col_type = 'uuid' THEN
                EXECUTE 'INSERT INTO public.bank_accounts (name, name_en, currency, balance, cost_base, book_rate, company_id)
                         SELECT v.name, v.name_en, v.currency, 0.00, 0.00, 1.00, ' || quote_literal(v_first_company_id) || '::uuid
                         FROM (VALUES
                           (''الجنيه المصري'',       ''Egyptian Pound'',  ''EGP''),
                           (''الدولار الأمريكي'',     ''US Dollar'',       ''USD''),
                           (''اليورو'',               ''Euro'',            ''EUR''),
                           (''الجنيه الإسترليني'',    ''British Pound'',   ''GBP'')
                         ) AS v(name, name_en, currency)
                         WHERE NOT EXISTS (SELECT 1 FROM public.bank_accounts ba WHERE ba.currency = v.currency)';
            ELSE
                EXECUTE 'INSERT INTO public.bank_accounts (name, name_en, currency, balance, cost_base, book_rate, company_id)
                         SELECT v.name, v.name_en, v.currency, 0.00, 0.00, 1.00, ' || quote_literal(v_first_company_id) || '
                         FROM (VALUES
                           (''الجنيه المصري'',       ''Egyptian Pound'',  ''EGP''),
                           (''الدولار الأمريكي'',     ''US Dollar'',       ''USD''),
                           (''اليورو'',               ''Euro'',            ''EUR''),
                           (''الجنيه الإسترليني'',    ''British Pound'',   ''GBP'')
                         ) AS v(name, name_en, currency)
                         WHERE NOT EXISTS (SELECT 1 FROM public.bank_accounts ba WHERE ba.currency = v.currency)';
            END IF;
        ELSE
            INSERT INTO public.bank_accounts (name, name_en, currency, balance, cost_base, book_rate)
            SELECT v.name, v.name_en, v.currency, 0.00, 0.00, 1.00
            FROM (VALUES
              ('الجنيه المصري',       'Egyptian Pound',  'EGP'),
              ('الدولار الأمريكي',     'US Dollar',       'USD'),
              ('اليورو',               'Euro',            'EUR'),
              ('الجنيه الإسترليني',    'British Pound',   'GBP')
            ) AS v(name, name_en, currency)
            WHERE NOT EXISTS (SELECT 1 FROM public.bank_accounts ba WHERE ba.currency = v.currency);
        END IF;

        -- تصفير الأرصدة
        UPDATE public.bank_accounts SET balance = 0, cost_base = 0, book_rate = 1.0;

        -- ربط الحسابات البنكية بدليل الحسابات
        UPDATE public.bank_accounts ba
        SET account_id = (
            SELECT a.id FROM public.accounts a 
            WHERE a.account_code = CASE ba.currency 
                WHEN 'EGP' THEN '12111' 
                WHEN 'USD' THEN '12112' 
                WHEN 'EUR' THEN '12113' 
                WHEN 'GBP' THEN '12114' 
                ELSE '12111'
            END 
            LIMIT 1
        )
        WHERE ba.account_id IS NULL;
    END IF;

    -- 4. المستودعات (INSERT مرة واحدة فقط)
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'warehouses') THEN
        IF v_first_company_id IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'warehouses' AND column_name = 'company_id') THEN
            IF v_col_type = 'uuid' THEN
                EXECUTE 'INSERT INTO public.warehouses (name, name_en, address, city, country, is_active, company_id)
                         SELECT v.name, v.name_en, v.address, v.city, v.country, true, ' || quote_literal(v_first_company_id) || '::uuid
                         FROM (VALUES
                           (''المستودع الرئيسي'',  ''Main Warehouse'',  ''المنطقة الصناعية'', ''القاهرة'',    ''Egypt''),
                           (''مستودع التصدير'',     ''Export Warehouse'', ''ميناء الإسكندرية'', ''الإسكندرية'', ''Egypt''),
                           (''مستودع التجميد'',     ''Cold Storage'',     ''المنطقة الصناعية'', ''القاهرة'',    ''Egypt'')
                         ) AS v(name, name_en, address, city, country)
                         WHERE NOT EXISTS (SELECT 1 FROM public.warehouses w WHERE w.name = v.name)';
            ELSE
                EXECUTE 'INSERT INTO public.warehouses (name, name_en, address, city, country, is_active, company_id)
                         SELECT v.name, v.name_en, v.address, v.city, v.country, true, ' || quote_literal(v_first_company_id) || '
                         FROM (VALUES
                           (''المستودع الرئيسي'',  ''Main Warehouse'',  ''المنطقة الصناعية'', ''القاهرة'',    ''Egypt''),
                           (''مستودع التصدير'',     ''Export Warehouse'', ''ميناء الإسكندرية'', ''الإسكندرية'', ''Egypt''),
                           (''مستودع التجميد'',     ''Cold Storage'',     ''المنطقة الصناعية'', ''القاهرة'',    ''Egypt'')
                         ) AS v(name, name_en, address, city, country)
                         WHERE NOT EXISTS (SELECT 1 FROM public.warehouses w WHERE w.name = v.name)';
            END IF;
        ELSE
            INSERT INTO public.warehouses (name, name_en, address, city, country, is_active)
            SELECT v.name, v.name_en, v.address, v.city, v.country, true
            FROM (VALUES
              ('المستودع الرئيسي',  'Main Warehouse',  'المنطقة الصناعية', 'القاهرة',    'Egypt'),
              ('مستودع التصدير',     'Export Warehouse', 'ميناء الإسكندرية', 'الإسكندرية', 'Egypt'),
              ('مستودع التجميد',     'Cold Storage',     'المنطقة الصناعية', 'القاهرة',    'Egypt')
            ) AS v(name, name_en, address, city, country)
            WHERE NOT EXISTS (SELECT 1 FROM public.warehouses w WHERE w.name = v.name);
        END IF;
    END IF;
END $$;

-- ── 1. دالة التخصيص التلقائي لحساب العهدة في شجرة الحسابات (Level 5 Posting Account) ──
CREATE OR REPLACE FUNCTION public.ensure_custody_account(
    p_treasury_id BIGINT,
    p_company_id UUID DEFAULT NULL
) RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_treasury_record RECORD;
    v_company_id UUID := p_company_id;
    v_user_full_name TEXT;
    v_raw_name TEXT;
    v_clean_name TEXT;
    v_arabic_name TEXT;
    v_english_name TEXT;
    v_parent_code TEXT := '12612';
    v_parent_id BIGINT;
    v_existing_acct_id BIGINT;
    v_new_code TEXT;
    v_new_acct_id BIGINT;
    v_currency TEXT;
BEGIN
    -- 1. Fetch treasury info
    SELECT id, name, type, employee_id, user_id, notes, company_id, account_id
    INTO v_treasury_record
    FROM public.treasuries
    WHERE id = p_treasury_id;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    -- Determine company
    IF v_company_id IS NULL THEN
        v_company_id := v_treasury_record.company_id;
    END IF;
    IF v_company_id IS NULL THEN
        SELECT id INTO v_company_id FROM public.sys_companies WHERE deleted_at IS NULL ORDER BY created_at ASC LIMIT 1;
    END IF;

    -- Determine parent code: 12613 for permanent custody, 12612 for temporary custody
    IF (COALESCE(v_treasury_record.notes, '') ILIKE '%مستديم%' 
        OR COALESCE(v_treasury_record.name, '') ILIKE '%مستديم%' 
        OR COALESCE(v_treasury_record.notes, '') ILIKE '%permanent%') THEN
        v_parent_code := '12613';
    ELSE
        v_parent_code := '12612';
    END IF;

    -- 2. Resolve employee name
    IF v_treasury_record.employee_id IS NOT NULL THEN
        SELECT full_name INTO v_user_full_name FROM public.users WHERE id = v_treasury_record.employee_id;
    END IF;
    IF (v_user_full_name IS NULL OR TRIM(v_user_full_name) = '') AND v_treasury_record.user_id IS NOT NULL THEN
        SELECT full_name INTO v_user_full_name FROM public.users WHERE id = v_treasury_record.user_id;
    END IF;

    v_raw_name := COALESCE(NULLIF(TRIM(v_user_full_name), ''), NULLIF(TRIM(v_treasury_record.name), ''), 'موظف');

    -- Clean up prefix words (خزنة, خزنه, عهدة, عهده, خزينة, خزينه)
    v_clean_name := regexp_replace(v_raw_name, '^(خزنة|خزنه|خزينة|خزينه|عهدة|عهده)\s*[-:]*\s*', '', 'i');
    v_clean_name := TRIM(COALESCE(NULLIF(v_clean_name, ''), v_raw_name));

    v_arabic_name := 'عهدة - ' || v_clean_name;
    v_english_name := 'Custody - ' || v_clean_name;

    -- 3. Check parent account in Chart of Accounts (12612 or 12613)
    SELECT id INTO v_parent_id
    FROM public.accounts
    WHERE (account_code = v_parent_code OR code = v_parent_code)
    ORDER BY (company_id = v_company_id) DESC, id ASC
    LIMIT 1;

    -- If parent doesn't exist, create it under 1261
    IF v_parent_id IS NULL THEN
        DECLARE
            v_grandparent_id BIGINT;
        BEGIN
            SELECT id INTO v_grandparent_id
            FROM public.accounts
            WHERE (account_code = '1261' OR code = '1261')
            ORDER BY (company_id = v_company_id) DESC, id ASC
            LIMIT 1;

            INSERT INTO public.accounts (
                account_code, name, account_name, account_type,
                company_id, parent_id, level, is_leaf, allow_posting, is_system, is_active, sort_order
            ) VALUES (
                v_parent_code,
                CASE v_parent_code WHEN '12613' THEN 'Permanent Cash Custody' ELSE 'Temporary Cash Custody' END,
                CASE v_parent_code WHEN '12613' THEN 'عهد نقديه مستديمه' ELSE 'عهد نقديه مؤقته' END,
                'asset', v_company_id, v_grandparent_id, 4, false, false, true, true, v_parent_code::INTEGER
            )
            RETURNING id INTO v_parent_id;
        END;
    ELSE
        -- Ensure parent is configured as a non-leaf category folder
        UPDATE public.accounts
        SET is_leaf = false, allow_posting = false
        WHERE id = v_parent_id AND (is_leaf = true OR allow_posting = true);
    END IF;

    -- 4. Check if treasury already has a valid Level-5 custody account
    IF v_treasury_record.account_id IS NOT NULL THEN
        SELECT id INTO v_existing_acct_id
        FROM public.accounts
        WHERE id = v_treasury_record.account_id
          AND account_code ~ ('^' || v_parent_code || '[0-9]+$')
          AND is_active = true;
    END IF;

    -- Check by name match if not found
    IF v_existing_acct_id IS NULL THEN
        SELECT id INTO v_existing_acct_id
        FROM public.accounts
        WHERE (account_name = v_arabic_name 
            OR name = v_english_name 
            OR account_name = 'عهدة ' || v_clean_name
            OR account_name = v_raw_name)
          AND account_code ~ ('^' || v_parent_code || '[0-9]+$')
          AND is_active = true
        ORDER BY (company_id = v_company_id) DESC, id ASC
        LIMIT 1;
    END IF;

    -- 5. If existing Level-5 account found, link and return
    IF v_existing_acct_id IS NOT NULL THEN
        UPDATE public.treasuries 
        SET account_id = v_existing_acct_id 
        WHERE id = p_treasury_id AND (account_id IS NULL OR account_id != v_existing_acct_id);

        UPDATE public.treasury_balances 
        SET account_id = v_existing_acct_id 
        WHERE treasury_id = p_treasury_id AND (account_id IS NULL OR account_id != v_existing_acct_id);

        RETURN v_existing_acct_id;
    END IF;

    -- 6. Generate next unique Level-5 account code
    v_new_code := public.get_next_entity_account_code(
        CASE v_parent_code WHEN '12613' THEN 'permanent_custody' ELSE 'custody' END,
        v_company_id
    );

    -- 7. Provision the dedicated Level-5 account (code is a generated column in accounts)
    INSERT INTO public.accounts (
        account_code,
        name,
        account_name,
        account_type,
        company_id,
        parent_id,
        level,
        is_leaf,
        allow_posting,
        is_system,
        is_active,
        sort_order
    ) VALUES (
        v_new_code,
        v_english_name,
        v_arabic_name,
        'asset',
        v_company_id,
        v_parent_id,
        5,
        true,
        true,
        false,
        true,
        v_new_code::BIGINT
    )
    RETURNING id INTO v_new_acct_id;

    -- 8. Bind to treasury and its balances
    UPDATE public.treasuries 
    SET account_id = v_new_acct_id 
    WHERE id = p_treasury_id;

    FOREACH v_currency IN ARRAY ARRAY['EGP', 'USD', 'EUR', 'GBP']
    LOOP
        INSERT INTO public.treasury_balances (treasury_id, currency, balance, account_id)
        VALUES (p_treasury_id, v_currency, 0, v_new_acct_id)
        ON CONFLICT (treasury_id, currency) DO UPDATE
        SET account_id = v_new_acct_id;
    END LOOP;

    RETURN v_new_acct_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.ensure_custody_account(BIGINT, UUID) TO authenticated, anon, service_role;

-- تريجر تلقائي لإنشاء حساب العهدة في شجرة الحسابات عند إضافة أو تعديل خزنة موظف
CREATE OR REPLACE FUNCTION public.trg_fn_ensure_custody_account()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    IF (NEW.type = 'employee' OR NEW.type = 'custody') THEN
        PERFORM public.ensure_custody_account(NEW.id, NEW.company_id);
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_ensure_custody_account ON public.treasuries;
CREATE TRIGGER trg_ensure_custody_account
AFTER INSERT OR UPDATE OF type, name, employee_id
ON public.treasuries
FOR EACH ROW
EXECUTE FUNCTION public.trg_fn_ensure_custody_account();

-- ── 2. دالة مركزية لحل حسابات الخزينة في الأستاذ العام لكافة العمليات ──
CREATE OR REPLACE FUNCTION public.resolve_treasury_account(
    p_treasury_id BIGINT,
    p_currency TEXT,
    p_company_id UUID DEFAULT NULL
) RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_account_id BIGINT;
    v_code TEXT;
    v_real_company_id UUID;
    v_treasury_type TEXT;
    v_treasury_name TEXT;
    v_user_id UUID;
BEGIN
    -- Resolve company_id if NULL
    v_real_company_id := p_company_id;
    IF v_real_company_id IS NULL THEN
        SELECT company_id INTO v_real_company_id FROM public.treasuries WHERE id = p_treasury_id;
    END IF;
    IF v_real_company_id IS NULL THEN
        SELECT id INTO v_real_company_id FROM public.sys_companies WHERE deleted_at IS NULL ORDER BY created_at ASC LIMIT 1;
    END IF;

    -- Get treasury info
    SELECT type, name, account_id, user_id INTO v_treasury_type, v_treasury_name, v_account_id, v_user_id
    FROM public.treasuries WHERE id = p_treasury_id;

    -- 1) If this is an Employee Custody treasury (type = 'employee' or 'custody'):
    -- Must ALWAYS use a dedicated Level-5 account under 12612 / 12613
    IF v_treasury_type = 'employee' OR v_treasury_type = 'custody' THEN
        -- If already linked to a dedicated Level-5 account under 12612 or 12613, return it
        IF v_account_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM public.accounts a
            WHERE a.id = v_account_id 
              AND a.account_code ~ '^1261[23][0-9]+$' 
              AND a.is_leaf = true 
              AND a.is_active = true
        ) THEN
            RETURN v_account_id;
        END IF;

        -- Otherwise, dynamically ensure and link the dedicated Level-5 account
        v_account_id := public.ensure_custody_account(p_treasury_id, v_real_company_id);
        IF v_account_id IS NOT NULL THEN
            RETURN v_account_id;
        END IF;
    END IF;

    -- 2) For main treasuries: if explicit account_id set and active
    IF v_account_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.accounts WHERE id = v_account_id AND is_active = true) THEN
        RETURN v_account_id;
    END IF;

    -- 3) Try treasury_balances.account_id
    SELECT tb.account_id INTO v_account_id
    FROM public.treasury_balances tb
    WHERE tb.treasury_id = p_treasury_id AND tb.currency = p_currency AND tb.account_id IS NOT NULL
      AND EXISTS (SELECT 1 FROM public.accounts a WHERE a.id = tb.account_id AND a.is_active = true)
    LIMIT 1;
    IF v_account_id IS NOT NULL THEN
        RETURN v_account_id;
    END IF;

    -- 4) Main Treasury currency-based GL accounts (Primary: 12211..12214, Fallback: 12121..12124)
    v_code := CASE p_currency
        WHEN 'EGP' THEN '12211'
        WHEN 'USD' THEN '12212'
        WHEN 'EUR' THEN '12213'
        WHEN 'GBP' THEN '12214'
        ELSE '12211'
    END;
    
    SELECT id INTO v_account_id FROM public.accounts WHERE (account_code = v_code OR code = v_code) AND is_active = true ORDER BY (company_id = v_real_company_id) DESC, id ASC LIMIT 1;
    IF v_account_id IS NOT NULL THEN
        UPDATE public.treasuries SET account_id = v_account_id WHERE id = p_treasury_id AND account_id IS NULL;
        UPDATE public.treasury_balances SET account_id = v_account_id WHERE treasury_id = p_treasury_id AND currency = p_currency AND (account_id IS NULL OR account_id != v_account_id);
        RETURN v_account_id;
    END IF;

    v_code := CASE p_currency
        WHEN 'EGP' THEN '12121'
        WHEN 'USD' THEN '12122'
        WHEN 'EUR' THEN '12123'
        WHEN 'GBP' THEN '12124'
        ELSE '12121'
    END;
    
    SELECT id INTO v_account_id FROM public.accounts WHERE (account_code = v_code OR code = v_code) AND is_active = true LIMIT 1;
    IF v_account_id IS NOT NULL THEN
        RETURN v_account_id;
    END IF;

    v_code := CASE p_currency
        WHEN 'EGP' THEN '11101'
        WHEN 'USD' THEN '11102'
        WHEN 'EUR' THEN '11103'
        WHEN 'GBP' THEN '11104'
        ELSE '11101'
    END;

    SELECT id INTO v_account_id FROM public.accounts WHERE (account_code = v_code OR code = v_code) AND is_active = true LIMIT 1;
    IF v_account_id IS NOT NULL THEN
        RETURN v_account_id;
    END IF;

    -- 5) Fallback to any 1212% or 111% or asset account
    SELECT id INTO v_account_id
    FROM public.accounts
    WHERE (account_code LIKE '1212%' OR account_code LIKE '111%' OR code LIKE '1212%' OR code LIKE '111%') AND is_active = true
    ORDER BY (company_id = v_real_company_id) DESC, account_code LIMIT 1;

    IF v_account_id IS NOT NULL THEN
        RETURN v_account_id;
    END IF;

    SELECT id INTO v_account_id
    FROM public.accounts
    WHERE account_type = 'asset' AND is_leaf = true AND is_active = true
    ORDER BY (company_id = v_real_company_id) DESC, account_code LIMIT 1;

    IF v_account_id IS NOT NULL THEN
        RETURN v_account_id;
    END IF;

    RAISE EXCEPTION 'Could not resolve any treasury GL account for treasury % currency %', p_treasury_id, p_currency;
END;
$$;

GRANT EXECUTE ON FUNCTION public.resolve_treasury_account(BIGINT, TEXT, UUID) TO authenticated, anon, service_role;

-- ── 3. دالة إنشاء الخزائن / العهد (create_treasury) ──────────────────────────
DROP FUNCTION IF EXISTS public.create_treasury(text, text, uuid, text);
DROP FUNCTION IF EXISTS public.create_treasury(text, text, uuid, text, uuid);

CREATE OR REPLACE FUNCTION public.create_treasury(
    p_name TEXT,
    p_type TEXT,
    p_employee_id UUID DEFAULT NULL,
    p_notes TEXT DEFAULT NULL,
    p_company_id UUID DEFAULT NULL
) RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_new_id BIGINT;
    v_account_id BIGINT;
    v_currency TEXT;
    v_company_id UUID := p_company_id;
BEGIN
    IF v_company_id IS NULL THEN
        SELECT id INTO v_company_id FROM sys_companies WHERE deleted_at IS NULL ORDER BY created_at ASC LIMIT 1;
    END IF;

    INSERT INTO public.treasuries (name, type, employee_id, user_id, notes, company_id, approval_status, is_active)
    VALUES (p_name, p_type, p_employee_id, p_employee_id, p_notes, v_company_id, 'approved', true)
    RETURNING id INTO v_new_id;

    IF p_type = 'main' THEN
        FOREACH v_currency IN ARRAY ARRAY['EGP','USD','EUR','GBP']
        LOOP
            SELECT id INTO v_account_id FROM accounts 
            WHERE (account_code = CASE v_currency
                WHEN 'EGP' THEN '12211'
                WHEN 'USD' THEN '12212'
                WHEN 'EUR' THEN '12213'
                WHEN 'GBP' THEN '12214'
            END OR code = CASE v_currency
                WHEN 'EGP' THEN '12211'
                WHEN 'USD' THEN '12212'
                WHEN 'EUR' THEN '12213'
                WHEN 'GBP' THEN '12214'
            END)
            AND deleted_at IS NULL
            LIMIT 1;

            INSERT INTO treasury_balances (treasury_id, currency, balance, account_id)
            VALUES (v_new_id, v_currency, 0, v_account_id)
            ON CONFLICT (treasury_id, currency) DO UPDATE
            SET account_id = COALESCE(EXCLUDED.account_id, treasury_balances.account_id);
        END LOOP;
    ELSE
        -- Employee Custody Treasury -> Automatically provision dedicated Level-5 account
        v_account_id := public.ensure_custody_account(v_new_id, v_company_id);

        FOREACH v_currency IN ARRAY ARRAY['EGP','USD','EUR','GBP']
        LOOP
            INSERT INTO treasury_balances (treasury_id, currency, balance, account_id)
            VALUES (v_new_id, v_currency, 0, v_account_id)
            ON CONFLICT (treasury_id, currency) DO UPDATE
            SET account_id = COALESCE(EXCLUDED.account_id, treasury_balances.account_id);
        END LOOP;
    END IF;

    RETURN v_new_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_treasury(TEXT, TEXT, UUID, TEXT, UUID) TO authenticated, anon, service_role;

