-- 1. العملات (Currencies)
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'currencies') THEN
        DELETE FROM public.currencies WHERE code IN ('SAR', 'AED');
        
        IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'currencies' AND column_name = 'name_en') THEN
            INSERT INTO public.currencies (code, name, name_en, symbol, is_default, is_active)
            SELECT v.code, v.name, v.name_en, v.symbol, v.is_default, v.is_active
            FROM (VALUES
              ('EGP', 'جنيه مصري',      'Egyptian Pound',  'ج.م',  true,  true),
              ('USD', 'دولار أمريكي',    'US Dollar',       '$',    false, true),
              ('EUR', 'يورو',           'Euro',            '€',    false, true),
              ('GBP', 'جنيه إسترليني',  'British Pound',   '£',    false, true)
            ) AS v(code, name, name_en, symbol, is_default, is_active)
            ON CONFLICT (code) DO UPDATE SET
                name = EXCLUDED.name,
                name_en = EXCLUDED.name_en,
                symbol = EXCLUDED.symbol,
                is_active = true;
        ELSIF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'currencies' AND column_name = 'name_ar') THEN
            INSERT INTO public.currencies (code, name, name_ar, symbol, is_base, is_active)
            SELECT v.code, v.name, v.name_ar, v.symbol, v.is_base, v.is_active
            FROM (VALUES
              ('EGP', 'Egyptian Pound',  'جنيه مصري',      'ج.م',  true,  true),
              ('USD', 'US Dollar',       'دولار أمريكي',    '$',    false, true),
              ('EUR', 'Euro',            'يورو',           '€',    false, true),
              ('GBP', 'British Pound',   'جنيه إسترليني',  '£',    false, true)
            ) AS v(code, name, name_ar, symbol, is_base, is_active)
            ON CONFLICT (code) DO UPDATE SET
                name = EXCLUDED.name,
                name_ar = EXCLUDED.name_ar,
                symbol = EXCLUDED.symbol,
                is_active = true;
        ELSE
            INSERT INTO public.currencies (code, name, symbol, is_active)
            SELECT v.code, v.name, v.symbol, true
            FROM (VALUES
              ('EGP', 'جنيه مصري',      'ج.م'),
              ('USD', 'دولار أمريكي',    '$'),
              ('EUR', 'يورو',           '€'),
              ('GBP', 'جنيه إسترليني',  '£')
            ) AS v(code, name, symbol)
            ON CONFLICT (code) DO UPDATE SET
                name = EXCLUDED.name,
                symbol = EXCLUDED.symbol,
                is_active = true;
        END IF;
    END IF;
END $$;

-- 2. أسعار الصرف (Exchange Rates & fn_get_exchange_rate)
CREATE TABLE IF NOT EXISTS public.exchange_rates (
    id BIGSERIAL PRIMARY KEY,
    currency_code VARCHAR(10) NOT NULL UNIQUE,
    currency_name VARCHAR(50) NOT NULL,
    name_ar VARCHAR(100) DEFAULT '',
    rate_to_egp NUMERIC(14,4) NOT NULL,
    sort_order INT DEFAULT 0,
    source TEXT DEFAULT 'system',
    effective_from TIMESTAMPTZ DEFAULT NOW(),
    effective_to TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE public.exchange_rates ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS exchange_rates_select_all ON public.exchange_rates;
CREATE POLICY exchange_rates_select_all ON public.exchange_rates FOR SELECT USING (true);
DROP POLICY IF EXISTS exchange_rates_all_auth ON public.exchange_rates;
CREATE POLICY exchange_rates_all_auth ON public.exchange_rates FOR ALL TO authenticated USING (true) WITH CHECK (true);

INSERT INTO public.exchange_rates (currency_code, currency_name, name_ar, rate_to_egp, sort_order, updated_at)
VALUES 
    ('USD', 'US Dollar',       'الدولار الأمريكي',   50.00, 1, NOW()),
    ('EUR', 'Euro',            'اليورو الأوروبي',    55.00, 2, NOW()),
    ('GBP', 'British Pound',   'الجنيه الاسترليني',  65.00, 3, NOW())
ON CONFLICT (currency_code) DO UPDATE SET 
    rate_to_egp = EXCLUDED.rate_to_egp,
    name_ar = EXCLUDED.name_ar,
    updated_at = NOW();

CREATE OR REPLACE FUNCTION public.fn_get_exchange_rate(p_currency TEXT)
RETURNS NUMERIC
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_rate NUMERIC;
BEGIN
    IF p_currency IS NULL OR UPPER(TRIM(p_currency)) IN ('EGP', '') THEN
        RETURN 1.0;
    END IF;

    BEGIN
        SELECT rate_to_egp INTO v_rate
        FROM public.exchange_rates
        WHERE UPPER(currency_code) = UPPER(TRIM(p_currency))
        ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST
        LIMIT 1;
    EXCEPTION WHEN OTHERS THEN
        v_rate := NULL;
    END;

    IF v_rate IS NOT NULL AND v_rate > 0 THEN
        RETURN v_rate;
    END IF;

    CASE UPPER(TRIM(p_currency))
        WHEN 'USD' THEN RETURN 50.0;
        WHEN 'EUR' THEN RETURN 55.0;
        WHEN 'GBP' THEN RETURN 65.0;
        WHEN 'SAR' THEN RETURN 13.3;
        WHEN 'AED' THEN RETURN 13.6;
        ELSE RETURN 1.0;
    END CASE;
END;
$$;

GRANT EXECUTE ON FUNCTION public.fn_get_exchange_rate(TEXT) TO authenticated, service_role, anon;


