-- ============================================================================
-- المرحلة 8: تثبيت دوال وتريجرز توليد الحسابات التلقائية للكيانات
-- ============================================================================

-- تنظيف وحذف الدوال القديمة بكافة توقيعاتها منعاً لخطأ 42P13
DROP FUNCTION IF EXISTS public.get_next_entity_account_code(TEXT, UUID) CASCADE;
DROP FUNCTION IF EXISTS public.get_next_entity_account_code(TEXT, TEXT) CASCADE;
DROP FUNCTION IF EXISTS public.get_next_entity_account_code(TEXT) CASCADE;
DROP FUNCTION IF EXISTS public.generate_next_customer_code() CASCADE;
DROP FUNCTION IF EXISTS public.create_customer_account() CASCADE;
DROP FUNCTION IF EXISTS public.create_supplier_account() CASCADE;
DROP FUNCTION IF EXISTS public.create_shipping_company_account() CASCADE;
DROP FUNCTION IF EXISTS public.create_clearing_agent_account() CASCADE;
DROP FUNCTION IF EXISTS public.create_shareholder_account() CASCADE;
DROP FUNCTION IF EXISTS public.sync_entity_name_to_account() CASCADE;
DROP FUNCTION IF EXISTS public.delete_entity_linked_account() CASCADE;

-- 1. دالة توليد كود العميل التلقائي
CREATE OR REPLACE FUNCTION public.generate_next_customer_code()
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    next_id int;
BEGIN
    SELECT COALESCE(MAX(
        CASE 
            WHEN code ~ '^[0-9]+$' THEN code::int
            WHEN code ~ '^CUST-[0-9]+$' THEN regexp_replace(code, '^CUST-', '')::int
            ELSE 0 
        END
    ), 0) + 1 INTO next_id FROM public.customers;
    RETURN LPAD(next_id::text, 4, '0');
END;
$$;

-- 2. دالة توليد كود الحساب الفرعي الموحد (متوافقة مع multi-tenant)
CREATE OR REPLACE FUNCTION public.get_next_entity_account_code(
  p_entity_type TEXT,
  p_company_id UUID DEFAULT NULL
) RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_pattern TEXT;
  v_start   INTEGER;
  v_next    INTEGER;
  v_code    TEXT;
BEGIN
  CASE p_entity_type
    WHEN 'customer'                                  THEN v_pattern := '^1251[0-9]+$'; v_start := 125100;
    WHEN 'supplier', 'crop_supplier', 'crop',
         'shipping_company', 'clearing_agent',
         'packaging_supplier', 'packaging', 'station',
         'shared_supplier', 'shared',
         'transport_supplier', 'transport'           THEN v_pattern := '^2111[0-9]+$'; v_start := 211100;
    WHEN 'notes_payable', 'note_payable'             THEN v_pattern := '^2112[0-9]+$'; v_start := 211200;
    WHEN 'shareholder'                               THEN v_pattern := '^2321[0-9]+$'; v_start := 232100;
    WHEN 'custody', 'employee_custody', 'temporary_custody' THEN v_pattern := '^12612[0-9]+$'; v_start := 1261200;
    WHEN 'permanent_custody'                         THEN v_pattern := '^12613[0-9]+$'; v_start := 1261300;
    ELSE RAISE EXCEPTION 'Unknown entity type: %', p_entity_type;
  END CASE;

  -- البحث عن أعلى كود حساب حالي لهذا النمط عبر كل الشركات
  LOOP
    SELECT COALESCE(MAX(account_code::bigint), v_start) + 1 INTO v_next
    FROM public.accounts
    WHERE account_code ~ v_pattern;

    IF v_next <= v_start THEN
      v_next := v_start + 1;
    END IF;

    v_code := v_next::TEXT;

    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.accounts WHERE account_code = v_code
    );

    v_start := v_next;
  END LOOP;

  RETURN v_code;
END;
$$;

-- Overload للدوال القديمة التي قد تمرر p_company_id كنص
CREATE OR REPLACE FUNCTION public.get_next_entity_account_code(
  p_entity_type TEXT,
  p_company_id TEXT
) RETURNS TEXT
LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN public.get_next_entity_account_code(p_entity_type, p_company_id::UUID);
END;
$$;

-- 3. تريجر ربط حساب العميل تلقائياً بالحسابات الماستر الموحدة (12511 للتصدير / 12512 للمحلي)
CREATE OR REPLACE FUNCTION public.create_customer_account()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_target_account_code TEXT;
  v_target_account_id   BIGINT;
  v_raw_type            TEXT;
BEGIN
  -- 1) إذا كان العميل مرتبطاً بحساب مسبقاً لا يتم عمل أي تعديل
  IF NEW.account_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- 2) تحديد نوع العميل (تصدير أو محلي)
  v_raw_type := LOWER(COALESCE(
    NEW.company_type,
    CASE WHEN (to_jsonb(NEW) ? 'customer_type') THEN to_jsonb(NEW)->>'customer_type' ELSE NULL END,
    'export'
  ));

  -- الربط المباشر بالحساب الماستر 12512 للمحلي أو 12511 للتصدير
  IF v_raw_type IN ('local', 'محلي', 'local_customer', 'عملاء محلي') THEN
    v_target_account_code := '12512';
  ELSE
    v_target_account_code := '12511';
  END IF;

  -- 3) البحث عن الحساب الماستر المناسب في الشركة أو الحسابات العامة
  SELECT id INTO v_target_account_id
  FROM public.accounts
  WHERE account_code = v_target_account_code
    AND (company_id = NEW.company_id OR company_id = 'a0000000-0000-0000-0000-000000000001'::uuid OR company_id IS NULL)
  ORDER BY (company_id = NEW.company_id) DESC NULLS LAST
  LIMIT 1;

  IF v_target_account_id IS NULL THEN
    SELECT id INTO v_target_account_id
    FROM public.accounts
    WHERE account_code = v_target_account_code
    LIMIT 1;
  END IF;

  -- احتياطي في حال عدم وجود الحساب الخاص
  IF v_target_account_id IS NULL THEN
    SELECT id INTO v_target_account_id
    FROM public.accounts
    WHERE account_code = '1251'
    LIMIT 1;
  END IF;

  -- 4) تحديث سجل العميل مباشرة بالـ account_id دون إنشاء أي حسابات فرعية عشوائية في شجرة الحسابات
  IF v_target_account_id IS NOT NULL THEN
    UPDATE public.customers
    SET account_id = v_target_account_id
    WHERE id = NEW.id;

    NEW.account_id := v_target_account_id;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_create_customer_account ON public.customers;
CREATE TRIGGER trg_create_customer_account
AFTER INSERT ON public.customers
FOR EACH ROW
EXECUTE FUNCTION public.create_customer_account();

-- 4. تريجر ربط حساب المورد تلقائياً بالحساب الماستر (المستوى الخامس)
CREATE OR REPLACE FUNCTION public.create_supplier_account()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_raw_type TEXT;
  v_target_account_code TEXT;
  v_target_account_id BIGINT;
BEGIN
  IF NEW.account_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  v_raw_type := LOWER(TRIM(COALESCE(NEW.supplier_type, 'crop')));

  -- تحديد كود الحساب الرئيسي المستوى الخامس بناءً على فئة المورد:
  -- موردي النقل والسيارات -> 21111
  -- موردي مواد التعبئة -> 21112
  -- موردي مشتريات محاصيل -> 21113
  -- موردين مشتركين -> 21114
  -- شركات الشحن -> 21115
  -- تحديد كود الحساب الرئيسي المستوى الخامس بناءً على فئة المورد:
  -- 'transport' -> 21111 (موردي النقل والسيارات)
  -- 'packaging' / 'sticker' -> 21112 (موردي مواد التعبئة)
  -- 'crop' -> 21113 (موردي مشتريات محاصيل)
  -- 'shared' -> 21114 (موردين مشتركين)
  -- 'shipping' -> 21115 (شركات الشحن)
  -- 'clearing' -> 21116 (مخلصي الجمارك)
  -- 'station' -> 21117 (موردي المحطات)
  -- 'deduction' -> 21118 (موردي التخصيمات)
  IF v_raw_type IN ('transport', 'transporter', 'مورد نقل', 'نقل', 'سيارات') 
     OR (NEW.code)::text LIKE '6%' THEN
    v_target_account_code := '21111';
  ELSIF v_raw_type IN ('station', 'stations', 'مورد محطة', 'موردي المحطات', 'محطة', 'محطات')
     OR (NEW.code)::text LIKE '85%' OR (NEW.code)::text LIKE '86%' OR (NEW.code)::text LIKE '87%' OR (NEW.code)::text LIKE '88%' OR (NEW.code)::text LIKE '89%' THEN
    v_target_account_code := '21117';
  ELSIF v_raw_type IN ('deduction', 'deductions', 'مورد تخصيم', 'موردي التخصيمات', 'تخصيم', 'تخصيمات')
     OR (NEW.code)::text LIKE '4%' THEN
    v_target_account_code := '21118';
  ELSIF v_raw_type IN ('packaging', 'packing', 'sticker', 'تعبئة', 'مواد تعبئة', 'استيكر')
     OR (NEW.code)::text LIKE '70%' OR (NEW.code)::text LIKE '71%' OR (NEW.code)::text LIKE '72%' OR (NEW.code)::text LIKE '73%' OR (NEW.code)::text LIKE '74%' THEN
    v_target_account_code := '21112';
  ELSIF v_raw_type IN ('shared', 'مشترك', 'مشتركين')
     OR (NEW.code)::text LIKE '75%' OR (NEW.code)::text LIKE '76%' OR (NEW.code)::text LIKE '77%' OR (NEW.code)::text LIKE '78%' OR (NEW.code)::text LIKE '79%' THEN
    v_target_account_code := '21114';
  ELSIF v_raw_type IN ('shipping', 'shipping_company', 'شحن', 'شركات الشحن')
     OR (NEW.code)::text LIKE '9%' THEN
    v_target_account_code := '21115';
  ELSIF v_raw_type IN ('clearing', 'clearance', 'customs', 'جمارك', 'تخليص') THEN
    v_target_account_code := '21116';
  ELSE
    -- الافتراضي: موردي مشتريات محاصيل
    v_target_account_code := '21113';
  END IF;

  SELECT id INTO v_target_account_id
  FROM public.accounts
  WHERE account_code = v_target_account_code
    AND (company_id = NEW.company_id OR company_id = 'a0000000-0000-0000-0000-000000000001'::uuid OR company_id IS NULL)
  ORDER BY (company_id = NEW.company_id) DESC NULLS LAST
  LIMIT 1;

  IF v_target_account_id IS NULL THEN
    SELECT id INTO v_target_account_id
    FROM public.accounts
    WHERE account_code = v_target_account_code
    LIMIT 1;
  END IF;

  IF v_target_account_id IS NULL THEN
    SELECT id INTO v_target_account_id
    FROM public.accounts
    WHERE account_code = '2111'
    LIMIT 1;
  END IF;

  IF v_target_account_id IS NOT NULL THEN
    NEW.account_id := v_target_account_id;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_create_supplier_account ON public.suppliers;
CREATE TRIGGER trg_create_supplier_account
BEFORE INSERT OR UPDATE OF supplier_type, code ON public.suppliers
FOR EACH ROW
EXECUTE FUNCTION public.create_supplier_account();

-- 5. تريجر ربط حساب شركة الشحن تلقائياً بالحساب الماستر 21115
CREATE OR REPLACE FUNCTION public.create_shipping_company_account()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_target_account_id BIGINT;
BEGIN
  IF NEW.account_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_target_account_id
  FROM public.accounts
  WHERE account_code = '21115'
    AND (company_id = NEW.company_id OR company_id = 'a0000000-0000-0000-0000-000000000001'::uuid OR company_id IS NULL)
  ORDER BY (company_id = NEW.company_id) DESC NULLS LAST
  LIMIT 1;

  IF v_target_account_id IS NULL THEN
    SELECT id INTO v_target_account_id
    FROM public.accounts
    WHERE account_code = '21115'
    LIMIT 1;
  END IF;

  IF v_target_account_id IS NULL THEN
    SELECT id INTO v_target_account_id
    FROM public.accounts
    WHERE account_code = '2111'
    LIMIT 1;
  END IF;

  IF v_target_account_id IS NOT NULL THEN
    UPDATE public.shipping_companies
    SET account_id = v_target_account_id
    WHERE id = NEW.id;

    NEW.account_id := v_target_account_id;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_create_shipping_company_account ON public.shipping_companies;
CREATE TRIGGER trg_create_shipping_company_account
AFTER INSERT ON public.shipping_companies
FOR EACH ROW
EXECUTE FUNCTION public.create_shipping_company_account();

