-- 7. تريجر إنشاء حساب المساهم تلقائياً
CREATE OR REPLACE FUNCTION public.create_shareholder_account()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_new_account_id BIGINT;
  v_parent_id BIGINT;
  v_code TEXT;
BEGIN
  IF NEW.account_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- التحقق أولاً إذا كان المساهم يطابق أحد الحسابات المعتمدة الثلاثة (23211, 23212, 23213)
  SELECT id INTO v_new_account_id
  FROM public.accounts
  WHERE (
    (NEW.name LIKE '%عماد%' AND account_code = '23211')
    OR (NEW.name LIKE '%عبدالباطن%' AND account_code = '23212')
    OR ((NEW.name LIKE '%إسلام%' OR NEW.name LIKE '%اسلام%') AND account_code = '23213')
  )
  ORDER BY id ASC
  LIMIT 1;

  IF v_new_account_id IS NOT NULL THEN
    UPDATE public.shareholders
    SET account_id = v_new_account_id
    WHERE id = NEW.id;
    NEW.account_id := v_new_account_id;
    RETURN NEW;
  END IF;

  SELECT id INTO v_parent_id
  FROM public.accounts
  WHERE account_code = '2321' AND (company_id = NEW.company_id OR company_id IS NULL)
  ORDER BY (company_id = NEW.company_id) DESC NULLS LAST
  LIMIT 1;
  IF v_parent_id IS NULL THEN
    SELECT id INTO v_parent_id FROM public.accounts WHERE account_code = '2321' LIMIT 1;
  END IF;
  IF v_parent_id IS NULL THEN
    SELECT id INTO v_parent_id FROM public.accounts WHERE account_code = '232' LIMIT 1;
  END IF;

  v_code := public.get_next_entity_account_code('shareholder', NEW.company_id);

  INSERT INTO public.accounts (
    account_code, name, account_name, account_type, sort_order,
    company_id, parent_id, level, is_leaf, allow_posting, is_system, is_active
  )
  VALUES (
    v_code,
    'Shareholder - ' || COALESCE(NEW.name, ''),
    'مساهم - ' || COALESCE(NEW.name, ''),
    'equity',
    COALESCE(v_code::bigint, 232199),
    NEW.company_id,
    v_parent_id,
    5,
    true,
    true,
    false,
    true
  )
  ON CONFLICT (account_code) DO UPDATE
  SET is_active = true,
      name = EXCLUDED.name,
      account_name = EXCLUDED.account_name,
      parent_id = COALESCE(EXCLUDED.parent_id, public.accounts.parent_id),
      level = COALESCE(EXCLUDED.level, public.accounts.level),
      company_id = COALESCE(EXCLUDED.company_id, public.accounts.company_id)
  RETURNING id INTO v_new_account_id;

  UPDATE public.shareholders
  SET account_id = v_new_account_id
  WHERE id = NEW.id;

  NEW.account_id := v_new_account_id;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_create_shareholder_account ON public.shareholders;
CREATE TRIGGER trg_create_shareholder_account
AFTER INSERT ON public.shareholders
FOR EACH ROW
EXECUTE FUNCTION public.create_shareholder_account();

-- 8. تريجر مزامنة تعديل اسم الكيان مع شجرة الحسابات
CREATE OR REPLACE FUNCTION public.sync_entity_name_to_account()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_prefix TEXT;
  v_account_code TEXT;
BEGIN
  IF NEW.account_id IS NOT NULL AND (OLD.name IS DISTINCT FROM NEW.name) THEN
    -- Never rename shared Level-5 master control accounts or higher level accounts
    SELECT account_code INTO v_account_code
    FROM public.accounts
    WHERE id = NEW.account_id;

    IF v_account_code IS NULL OR v_account_code IN (
      '12511', '12512',
      '21111', '21112', '21113', '21114', '21115', '21116', '21121',
      '1251', '2111', '2112'
    ) OR LENGTH(v_account_code) <= 5 THEN
      RETURN NEW;
    END IF;

    CASE TG_TABLE_NAME
      WHEN 'customers'          THEN v_prefix := 'عميل - ';
      WHEN 'suppliers'          THEN v_prefix := 'مورد - ';
      WHEN 'shipping_companies' THEN v_prefix := 'شركة شحن - ';
      WHEN 'clearing_agents'    THEN v_prefix := 'مخلص جمركي - ';
      WHEN 'transport_suppliers' THEN v_prefix := 'مورد نقل - ';
      WHEN 'shareholders'       THEN v_prefix := 'جاري / ';
      WHEN 'treasuries'         THEN v_prefix := 'عهدة - ';
      ELSE v_prefix := '';
    END CASE;

    UPDATE public.accounts
    SET name = v_prefix || COALESCE(NEW.name, ''),
        account_name = v_prefix || COALESCE(NEW.name, ''),
        updated_at = NOW()
    WHERE id = NEW.account_id;
  END IF;

  RETURN NEW;
END;
$$;

