DROP TRIGGER IF EXISTS trg_transport_supplier_delete_account ON public.transport_suppliers;
CREATE TRIGGER trg_transport_supplier_delete_account
AFTER DELETE ON public.transport_suppliers
FOR EACH ROW
EXECUTE FUNCTION public.delete_entity_linked_account();

-- ============================================================================
-- المرحلة 9: تصفير الأرصدة والـ Sequences
-- ============================================================================

-- تصفير أرصدة الحسابات
UPDATE public.accounts SET balance = 0, updated_at = NOW();

-- حذف سجلات الأكواد المحذوفة السابقة إن وجدت
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'deleted_account_codes') THEN
        DELETE FROM public.deleted_account_codes;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'deleted_entity_codes') THEN
        DELETE FROM public.deleted_entity_codes;
    END IF;
END $$;

-- تصفير Sequences في PostgreSQL ومزامنتها ديناميكياً بدقة
DO $$
DECLARE
    r RECORD;
    v_seq TEXT;
    v_max_id BIGINT;
BEGIN
    -- 1. تصفير أي sequences عامة غير مرتبطة مباشرة بأعمدة
    FOR r IN (
        SELECT s.sequence_name
        FROM information_schema.sequences s
        WHERE s.sequence_schema = 'public'
          AND s.sequence_name NOT LIKE '%accounts%'
          AND s.sequence_name NOT LIKE '%expense%'
          AND s.sequence_name NOT IN ('journal_entries_id_seq', 'account_ledger_entries_id_seq')
    ) LOOP
        BEGIN
            EXECUTE 'ALTER SEQUENCE public.' || quote_ident(r.sequence_name) || ' RESTART WITH 1;';
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END LOOP;

    -- 2. مزامنة كل sequence مربوط بعمود جدول بدقة مع أعلى ID موجود + 1
    FOR r IN (
        SELECT table_name
        FROM information_schema.columns
        WHERE table_schema = 'public' AND column_name = 'id' AND data_type IN ('integer', 'bigint', 'smallint')
    ) LOOP
        BEGIN
            v_seq := pg_get_serial_sequence('public.' || quote_ident(r.table_name), 'id');
            IF v_seq IS NOT NULL THEN
                EXECUTE format('SELECT COALESCE(MAX(id), 0) + 1 FROM public.%I', r.table_name) INTO v_max_id;
                EXECUTE format('ALTER SEQUENCE %s RESTART WITH %s', v_seq, v_max_id);
            END IF;
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END LOOP;

    -- تصفير عدادات المستندات والفواتير (OB, INV, PUR, الخ)
    BEGIN
        EXECUTE 'UPDATE public.invoice_numbering SET next_number = 1;';
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    
    BEGIN
        EXECUTE 'UPDATE public.sys_document_types SET next_number = 1;';
    EXCEPTION WHEN OTHERS THEN NULL;
    END;

    BEGIN
        EXECUTE 'DELETE FROM public.sys_sequences;';
    EXCEPTION WHEN OTHERS THEN
        EXECUTE 'UPDATE public.sys_sequences SET current_value = 0;';
    END;
END $$;

-- ============================================================================
-- المرحلة 10: الفحص والتحقق الشامل النهائي (Comprehensive Verification)
-- ============================================================================

DO $$
DECLARE
  v_tbl TEXT;
  v_count INT;
  v_missing_core TEXT[] := '{}';
  v_core_code TEXT;
  v_company_count INT := 0;
  v_main_treasury INT := 0;
  v_treasury_currencies INT := 0;
  v_treasury_links_ok INT := 0;
  v_bank_accounts INT := 0;
  v_warehouses INT := 0;
  v_total_accounts INT := 0;
BEGIN
  -- عدد الشركات في النظام (للتحقق بنسبة)
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'sys_companies') THEN
    SELECT COUNT(*) INTO v_company_count FROM public.sys_companies WHERE deleted_at IS NULL;
  END IF;
  IF v_company_count < 1 THEN v_company_count := 1; END IF;

  -- التحقق من خلو المعاملات التشغيلية والمخازن الفرعية
  FOREACH v_tbl IN ARRAY ARRAY[
    'journal_entries', 'account_ledger_entries', 'customers', 'suppliers', 
    'purchase_invoices', 'export_shipments', 'stock_batches', 
    'treasury_transactions', 'bank_account_transactions',
    'packing_orders', 'lot_receipts', 'crop_purchases', 'purchases', 'lots', 'invoices', 'transactions',
    'cost_center_transactions', 'stations'
  ] LOOP
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = v_tbl) THEN
      EXECUTE 'SELECT COUNT(*) FROM public.' || quote_ident(v_tbl) INTO v_count;
      IF v_count > 0 THEN
        RAISE EXCEPTION 'Verification Failed: Table % has % rows, expected 0.', v_tbl, v_count;
      END IF;
    END IF;
  END LOOP;

  -- التحقق من خلو أصناف الفاكهة ومراكز تكلفتها للبدء من جديد
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'fruit_types') THEN
    EXECUTE 'SELECT COUNT(*) FROM public.fruit_types' INTO v_count;
    IF v_count > 0 THEN
      RAISE EXCEPTION 'Verification Failed: Table fruit_types has % rows, expected 0.', v_count;
    END IF;
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'cost_centers') THEN
    EXECUTE 'SELECT COUNT(*) FROM public.cost_centers WHERE cost_center_type = ''variety'' OR entity_type = ''fruit_type''' INTO v_count;
    IF v_count > 0 THEN
      RAISE EXCEPTION 'Verification Failed: Table cost_centers has % variety rows, expected 0.', v_count;
    END IF;
  END IF;

  -- التحقق من السنة المالية والعدادات
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'fiscal_years') THEN
    SELECT COUNT(*) INTO v_count FROM public.fiscal_years WHERE is_current = true;
    IF v_count != 1 THEN
      RAISE EXCEPTION 'Verification Failed: Expected exactly 1 active fiscal year, but found %.', v_count;
    END IF;
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'sys_sequences') THEN
    DELETE FROM public.sys_sequences;
    SELECT COUNT(*) INTO v_count FROM public.sys_sequences WHERE current_value > 0;
    IF v_count > 0 THEN
      RAISE EXCEPTION 'Verification Failed: Expected sys_sequences active counters to be 0, but found % rows.', v_count;
    END IF;
  END IF;

  -- التحقق من الحسابات القياسية الأساسية (بما فيها حساب جاري المساهمين والشركات الوسيطة)
  FOREACH v_core_code IN ARRAY ARRAY[
    '1', '2', '3', '4', '9',
    '11', '12', '21', '22', '23', '31', '32', '33', '41', '42', '91',
    '121', '122', '211', '231', '232', '311', '321', '322', '411', '911', '912',
    '1211', '1212', '12121', '1221', '1231', '1232', '1234', '2111', '2112', '2321',
    '3111', '3211', '3221', '4111', '9111', '9112', '9121', '9122', '9123', '9124'
  ] LOOP
    IF NOT EXISTS (SELECT 1 FROM public.accounts WHERE account_code = v_core_code) THEN
      v_missing_core := array_append(v_missing_core, v_core_code);
    END IF;
  END LOOP;

  IF array_length(v_missing_core, 1) > 0 THEN
    RAISE EXCEPTION 'Verification Failed: Missing core accounts: %', v_missing_core;
  END IF;

  -- خطوة وقائية تأكيدية: تنظيف أو ربط أي حساب يتيم خارج الجذور القياسية قبل الفحص
  UPDATE public.accounts a
  SET parent_id = p.id
  FROM public.accounts p
  WHERE a.parent_id IS NULL 
    AND a.account_code NOT IN ('1', '2', '3', '4', '9')
    AND p.account_code = (
        CASE 
            WHEN a.account_code ~ '^2321[0-9]+' THEN '2321'
            WHEN a.account_code ~ '^2315[0-9]+' THEN '2321'
            WHEN a.account_code ~ '^1221[0-9]+' THEN '1221'
            WHEN a.account_code ~ '^2111[0-9]+' THEN '2111'
            WHEN a.account_code ~ '^2112[0-9]+' THEN '2112'
            WHEN a.account_code = '1000' THEN '1'
            WHEN a.account_code = '2000' THEN '2'
            WHEN a.account_code = '3000' THEN '3'
            WHEN a.account_code = '4000' THEN '4'
            WHEN a.account_code IN ('5', '5000') THEN '32'
            WHEN a.account_code LIKE '5%' THEN '321'
            WHEN LENGTH(a.account_code) >= 5    THEN SUBSTRING(a.account_code FROM 1 FOR 4)
            WHEN LENGTH(a.account_code) = 4     THEN SUBSTRING(a.account_code FROM 1 FOR 3)
            WHEN LENGTH(a.account_code) = 3     THEN SUBSTRING(a.account_code FROM 1 FOR 2)
            WHEN LENGTH(a.account_code) = 2     THEN SUBSTRING(a.account_code FROM 1 FOR 1)
            ELSE NULL
        END
    );

  DELETE FROM public.accounts
  WHERE parent_id IS NULL AND account_code NOT IN ('1', '2', '3', '4', '9');

  -- التحقق الصارم من عدم وجود أي حسابات يتيمة بلا أب سوى الجذور القياسية الخمسة (1, 2, 3, 4, 9)
  SELECT COUNT(*) INTO v_count
  FROM public.accounts
  WHERE parent_id IS NULL AND account_code NOT IN ('1', '2', '3', '4', '9');
  IF v_count > 0 THEN
    RAISE EXCEPTION 'Verification Failed: Found % orphan root accounts with parent_id IS NULL outside of standard roots (1,2,3,4,9).', v_count;
  END IF;

  -- التحقق من صحة إعدادات حساب جاري المساهمين 2321
  IF NOT EXISTS (
    SELECT 1 FROM public.accounts 
    WHERE account_code = '2321' 
      AND level = 4 
      AND is_leaf = false 
      AND allow_posting = false
  ) THEN
    RAISE EXCEPTION 'Verification Failed: Account 2321 must exist at level 4 with is_leaf=false and allow_posting=false.';
  END IF;

  -- التحقق من الخزينة الرئيسية والربط (multi-tenant: عدد الشركات × العملات)
  SELECT COUNT(*) INTO v_main_treasury FROM public.treasuries WHERE type = 'main';
  SELECT COUNT(*) INTO v_treasury_currencies FROM public.treasury_balances;
  SELECT COUNT(*) INTO v_treasury_links_ok FROM public.treasury_balances tb JOIN public.accounts a ON tb.account_id = a.id;

  IF v_main_treasury < 1 THEN
    RAISE EXCEPTION 'Verification Failed: No main treasury found (count=%)', v_main_treasury;
  END IF;
  IF v_treasury_currencies < 4 THEN
    RAISE EXCEPTION 'Verification Failed: Treasury currencies insufficient (count=%, expected >= 4)', v_treasury_currencies;
  END IF;
  IF v_treasury_links_ok < 4 THEN
    RAISE EXCEPTION 'Verification Failed: Treasury GL links insufficient (count=%, expected >= 4)', v_treasury_links_ok;
  END IF;

  -- التحقق من البنوك والمخازن (multi-tenant: عدد الشركات × الأصول)
  SELECT COUNT(*) INTO v_bank_accounts FROM public.bank_accounts;
  SELECT COUNT(*) INTO v_warehouses FROM public.warehouses;

  IF v_bank_accounts < 4 THEN
    RAISE EXCEPTION 'Verification Failed: Bank accounts insufficient (count=%, expected >= 4)', v_bank_accounts;
  END IF;
  IF v_warehouses < 3 THEN
    RAISE EXCEPTION 'Verification Failed: Warehouses insufficient (count=%, expected >= 3)', v_warehouses;
  END IF;

  SELECT COUNT(*) INTO v_total_accounts FROM public.accounts;

  RAISE NOTICE '======================================================';
  RAISE NOTICE '   ENTERPRISE HANDOVER RESET COMPLETED SUCCESSFULLY   ';
  RAISE NOTICE '======================================================';
  RAISE NOTICE '  ✓ All Operational Transactions Reset to 0';
  RAISE NOTICE '  ✓ Companies: %   Total Standard Accounts: %', v_company_count, v_total_accounts;
  RAISE NOTICE '  ✓ Main Treasuries: %  with % Currencies & % GL Links', v_main_treasury, v_treasury_currencies, v_treasury_links_ok;
  RAISE NOTICE '  ✓ Bank Accounts: %  Warehouses: %', v_bank_accounts, v_warehouses;
  RAISE NOTICE '  ✓ Sub-Warehouses / Stations: Reset to 0 (Fresh Start for Client)';
  RAISE NOTICE '  ✓ Auto-Creation Entity Triggers: PASS';
  RAISE NOTICE '  ✓ Database Ready for Client Handover: 100%%';
  RAISE NOTICE '======================================================';
END $$;

-- ============================================================================
-- ضمان توافق دالة مزامنة الأرصدة الافتتاحية مع كافة الكيانات (shareholders, customers, suppliers)
-- قبل إعادة تفعيل التريجرز لتجنب أخطاء 42703 أثناء إدخال البيانات المرجعية
-- ============================================================================
CREATE OR REPLACE FUNCTION public.sync_entity_opening_balance_gl()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_equity_account_id BIGINT;
    v_je_id BIGINT;
    v_desc TEXT;
    v_account_id BIGINT;
    v_company_id UUID;
    v_new_balance NUMERIC;
    v_direction TEXT;
    v_currency TEXT;
    v_source_id TEXT;
    v_entry_number TEXT;
    v_new_json JSONB;
    v_old_json JSONB;
    v_is_multi BOOLEAN := false;
    v_balances_map JSONB := NULL;
    r_key TEXT;
    r_item JSONB;
    r_cur TEXT;
    r_amt NUMERIC;
    r_dir TEXT;
    r_rate NUMERIC;
    r_base_amt NUMERIC;
    r_has_entries BOOLEAN := false;
    v_base_balance NUMERIC;
BEGIN
    v_new_json := to_jsonb(NEW);
    IF TG_OP = 'UPDATE' THEN
        v_old_json := to_jsonb(OLD);
    END IF;

    -- التحقق من حدوث تغيير فعلي في الرصيد أو الاتجاه أو خريطة العملات عند الـ UPDATE
    IF TG_OP = 'UPDATE' THEN
        IF TG_TABLE_NAME = 'shareholders' THEN
            IF (v_new_json->>'initial_balance_egp') IS NOT DISTINCT FROM (v_old_json->>'initial_balance_egp') 
               AND (v_new_json->>'initial_balance_usd') IS NOT DISTINCT FROM (v_old_json->>'initial_balance_usd')
               AND (v_new_json->>'initial_balance_eur') IS NOT DISTINCT FROM (v_old_json->>'initial_balance_eur')
               AND (v_new_json->>'initial_balance_gbp') IS NOT DISTINCT FROM (v_old_json->>'initial_balance_gbp')
               AND (v_new_json->>'initial_balance_direction') IS NOT DISTINCT FROM (v_old_json->>'initial_balance_direction')
               AND (v_new_json->>'initial_balance_direction_egp') IS NOT DISTINCT FROM (v_old_json->>'initial_balance_direction_egp')
               AND (v_new_json->>'account_id') IS NOT DISTINCT FROM (v_old_json->>'account_id') THEN
                RETURN NEW;
            END IF;
        ELSIF TG_TABLE_NAME = 'suppliers' THEN
            IF (v_new_json->>'initial_balance') IS NOT DISTINCT FROM (v_old_json->>'initial_balance') 
               AND (v_new_json->>'initial_balance_direction') IS NOT DISTINCT FROM (v_old_json->>'initial_balance_direction')
               AND (v_new_json->'initial_balances_by_currency') IS NOT DISTINCT FROM (v_old_json->'initial_balances_by_currency')
               AND (v_new_json->>'account_id') IS NOT DISTINCT FROM (v_old_json->>'account_id') THEN
                RETURN NEW;
            END IF;
        ELSE
            IF (v_new_json->>'initial_balance') IS NOT DISTINCT FROM (v_old_json->>'initial_balance') 
               AND (v_new_json->>'initial_balance_direction') IS NOT DISTINCT FROM (v_old_json->>'initial_balance_direction')
               AND (v_new_json->>'account_id') IS NOT DISTINCT FROM (v_old_json->>'account_id') THEN
                RETURN NEW;
            END IF;
        END IF;
    END IF;

    -- استخراج الرصيد والوصف بحسب الجدول
    IF TG_TABLE_NAME = 'shareholders' THEN
        v_new_balance := COALESCE((v_new_json->>'initial_balance_egp')::numeric, 0);
        v_desc := 'رصيد افتتاحي - ' || COALESCE(v_new_json->>'name', '');
    ELSIF TG_TABLE_NAME = 'customers' THEN
        v_new_balance := COALESCE((v_new_json->>'initial_balance')::numeric, 0);
        v_desc := 'رصيد افتتاحي - ' || COALESCE(v_new_json->>'name', '');
    ELSIF TG_TABLE_NAME = 'clearing_agents' THEN
        v_new_balance := COALESCE((v_new_json->>'initial_balance')::numeric, 0);
        v_desc := 'رصيد افتتاحي - ' || COALESCE(v_new_json->>'name', '');
    ELSIF TG_TABLE_NAME = 'shipping_companies' THEN
        v_new_balance := COALESCE((v_new_json->>'initial_balance')::numeric, 0);
        v_desc := 'رصيد افتتاحي - ' || COALESCE(v_new_json->>'name', '');
    ELSIF TG_TABLE_NAME = 'transport_suppliers' THEN
        v_new_balance := COALESCE((v_new_json->>'initial_balance')::numeric, 0);
        v_desc := 'رصيد افتتاحي - ' || COALESCE(v_new_json->>'name', '');
    ELSIF TG_TABLE_NAME = 'suppliers' THEN
        v_new_balance := COALESCE((v_new_json->>'initial_balance')::numeric, 0);
        v_desc := 'رصيد أول المدة للمورد: ' || COALESCE(v_new_json->>'name', '');
    ELSE
        v_new_balance := COALESCE((v_new_json->>'initial_balance')::numeric, 0);
        v_desc := 'رصيد افتتاحي - ' || COALESCE(v_new_json->>'name', '');
    END IF;

    IF (v_new_json->>'account_id') IS NOT NULL THEN
        v_account_id := (v_new_json->>'account_id')::bigint;
    END IF;
    IF (v_new_json->>'company_id') IS NOT NULL THEN
        v_company_id := (v_new_json->>'company_id')::uuid;
    END IF;
    
    -- الاتجاه الافتراضي
    IF TG_TABLE_NAME = 'customers' THEN
        v_direction := COALESCE(v_new_json->>'initial_balance_direction', 'DEBIT');
    ELSIF TG_TABLE_NAME = 'shareholders' THEN
        v_direction := COALESCE(v_new_json->>'initial_balance_direction_egp', v_new_json->>'initial_balance_direction', 'CREDIT');
    ELSE
        v_direction := COALESCE(v_new_json->>'initial_balance_direction', 'CREDIT');
    END IF;
    
    -- استخراج العملة
    v_currency := UPPER(COALESCE(v_new_json->>'currency', 'EGP'));
    IF v_currency = '' OR v_currency = 'MULTI' THEN
        v_currency := 'EGP';
    END IF;

    -- حل الحساب المالي في حال عدم تمرير account_id
    IF v_account_id IS NULL THEN
        IF TG_TABLE_NAME = 'customers' THEN
            SELECT id INTO v_account_id FROM accounts 
            WHERE (
                (COALESCE(v_new_json->>'company_type', v_new_json->>'customer_type', 'export') IN ('local', 'محلي', 'local_customer', 'عملاء محلي') AND account_code = '12512')
                OR (COALESCE(v_new_json->>'company_type', v_new_json->>'customer_type', 'export') NOT IN ('local', 'محلي', 'local_customer', 'عملاء محلي') AND account_code = '12511')
                OR account_code IN ('12511', '12512', '1251')
            )
              AND (company_id = v_company_id OR company_id IS NULL) 
            ORDER BY (company_id = v_company_id) DESC, id ASC 
            LIMIT 1;
        ELSIF TG_TABLE_NAME = 'suppliers' THEN
            -- Resolve exact Level-5 account based on supplier_type, category, or code range
            IF (v_new_json->>'supplier_type' IN ('packaging', 'sticker')
                OR v_new_json->>'category' IN ('packaging', 'مواد تعبئة', 'تعبئة', 'كرتون', 'استيكر')
                OR (v_new_json->>'code')::text LIKE '70%' OR (v_new_json->>'code')::text LIKE '71%'
                OR (v_new_json->>'code')::text LIKE '72%' OR (v_new_json->>'code')::text LIKE '73%'
                OR (v_new_json->>'code')::text LIKE '74%') THEN
                SELECT id INTO v_account_id FROM accounts WHERE account_code = '21112' AND (company_id = v_company_id OR company_id IS NULL) ORDER BY (company_id = v_company_id) DESC, id ASC LIMIT 1;
            ELSIF (v_new_json->>'supplier_type' IN ('shared')
                OR v_new_json->>'category' IN ('shared', 'مشترك', 'مشتركين')
                OR (v_new_json->>'code')::text LIKE '75%' OR (v_new_json->>'code')::text LIKE '76%'
                OR (v_new_json->>'code')::text LIKE '77%' OR (v_new_json->>'code')::text LIKE '78%'
                OR (v_new_json->>'code')::text LIKE '79%') THEN
                SELECT id INTO v_account_id FROM accounts WHERE account_code = '21114' AND (company_id = v_company_id OR company_id IS NULL) ORDER BY (company_id = v_company_id) DESC, id ASC LIMIT 1;
            ELSIF (v_new_json->>'supplier_type' IN ('transport') OR (v_new_json->>'code')::text LIKE '6%') THEN
                SELECT id INTO v_account_id FROM accounts WHERE account_code = '21111' AND (company_id = v_company_id OR company_id IS NULL) ORDER BY (company_id = v_company_id) DESC, id ASC LIMIT 1;
            ELSIF (v_new_json->>'supplier_type' IN ('shipping') OR (v_new_json->>'code')::text LIKE '9%') THEN
                SELECT id INTO v_account_id FROM accounts WHERE account_code = '21115' AND (company_id = v_company_id OR company_id IS NULL) ORDER BY (company_id = v_company_id) DESC, id ASC LIMIT 1;
            ELSIF (v_new_json->>'supplier_type' IN ('clearing', 'customs')) THEN
                SELECT id INTO v_account_id FROM accounts WHERE account_code = '21116' AND (company_id = v_company_id OR company_id IS NULL) ORDER BY (company_id = v_company_id) DESC, id ASC LIMIT 1;
            ELSE
                -- Default: Crop Purchase Suppliers (50000-59999)
                SELECT id INTO v_account_id FROM accounts WHERE account_code = '21113' AND (company_id = v_company_id OR company_id IS NULL) ORDER BY (company_id = v_company_id) DESC, id ASC LIMIT 1;
            END IF;

            IF v_account_id IS NULL THEN
                SELECT id INTO v_account_id FROM accounts WHERE account_code IN ('21113', '2111', '2110') AND (company_id = v_company_id OR company_id IS NULL) ORDER BY (company_id = v_company_id) DESC, id ASC LIMIT 1;
            END IF;
        ELSIF TG_TABLE_NAME = 'clearing_agents' THEN
            SELECT id INTO v_account_id FROM accounts 
            WHERE account_code = '21116'
              AND (company_id = v_company_id OR company_id IS NULL) 
            ORDER BY (company_id = v_company_id) DESC, id ASC 
            LIMIT 1;
        ELSIF TG_TABLE_NAME = 'shipping_companies' THEN
            SELECT id INTO v_account_id FROM accounts 
            WHERE account_code = '21115'
              AND (company_id = v_company_id OR company_id IS NULL) 
            ORDER BY (company_id = v_company_id) DESC, id ASC 
            LIMIT 1;
        ELSIF TG_TABLE_NAME = 'transport_suppliers' THEN
            SELECT id INTO v_account_id FROM accounts 
            WHERE account_code = '21111'
              AND (company_id = v_company_id OR company_id IS NULL) 
            ORDER BY (company_id = v_company_id) DESC, id ASC 
            LIMIT 1;
        END IF;
    END IF;

    IF v_account_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- معرف مصدر موحد وغير قابل للتعارض بين الجداول
    v_source_id := TG_TABLE_NAME || '_' || (v_new_json->>'id');

    -- البحث عن قيد موجود مسبقاً لهذا السجل
    SELECT id INTO v_je_id
    FROM journal_entries
    WHERE source_type::text = 'opening_balance' 
      AND (source_id::text = v_source_id OR source_id::text = (v_new_json->>'id'))
      AND (company_id = v_company_id OR company_id IS NULL)
    ORDER BY id DESC
    LIMIT 1;

    -- تهيئة مسار العملات المتعددة (Suppliers أو Shareholders)
    IF TG_TABLE_NAME = 'suppliers' THEN
        v_is_multi := COALESCE((v_new_json->>'is_multi_currency')::boolean, false);
        v_balances_map := v_new_json->'initial_balances_by_currency';
    ELSIF TG_TABLE_NAME = 'shareholders' THEN
        v_is_multi := true;
        v_balances_map := jsonb_build_object(
            'EGP', jsonb_build_object('amount', COALESCE((v_new_json->>'initial_balance_egp')::numeric, 0), 'direction', COALESCE(v_new_json->>'initial_balance_direction_egp', v_new_json->>'initial_balance_direction', 'CREDIT')),
            'USD', jsonb_build_object('amount', COALESCE((v_new_json->>'initial_balance_usd')::numeric, 0), 'direction', COALESCE(v_new_json->>'initial_balance_direction', 'CREDIT')),
            'EUR', jsonb_build_object('amount', COALESCE((v_new_json->>'initial_balance_eur')::numeric, 0), 'direction', COALESCE(v_new_json->>'initial_balance_direction', 'CREDIT')),
            'GBP', jsonb_build_object('amount', COALESCE((v_new_json->>'initial_balance_gbp')::numeric, 0), 'direction', COALESCE(v_new_json->>'initial_balance_direction', 'CREDIT'))
        );
    END IF;

    IF (TG_TABLE_NAME = 'suppliers' AND v_is_multi = true AND v_balances_map IS NOT NULL AND jsonb_typeof(v_balances_map) = 'object')
       OR (TG_TABLE_NAME = 'shareholders' AND v_balances_map IS NOT NULL) THEN
        
        -- التأكد من وجود عملة واحدة على الأقل برصيد أكبر من صفر
        FOR r_key, r_item IN SELECT * FROM jsonb_each(v_balances_map) LOOP
            IF COALESCE((r_item->>'amount')::numeric, 0) > 0 THEN
                r_has_entries := true;
            END IF;
        END LOOP;

        IF NOT r_has_entries THEN
            IF v_je_id IS NOT NULL THEN
                DELETE FROM account_ledger_entries WHERE journal_entry_id = v_je_id;
                DELETE FROM journal_entries WHERE id = v_je_id;
            END IF;
            RETURN NEW;
        END IF;

        IF v_je_id IS NOT NULL THEN
            DELETE FROM account_ledger_entries WHERE journal_entry_id = v_je_id;
            UPDATE journal_entries 
            SET description = v_desc,
                source_id = v_source_id,
                entry_date = CURRENT_DATE,
                status = 'posted'
            WHERE id = v_je_id;
        ELSE
            -- توليد حتمي آمن بدون أي Race condition
            v_entry_number := public.fn_get_next_sequence(v_company_id, 'opening_balance', NULL, NULL);
            IF v_entry_number IS NULL OR v_entry_number = '' THEN
                RAISE EXCEPTION 'Failed to generate entry_number via fn_get_next_sequence for opening_balance (company_id: %)', v_company_id;
            END IF;

            INSERT INTO journal_entries (
                source_type, source_id, entry_date, description, created_by, company_id, entry_number, status
            ) VALUES (
                'opening_balance', v_source_id, CURRENT_DATE, v_desc, auth.uid(), v_company_id, v_entry_number, 'posted'
            ) RETURNING id INTO v_je_id;
        END IF;

        -- إنشاء سطور الأستاذ لكل عملة ذات رصيد موجب فقط
        FOR r_key, r_item IN SELECT * FROM jsonb_each(v_balances_map) LOOP
            r_cur := UPPER(COALESCE(r_item->>'currency', r_key));
            r_amt := COALESCE((r_item->>'amount')::numeric, 0);
            r_dir := UPPER(COALESCE(r_item->>'direction', 'CREDIT'));
            
            -- جلب سعر الصرف بشكل حتمي 100%
            IF r_cur = 'EGP' THEN
                r_rate := 1.0;
            ELSE
                r_rate := COALESCE((r_item->>'exchange_rate')::numeric, NULL);
                IF r_rate IS NULL OR r_rate <= 0 THEN
                    SELECT rate_to_egp INTO r_rate 
                    FROM exchange_rates 
                    WHERE currency_code = r_cur 
                    ORDER BY effective_from DESC, updated_at DESC, id DESC 
                    LIMIT 1;
                END IF;
                IF r_rate IS NULL OR r_rate <= 0 THEN r_rate := 1.0; END IF;
            END IF;

            r_base_amt := r_amt * r_rate;

            IF r_amt > 0 THEN
                -- حل حساب حقوق الملكية المقابل
                v_equity_account_id := public.resolve_opening_balance_equity_account(r_cur, v_company_id);

                IF v_equity_account_id IS NULL THEN
                    SELECT id INTO v_equity_account_id
                    FROM accounts
                    WHERE account_code::text = ANY(
                        CASE r_cur
                            WHEN 'USD' THEN ARRAY['23421', '2332', '3902', '2312', '3002']
                            WHEN 'EUR' THEN ARRAY['23421', '2333', '3903', '2313', '3003']
                            WHEN 'GBP' THEN ARRAY['23421', '2334', '3904', '2314', '3004']
                            ELSE ARRAY['23421', '2331', '3901', '2311', '3001']
                        END
                    )
                    AND (company_id = v_company_id OR company_id IS NULL)
                    ORDER BY (company_id = v_company_id) DESC, id ASC
                    LIMIT 1;
                END IF;

                IF v_equity_account_id IS NULL THEN
                    SELECT id INTO v_equity_account_id
                    FROM accounts
                    WHERE account_code::text IN ('23421', '2342', '2330', '233', '2310', '231', '3900', '3901', '3001', '3000', '3300')
                      AND (company_id = v_company_id OR company_id IS NULL)
                    ORDER BY (company_id = v_company_id) DESC, id ASC
                    LIMIT 1;
                END IF;

                IF v_equity_account_id IS NULL THEN
                    SELECT id INTO v_equity_account_id
                    FROM accounts
                    WHERE account_type = 'equity' AND (allow_posting = true OR is_leaf = true)
                      AND (company_id = v_company_id OR company_id IS NULL)
                    ORDER BY (company_id = v_company_id) DESC, id ASC
                    LIMIT 1;
                END IF;

                -- إدراج سطرين متزنين للقيد
                IF v_account_id IS NOT NULL AND v_equity_account_id IS NOT NULL THEN
                    IF r_dir = 'DEBIT' THEN
                        INSERT INTO account_ledger_entries (journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id)
                        VALUES (v_je_id, v_account_id, r_amt, 0, r_cur, r_base_amt, v_desc || ' (' || r_cur || ')', v_company_id);
                        INSERT INTO account_ledger_entries (journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id)
                        VALUES (v_je_id, v_equity_account_id, 0, r_amt, r_cur, r_base_amt, v_desc || ' (' || r_cur || ')', v_company_id);
                    ELSE
                        INSERT INTO account_ledger_entries (journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id)
                        VALUES (v_je_id, v_account_id, 0, r_amt, r_cur, r_base_amt, v_desc || ' (' || r_cur || ')', v_company_id);
                        INSERT INTO account_ledger_entries (journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id)
                        VALUES (v_je_id, v_equity_account_id, r_amt, 0, r_cur, r_base_amt, v_desc || ' (' || r_cur || ')', v_company_id);
                    END IF;
                END IF;
            END IF;
        END LOOP;

        RETURN NEW;
    END IF;

    -- =========================================================================
    -- مسار العملة الفردية القياسي (Customers, Clearing, Shipping, Transport, Single-currency Suppliers)
    -- =========================================================================
    v_equity_account_id := public.resolve_opening_balance_equity_account(v_currency, v_company_id);

    IF v_equity_account_id IS NULL THEN
        SELECT id INTO v_equity_account_id
        FROM accounts
        WHERE account_code::text = ANY(
            CASE v_currency
                WHEN 'USD' THEN ARRAY['23421', '2332', '3902', '2312', '3002']
                WHEN 'EUR' THEN ARRAY['23421', '2333', '3903', '2313', '3003']
                WHEN 'GBP' THEN ARRAY['23421', '2334', '3904', '2314', '3004']
                ELSE ARRAY['23421', '2331', '3901', '2311', '3001']
            END
        )
        AND (company_id = v_company_id OR company_id IS NULL)
        ORDER BY (company_id = v_company_id) DESC, id ASC
        LIMIT 1;
    END IF;

    IF v_equity_account_id IS NULL THEN
        SELECT id INTO v_equity_account_id
        FROM accounts
        WHERE account_code::text IN ('23421', '2342', '2330', '233', '2310', '231', '3900', '3901', '3001', '3000', '3300')
          AND (company_id = v_company_id OR company_id IS NULL)
        ORDER BY (company_id = v_company_id) DESC, id ASC
        LIMIT 1;
    END IF;

    IF v_equity_account_id IS NULL THEN
        SELECT id INTO v_equity_account_id
        FROM accounts
        WHERE account_type = 'equity' AND (allow_posting = true OR is_leaf = true)
          AND (company_id = v_company_id OR company_id IS NULL)
        ORDER BY (company_id = v_company_id) DESC, id ASC
        LIMIT 1;
    END IF;
    
    IF v_equity_account_id IS NULL OR v_account_id IS NULL THEN
        RETURN NEW;
    END IF;

    IF v_je_id IS NOT NULL THEN
        DELETE FROM account_ledger_entries WHERE journal_entry_id = v_je_id;
        
        IF v_new_balance = 0 THEN
            DELETE FROM journal_entries WHERE id = v_je_id;
            RETURN NEW;
        END IF;

        UPDATE journal_entries 
        SET description = v_desc,
            source_id = v_source_id,
            entry_date = CURRENT_DATE,
            status = 'posted'
        WHERE id = v_je_id;
    ELSE
        IF v_new_balance = 0 THEN
            RETURN NEW;
        END IF;
        
        -- توليد حتمي آمن بدون أي Race condition
        v_entry_number := public.fn_get_next_sequence(v_company_id, 'opening_balance', NULL, NULL);
        IF v_entry_number IS NULL OR v_entry_number = '' THEN
            RAISE EXCEPTION 'Failed to generate entry_number via fn_get_next_sequence for opening_balance (company_id: %)', v_company_id;
        END IF;

        INSERT INTO journal_entries (
            source_type, source_id, entry_date, description, created_by, company_id, entry_number, status
        ) VALUES (
            'opening_balance', v_source_id, CURRENT_DATE, v_desc, auth.uid(), v_company_id, v_entry_number, 'posted'
        ) RETURNING id INTO v_je_id;
    END IF;

    -- حساب القيمة بالعملة المحلية مع تحديد سعر الصرف حتمياً
    r_rate := 1.0;
    IF v_currency IS NOT NULL AND v_currency <> 'EGP' THEN
        SELECT rate_to_egp INTO r_rate 
        FROM exchange_rates 
        WHERE currency_code = v_currency 
        ORDER BY effective_from DESC, updated_at DESC, id DESC 
        LIMIT 1;
        IF r_rate IS NULL OR r_rate <= 0 THEN r_rate := 1.0; END IF;
    END IF;
    v_base_balance := v_new_balance * r_rate;

    -- إنشاء سطور القيد بناءً على الاتجاه المحدد
    IF v_direction = 'DEBIT' THEN
        INSERT INTO account_ledger_entries (
            journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id
        ) VALUES (
            v_je_id, v_account_id, v_new_balance, 0, v_currency, v_base_balance, v_desc, v_company_id
        );
        INSERT INTO account_ledger_entries (
            journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id
        ) VALUES (
            v_je_id, v_equity_account_id, 0, v_new_balance, v_currency, v_base_balance, v_desc, v_company_id
        );
    ELSE
        INSERT INTO account_ledger_entries (
            journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id
        ) VALUES (
            v_je_id, v_account_id, 0, v_new_balance, v_currency, v_base_balance, v_desc, v_company_id
        );
        INSERT INTO account_ledger_entries (
            journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id
        ) VALUES (
            v_je_id, v_equity_account_id, v_new_balance, 0, v_currency, v_base_balance, v_desc, v_company_id
        );
    END IF;

    RETURN NEW;
END;
$$;

-- إعادة تفعيل تريجرز النظام إلى الوضع الطبيعي
SET LOCAL session_replication_role = 'origin';

-- تفعيل تريجرز مزامنة الأرصدة الافتتاحية مع دفتر الأستاذ العام لكافة الكيانات
DROP TRIGGER IF EXISTS trg_supplier_opening_balance_gl ON public.suppliers;
CREATE TRIGGER trg_supplier_opening_balance_gl
AFTER INSERT OR UPDATE OF initial_balance, initial_balance_direction, initial_balances_by_currency, account_id
ON public.suppliers
FOR EACH ROW EXECUTE FUNCTION public.sync_entity_opening_balance_gl();

DROP TRIGGER IF EXISTS trg_customer_opening_balance_gl ON public.customers;
CREATE TRIGGER trg_customer_opening_balance_gl
AFTER INSERT OR UPDATE OF initial_balance, initial_balance_direction, account_id
ON public.customers
FOR EACH ROW EXECUTE FUNCTION public.sync_entity_opening_balance_gl();

-- ⚠️ ORDER-DEPENDENT: assumes trg_create_shareholder_account (alphabetically
-- earlier) fires first on the same AFTER INSERT event and populates account_id
-- via its own UPDATE, which re-triggers this trigger. Renaming either trigger
-- breaks this chain silently.
DROP TRIGGER IF EXISTS trg_shareholder_opening_balance_gl ON public.shareholders;
CREATE TRIGGER trg_shareholder_opening_balance_gl
AFTER INSERT OR UPDATE OF initial_balance_egp, initial_balance_usd, initial_balance_eur, initial_balance_gbp, initial_balance_direction, initial_balance_direction_egp, account_id
ON public.shareholders
FOR EACH ROW EXECUTE FUNCTION public.sync_entity_opening_balance_gl();

DROP TRIGGER IF EXISTS trg_shipping_company_opening_balance_gl ON public.shipping_companies;
CREATE TRIGGER trg_shipping_company_opening_balance_gl
AFTER INSERT OR UPDATE OF initial_balance, initial_balance_direction, account_id
ON public.shipping_companies
FOR EACH ROW EXECUTE FUNCTION public.sync_entity_opening_balance_gl();

DROP TRIGGER IF EXISTS trg_clearing_agent_opening_balance_gl ON public.clearing_agents;
CREATE TRIGGER trg_clearing_agent_opening_balance_gl
AFTER INSERT OR UPDATE OF initial_balance, initial_balance_direction, account_id
ON public.clearing_agents
FOR EACH ROW EXECUTE FUNCTION public.sync_entity_opening_balance_gl();

DROP TRIGGER IF EXISTS trg_transport_supplier_opening_balance_gl ON public.transport_suppliers;
CREATE TRIGGER trg_transport_supplier_opening_balance_gl
AFTER INSERT OR UPDATE OF initial_balance, initial_balance_direction, account_id
ON public.transport_suppliers
FOR EACH ROW EXECUTE FUNCTION public.sync_entity_opening_balance_gl();

CREATE OR REPLACE FUNCTION public.rpc_apply_packing_order_item_debit_note(
    p_order_id BIGINT,
    p_item_type TEXT,
    p_item_id BIGINT DEFAULT NULL,
    p_batch_id BIGINT DEFAULT NULL,
    p_discount_amount NUMERIC DEFAULT 0,
    p_reason TEXT DEFAULT NULL,
    p_supplier_uuid UUID DEFAULT NULL,
    p_user_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_order RECORD;
    v_company_id UUID;
    v_entry_date DATE;
    v_supplier_uuid UUID := p_supplier_uuid;
    v_supplier_name TEXT;
    v_supplier_currency TEXT := 'EGP';
    v_exchange_rate NUMERIC := 1.0;
    v_foreign_discount NUMERIC;
    v_applied NUMERIC;
    v_old_total NUMERIC;
    v_new_total NUMERIC;
    v_qty NUMERIC;
    v_cost_center_id TEXT;
    v_cost_center_name TEXT;
    v_cost_center_type TEXT := 'operational';
    v_item_name TEXT := 'بند أمر تعبئة';
    v_category TEXT := 'مواد التعبئة';
    v_source_account_id UUID;
    v_dest_account_id UUID;
    v_is_shipped BOOLEAN;
    v_notes JSONB;
    v_elem JSONB;
    v_je_id UUID;
    v_entry_num TEXT;
BEGIN
    -- 1. Validate & Lock Packing Order
    SELECT * INTO v_order FROM public.packing_orders WHERE id = p_order_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'أمر التعبئة غير موجود');
    END IF;

    IF p_discount_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'مبلغ الخصم يجب أن يكون أكبر من الصفر');
    END IF;

    -- 2. Check Profit Distribution Lock
    IF EXISTS (
        SELECT 1 
        FROM public.export_shipment_items esi
        JOIN public.shareholder_profit_distributions spd ON spd.shipment_id = esi.shipment_id
        WHERE esi.packing_order_id = p_order_id
          AND spd.deleted_at IS NULL
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'تم توزيع أرباح الشحنة المرتبطة بهذا الأمر على المساهمين - لا يمكن تعديل الأسعار أو التكاليف');
    END IF;

    v_company_id := v_order.company_id;
    IF v_company_id IS NULL THEN
        SELECT id INTO v_company_id FROM public.sys_companies LIMIT 1;
    END IF;

    v_entry_date := (NOW() AT TIME ZONE 'Africa/Cairo')::DATE;

    -- 3. Auto-resolve Supplier UUID if not explicitly provided
    IF v_supplier_uuid IS NULL THEN
        IF p_item_type = 'material' AND p_batch_id > 0 THEN
            SELECT supplier_id INTO v_supplier_uuid
            FROM public.station_product_batches
            WHERE id = p_batch_id;

            IF v_supplier_uuid IS NULL THEN
                SELECT pi.supplier_id INTO v_supplier_uuid
                FROM public.station_product_batches spb
                JOIN public.purchase_invoices pi ON pi.id = spb.purchase_invoice_id
                WHERE spb.id = p_batch_id;
            END IF;
        END IF;

        -- Fallback to lot supplier linked to this packing order
        IF v_supplier_uuid IS NULL AND v_order.lot_id IS NOT NULL THEN
            SELECT supplier_id INTO v_supplier_uuid
            FROM public.lot_receipts
            WHERE id = v_order.lot_id;

            IF v_supplier_uuid IS NULL THEN
                SELECT supplier_id INTO v_supplier_uuid
                FROM public.lots
                WHERE id = v_order.lot_id;
            END IF;
        END IF;

        -- Fallback to system default supplier if only one exists
        IF v_supplier_uuid IS NULL THEN
            SELECT id INTO v_supplier_uuid FROM public.suppliers LIMIT 1;
        END IF;
    END IF;

    -- 4. Load Supplier details
    IF v_supplier_uuid IS NOT NULL THEN
        SELECT name, COALESCE(currency, 'EGP')
        INTO v_supplier_name, v_supplier_currency
        FROM public.suppliers
        WHERE id = v_supplier_uuid;

        v_exchange_rate := COALESCE(public.fn_get_exchange_rate(v_supplier_currency), 1.0);
    END IF;

    IF v_supplier_name IS NULL OR v_supplier_name = '' THEN
        v_supplier_name := 'المورد المرتبط';
    END IF;

    -- 5. Identify Accounts
    -- Source: Supplier Payable Account (2001 / 2000 / 2112)
    BEGIN
        SELECT account_id INTO v_source_account_id
        FROM public.suppliers
        WHERE id = v_supplier_uuid;
    EXCEPTION WHEN OTHERS THEN
        v_source_account_id := NULL;
    END;

    IF v_source_account_id IS NULL THEN
        v_source_account_id := public.resolve_gl_account('2001', v_company_id);
    END IF;
    IF v_source_account_id IS NULL THEN
        v_source_account_id := public.resolve_gl_account('2000', v_company_id);
    END IF;
    IF v_source_account_id IS NULL THEN
        v_source_account_id := public.resolve_gl_account('2112', v_company_id);
    END IF;
    IF v_source_account_id IS NULL THEN
        SELECT id INTO v_source_account_id FROM public.accounts WHERE account_code IN ('2112', '2001', '2000') LIMIT 1;
    END IF;
    IF v_source_account_id IS NULL THEN
        SELECT id INTO v_source_account_id FROM public.accounts WHERE account_type = 'liability' LIMIT 1;
    END IF;

    -- Destination Account: COGS (3111/5000) if shipped, Packaging Inventory (12411/1040) or Crop Inventory (12412/1030) or Finished Goods (12413/1031) if not
    SELECT EXISTS (
        SELECT 1 FROM public.export_shipment_items WHERE packing_order_id = p_order_id
    ) INTO v_is_shipped;

    IF v_is_shipped THEN
        v_dest_account_id := public.resolve_gl_account('3111', v_company_id);
        IF v_dest_account_id IS NULL THEN
            v_dest_account_id := public.resolve_gl_account('5000', v_company_id);
        END IF;
        IF v_dest_account_id IS NULL THEN
            SELECT id INTO v_dest_account_id FROM public.accounts WHERE account_code IN ('3111', '5000', '5101', '3110') LIMIT 1;
        END IF;
        IF v_dest_account_id IS NULL THEN
            SELECT id INTO v_dest_account_id FROM public.accounts WHERE account_type IN ('cost_of_goods_sold', 'expense') LIMIT 1;
        END IF;
    ELSE
        IF p_item_type = 'material' THEN
            v_dest_account_id := public.resolve_gl_account('12411', v_company_id);
            IF v_dest_account_id IS NULL THEN
                v_dest_account_id := public.resolve_gl_account('1040', v_company_id);
            END IF;
        ELSE
            v_dest_account_id := public.resolve_gl_account('12412', v_company_id);
            IF v_dest_account_id IS NULL THEN
                v_dest_account_id := public.resolve_gl_account('1030', v_company_id);
            END IF;
        END IF;

        IF v_dest_account_id IS NULL THEN
            v_dest_account_id := public.resolve_gl_account('12413', v_company_id);
        END IF;
        IF v_dest_account_id IS NULL THEN
            v_dest_account_id := public.resolve_gl_account('1031', v_company_id);
        END IF;
        IF v_dest_account_id IS NULL THEN
            SELECT id INTO v_dest_account_id FROM public.accounts WHERE account_code IN ('12413', '1031', '12411', '1040', '12412', '1030') LIMIT 1;
        END IF;
        IF v_dest_account_id IS NULL THEN
            SELECT id INTO v_dest_account_id FROM public.accounts WHERE account_type = 'asset' LIMIT 1;
        END IF;
    END IF;

    IF v_source_account_id IS NULL OR v_dest_account_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'تعذر تحديد حسابات اليومية (حساب المورد أو حساب المخزون/التكلفة)');
    END IF;

    -- 6. Resolve Cost Center & Item Details
    BEGIN
        v_notes := v_order.notes::jsonb;
    EXCEPTION WHEN OTHERS THEN
        v_notes := '{}'::jsonb;
    END;

    IF p_item_type = 'material' THEN
        v_category := 'مواد التعبئة';
        v_cost_center_type := 'operational';
        
        IF v_notes ? 'materials' AND jsonb_typeof(v_notes->'materials') = 'array' THEN
            FOR v_elem IN SELECT * FROM jsonb_array_elements(v_notes->'materials')
            LOOP
                IF (p_batch_id > 0 AND (v_elem->>'batch_id')::bigint = p_batch_id) OR
                   (p_item_id IS NOT NULL AND (v_elem->>'id')::bigint = p_item_id) THEN
                    v_cost_center_id := NULLIF(v_elem->>'cost_center_id', '');
                    v_cost_center_name := NULLIF(v_elem->>'cost_center_name', '');
                    v_item_name := COALESCE(NULLIF(v_elem->>'item_name', ''), NULLIF(v_elem->>'name', ''), 'مواد تعبئة');
                    EXIT;
                END IF;
            END LOOP;
        END IF;

        IF v_cost_center_id IS NULL THEN
            SELECT code, COALESCE(name_ar, name)
            INTO v_cost_center_id, v_cost_center_name
            FROM public.cost_centers
            WHERE code = 'CC-PACKING' OR code = 'packing_station'
            LIMIT 1;
        END IF;

        IF v_cost_center_id IS NULL THEN
            v_cost_center_id := 'CC-PACKING';
            v_cost_center_name := 'محطة التعبئة والتجهيز';
        END IF;
    ELSIF p_item_type = 'crop' THEN
        v_category := 'تكلفة المحاصيل';
        v_cost_center_type := 'variety';
        v_item_name := COALESCE(v_order.product_name, 'محصول');

        SELECT code, COALESCE(name_ar, name)
        INTO v_cost_center_id, v_cost_center_name
        FROM public.cost_centers
        WHERE (product_id = v_order.fruit_type_id OR name_ar = v_order.product_name OR crop_name = v_order.product_name)
          AND cost_center_type = 'variety'
        LIMIT 1;

        IF v_cost_center_id IS NULL THEN
            SELECT code, COALESCE(name_ar, name)
            INTO v_cost_center_id, v_cost_center_name
            FROM public.cost_centers
            WHERE cost_center_type = 'variety'
            LIMIT 1;
        END IF;

        IF v_cost_center_id IS NULL THEN
            v_cost_center_id := 'CC-CROP';
            v_cost_center_name := 'تكلفة المحاصيل';
        END IF;
    END IF;

    -- 7. Generate Journal Entry
    v_foreign_discount := ROUND(p_discount_amount / GREATEST(v_exchange_rate, 0.0001), 2);

    INSERT INTO public.journal_entries (
        entry_number, entry_date, description, status,
        is_auto_generated, source_type, source_id, company_id,
        created_by, created_at, updated_at
    ) VALUES (
        'PENDING',
        v_entry_date,
        'إشعار خصم مورد على أمر تعبئة رقم ' || p_order_id::text || ' - مورد: ' || COALESCE(v_supplier_name, '') || ' - ' || COALESCE(p_reason, ''),
        'posted', true, 'packing_debit_note', p_order_id::text, v_company_id,
        COALESCE(p_user_id, auth.uid()), now(), now()
    ) RETURNING id INTO v_je_id;

    v_entry_num := public.fn_get_next_sequence(v_company_id, 'packing_debit_note', NULL, NULL);
    IF v_entry_num IS NULL OR v_entry_num = '' THEN
        v_entry_num := 'DN-' || LPAD(v_je_id::text, 5, '0');
    END IF;
    UPDATE public.journal_entries SET entry_number = v_entry_num WHERE id = v_je_id;

    -- DR: Supplier account (decreases payable)
    INSERT INTO public.account_ledger_entries (
        journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id, cost_center_id
    ) VALUES (
        v_je_id, v_source_account_id, v_foreign_discount, 0, v_supplier_currency, p_discount_amount,
        'إشعار خصم من المورد ' || COALESCE(v_supplier_name, '') || ' لأمر تعبئة #' || p_order_id::text,
        v_company_id, v_cost_center_id
    );

    -- CR: Inventory or COGS (reduces cost)
    INSERT INTO public.account_ledger_entries (
        journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id, cost_center_id
    ) VALUES (
        v_je_id, v_dest_account_id, 0, p_discount_amount, 'EGP', p_discount_amount,
        'تخفيض تكلفة الإنتاج لأمر تعبئة #' || p_order_id::text || ' بإشعار خصم مورد ' || COALESCE(v_supplier_name, ''),
        v_company_id, v_cost_center_id
    );

    -- 7. Update Supplier Subledger & Account Statement (ledger_entries and supplier balance)
    IF v_supplier_uuid IS NOT NULL THEN
        UPDATE public.suppliers
        SET outstanding_balance = GREATEST(0, COALESCE(outstanding_balance, 0) - p_discount_amount),
            current_balances_by_currency = jsonb_set(
                COALESCE(current_balances_by_currency, '{}'::jsonb),
                array[v_supplier_currency],
                to_jsonb(COALESCE((current_balances_by_currency->>v_supplier_currency)::numeric, 0) - v_foreign_discount)
            ),
            updated_at = now()
        WHERE id = v_supplier_uuid;

        INSERT INTO public.ledger_entries (
            entity_type,
            entity_id,
            entry_type,
            amount,
            currency,
            reference_type,
            reference_id,
            reference_text,
            description,
            created_by,
            created_at
        ) VALUES (
            'supplier',
            v_supplier_uuid::text,
            'debit',
            v_foreign_discount,
            v_supplier_currency,
            'packing_order_debit_note',
            p_order_id,
            v_entry_num,
            'إشعار خصم وتسوية أمر تعبئة #' || p_order_id::text || ' - مورد: ' || COALESCE(v_supplier_name, '') || ' (' || COALESCE(p_reason, '') || ')',
            COALESCE(p_user_id, auth.uid()),
            now()
        );
    END IF;

    -- 8. Sync into Cost Center Transactions (Reduces Cost Center Expenses)
    IF v_cost_center_id IS NOT NULL THEN
        INSERT INTO public.cost_center_transactions (
            cost_center_id,
            cost_center_name,
            cost_center_type,
            source_type,
            source_id,
            transaction_date,
            supplier_id,
            supplier_name,
            item_name,
            category,
            quantity,
            unit_price,
            currency,
            exchange_rate,
            total_in_currency,
            amount,
            notes,
            is_confirmed
        ) VALUES (
            v_cost_center_id,
            v_cost_center_name,
            v_cost_center_type,
            'packing_debit_note',
            'pkdn_' || p_order_id::text || '_' || v_je_id::text,
            v_entry_date,
            v_supplier_uuid::text,
            v_supplier_name,
            'إشعار خصم تسوية - ' || v_item_name,
            v_category,
            0,
            0,
            v_supplier_currency,
            v_exchange_rate,
            -v_foreign_discount,
            -p_discount_amount,
            'إشعار خصم وتسوية أمر تعبئة #' || p_order_id::text || ' - مورد: ' || COALESCE(v_supplier_name, '') || ' (' || COALESCE(p_reason, '') || ')',
            true
        ) ON CONFLICT (source_type, source_id) DO UPDATE SET
            cost_center_id = EXCLUDED.cost_center_id,
            cost_center_name = EXCLUDED.cost_center_name,
            cost_center_type = EXCLUDED.cost_center_type,
            supplier_id = EXCLUDED.supplier_id,
            supplier_name = EXCLUDED.supplier_name,
            item_name = EXCLUDED.item_name,
            category = EXCLUDED.category,
            currency = EXCLUDED.currency,
            exchange_rate = EXCLUDED.exchange_rate,
            total_in_currency = EXCLUDED.total_in_currency,
            amount = EXCLUDED.amount,
            notes = EXCLUDED.notes,
            updated_at = now();
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'تم تطبيق إشعار الخصم بنجاح وتحديث الحسابات والمراكز والتكاليف',
        'journal_entry_id', v_je_id,
        'entry_number', v_entry_num,
        'foreign_discount', v_foreign_discount,
        'base_discount', p_discount_amount
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_apply_packing_order_item_debit_note(BIGINT, TEXT, BIGINT, BIGINT, NUMERIC, TEXT, UUID, UUID) TO authenticated, service_role, anon;

-- ============================================================================
-- 10. تحديث جذر حسابات الموردين ليتطابق دائما مع كشف الحساب
-- ============================================================================
ALTER TABLE public.purchase_invoices ADD COLUMN IF NOT EXISTS exchange_rate NUMERIC(15, 6) DEFAULT 1.0;
ALTER TABLE public.suppliers ADD COLUMN IF NOT EXISTS is_multi_currency BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE public.suppliers ADD COLUMN IF NOT EXISTS initial_balances_by_currency JSONB DEFAULT '{}'::jsonb;

CREATE OR REPLACE FUNCTION public.get_supplier_true_balances()
RETURNS TABLE (
  supplier_id uuid,
  true_balance numeric
)
LANGUAGE sql
SECURITY DEFINER
AS $func$
  SELECT
    s.id,
    (
      -- 1. Initial Balance (EGP equivalent for multi-currency, or native for single)
      (CASE 
        WHEN s.is_multi_currency = true AND s.initial_balances_by_currency IS NOT NULL AND jsonb_typeof(s.initial_balances_by_currency) = 'object' THEN 
          (SELECT COALESCE(SUM((val->>'amount')::numeric * COALESCE((val->>'exchange_rate')::numeric, 1.0) * (CASE WHEN UPPER(COALESCE(val->>'direction', 'CREDIT')) = 'DEBIT' THEN -1 ELSE 1 END)), 0) 
           FROM jsonb_each(s.initial_balances_by_currency) elem(k, val))
        WHEN s.initial_balance_direction = 'CREDIT' THEN COALESCE(s.initial_balance, 0) 
        ELSE -COALESCE(s.initial_balance, 0) 
      END)
      
      -- 2. Purchases (converted to base EGP using exchange_rate)
      + COALESCE((SELECT SUM(COALESCE(total_amount * COALESCE(exchange_rate, 1.0), total_amount)) FROM purchase_invoices WHERE supplier_id = s.id AND status = 'confirmed'), 0)
      
      -- 3. Treasury Transactions
      + COALESCE((SELECT SUM(amount) FROM treasury_transactions WHERE supplier_id = s.id AND type IN ('deposit', 'receive', 'income', 'supplier_refund') AND (status = 'confirmed' OR status IS NULL)), 0)
      - COALESCE((SELECT SUM(amount) FROM treasury_transactions WHERE supplier_id = s.id AND type IN ('expense', 'supplier_payment') AND (status = 'confirmed' OR status IS NULL)), 0)
      
      -- 4. Bank Transactions
      + COALESCE((SELECT SUM(amount) FROM bank_account_transactions WHERE entity_type = 'supplier' AND entity_id = s.id::TEXT AND type IN ('deposit', 'receive', 'income', 'supplier_refund') AND (status = 'confirmed' OR status IS NULL)), 0)
      - COALESCE((SELECT SUM(amount) FROM bank_account_transactions WHERE entity_type = 'supplier' AND entity_id = s.id::TEXT AND type IN ('withdraw', 'expense', 'supplier_payment') AND (status = 'confirmed' OR status IS NULL)), 0)
      
      -- 5. Cheques
      + COALESCE((SELECT SUM(amount) FROM cheques WHERE supplier_id = s.id AND type = 'incoming' AND status IN ('cleared', 'collected')), 0)
      - COALESCE((SELECT SUM(amount) FROM cheques WHERE supplier_id = s.id AND type = 'outgoing' AND status IN ('cleared', 'collected')), 0)
      
      -- 6. Legacy Ledger Entries (Manual journal entries, packing costs, old lot receipts, etc.)
      -- We EXCLUDE entries that are already represented by treasury_transactions or bank_transactions above 
      + COALESCE((
          SELECT SUM(CASE WHEN entry_type = 'credit' THEN amount ELSE -amount END)
          FROM ledger_entries le
          WHERE le.entity_type = 'supplier' 
            AND le.entity_id IN (s.id::text, s.code)
            AND NOT (
                le.reference_type IN ('supplier_payment', 'treasury_deposit', 'treasury_withdrawal', 'treasury_transaction', 'cash_payment', 'receive', 'deposit', 'supplier_refund')
                AND EXISTS (SELECT 1 FROM treasury_transactions tt WHERE tt.id::TEXT = le.reference_id::TEXT)
            )
            AND NOT (
                le.reference_type IN ('bank_payment', 'bank_receipt', 'bank_transaction', 'cheque', 'supplier_payment', 'cheque_payment', 'receive', 'deposit', 'supplier_refund')
                AND EXISTS (SELECT 1 FROM bank_account_transactions bt WHERE bt.id::TEXT = le.reference_id::TEXT)
            )
            AND le.reference_type NOT IN ('lot_receipt', 'lot_adjustment', 'lot_price_adjustment', 'lot_return')
      ), 0)

      -- 7. New Enterprise Account Ledger Entries (New lot receipts, adjustments)
      -- Include source types that were migrated to enterprise journals and are no longer in legacy ledger_entries
      + COALESCE((
          SELECT SUM(ale.credit - ale.debit)
          FROM account_ledger_entries ale
          JOIN journal_entries je ON je.id = ale.journal_entry_id
          WHERE ale.account_id = s.account_id
            AND je.source_type IN (
              'lot_receipt', 'lot_adjustment', 'lot_price_adjustment', 'lot_return', 'manual'
            )
      ), 0)
    ) AS true_balance
  FROM suppliers s;
$func$;

GRANT EXECUTE ON FUNCTION public.get_supplier_true_balances() TO authenticated, anon, service_role;

CREATE OR REPLACE FUNCTION public.get_customer_true_balances()
RETURNS TABLE (
  customer_id bigint,
  true_balance numeric
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $func$
  SELECT
    c.id,
    (
      -- 1. Initial Balance (DEBIT is positive debt / customer owes us, CREDIT is negative / overpayment)
      (CASE 
        WHEN UPPER(COALESCE(c.initial_balance_direction, 'DEBIT')) = 'CREDIT' THEN -COALESCE(c.initial_balance, 0) 
        ELSE COALESCE(c.initial_balance, 0) 
      END)
      
      -- 2. Export Shipments (Debits - customer owes us)
      + COALESCE((
          SELECT SUM(
            CASE 
              WHEN UPPER(COALESCE(c.currency, 'EGP')) = 'EGP' THEN COALESCE(es.total_revenue_egp, 0)
              ELSE COALESCE(es.total_revenue_foreign, es.total_revenue_egp, 0)
            END 
            - COALESCE(es.discount_amount, 0)
          )
          FROM public.export_shipments es
          WHERE es.customer_id = c.id
            AND es.is_confirmed = true
            AND (es.status IS NULL OR es.status <> 'cancelled')
        ), 0)

      -- 3. Local Invoices (Debits - customer owes us)
      + COALESCE((
          SELECT SUM(COALESCE(inv.total_amount, 0))
          FROM public.invoices inv
          WHERE inv.customer_id = c.id
            AND inv.status IN ('confirmed', 'paid')
        ), 0)

      -- 4. Treasury Transactions (Receiving money from customer is Credit / reduces debt; refund is Debit)
      - COALESCE((SELECT SUM(amount) FROM public.treasury_transactions WHERE customer_id = c.id AND type IN ('deposit', 'receive', 'income') AND (status = 'confirmed' OR status IS NULL)), 0)
      + COALESCE((SELECT SUM(amount) FROM public.treasury_transactions WHERE customer_id = c.id AND type IN ('expense', 'withdrawal', 'customer_refund') AND (status = 'confirmed' OR status IS NULL)), 0)
      
      -- 5. Bank Transactions (Deposit from customer is Credit; withdrawal/refund is Debit)
      - COALESCE((SELECT SUM(amount) FROM public.bank_account_transactions WHERE entity_type = 'customer' AND entity_id = c.id::TEXT AND type IN ('deposit', 'receive', 'income') AND (status = 'confirmed' OR status IS NULL)), 0)
      + COALESCE((SELECT SUM(amount) FROM public.bank_account_transactions WHERE entity_type = 'customer' AND entity_id = c.id::TEXT AND type IN ('withdraw', 'withdrawal', 'expense') AND (status = 'confirmed' OR status IS NULL)), 0)
      
      -- 6. Cheques (Incoming cheques from customer are Credit / reduces debt; outgoing refund cheques are Debit)
      - COALESCE((SELECT SUM(amount) FROM public.cheques WHERE (counterparty_type = 'customer' AND counterparty_id = c.id) AND type = 'incoming' AND status IN ('cleared', 'collected', 'pending')), 0)
      + COALESCE((SELECT SUM(amount) FROM public.cheques WHERE (counterparty_type = 'customer' AND counterparty_id = c.id) AND type = 'outgoing' AND status IN ('cleared', 'collected', 'pending')), 0)

      -- 7. Direct / Manual Journal Entries specifically for this customer
      -- MUST EXCLUDE 'opening_balance' because initial_balance is already included in step 1!
      -- Also excludes automated entries for shipments, invoices, treasury, bank, and cheques.
      + COALESCE((
          SELECT SUM(ale.debit - ale.credit)
          FROM public.account_ledger_entries ale
          JOIN public.journal_entries je ON je.id = ale.journal_entry_id
          WHERE ale.account_id = c.account_id
            AND (je.source_id = 'customers_' || c.id::text OR je.source_id = c.id::text)
            AND je.source_type NOT IN (
                'opening_balance',
                'customer_opening_balance',
                'export_shipment',
                'invoice',
                'sales_invoice',
                'treasury_transaction',
                'treasury_deposit',
                'treasury_receive',
                'treasury_expense',
                'bank_transaction',
                'bank_deposit',
                'bank_withdrawal',
                'cheque_receipt',
                'cheque_issuance',
                'cheque_deposit',
                'cheque_clearance'
            )
        ), 0)
    ) AS true_balance
  FROM public.customers c;
$func$;

GRANT EXECUTE ON FUNCTION public.get_customer_true_balances() TO authenticated, anon, service_role;

-- ============================================================================
-- 10.1 True Balances for Shipping Companies & Clearing Agents
-- ============================================================================
CREATE OR REPLACE FUNCTION public.get_shipping_company_true_balances()
RETURNS TABLE (
  shipping_company_id bigint,
  true_balance numeric
)
LANGUAGE sql
SECURITY DEFINER
AS $func$
  SELECT
    sc.id,
    (
      -- 1. Initial Balance
      (CASE WHEN sc.initial_balance_direction = 'CREDIT' THEN COALESCE(sc.initial_balance, 0) ELSE -COALESCE(sc.initial_balance, 0) END)
      
      -- 2. Shipment Cost Items (تكاليف الشحن)
      + COALESCE((
          SELECT SUM(sci.total_price / COALESCE(NULLIF(sci.exchange_rate, 0), 1.0))
          FROM public.shipment_cost_items sci
          WHERE (
            (sci.shipping_company_id IS NOT NULL AND sci.shipping_company_id = sc.id)
            OR
            (sci.vendor_type = 'shipping_company' AND sci.vendor_id = sc.id)
          )
        ), 0)
      
      -- 3. Treasury Transactions
      + COALESCE((SELECT SUM(amount) FROM public.treasury_transactions WHERE shipping_company_id = sc.id AND type IN ('deposit', 'receive', 'income') AND (status = 'confirmed' OR status IS NULL)), 0)
      - COALESCE((SELECT SUM(amount) FROM public.treasury_transactions WHERE shipping_company_id = sc.id AND type IN ('expense', 'shipping_company_payment', 'payment') AND (status = 'confirmed' OR status IS NULL)), 0)
      
      -- 4. Bank Transactions
      + COALESCE((SELECT SUM(amount) FROM public.bank_account_transactions WHERE entity_type = 'shipping_company' AND entity_id = sc.id::TEXT AND type IN ('deposit', 'receive', 'income') AND (status = 'confirmed' OR status IS NULL)), 0)
      - COALESCE((SELECT SUM(amount) FROM public.bank_account_transactions WHERE entity_type = 'shipping_company' AND entity_id = sc.id::TEXT AND type IN ('withdraw', 'withdrawal', 'expense', 'shipping_company_payment', 'payment') AND (status = 'confirmed' OR status IS NULL)), 0)
      
      -- 5. Cheques
      + COALESCE((SELECT SUM(amount) FROM public.cheques WHERE (shipping_company_id = sc.id OR (counterparty_type = 'shipping_company' AND counterparty_id = sc.id)) AND type = 'incoming' AND status IN ('cleared', 'collected')), 0)
      - COALESCE((SELECT SUM(amount) FROM public.cheques WHERE (shipping_company_id = sc.id OR (counterparty_type = 'shipping_company' AND counterparty_id = sc.id)) AND type = 'outgoing' AND status IN ('cleared', 'collected')), 0)

      -- 6. Direct Ledger Entries (excluding ones created for treasury/bank transactions already counted)
      + COALESCE((
          SELECT SUM(CASE WHEN entry_type = 'credit' THEN amount ELSE -amount END)
          FROM public.ledger_entries le
          WHERE le.entity_type = 'shipping_company' 
            AND le.entity_id = sc.id::text
            AND le.reference_type NOT IN ('shipment_cost_item', 'expense', 'receive')
            AND NOT (
                le.reference_type IN ('shipping_company_payment', 'treasury_deposit', 'treasury_withdrawal', 'treasury_transaction', 'cash_payment', 'receive', 'deposit')
                AND EXISTS (SELECT 1 FROM public.treasury_transactions tt WHERE tt.id::TEXT = le.reference_id::TEXT)
            )
            AND NOT (
                le.reference_type IN ('bank_payment', 'bank_receipt', 'bank_transaction', 'cheque', 'shipping_company_payment', 'receive', 'deposit')
                AND EXISTS (SELECT 1 FROM public.bank_account_transactions bt WHERE bt.id::TEXT = le.reference_id::TEXT)
            )
      ), 0)
    ) AS true_balance
  FROM public.shipping_companies sc;
$func$;

GRANT EXECUTE ON FUNCTION public.get_shipping_company_true_balances() TO authenticated, anon, service_role;

CREATE OR REPLACE FUNCTION public.get_clearing_agent_true_balances()
RETURNS TABLE (
  clearing_agent_id bigint,
  true_balance numeric
)
LANGUAGE sql
SECURITY DEFINER
AS $func$
  SELECT
    ca.id,
    (
      -- 1. Initial Balance
      (CASE WHEN ca.initial_balance_direction = 'CREDIT' THEN COALESCE(ca.initial_balance, 0) ELSE -COALESCE(ca.initial_balance, 0) END)
      
      -- 2. Shipment Cost Items (تكاليف التخليص)
      + COALESCE((
          SELECT SUM(sci.total_price / COALESCE(NULLIF(sci.exchange_rate, 0), 1.0))
          FROM public.shipment_cost_items sci
          WHERE (
            (sci.clearing_agent_id IS NOT NULL AND sci.clearing_agent_id = ca.id)
            OR
            (sci.vendor_type = 'clearing_agent' AND sci.vendor_id = ca.id)
          )
        ), 0)
      
      -- 3. Treasury Transactions
      + COALESCE((SELECT SUM(amount) FROM public.treasury_transactions WHERE clearing_agent_id = ca.id AND type IN ('deposit', 'receive', 'income') AND (status = 'confirmed' OR status IS NULL)), 0)
      - COALESCE((SELECT SUM(amount) FROM public.treasury_transactions WHERE clearing_agent_id = ca.id AND type IN ('expense', 'clearing_agent_payment', 'payment') AND (status = 'confirmed' OR status IS NULL)), 0)
      
      -- 4. Bank Transactions
      + COALESCE((SELECT SUM(amount) FROM public.bank_account_transactions WHERE entity_type = 'clearing_agent' AND entity_id = ca.id::TEXT AND type IN ('deposit', 'receive', 'income') AND (status = 'confirmed' OR status IS NULL)), 0)
      - COALESCE((SELECT SUM(amount) FROM public.bank_account_transactions WHERE entity_type = 'clearing_agent' AND entity_id = ca.id::TEXT AND type IN ('withdraw', 'withdrawal', 'expense', 'clearing_agent_payment', 'payment') AND (status = 'confirmed' OR status IS NULL)), 0)
      
      -- 5. Cheques
      + COALESCE((SELECT SUM(amount) FROM public.cheques WHERE (clearing_agent_id = ca.id OR (counterparty_type = 'clearing_agent' AND counterparty_id = ca.id)) AND type = 'incoming' AND status IN ('cleared', 'collected')), 0)
      - COALESCE((SELECT SUM(amount) FROM public.cheques WHERE (clearing_agent_id = ca.id OR (counterparty_type = 'clearing_agent' AND counterparty_id = ca.id)) AND type = 'outgoing' AND status IN ('cleared', 'collected')), 0)

      -- 6. Direct Ledger Entries (excluding ones created for treasury/bank transactions already counted)
      + COALESCE((
          SELECT SUM(CASE WHEN entry_type = 'credit' THEN amount ELSE -amount END)
          FROM public.ledger_entries le
          WHERE le.entity_type = 'clearing_agent' 
            AND le.entity_id = ca.id::text
            AND le.reference_type NOT IN ('shipment_cost_item', 'expense', 'receive')
            AND NOT (
                le.reference_type IN ('clearing_agent_payment', 'treasury_deposit', 'treasury_withdrawal', 'treasury_transaction', 'cash_payment', 'receive', 'deposit')
                AND EXISTS (SELECT 1 FROM public.treasury_transactions tt WHERE tt.id::TEXT = le.reference_id::TEXT)
            )
            AND NOT (
                le.reference_type IN ('bank_payment', 'bank_receipt', 'bank_transaction', 'cheque', 'clearing_agent_payment', 'receive', 'deposit')
                AND EXISTS (SELECT 1 FROM public.bank_account_transactions bt WHERE bt.id::TEXT = le.reference_id::TEXT)
            )
      ), 0)
    ) AS true_balance
  FROM public.clearing_agents ca;
$func$;

GRANT EXECUTE ON FUNCTION public.get_clearing_agent_true_balances() TO authenticated, anon, service_role;

-- ============================================================================
-- 10.5 View: v_journal_entry_lines (عرض أسطر القيود اليومية)
-- ============================================================================
DROP VIEW IF EXISTS public.v_journal_entry_lines CASCADE;

CREATE OR REPLACE VIEW public.v_journal_entry_lines AS
SELECT
    ale.id,
    ale.journal_entry_id,
    je.id AS entry_id,
    je.entry_number,
    je.entry_date AS transaction_date,
    ale.account_id,
    COALESCE(NULLIF(a.account_code, ''), NULLIF(a.code, ''), '') AS account_code,
    COALESCE(NULLIF(a.account_name, ''), NULLIF(a.name, ''), '') AS account_name,
    CASE WHEN ale.debit > 0 THEN 'debit' ELSE 'credit' END AS type,
    (CASE WHEN ale.debit > 0 THEN ale.debit ELSE ale.credit END) AS amount,
    ale.description,
    je.created_by,
    je.created_at,
    je.company_id,
    ale.debit,
    ale.credit,
    ale.currency,
    ale.amount_in_base_currency,
    je.source_type,
    je.source_id,
    je.status,
    ale.cost_center_id,
    COALESCE(cc.name_ar, cc.name, cc.code, ale.cost_center_id, '') AS cost_center_name,
    COALESCE(cc.code, ale.cost_center_id, '') AS cost_center_code,
    ale.entity_type,
    ale.entity_id,
    ale.branch_id,
    st.name AS branch_name,
    st.code AS branch_code
FROM public.account_ledger_entries ale
JOIN public.journal_entries je ON je.id = ale.journal_entry_id
LEFT JOIN public.accounts a ON a.id = ale.account_id
LEFT JOIN public.stations st ON st.id = ale.branch_id
LEFT JOIN public.cost_centers cc ON (
    cc.code = ale.cost_center_id 
    OR cc.code = 'CC-' || UPPER(ale.cost_center_id)
    OR (ale.cost_center_id = 'general_admin' AND cc.code = 'CC-ADMIN')
    OR (ale.cost_center_id = 'packing_station' AND cc.code = 'CC-PACKING')
    OR (ale.cost_center_id = 'freight_logistics' AND cc.code = 'CC-LOGISTICS')
    OR (ale.cost_center_id = 'customs_clearance' AND cc.code = 'CC-CUSTOMS')
    OR cc.id::TEXT = ale.cost_center_id
)
WHERE je.deleted_at IS NULL
  AND ale.deleted_at IS NULL;

GRANT SELECT ON public.v_journal_entry_lines TO authenticated, service_role, anon;

CREATE OR REPLACE VIEW public.journal_entry_lines AS
SELECT * FROM public.v_journal_entry_lines;

GRANT SELECT ON public.journal_entry_lines TO authenticated, service_role, anon;

-- RPC: Build and Post Cash Receipt Journal Entry
CREATE OR REPLACE FUNCTION public.rpc_build_cash_receipt_journal(payload jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_date date;
    v_amount numeric;
    v_mode text;
    v_customer_id bigint;
    v_supplier_id bigint;
    v_desc text;
    v_idempotency_key text;
    v_journal_id bigint;
    v_entry_number text;
    v_cash_account_id bigint;
    v_credit_account_id bigint;
BEGIN
    v_date := COALESCE((payload->>'date')::date, CURRENT_DATE);
    v_amount := (payload->>'amount')::numeric;
    v_mode := COALESCE(payload->>'mode', 'customer');
    v_customer_id := (payload->>'customer_id')::bigint;
    v_supplier_id := (payload->>'supplier_id')::bigint;
    v_desc := COALESCE(payload->>'description', 'سند قبض نقدي');
    v_idempotency_key := payload->>'idempotency_key';

    IF v_amount IS NULL OR v_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'المبلغ يجب أن يكون أكبر من صفر');
    END IF;

    IF v_idempotency_key IS NOT NULL THEN
        SELECT id, entry_number INTO v_journal_id, v_entry_number
        FROM public.journal_entries
        WHERE idempotency_key = v_idempotency_key
        LIMIT 1;

        IF FOUND THEN
            RETURN jsonb_build_object('success', true, 'journal_id', v_journal_id, 'journal_number', v_entry_number);
        END IF;
    END IF;

    SELECT id INTO v_cash_account_id
    FROM public.accounts
    WHERE (code = '12111' OR account_code = '12111' OR account_code = '12211' OR name LIKE '%صندوق%' OR name LIKE '%خزينة%')
      AND is_active = true
    ORDER BY id ASC LIMIT 1;

    IF v_cash_account_id IS NULL THEN
        SELECT id INTO v_cash_account_id FROM public.accounts WHERE is_active = true LIMIT 1;
    END IF;

    IF v_mode = 'customer' AND v_customer_id IS NOT NULL THEN
        SELECT account_id INTO v_credit_account_id FROM public.customers WHERE id = v_customer_id;
    ELSIF v_mode = 'supplier' AND v_supplier_id IS NOT NULL THEN
        SELECT account_id INTO v_credit_account_id FROM public.suppliers WHERE id = v_supplier_id;
    END IF;

    IF v_credit_account_id IS NULL THEN
        SELECT id INTO v_credit_account_id FROM public.accounts WHERE (code = '12511' OR account_code = '12511') LIMIT 1;
    END IF;

    v_entry_number := 'CR-' || to_char(now(), 'YYYYMMDD') || '-' || lpad((nextval('public.journal_entries_id_seq'::regclass) % 10000)::text, 4, '0');

    INSERT INTO public.journal_entries (
        entry_number, entry_date, description, status, source_type, source_id, idempotency_key
    ) VALUES (
        v_entry_number, v_date, v_desc, 'posted', 'cash_receipt', 
        CASE WHEN v_customer_id IS NOT NULL THEN 'customers_' || v_customer_id::text ELSE NULL END,
        v_idempotency_key
    ) RETURNING id INTO v_journal_id;

    INSERT INTO public.account_ledger_entries (
        journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description
    ) VALUES (
        v_journal_id, v_cash_account_id, v_amount, 0, 'EGP', v_amount, v_desc
    );

    INSERT INTO public.account_ledger_entries (
        journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description,
        entity_type, entity_id
    ) VALUES (
        v_journal_id, v_credit_account_id, 0, v_amount, 'EGP', v_amount, v_desc,
        CASE WHEN v_customer_id IS NOT NULL THEN 'customer' WHEN v_supplier_id IS NOT NULL THEN 'supplier' ELSE NULL END,
        CASE WHEN v_customer_id IS NOT NULL THEN v_customer_id::text WHEN v_supplier_id IS NOT NULL THEN v_supplier_id::text ELSE NULL END
    );

    RETURN jsonb_build_object(
        'success', true,
        'journal_id', v_journal_id,
        'journal_number', v_entry_number
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_build_cash_receipt_journal(jsonb) TO authenticated, service_role, anon;

-- RPC: Build and Post Cash Payment Journal Entry
CREATE OR REPLACE FUNCTION public.rpc_build_cash_payment_journal(payload jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_date date;
    v_amount numeric;
    v_mode text;
    v_customer_id bigint;
    v_supplier_id bigint;
    v_desc text;
    v_idempotency_key text;
    v_journal_id bigint;
    v_entry_number text;
    v_cash_account_id bigint;
    v_debit_account_id bigint;
BEGIN
    v_date := COALESCE((payload->>'date')::date, CURRENT_DATE);
    v_amount := (payload->>'amount')::numeric;
    v_mode := COALESCE(payload->>'mode', 'supplier');
    v_customer_id := (payload->>'customer_id')::bigint;
    v_supplier_id := (payload->>'supplier_id')::bigint;
    v_desc := COALESCE(payload->>'description', 'سند صرف نقدي');
    v_idempotency_key := payload->>'idempotency_key';

    IF v_amount IS NULL OR v_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'المبلغ يجب أن يكون أكبر من صفر');
    END IF;

    IF v_idempotency_key IS NOT NULL THEN
        SELECT id, entry_number INTO v_journal_id, v_entry_number
        FROM public.journal_entries
        WHERE idempotency_key = v_idempotency_key
        LIMIT 1;

        IF FOUND THEN
            RETURN jsonb_build_object('success', true, 'journal_id', v_journal_id, 'journal_number', v_entry_number);
        END IF;
    END IF;

    SELECT id INTO v_cash_account_id
    FROM public.accounts
    WHERE (code = '12111' OR account_code = '12111' OR account_code = '12211' OR name LIKE '%صندوق%' OR name LIKE '%خزينة%')
      AND is_active = true
    ORDER BY id ASC LIMIT 1;

    IF v_cash_account_id IS NULL THEN
        SELECT id INTO v_cash_account_id FROM public.accounts WHERE is_active = true LIMIT 1;
    END IF;

    IF v_mode = 'customer' AND v_customer_id IS NOT NULL THEN
        SELECT account_id INTO v_debit_account_id FROM public.customers WHERE id = v_customer_id;
    ELSIF v_mode = 'supplier' AND v_supplier_id IS NOT NULL THEN
        SELECT account_id INTO v_debit_account_id FROM public.suppliers WHERE id = v_supplier_id;
    END IF;

    IF v_debit_account_id IS NULL THEN
        IF v_mode = 'customer' THEN
            SELECT id INTO v_debit_account_id FROM public.accounts WHERE (code = '12511' OR account_code = '12511') LIMIT 1;
        ELSE
            SELECT id INTO v_debit_account_id FROM public.accounts WHERE (code = '21111' OR account_code = '21111') LIMIT 1;
        END IF;
    END IF;

    v_entry_number := 'CP-' || to_char(now(), 'YYYYMMDD') || '-' || lpad((nextval('public.journal_entries_id_seq'::regclass) % 10000)::text, 4, '0');

    INSERT INTO public.journal_entries (
        entry_number, entry_date, description, status, source_type, source_id, idempotency_key
    ) VALUES (
        v_entry_number, v_date, v_desc, 'posted', 'cash_payment',
        CASE WHEN v_customer_id IS NOT NULL THEN 'customers_' || v_customer_id::text WHEN v_supplier_id IS NOT NULL THEN 'suppliers_' || v_supplier_id::text ELSE NULL END,
        v_idempotency_key
    ) RETURNING id INTO v_journal_id;

    INSERT INTO public.account_ledger_entries (
        journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description,
        entity_type, entity_id
    ) VALUES (
        v_journal_id, v_debit_account_id, v_amount, 0, 'EGP', v_amount, v_desc,
        CASE WHEN v_customer_id IS NOT NULL THEN 'customer' WHEN v_supplier_id IS NOT NULL THEN 'supplier' ELSE NULL END,
        CASE WHEN v_customer_id IS NOT NULL THEN v_customer_id::text WHEN v_supplier_id IS NOT NULL THEN v_supplier_id::text ELSE NULL END
    );

    INSERT INTO public.account_ledger_entries (
        journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description
    ) VALUES (
        v_journal_id, v_cash_account_id, 0, v_amount, 'EGP', v_amount, v_desc
    );

    RETURN jsonb_build_object(
        'success', true,
        'journal_id', v_journal_id,
        'journal_number', v_entry_number
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_build_cash_payment_journal(jsonb) TO authenticated, service_role, anon;

-- ============================================================================
-- 11. ترتيب دفتر قيود اليومية حسب الأحدث إضافة (created_at DESC)
-- ============================================================================
CREATE OR REPLACE FUNCTION rpc_get_journal_history(
    p_search text DEFAULT NULL,
    p_from_date date DEFAULT NULL,
    p_to_date date DEFAULT NULL,
    p_limit int DEFAULT 300
)
RETURNS SETOF v_journal_entry_lines AS $$
BEGIN
  IF p_search IS NULL OR p_search = '' THEN
    RETURN QUERY
    WITH latest AS (
      SELECT id 
      FROM journal_entries 
      WHERE deleted_at IS NULL
        AND (p_from_date IS NULL OR entry_date >= p_from_date)
        AND (p_to_date IS NULL OR entry_date <= p_to_date)
      ORDER BY created_at DESC, id DESC 
      LIMIT p_limit
    )
    SELECT v.*
    FROM v_journal_entry_lines v
    JOIN latest l ON l.id = v.entry_id
    ORDER BY v.created_at DESC, v.entry_id DESC, v.id ASC;
  ELSE
    RETURN QUERY
    WITH matched_entries AS (
      SELECT entry_id
      FROM v_journal_entry_lines
      WHERE (p_from_date IS NULL OR transaction_date >= p_from_date)
        AND (p_to_date IS NULL OR transaction_date <= p_to_date)
        AND (
          entry_number ILIKE '%' || p_search || '%'
          OR account_name ILIKE '%' || p_search || '%'
          OR account_code ILIKE '%' || p_search || '%'
          OR description ILIKE '%' || p_search || '%'
        )
      GROUP BY entry_id
      ORDER BY MAX(created_at) DESC, entry_id DESC
      LIMIT p_limit
    )
    SELECT v.*
    FROM v_journal_entry_lines v
    JOIN matched_entries m ON m.entry_id = v.entry_id
    ORDER BY v.created_at DESC, v.entry_id DESC, v.id ASC;
  END IF;
END;
$$ LANGUAGE plpgsql;

GRANT EXECUTE ON FUNCTION rpc_get_journal_history(text, date, date, int) TO authenticated, service_role, anon;

-- ============================================================================
-- 12. دوال تسوية أسعار بنود أوامر التعبئة وقفل الأرباح الموزعة
-- ============================================================================
CREATE OR REPLACE FUNCTION public.rpc_get_orders_with_distributed_shipments()
RETURNS SETOF BIGINT
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    SELECT DISTINCT esi.packing_order_id
    FROM public.export_shipment_items esi
    JOIN public.shareholder_profit_distributions spd ON spd.shipment_id = esi.shipment_id
    WHERE esi.packing_order_id IS NOT NULL
      AND spd.deleted_at IS NULL;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_get_orders_with_distributed_shipments() TO authenticated;

DROP FUNCTION IF EXISTS public.rpc_apply_packing_order_item_debit_note(BIGINT, TEXT, BIGINT, BIGINT, NUMERIC, TEXT, UUID);
DROP FUNCTION IF EXISTS public.rpc_apply_packing_order_item_debit_note(BIGINT, TEXT, BIGINT, NUMERIC, TEXT, UUID);
DROP FUNCTION IF EXISTS public.rpc_apply_packing_order_item_debit_note(BIGINT, TEXT, BIGINT, NUMERIC, UUID, TEXT);
DROP FUNCTION IF EXISTS public.rpc_apply_packing_order_item_debit_note(BIGINT, TEXT, BIGINT, NUMERIC, UUID, TEXT, UUID);
DROP FUNCTION IF EXISTS public.rpc_apply_packing_order_item_debit_note(BIGINT, TEXT, BIGINT, NUMERIC, UUID, TEXT, BIGINT, UUID);
DROP FUNCTION IF EXISTS public.rpc_apply_packing_order_item_debit_note(BIGINT, TEXT, BIGINT, NUMERIC, UUID, TEXT, BIGINT, UUID, TEXT);

CREATE OR REPLACE FUNCTION public.rpc_apply_packing_order_item_debit_note(
    p_order_id BIGINT,
    p_item_type TEXT,                -- 'material' or 'crop'
    p_batch_id BIGINT DEFAULT 0,     -- station_product_batch_id or lot_id
    p_discount_amount NUMERIC DEFAULT 0, -- Total discount amount in EGP (base currency)
    p_supplier_id UUID DEFAULT NULL, -- Explicit supplier UUID (or auto-resolved)
    p_reason TEXT DEFAULT 'تسوية سعر / إشعار خصم مورد',
    p_item_id BIGINT DEFAULT NULL,   -- Optional
    p_user_id UUID DEFAULT auth.uid(),
    p_item_name TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_order RECORD;
    v_notes JSONB;
    v_materials JSONB;
    v_new_materials JSONB := '[]'::jsonb;
    v_elem JSONB;
    v_found BOOLEAN := false;
    v_company_id UUID;
    v_source_account_id BIGINT;
    v_dest_account_id BIGINT;
    v_dest_account_code TEXT := '1031';
    v_is_shipped BOOLEAN := false;
    v_je_id BIGINT;
    v_entry_num TEXT;
    v_entry_date DATE;
    v_old_mat_cost NUMERIC;
    v_new_mat_cost NUMERIC;
    v_new_fruit_cost NUMERIC;
    v_new_total_pkg_cost NUMERIC;
    v_new_cost_per_carton NUMERIC;
    v_carton_count INT;
    v_supplier_uuid UUID := p_supplier_id;
    v_supplier_name TEXT := '';
    v_supplier_currency TEXT := 'EGP';
    v_exchange_rate NUMERIC := 1.0;
    v_foreign_discount NUMERIC;
    v_applied NUMERIC;
    v_old_total NUMERIC;
    v_new_total NUMERIC;
    v_qty NUMERIC;
    v_cost_center_id TEXT;
    v_cost_center_name TEXT;
    v_cost_center_type TEXT := 'operational';
    v_item_name TEXT := 'بند أمر تعبئة';
    v_category TEXT := 'مواد التعبئة';
BEGIN
    -- 1. Validate & Lock Packing Order
    SELECT * INTO v_order FROM public.packing_orders WHERE id = p_order_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'أمر التعبئة غير موجود');
    END IF;

    IF p_discount_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'مبلغ الخصم يجب أن يكون أكبر من الصفر');
    END IF;

    -- 2. Check Profit Distribution Lock
    IF EXISTS (
        SELECT 1 
        FROM public.export_shipment_items esi
        JOIN public.shareholder_profit_distributions spd ON spd.shipment_id = esi.shipment_id
        WHERE esi.packing_order_id = p_order_id
          AND spd.deleted_at IS NULL
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'تم توزيع أرباح الشحنة المرتبطة بهذا الأمر على المساهمين - لا يمكن تعديل الأسعار أو التكاليف');
    END IF;

    v_company_id := v_order.company_id;
    IF v_company_id IS NULL THEN
        SELECT id INTO v_company_id FROM public.sys_companies LIMIT 1;
    END IF;

    v_entry_date := (NOW() AT TIME ZONE 'Africa/Cairo')::DATE;

    -- 3. Auto-resolve Supplier UUID if not explicitly provided
    IF v_supplier_uuid IS NULL THEN
        IF p_item_type = 'material' AND p_batch_id > 0 THEN
            SELECT supplier_id INTO v_supplier_uuid
            FROM public.station_product_batches
            WHERE id = p_batch_id;

            IF v_supplier_uuid IS NULL THEN
                SELECT pi.supplier_id INTO v_supplier_uuid
                FROM public.station_product_batches spb
                JOIN public.purchase_invoices pi ON pi.id = spb.purchase_invoice_id
                WHERE spb.id = p_batch_id;
            END IF;
        END IF;

        IF v_supplier_uuid IS NULL AND v_order.lot_id IS NOT NULL THEN
            SELECT supplier_id INTO v_supplier_uuid
            FROM public.lot_receipts
            WHERE id = v_order.lot_id;

            IF v_supplier_uuid IS NULL THEN
                SELECT supplier_id INTO v_supplier_uuid
                FROM public.lots
                WHERE id = v_order.lot_id;
            END IF;
        END IF;

        IF v_supplier_uuid IS NULL THEN
            SELECT id INTO v_supplier_uuid FROM public.suppliers LIMIT 1;
        END IF;
    END IF;

    -- 4. Load Supplier details
    IF v_supplier_uuid IS NOT NULL THEN
        SELECT name, COALESCE(currency, 'EGP')
        INTO v_supplier_name, v_supplier_currency
        FROM public.suppliers
        WHERE id = v_supplier_uuid;

        v_exchange_rate := COALESCE(public.fn_get_exchange_rate(v_supplier_currency), 1.0);
    END IF;

    IF v_supplier_name IS NULL OR v_supplier_name = '' THEN
        v_supplier_name := 'المورد المرتبط';
    END IF;

    -- 5. Identify Accounts
    BEGIN
        SELECT account_id INTO v_source_account_id
        FROM public.suppliers
        WHERE id = v_supplier_uuid;
    EXCEPTION WHEN OTHERS THEN
        v_source_account_id := NULL;
    END;

    IF v_source_account_id IS NULL THEN
        v_source_account_id := public.resolve_gl_account('2001', v_company_id);
    END IF;
    IF v_source_account_id IS NULL THEN
        v_source_account_id := public.resolve_gl_account('2000', v_company_id);
    END IF;
    IF v_source_account_id IS NULL THEN
        v_source_account_id := public.resolve_gl_account('2112', v_company_id);
    END IF;
    IF v_source_account_id IS NULL THEN
        SELECT id INTO v_source_account_id FROM public.accounts WHERE account_code IN ('2112', '2001', '2000') LIMIT 1;
    END IF;
    IF v_source_account_id IS NULL THEN
        SELECT id INTO v_source_account_id FROM public.accounts WHERE account_type = 'liability' LIMIT 1;
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM public.export_shipment_items WHERE packing_order_id = p_order_id
    ) INTO v_is_shipped;

    IF v_is_shipped THEN
        v_dest_account_id := public.resolve_gl_account('3111', v_company_id);
        IF v_dest_account_id IS NULL THEN
            v_dest_account_id := public.resolve_gl_account('5000', v_company_id);
        END IF;
        IF v_dest_account_id IS NULL THEN
            SELECT id INTO v_dest_account_id FROM public.accounts WHERE account_code IN ('3111', '5000', '5101', '3110') LIMIT 1;
        END IF;
        IF v_dest_account_id IS NULL THEN
            SELECT id INTO v_dest_account_id FROM public.accounts WHERE account_type IN ('cost_of_goods_sold', 'expense') LIMIT 1;
        END IF;
    ELSE
        IF p_item_type = 'material' THEN
            v_dest_account_id := public.resolve_gl_account('12411', v_company_id);
            IF v_dest_account_id IS NULL THEN
                v_dest_account_id := public.resolve_gl_account('1040', v_company_id);
            END IF;
        ELSE
            v_dest_account_id := public.resolve_gl_account('12412', v_company_id);
            IF v_dest_account_id IS NULL THEN
                v_dest_account_id := public.resolve_gl_account('1030', v_company_id);
            END IF;
        END IF;

        IF v_dest_account_id IS NULL THEN
            v_dest_account_id := public.resolve_gl_account('12413', v_company_id);
        END IF;
        IF v_dest_account_id IS NULL THEN
            v_dest_account_id := public.resolve_gl_account('1031', v_company_id);
        END IF;
        IF v_dest_account_id IS NULL THEN
            SELECT id INTO v_dest_account_id FROM public.accounts WHERE account_code IN ('12413', '1031', '12411', '1040', '12412', '1030') LIMIT 1;
        END IF;
        IF v_dest_account_id IS NULL THEN
            SELECT id INTO v_dest_account_id FROM public.accounts WHERE account_type = 'asset' LIMIT 1;
        END IF;
    END IF;

    IF v_source_account_id IS NULL OR v_dest_account_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'تعذر تحديد حسابات اليومية (حساب المورد أو حساب المخزون/التكلفة)');
    END IF;

    -- 6. Resolve Cost Center & Item Details
    BEGIN
        v_notes := v_order.notes::jsonb;
    EXCEPTION WHEN OTHERS THEN
        v_notes := '{}'::jsonb;
    END;

    IF p_item_type = 'material' THEN
        v_category := 'مواد التعبئة';
        v_cost_center_type := 'operational';
        
        IF v_notes ? 'materials' AND jsonb_typeof(v_notes->'materials') = 'array' THEN
            FOR v_elem IN SELECT * FROM jsonb_array_elements(v_notes->'materials')
            LOOP
                IF (p_batch_id > 0 AND COALESCE((v_elem->>'batch_id')::bigint, 0) = p_batch_id) OR
                   (p_item_id IS NOT NULL AND (v_elem->>'id')::text = p_item_id::text) OR
                   (p_item_name IS NOT NULL AND p_item_name <> '' AND (
                       COALESCE(v_elem->>'product_name', v_elem->>'name', v_elem->>'item_name') = p_item_name
                   )) OR
                   (jsonb_array_length(v_notes->'materials') = 1) THEN
                    v_cost_center_id := NULLIF(v_elem->>'cost_center_id', '');
                    v_cost_center_name := NULLIF(v_elem->>'cost_center_name', '');
                    v_item_name := COALESCE(NULLIF(v_elem->>'product_name', ''), NULLIF(v_elem->>'item_name', ''), NULLIF(v_elem->>'name', ''), p_item_name, 'مواد تعبئة');
                    EXIT;
                END IF;
            END LOOP;
        END IF;

        IF v_cost_center_id IS NULL THEN
            SELECT code, COALESCE(name_ar, name)
            INTO v_cost_center_id, v_cost_center_name
            FROM public.cost_centers
            WHERE code = 'CC-PACKING' OR code = 'packing_station'
            LIMIT 1;
        END IF;

        IF v_cost_center_id IS NULL THEN
            v_cost_center_id := 'CC-PACKING';
            v_cost_center_name := 'محطة التعبئة والتجهيز';
        END IF;
    ELSIF p_item_type = 'crop' THEN
        v_category := 'تكلفة المحاصيل';
        v_cost_center_type := 'variety';
        v_item_name := COALESCE(v_order.product_name, 'محصول');

        SELECT code, COALESCE(name_ar, name)
        INTO v_cost_center_id, v_cost_center_name
        FROM public.cost_centers
        WHERE (product_id = v_order.fruit_type_id OR name_ar = v_order.product_name OR crop_name = v_order.product_name)
          AND cost_center_type = 'variety'
        LIMIT 1;

        IF v_cost_center_id IS NULL THEN
            SELECT code, COALESCE(name_ar, name)
            INTO v_cost_center_id, v_cost_center_name
            FROM public.cost_centers
            WHERE cost_center_type = 'variety'
            LIMIT 1;
        END IF;

        IF v_cost_center_id IS NULL THEN
            v_cost_center_id := 'CC-CROP';
            v_cost_center_name := 'تكلفة المحاصيل';
        END IF;
    END IF;

    -- 7. Generate Journal Entry
    v_foreign_discount := ROUND(p_discount_amount / GREATEST(v_exchange_rate, 0.0001), 2);

    INSERT INTO public.journal_entries (
        entry_number, entry_date, description, status,
        is_auto_generated, source_type, source_id, company_id,
        created_by, created_at, updated_at
    ) VALUES (
        'PENDING',
        v_entry_date,
        'إشعار خصم مورد على أمر تعبئة رقم ' || p_order_id::text || ' - مورد: ' || COALESCE(v_supplier_name, '') || ' - ' || COALESCE(p_reason, ''),
        'posted', true, 'packing_debit_note', p_order_id::text, v_company_id,
        COALESCE(p_user_id, auth.uid()), now(), now()
    ) RETURNING id INTO v_je_id;

    v_entry_num := public.fn_get_next_sequence(v_company_id, 'packing_debit_note', NULL, NULL);
    IF v_entry_num IS NULL OR v_entry_num = '' THEN
        v_entry_num := 'DN-' || LPAD(v_je_id::text, 5, '0');
    END IF;
    UPDATE public.journal_entries SET entry_number = v_entry_num WHERE id = v_je_id;

    -- DR: Supplier account (decreases payable)
    INSERT INTO public.account_ledger_entries (
        journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id, cost_center_id
    ) VALUES (
        v_je_id, v_source_account_id, v_foreign_discount, 0, v_supplier_currency, p_discount_amount,
        'إشعار خصم من المورد ' || COALESCE(v_supplier_name, '') || ' لأمر تعبئة #' || p_order_id::text,
        v_company_id, v_cost_center_id
    );

    -- CR: Inventory or COGS (reduces cost)
    INSERT INTO public.account_ledger_entries (
        journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id, cost_center_id
    ) VALUES (
        v_je_id, v_dest_account_id, 0, p_discount_amount, 'EGP', p_discount_amount,
        'تخفيض تكلفة الإنتاج لأمر تعبئة #' || p_order_id::text || ' بإشعار خصم مورد ' || COALESCE(v_supplier_name, ''),
        v_company_id, v_cost_center_id
    );

    -- Update Supplier Subledger & Account Statement
    IF v_supplier_uuid IS NOT NULL THEN
        UPDATE public.suppliers
        SET outstanding_balance = GREATEST(0, COALESCE(outstanding_balance, 0) - p_discount_amount),
            current_balances_by_currency = jsonb_set(
                COALESCE(current_balances_by_currency, '{}'::jsonb),
                array[v_supplier_currency],
                to_jsonb(COALESCE((current_balances_by_currency->>v_supplier_currency)::numeric, 0) - v_foreign_discount)
            ),
            updated_at = now()
        WHERE id = v_supplier_uuid;

        INSERT INTO public.ledger_entries (
            entity_type,
            entity_id,
            entry_type,
            amount,
            currency,
            reference_type,
            reference_id,
            reference_text,
            description,
            created_by,
            created_at
        ) VALUES (
            'supplier',
            v_supplier_uuid::text,
            'debit',
            v_foreign_discount,
            v_supplier_currency,
            'packing_order_debit_note',
            p_order_id,
            v_entry_num,
            'إشعار خصم وتسوية أمر تعبئة #' || p_order_id::text || ' - مورد: ' || COALESCE(v_supplier_name, '') || ' (' || COALESCE(p_reason, '') || ')',
            COALESCE(p_user_id, auth.uid()),
            now()
        );
    END IF;

    -- Sync into Cost Center Transactions
    IF v_cost_center_id IS NOT NULL THEN
        INSERT INTO public.cost_center_transactions (
            cost_center_id,
            cost_center_name,
            cost_center_type,
            source_type,
            source_id,
            transaction_date,
            supplier_id,
            supplier_name,
            item_name,
            category,
            quantity,
            unit_price,
            currency,
            exchange_rate,
            total_in_currency,
            amount,
            notes,
            is_confirmed
        ) VALUES (
            v_cost_center_id,
            v_cost_center_name,
            v_cost_center_type,
            'packing_debit_note',
            'pkdn_' || p_order_id::text || '_' || v_je_id::text,
            v_entry_date,
            v_supplier_uuid::text,
            v_supplier_name,
            'إشعار خصم تسوية - ' || v_item_name,
            v_category,
            0,
            0,
            v_supplier_currency,
            v_exchange_rate,
            -v_foreign_discount,
            -p_discount_amount,
            'إشعار خصم وتسوية أمر تعبئة #' || p_order_id::text || ' - مورد: ' || COALESCE(v_supplier_name, '') || ' (' || COALESCE(p_reason, '') || ')',
            true
        ) ON CONFLICT (source_type, source_id) DO UPDATE SET
            cost_center_id = EXCLUDED.cost_center_id,
            cost_center_name = EXCLUDED.cost_center_name,
            cost_center_type = EXCLUDED.cost_center_type,
            supplier_id = EXCLUDED.supplier_id,
            supplier_name = EXCLUDED.supplier_name,
            item_name = EXCLUDED.item_name,
            category = EXCLUDED.category,
            currency = EXCLUDED.currency,
            exchange_rate = EXCLUDED.exchange_rate,
            total_in_currency = EXCLUDED.total_in_currency,
            amount = EXCLUDED.amount,
            notes = EXCLUDED.notes,
            updated_at = now();
    END IF;

    -- Recalculate Packing Order Costs & Update JSON Notes
    v_carton_count := GREATEST(1, COALESCE(v_order.carton_count, 1));
    v_new_total_pkg_cost := GREATEST(0, COALESCE(v_order.total_packing_cost, 0) - p_discount_amount);
    v_new_cost_per_carton := ROUND(v_new_total_pkg_cost / v_carton_count, 2);

    BEGIN
        v_notes := v_order.notes::jsonb;
    EXCEPTION WHEN OTHERS THEN
        v_notes := '{}'::jsonb;
    END;

    IF p_item_type = 'material' THEN
        v_new_mat_cost := GREATEST(0, COALESCE(v_order.actual_material_cost, 0) - p_discount_amount);
        
        IF v_notes ? 'materials' AND jsonb_typeof(v_notes->'materials') = 'array' THEN
            FOR v_elem IN SELECT * FROM jsonb_array_elements(v_notes->'materials')
            LOOP
                IF NOT v_found AND (
                    (p_batch_id > 0 AND COALESCE((v_elem->>'batch_id')::bigint, 0) = p_batch_id) OR
                    (p_item_id IS NOT NULL AND (v_elem->>'id')::text = p_item_id::text) OR
                    (p_item_name IS NOT NULL AND p_item_name <> '' AND (
                        COALESCE(v_elem->>'product_name', v_elem->>'name', v_elem->>'item_name') = p_item_name
                    )) OR
                    (jsonb_array_length(v_notes->'materials') = 1)
                ) THEN
                    v_found := true;
                    v_applied := COALESCE(NULLIF(v_elem->>'discount_applied', '')::numeric, 0) + p_discount_amount;
                    v_qty := GREATEST(1, COALESCE(
                        NULLIF(v_elem->>'used_qty', '')::numeric,
                        NULLIF(v_elem->>'quantity', '')::numeric,
                        1
                    ));
                    v_old_total := COALESCE(
                        NULLIF(v_elem->>'total', '')::numeric,
                        NULLIF(v_elem->>'total_cost', '')::numeric,
                        ROUND(v_qty * COALESCE(NULLIF(v_elem->>'unit_cost', '')::numeric, NULLIF(v_elem->>'cost', '')::numeric, 0), 2)
                    );
                    v_new_total := GREATEST(0, v_old_total - p_discount_amount);
                    
                    v_elem := v_elem || jsonb_build_object(
                        'discount_applied', v_applied,
                        'total', v_new_total,
                        'total_cost', v_new_total,
                        'unit_cost', ROUND(v_new_total / v_qty, 3),
                        'cost', ROUND(v_new_total / v_qty, 3),
                        'supplier_name', v_supplier_name,
                        'supplier_id', v_supplier_uuid
                    );
                END IF;
                v_new_materials := v_new_materials || jsonb_build_array(v_elem);
            END LOOP;
            v_notes := v_notes || jsonb_build_object('materials', v_new_materials);
        END IF;

        UPDATE public.packing_orders
        SET actual_material_cost = v_new_mat_cost,
            total_packing_cost = v_new_total_pkg_cost,
            packing_cost_per_carton = v_new_cost_per_carton,
            notes = v_notes::text
        WHERE id = p_order_id;

        UPDATE public.packing_order_lines
        SET final_cost = ROUND(v_new_cost_per_carton * carton_count, 2),
            final_unit_cost = v_new_cost_per_carton
        WHERE packing_order_id = p_order_id;

    ELSIF p_item_type = 'crop' THEN
        v_new_fruit_cost := GREATEST(0, COALESCE(v_order.fruit_cost_allocated, 0) - p_discount_amount);

        UPDATE public.packing_orders
        SET fruit_cost_allocated = v_new_fruit_cost,
            fruit_cost_base = GREATEST(0, COALESCE(fruit_cost_base, 0) - p_discount_amount),
            total_packing_cost = v_new_total_pkg_cost,
            packing_cost_per_carton = v_new_cost_per_carton
        WHERE id = p_order_id;

        UPDATE public.packing_order_lines
        SET final_cost = ROUND(v_new_cost_per_carton * carton_count, 2),
            final_unit_cost = v_new_cost_per_carton
        WHERE packing_order_id = p_order_id;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'journal_entry_id', v_je_id,
        'entry_number', v_entry_num,
        'discount_amount', p_discount_amount,
        'new_packing_cost_per_carton', v_new_cost_per_carton,
        'new_total_packing_cost', v_new_total_pkg_cost,
        'new_actual_material_cost', v_new_mat_cost,
        'supplier_name', v_supplier_name,
        'cost_center_id', v_cost_center_id,
        'cost_center_name', v_cost_center_name
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_apply_packing_order_item_debit_note(BIGINT, TEXT, BIGINT, NUMERIC, UUID, TEXT, BIGINT, UUID, TEXT) TO authenticated, anon, service_role;

-- ── 1. Ensure Discount Account exists under Level 3 (411 - إيرادات النشاط) ──
DO $$
DECLARE
  v_comp uuid;
  v_p411 bigint;
BEGIN
  SELECT company_id INTO v_comp FROM public.accounts WHERE company_id IS NOT NULL LIMIT 1;
  IF v_comp IS NULL THEN v_comp := 'a0000000-0000-0000-0000-000000000001'::uuid; END IF;

  SELECT id INTO v_p411 FROM public.accounts WHERE account_code = '411' LIMIT 1;
  IF v_p411 IS NULL THEN
    SELECT id INTO v_p411 FROM public.accounts WHERE account_code = '41' LIMIT 1;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.accounts WHERE account_code = '41131') THEN
    INSERT INTO public.accounts (
      account_code, name, account_name, parent_id,
      account_type, is_leaf, allow_posting, is_active, company_id, level
    ) VALUES (
      '41131', 'Sales Discounts - Export', 'خصم مسموح به - مبيعات تصدير',
      v_p411, 'revenue', true, true, true, v_comp, 5
    );
  END IF;
END $$;

-- ── 2. Ensure Required Columns Exist on Tables ──
ALTER TABLE public.export_shipments ADD COLUMN IF NOT EXISTS destination_country text;
ALTER TABLE public.export_shipments ADD COLUMN IF NOT EXISTS internal_notes text;
ALTER TABLE public.export_shipments ADD COLUMN IF NOT EXISTS notes text;
ALTER TABLE public.export_shipments ADD COLUMN IF NOT EXISTS paid_amount numeric DEFAULT 0;
ALTER TABLE public.export_shipments ADD COLUMN IF NOT EXISTS payment_source_type text DEFAULT 'treasury';
ALTER TABLE public.export_shipments ADD COLUMN IF NOT EXISTS payment_treasury_id text;
ALTER TABLE public.export_shipments ADD COLUMN IF NOT EXISTS payment_bank_account_id bigint;
ALTER TABLE public.export_shipments ADD COLUMN IF NOT EXISTS is_confirmed boolean DEFAULT false;
ALTER TABLE public.export_shipments ADD COLUMN IF NOT EXISTS allocated_admin_expenses numeric DEFAULT 0;
ALTER TABLE public.export_shipments ADD COLUMN IF NOT EXISTS allocated_taxes numeric DEFAULT 0;
ALTER TABLE public.export_shipments ADD COLUMN IF NOT EXISTS discount_amount numeric DEFAULT 0;
ALTER TABLE public.export_shipments ADD COLUMN IF NOT EXISTS discount_reason text;
ALTER TABLE public.export_shipments ADD COLUMN IF NOT EXISTS applied_discount_amount numeric DEFAULT 0;
ALTER TABLE public.export_shipments ADD COLUMN IF NOT EXISTS updated_at timestamp with time zone DEFAULT now();

ALTER TABLE public.export_shipment_items ADD COLUMN IF NOT EXISTS packing_order_line_id bigint;
ALTER TABLE public.export_shipment_items ADD COLUMN IF NOT EXISTS export_price_per_carton numeric;
ALTER TABLE public.export_shipment_items ADD COLUMN IF NOT EXISTS invoice_product_name text DEFAULT '';
ALTER TABLE public.export_shipment_items ADD COLUMN IF NOT EXISTS currency_snapshot jsonb;

-- ── 3. Update rpc_process_export_shipment_ledger ──
CREATE OR REPLACE FUNCTION public.rpc_process_export_shipment_ledger(
  p_shipment_id bigint,
  p_user_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_shipment RECORD;
  v_total_revenue numeric := 0;
  v_discount numeric := 0;
  v_paid numeric := 0;
  v_net_revenue numeric := 0;
  v_desc text;
  v_old_amount numeric := 0;
  v_company_id uuid;
  v_ar_acct bigint;
  v_rev_acct bigint;
  v_disc_acct bigint;
  v_cogs_acct bigint;
  v_inv_acct bigint;
  v_pay_acct bigint;
  v_sale_lines jsonb;
  v_sale_je_id bigint;
  v_cogs_je_id bigint;
  v_pay_je_id bigint;
  v_je_id bigint;
  v_raw_ar bigint;
  v_base_revenue numeric := 0;
  v_base_discount numeric := 0;
  v_base_net numeric := 0;
  v_base_paid numeric := 0;
  v_exch_rate numeric := 1.0;
  v_cogs_amount numeric := 0;
  v_entry_date date;
  v_customer_name text;
  v_currency text;
  v_revenue_code text;
BEGIN
  -- 1. Get Matching Company ID from accounts table
  SELECT company_id INTO v_company_id FROM public.accounts WHERE company_id IS NOT NULL LIMIT 1;
  IF v_company_id IS NULL THEN 
    v_company_id := 'a0000000-0000-0000-0000-000000000001'::uuid;
  END IF;

  -- 2. Fetch Export Shipment
  SELECT * INTO v_shipment
  FROM public.export_shipments
  WHERE id = p_shipment_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'الشحنة غير موجودة');
  END IF;

  IF v_shipment.customer_id IS NULL THEN
    RETURN jsonb_build_object('success', true, 'message', 'لا يوجد عميل مخصص للشحنة');
  END IF;

  -- 3. Calculate Revenue from Items
  SELECT COALESCE(
    SUM(COALESCE(NULLIF(amount, 0), quantity * COALESCE(export_price_per_carton, price, 0))),
    0
  )
  INTO v_total_revenue
  FROM public.export_shipment_items
  WHERE shipment_id = p_shipment_id;

  IF v_total_revenue = 0 THEN
    v_total_revenue := COALESCE(v_shipment.total_revenue_foreign, 0);
  END IF;

  v_discount := COALESCE(v_shipment.discount_amount, 0);
  v_paid := COALESCE(v_shipment.paid_amount, 0);
  v_net_revenue := GREATEST(v_total_revenue - v_discount, 0);

  -- 4. Currency and Exchange Rate
  v_currency := COALESCE(NULLIF(v_shipment.currency_code, ''), NULLIF(v_shipment.currency, ''), 'USD');
  v_exch_rate := COALESCE(v_shipment.exchange_rate, 1.0);
  IF v_exch_rate <= 0 THEN
    v_exch_rate := 1.0;
  END IF;

  v_base_revenue := ROUND(v_total_revenue * v_exch_rate, 2);
  v_base_discount := ROUND(v_discount * v_exch_rate, 2);
  v_base_net := ROUND(v_net_revenue * v_exch_rate, 2);
  v_base_paid := ROUND(v_paid * v_exch_rate, 2);

  -- 5. Calculate COGS (Cost of Goods Sold)
  SELECT COALESCE(SUM(
    ROUND(
      COALESCE(esi.quantity, 0) * 
      COALESCE(
        CASE WHEN COALESCE(pol.carton_count, 0) > 0 THEN pol.final_cost / pol.carton_count ELSE NULL END,
        NULLIF(esi.price, 0),
        po.packing_cost_per_carton,
        0
      ),
      2
    )
  ), 0)
  INTO v_cogs_amount
  FROM public.export_shipment_items esi
  LEFT JOIN public.packing_order_lines pol ON pol.id = esi.packing_order_line_id
  LEFT JOIN public.packing_orders po ON po.id = esi.packing_order_id
  WHERE esi.shipment_id = p_shipment_id;

  IF v_cogs_amount = 0 THEN
    v_cogs_amount := COALESCE(v_shipment.total_fruit_cost, 0) + COALESCE(v_shipment.total_packing_material_cost, 0);
  END IF;
  IF v_cogs_amount = 0 AND COALESCE(v_shipment.cost_per_carton, 0) > 0 AND COALESCE(v_shipment.carton_count, 0) > 0 THEN
    v_cogs_amount := ROUND(v_shipment.cost_per_carton * v_shipment.carton_count, 2);
  END IF;
  IF v_cogs_amount = 0 AND COALESCE(v_shipment.total_landed_cost, 0) > 0 THEN
    v_cogs_amount := v_shipment.total_landed_cost;
  END IF;

  -- 6. Update Shipment Record with figures
  UPDATE public.export_shipments
  SET currency_code = v_currency,
      currency = v_currency,
      exchange_rate = v_exch_rate,
      total_revenue_foreign = v_total_revenue,
      total_revenue_egp = v_base_revenue,
      total_fruit_cost = v_cogs_amount,
      updated_at = now()
  WHERE id = p_shipment_id;

  -- 7. Clean up existing Journal Entries for this shipment
  FOR v_je_id IN
      SELECT id FROM public.journal_entries
      WHERE (source_type IN ('export_shipment', 'export_discount', 'customer_payment') AND source_id = p_shipment_id::text)
         OR (description ILIKE '%' || v_shipment.shipment_no || '%')
  LOOP
      DELETE FROM public.account_ledger_entries WHERE journal_entry_id = v_je_id;
      DELETE FROM public.journal_entries WHERE id = v_je_id;
  END LOOP;

  -- 8. Customer Ledger cleanup & update
  SELECT
    COALESCE(SUM(CASE WHEN entry_type = 'debit' THEN amount ELSE -amount END), 0)
  INTO v_old_amount
  FROM public.ledger_entries
  WHERE entity_type = 'customer'
    AND entity_id = v_shipment.customer_id::TEXT
    AND reference_type = 'export_shipment'
    AND reference_text = p_shipment_id::TEXT;

  UPDATE public.customers
  SET balance = COALESCE(balance, 0) - v_old_amount + (v_net_revenue - v_paid),
      updated_at = now()
  WHERE id = v_shipment.customer_id;

  DELETE FROM public.ledger_entries
  WHERE entity_type = 'customer'
    AND entity_id = v_shipment.customer_id::TEXT
    AND reference_type = 'export_shipment'
    AND reference_text = p_shipment_id::TEXT;

  -- 9. Resolve GL Accounts (Level 5)
  -- A. AR Account (حساب العميل): 12511 (عملاء تصدير) أو 12512 (عملاء محلي)
  SELECT c.account_id INTO v_raw_ar FROM public.customers c WHERE c.id = v_shipment.customer_id;
  IF v_raw_ar IS NOT NULL THEN
    SELECT id INTO v_ar_acct FROM public.accounts WHERE id = v_raw_ar AND is_leaf = true LIMIT 1;
  END IF;

  IF v_ar_acct IS NULL THEN
    SELECT id INTO v_ar_acct FROM public.accounts WHERE account_code = '12511' AND is_leaf = true LIMIT 1;
  END IF;
  IF v_ar_acct IS NULL THEN
    SELECT id INTO v_ar_acct FROM public.accounts WHERE account_code = '12512' AND is_leaf = true LIMIT 1;
  END IF;
  IF v_ar_acct IS NULL THEN
    SELECT id INTO v_ar_acct FROM public.accounts WHERE account_code LIKE '1251%' AND is_leaf = true ORDER BY account_code LIMIT 1;
  END IF;
  IF v_ar_acct IS NULL THEN
    SELECT id INTO v_ar_acct FROM public.accounts WHERE account_code LIKE '125%' AND is_leaf = true ORDER BY account_code LIMIT 1;
  END IF;

  -- B. Revenue Account (حساب الإيراد): حسب نوع المحصول 41111 (فراولة), 41112 (مانجو), 41113 (بلح), 41114 (بلوبيري)
  SELECT 
    CASE 
      WHEN bool_or(LOWER(COALESCE(product_name, invoice_product_name, '')) LIKE '%مانجو%' OR LOWER(COALESCE(product_name, invoice_product_name, '')) LIKE '%mango%') THEN '41112'
      WHEN bool_or(LOWER(COALESCE(product_name, invoice_product_name, '')) LIKE '%بلح%' OR LOWER(COALESCE(product_name, invoice_product_name, '')) LIKE '%تمر%' OR LOWER(COALESCE(product_name, invoice_product_name, '')) LIKE '%date%') THEN '41113'
      WHEN bool_or(LOWER(COALESCE(product_name, invoice_product_name, '')) LIKE '%فراول%' OR LOWER(COALESCE(product_name, invoice_product_name, '')) LIKE '%strawberr%') THEN '41111'
      WHEN bool_or(LOWER(COALESCE(product_name, invoice_product_name, '')) LIKE '%بلوبير%' OR LOWER(COALESCE(product_name, invoice_product_name, '')) LIKE '%blueberr%') THEN '41114'
      WHEN bool_or(LOWER(COALESCE(product_name, invoice_product_name, '')) LIKE '%فرز%') THEN '41121'
      ELSE NULL
    END
  INTO v_revenue_code
  FROM public.export_shipment_items
  WHERE shipment_id = p_shipment_id;

  IF v_revenue_code IS NOT NULL THEN
    SELECT id INTO v_rev_acct FROM public.accounts WHERE account_code = v_revenue_code AND is_leaf = true LIMIT 1;
  END IF;

  IF v_rev_acct IS NULL THEN
    SELECT id INTO v_rev_acct FROM public.accounts WHERE account_code = '41112' AND is_leaf = true LIMIT 1;
  END IF;
  IF v_rev_acct IS NULL THEN
    SELECT id INTO v_rev_acct FROM public.accounts WHERE account_code LIKE '4111%' AND is_leaf = true ORDER BY account_code LIMIT 1;
  END IF;
  IF v_rev_acct IS NULL THEN
    SELECT id INTO v_rev_acct FROM public.accounts WHERE account_code LIKE '41%' AND is_leaf = true ORDER BY account_code LIMIT 1;
  END IF;

  -- C. Discount Account: 41131 (خصم مسموح به - مبيعات تصدير)
  SELECT id INTO v_disc_acct FROM public.accounts WHERE account_code = '41131' AND is_leaf = true LIMIT 1;
  IF v_disc_acct IS NULL THEN
    SELECT id INTO v_disc_acct FROM public.accounts WHERE account_name ILIKE '%خصم%' AND is_leaf = true LIMIT 1;
  END IF;

  -- D. Inventory Account: 12413 (مخزن الإنتاج التام)
  SELECT id INTO v_inv_acct FROM public.accounts WHERE account_code = '12413' AND is_leaf = true LIMIT 1;
  IF v_inv_acct IS NULL THEN
    SELECT id INTO v_inv_acct FROM public.accounts WHERE account_code LIKE '1241%' AND is_leaf = true ORDER BY account_code LIMIT 1;
  END IF;

  -- E. COGS Account: 34111 (تكاليف مشتريات خام / تكلفة المحاصيل المباعة - مستوى 5 ترحيل معتمد)
  SELECT id INTO v_cogs_acct FROM public.accounts 
  WHERE account_code = '34111' AND is_leaf = true AND is_active = true LIMIT 1;
  IF v_cogs_acct IS NULL THEN
    SELECT id INTO v_cogs_acct FROM public.accounts 
    WHERE account_code LIKE '3411%' AND is_leaf = true AND is_active = true 
    ORDER BY account_code LIMIT 1;
  END IF;
  IF v_cogs_acct IS NULL THEN
    SELECT id INTO v_cogs_acct FROM public.accounts 
    WHERE account_code LIKE '341%' AND is_leaf = true AND is_active = true 
    ORDER BY account_code LIMIT 1;
  END IF;

  -- F. Treasury / Bank Account (في حالة السداد)
  IF v_paid > 0 THEN
    IF v_shipment.payment_source_type = 'bank' THEN
      IF v_currency = 'USD' THEN
        SELECT id INTO v_pay_acct FROM public.accounts WHERE account_code = '12112' AND is_leaf = true LIMIT 1; -- CIB USD
      ELSE
        SELECT id INTO v_pay_acct FROM public.accounts WHERE account_code = '12111' AND is_leaf = true LIMIT 1; -- CIB EGP
      END IF;
      IF v_pay_acct IS NULL THEN
        SELECT id INTO v_pay_acct FROM public.accounts WHERE account_code LIKE '1211%' AND is_leaf = true LIMIT 1;
      END IF;
    ELSE
      IF v_currency = 'USD' THEN
        SELECT id INTO v_pay_acct FROM public.accounts WHERE account_code = '12212' AND is_leaf = true LIMIT 1; -- Treasury USD
      ELSE
        SELECT id INTO v_pay_acct FROM public.accounts WHERE account_code = '12211' AND is_leaf = true LIMIT 1; -- Treasury EGP
      END IF;
      IF v_pay_acct IS NULL THEN
        SELECT id INTO v_pay_acct FROM public.accounts WHERE account_code LIKE '1221%' AND is_leaf = true LIMIT 1;
      END IF;
    END IF;
  END IF;

  -- 10. Dates and Descriptions
  v_entry_date := COALESCE(
    v_shipment.shipment_date,
    (v_shipment.created_at AT TIME ZONE 'Africa/Cairo')::date,
    CURRENT_DATE
  );
  SELECT name INTO v_customer_name FROM public.customers WHERE id = v_shipment.customer_id;
  v_desc := 'شحنة تصدير رقم ' || v_shipment.shipment_no || COALESCE(' - العميل: ' || v_customer_name, '');

  -- 11. Legacy Customer Ledger Records
  IF v_total_revenue > 0 THEN
    INSERT INTO public.ledger_entries (
      entity_type, entity_id, entry_type, amount, currency,
      reference_type, reference_text, description, created_by
    ) VALUES (
      'customer', v_shipment.customer_id::TEXT, 'debit', v_total_revenue,
      v_currency, 'export_shipment', p_shipment_id::TEXT, v_desc, p_user_id
    );
  END IF;

  IF v_discount > 0 THEN
    INSERT INTO public.ledger_entries (
      entity_type, entity_id, entry_type, amount, currency,
      reference_type, reference_text, description, created_by
    ) VALUES (
      'customer', v_shipment.customer_id::TEXT, 'credit', v_discount,
      v_currency, 'export_shipment', p_shipment_id::TEXT, v_desc || ' (خصم مسموح به)', p_user_id
    );
  END IF;

  IF v_paid > 0 THEN
    INSERT INTO public.ledger_entries (
      entity_type, entity_id, entry_type, amount, currency,
      reference_type, reference_text, description, created_by
    ) VALUES (
      'customer', v_shipment.customer_id::TEXT, 'credit', v_paid,
      v_currency, 'export_shipment', p_shipment_id::TEXT, v_desc || ' (سداد دفعة نقدية)', p_user_id
    );
  END IF;

  -- 12. ── JOURNAL ENTRY 1: Sales Revenue & Discount (متزن تماماً مدين = دائن) ──
  IF v_total_revenue > 0 AND v_ar_acct IS NOT NULL AND v_rev_acct IS NOT NULL THEN
    v_sale_lines := jsonb_build_array();

    -- الطرف المدين: العميل بالصافي المستحق
    IF v_net_revenue > 0 THEN
      v_sale_lines := v_sale_lines || jsonb_build_array(
        jsonb_build_object(
          'account_id', v_ar_acct,
          'debit', v_net_revenue,
          'credit', 0,
          'base_debit', v_base_net,
          'base_credit', 0,
          'currency', v_currency,
          'description', v_desc || ' - استحقاق صافي قيمة الشحنة'
        )
      );
    END IF;

    -- الطرف المدين: الخصم المسموح به (إذا وجد)
    IF v_discount > 0 THEN
      v_sale_lines := v_sale_lines || jsonb_build_array(
        jsonb_build_object(
          'account_id', COALESCE(v_disc_acct, v_rev_acct),
          'debit', v_discount,
          'credit', 0,
          'base_debit', v_base_discount,
          'base_credit', 0,
          'currency', v_currency,
          'description', v_desc || ' - خصم مسموح به'
        )
      );
    END IF;

    -- الطرف الدائن: إيرادات مبيعات المحاصيل بالإجمالي
    v_sale_lines := v_sale_lines || jsonb_build_array(
      jsonb_build_object(
        'account_id', v_rev_acct,
        'debit', 0,
        'credit', v_total_revenue,
        'base_debit', 0,
        'base_credit', v_base_revenue,
        'currency', v_currency,
        'description', v_desc || ' - إيرادات مبيعات المحاصيل'
      )
    );

    v_sale_je_id := public.post_journal_entry(
      'export_shipment',
      v_desc || ' - إثبات مبيعات التصدير',
      v_entry_date,
      v_company_id,
      p_user_id,
      v_sale_lines,
      p_shipment_id::text
    );
  END IF;

  -- 13. ── JOURNAL ENTRY 2: Cost of Goods Sold (تكلفة البضاعة المباعة والمخزون) ──
  IF v_cogs_amount > 0 AND v_cogs_acct IS NOT NULL AND v_inv_acct IS NOT NULL THEN
    v_cogs_je_id := public.post_journal_entry(
      'export_shipment',
      v_desc || ' - تكلفة البضاعة المباعة',
      v_entry_date,
      v_company_id,
      p_user_id,
      jsonb_build_array(
        jsonb_build_object(
          'account_id', v_cogs_acct,
          'debit', v_cogs_amount,
          'credit', 0,
          'base_debit', v_cogs_amount,
          'base_credit', 0,
          'currency', 'EGP',
          'description', v_desc || ' - تكلفة المحاصيل المباعة'
        ),
        jsonb_build_object(
          'account_id', v_inv_acct,
          'debit', 0,
          'credit', v_cogs_amount,
          'base_debit', 0,
          'base_credit', v_cogs_amount,
          'currency', 'EGP',
          'description', v_desc || ' - صرف من مخزن الإنتاج التام (12413)'
        )
      ),
      p_shipment_id::text
    );
  END IF;

  -- 14. ── JOURNAL ENTRY 3: Customer Advance Payment (سداد العميل النقدي / البنكي) ──
  IF v_paid > 0 AND v_pay_acct IS NOT NULL AND v_ar_acct IS NOT NULL THEN
    v_pay_je_id := public.post_journal_entry(
      'customer_payment',
      v_desc || ' - سداد دفعة من العميل',
      v_entry_date,
      v_company_id,
      p_user_id,
      jsonb_build_array(
        jsonb_build_object(
          'account_id', v_pay_acct,
          'debit', v_paid,
          'credit', 0,
          'base_debit', v_base_paid,
          'base_credit', 0,
          'currency', v_currency,
          'description', v_desc || ' - إيداع مسدد من العميل'
        ),
        jsonb_build_object(
          'account_id', v_ar_acct,
          'debit', 0,
          'credit', v_paid,
          'base_debit', 0,
          'base_credit', v_base_paid,
          'currency', v_currency,
          'description', v_desc || ' - تخفيض حساب العميل بالمسدد'
        )
      ),
      p_shipment_id::text
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'تم ترحيل قيود الشحنة بنجاح',
    'sale_journal_entry_id', v_sale_je_id,
    'cogs_journal_entry_id', v_cogs_je_id,
    'payment_journal_entry_id', v_pay_je_id,
    'revenue_egp', v_base_revenue,
    'discount_egp', v_base_discount,
    'net_egp', v_base_net,
    'cogs_egp', v_cogs_amount,
    'paid_egp', v_base_paid
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_process_export_shipment_ledger(bigint, uuid) TO authenticated, service_role, anon;

-- ── 4. Update rpc_save_export_shipment to Automatically Trigger Ledger Posting ──
CREATE OR REPLACE FUNCTION public.rpc_save_export_shipment(
  p_shipment jsonb,
  p_items jsonb DEFAULT '[]'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_shipment_id bigint;
  v_item jsonb;
  v_idx int := 0;
  v_ledger_res jsonb;
BEGIN
  -- 1. Insert or Update export_shipments
  IF p_shipment ? 'id' AND p_shipment->>'id' IS NOT NULL AND p_shipment->>'id' != '' THEN
    v_shipment_id := (p_shipment->>'id')::bigint;
    UPDATE public.export_shipments
    SET
      shipment_no = COALESCE(p_shipment->>'shipment_no', shipment_no),
      customer_id = (NULLIF(p_shipment->>'customer_id', ''))::bigint,
      customer_name = p_shipment->>'customer_name',
      customer_code = p_shipment->>'customer_code',
      clearing_agent_id = (NULLIF(p_shipment->>'clearing_agent_id', ''))::bigint,
      clearing_agent_name = p_shipment->>'clearing_agent_name',
      contact_person = p_shipment->>'contact_person',
      destination_country = COALESCE(p_shipment->>'destination_country', p_shipment->>'country'),
      country_of_origin = COALESCE(p_shipment->>'country_of_origin', 'Egypt'),
      destination_address = p_shipment->>'destination_address',
      container_number = p_shipment->>'container_number',
      container_type = p_shipment->>'container_type',
      bl_number = p_shipment->>'bl_number',
      vessel_name = p_shipment->>'vessel_name',
      shipping_company = p_shipment->>'shipping_company',
      data_logger_no = p_shipment->>'data_logger_no',
      port_of_loading = p_shipment->>'port_of_loading',
      port_of_destination = p_shipment->>'port_of_destination',
      transport_mode = COALESCE(p_shipment->>'transport_mode', 'sea'),
      pallet_count = COALESCE((NULLIF(p_shipment->>'pallet_count', ''))::int, 0),
      carton_count = COALESCE((NULLIF(p_shipment->>'carton_count', ''))::int, 0),
      net_weight = COALESCE((NULLIF(p_shipment->>'net_weight', ''))::numeric, 0),
      gross_weight = COALESCE((NULLIF(p_shipment->>'gross_weight', ''))::numeric, 0),
      incoterm = p_shipment->>'incoterm',
      payment_terms = p_shipment->>'payment_terms',
      currency = p_shipment->>'currency',
      currency_code = COALESCE(p_shipment->>'currency_code', 'USD'),
      exchange_rate = COALESCE((NULLIF(p_shipment->>'exchange_rate', ''))::numeric, 1.0),
      total_revenue_foreign = COALESCE((NULLIF(p_shipment->>'total_revenue_foreign', ''))::numeric, 0),
      total_revenue_egp = COALESCE((NULLIF(p_shipment->>'total_revenue_egp', ''))::numeric, 0),
      net_profit_egp = COALESCE((NULLIF(p_shipment->>'net_profit_egp', ''))::numeric, 0),
      discount_amount = COALESCE((NULLIF(p_shipment->>'discount_amount', ''))::numeric, 0),
      discount_reason = p_shipment->>'discount_reason',
      paid_amount = COALESCE((NULLIF(p_shipment->>'paid_amount', ''))::numeric, 0),
      payment_source_type = COALESCE(p_shipment->>'payment_source_type', 'treasury'),
      payment_treasury_id = p_shipment->>'payment_treasury_id',
      payment_bank_account_id = (NULLIF(p_shipment->>'payment_bank_account_id', ''))::bigint,
      status = COALESCE(p_shipment->>'status', 'draft'),
      shipment_date = (NULLIF(p_shipment->>'shipment_date', ''))::date,
      terms_conditions = p_shipment->>'terms_conditions',
      internal_notes = COALESCE(p_shipment->>'internal_notes', p_shipment->>'notes'),
      notes = COALESCE(p_shipment->>'notes', p_shipment->>'internal_notes'),
      updated_at = now()
    WHERE id = v_shipment_id;

    DELETE FROM public.export_shipment_items WHERE shipment_id = v_shipment_id;
  ELSE
    INSERT INTO public.export_shipments (
      shipment_no, customer_id, customer_name, customer_code,
      clearing_agent_id, clearing_agent_name, contact_person,
      destination_country, country_of_origin, destination_address,
      container_number, container_type, bl_number, vessel_name,
      shipping_company, data_logger_no, port_of_loading, port_of_destination,
      transport_mode, pallet_count, carton_count, net_weight, gross_weight,
      incoterm, payment_terms, currency, currency_code, exchange_rate,
      total_revenue_foreign, total_revenue_egp, net_profit_egp,
      discount_amount, discount_reason, paid_amount,
      payment_source_type, payment_treasury_id, payment_bank_account_id,
      status, shipment_date, terms_conditions, internal_notes, notes
    ) VALUES (
      p_shipment->>'shipment_no',
      (NULLIF(p_shipment->>'customer_id', ''))::bigint,
      p_shipment->>'customer_name',
      p_shipment->>'customer_code',
      (NULLIF(p_shipment->>'clearing_agent_id', ''))::bigint,
      p_shipment->>'clearing_agent_name',
      p_shipment->>'contact_person',
      COALESCE(p_shipment->>'destination_country', p_shipment->>'country'),
      COALESCE(p_shipment->>'country_of_origin', 'Egypt'),
      p_shipment->>'destination_address',
      p_shipment->>'container_number',
      p_shipment->>'container_type',
      p_shipment->>'bl_number',
      p_shipment->>'vessel_name',
      p_shipment->>'shipping_company',
      p_shipment->>'data_logger_no',
      p_shipment->>'port_of_loading',
      p_shipment->>'port_of_destination',
      COALESCE(p_shipment->>'transport_mode', 'sea'),
      COALESCE((NULLIF(p_shipment->>'pallet_count', ''))::int, 0),
      COALESCE((NULLIF(p_shipment->>'carton_count', ''))::int, 0),
      COALESCE((NULLIF(p_shipment->>'net_weight', ''))::numeric, 0),
      COALESCE((NULLIF(p_shipment->>'gross_weight', ''))::numeric, 0),
      p_shipment->>'incoterm',
      p_shipment->>'payment_terms',
      p_shipment->>'currency',
      COALESCE(p_shipment->>'currency_code', 'USD'),
      COALESCE((NULLIF(p_shipment->>'exchange_rate', ''))::numeric, 1.0),
      COALESCE((NULLIF(p_shipment->>'total_revenue_foreign', ''))::numeric, 0),
      COALESCE((NULLIF(p_shipment->>'total_revenue_egp', ''))::numeric, 0),
      COALESCE((NULLIF(p_shipment->>'net_profit_egp', ''))::numeric, 0),
      COALESCE((NULLIF(p_shipment->>'discount_amount', ''))::numeric, 0),
      p_shipment->>'discount_reason',
      COALESCE((NULLIF(p_shipment->>'paid_amount', ''))::numeric, 0),
      COALESCE(p_shipment->>'payment_source_type', 'treasury'),
      p_shipment->>'payment_treasury_id',
      (NULLIF(p_shipment->>'payment_bank_account_id', ''))::bigint,
      COALESCE(p_shipment->>'status', 'draft'),
      COALESCE((NULLIF(p_shipment->>'shipment_date', ''))::date, CURRENT_DATE),
      p_shipment->>'terms_conditions',
      COALESCE(p_shipment->>'internal_notes', p_shipment->>'notes'),
      COALESCE(p_shipment->>'notes', p_shipment->>'internal_notes')
    )
    RETURNING id INTO v_shipment_id;
  END IF;

  -- 2. Insert items
  IF p_items IS NOT NULL AND jsonb_array_length(p_items) > 0 THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
      INSERT INTO public.export_shipment_items (
        shipment_id,
        product_name,
        invoice_product_name,
        finished_product_id,
        grade,
        country_of_origin,
        hs_code,
        quantity,
        price,
        export_price_per_carton,
        weight_per_carton,
        net_weight,
        gross_weight,
        amount,
        pallets,
        packing_order_id,
        packing_order_line_id,
        sort_order
      ) VALUES (
        v_shipment_id,
        COALESCE(v_item->>'name', v_item->>'product_name', ''),
        COALESCE(v_item->>'product_name', v_item->>'invoice_product_name', v_item->>'name', ''),
        (NULLIF(v_item->>'productId', ''))::bigint,
        v_item->>'grade',
        COALESCE(v_item->>'countryOfOrigin', v_item->>'country_of_origin', 'Egypt'),
        COALESCE(v_item->>'hsCode', v_item->>'hs_code'),
        COALESCE((NULLIF(COALESCE(v_item->>'qty', v_item->>'quantity'), ''))::int, 0),
        COALESCE((NULLIF(v_item->>'price', ''))::numeric, 0),
        COALESCE((NULLIF(COALESCE(v_item->>'exportPricePerCarton', v_item->>'export_price_per_carton'), ''))::numeric, 0),
        COALESCE((NULLIF(COALESCE(v_item->>'weightPerCarton', v_item->>'weight_per_carton'), ''))::numeric, 15),
        COALESCE((NULLIF(COALESCE(v_item->>'netWt', v_item->>'net_weight'), ''))::numeric, 0),
        COALESCE((NULLIF(COALESCE(v_item->>'grossWt', v_item->>'gross_weight'), ''))::numeric, 0),
        COALESCE((NULLIF(v_item->>'amount', ''))::numeric, 0),
        COALESCE((NULLIF(v_item->>'pallets', ''))::int, 0),
        (NULLIF(v_item->>'packingOrderId', ''))::bigint,
        (NULLIF(v_item->>'packing_order_line_id', ''))::bigint,
        v_idx
      );
      v_idx := v_idx + 1;
    END LOOP;
  END IF;

  -- 3. Automatic Ledger & Double-Entry Journal Creation on Save
  BEGIN
    v_ledger_res := public.rpc_process_export_shipment_ledger(v_shipment_id);
  EXCEPTION WHEN OTHERS THEN
    v_ledger_res := jsonb_build_object('success', false, 'warning', SQLERRM);
  END;

  RETURN jsonb_build_object(
    'success', true,
    'id', v_shipment_id,
    'ledger', v_ledger_res
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_save_export_shipment(jsonb, jsonb) TO authenticated, service_role, anon;

-- ── 12.1 دالة تطبيق وتحديث الخصم للشحنات التصديرية وتحديث القيود آلياً ──
CREATE OR REPLACE FUNCTION public.rpc_apply_export_discount(
  p_shipment_id bigint,
  p_discount_amount numeric,
  p_discount_reason text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_shipment RECORD;
  v_res jsonb;
BEGIN
  SELECT * INTO v_shipment
  FROM public.export_shipments
  WHERE id = p_shipment_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'الشحنة التصديرية غير موجودة');
  END IF;

  IF p_discount_amount < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'قيمة الخصم لا يمكن أن تكون سالبة');
  END IF;

  UPDATE public.export_shipments
  SET discount_amount = COALESCE(p_discount_amount, 0),
      discount_reason = p_discount_reason,
      applied_discount_amount = COALESCE(p_discount_amount, 0),
      updated_at = now()
  WHERE id = p_shipment_id;

  -- Re-process shipment ledger to update customer ledger and double-entry journals
  BEGIN
    v_res := public.rpc_process_export_shipment_ledger(p_shipment_id);
  EXCEPTION WHEN OTHERS THEN
    v_res := jsonb_build_object('success', false, 'warning', SQLERRM);
  END;

  RETURN jsonb_build_object(
    'success', true,
    'shipment_id', p_shipment_id,
    'discount_amount', p_discount_amount,
    'discount_reason', p_discount_reason,
    'ledger_result', v_res
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_apply_export_discount(bigint, numeric, text) TO authenticated, service_role, anon;

-- ── 12.2 تريجر المزامنة اللحظية لتكلفة الكرتونة بين أوامر التعبئة والشحنات التصديرية والربحية ──
CREATE OR REPLACE FUNCTION public.sync_packing_order_costs_to_export_shipments()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_shipment RECORD;
  v_new_cost NUMERIC;
BEGIN
  v_new_cost := COALESCE(NEW.packing_cost_per_carton, 0);

  IF TG_OP = 'UPDATE' AND (OLD.packing_cost_per_carton IS NOT DISTINCT FROM NEW.packing_cost_per_carton) THEN
    RETURN NEW;
  END IF;

  IF v_new_cost <= 0 THEN
    RETURN NEW;
  END IF;

  -- 1. Update export_shipment_items prices linked to this packing order
  UPDATE public.export_shipment_items
  SET price = v_new_cost,
      amount = ROUND(quantity * v_new_cost, 2)
  WHERE packing_order_id = NEW.id;

  -- 2. Update read-only packing cost items in shipment_cost_items
  UPDATE public.shipment_cost_items sci
  SET unit_price = v_new_cost
  FROM public.export_shipment_items esi
  WHERE esi.shipment_id::text = sci.shipment_id::text
    AND esi.packing_order_id = NEW.id
    AND sci.category = 'packing';

  -- 3. Recalculate cost_per_carton & total_landed_cost for affected export_shipments
  FOR v_shipment IN
    SELECT DISTINCT shipment_id
    FROM public.export_shipment_items
    WHERE packing_order_id = NEW.id
  LOOP
    UPDATE public.export_shipments s
    SET cost_per_carton = COALESCE((
          SELECT ROUND(SUM(esi.quantity * esi.price) / GREATEST(1, SUM(esi.quantity)), 2)
          FROM public.export_shipment_items esi
          WHERE esi.shipment_id::text = s.id::text
        ), s.cost_per_carton),
        total_landed_cost = COALESCE((
          SELECT ROUND(SUM(esi.quantity * esi.price), 2)
          FROM public.export_shipment_items esi
          WHERE esi.shipment_id::text = s.id::text
        ), 0) + COALESCE((
          SELECT ROUND(SUM(sci.total_price), 2)
          FROM public.shipment_cost_items sci
          WHERE sci.shipment_id::text = s.id::text
            AND sci.category <> 'packing'
        ), 0),
        updated_at = now()
    WHERE s.id::text = v_shipment.shipment_id::text;
  END LOOP;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_packing_order_costs ON public.packing_orders;
CREATE TRIGGER trg_sync_packing_order_costs
AFTER UPDATE OF packing_cost_per_carton ON public.packing_orders
FOR EACH ROW
EXECUTE FUNCTION public.sync_packing_order_costs_to_export_shipments();


-- ============================================================================
-- 13. دالة تحميل المصروفات الإدارية على الشحنة وقفل توزيع الأرباح
-- ============================================================================
ALTER TABLE public.export_shipments 
    ADD COLUMN IF NOT EXISTS allocated_admin_expenses NUMERIC(18,2) DEFAULT 0.00;

-- (Replaced by canonical rpc_save_shipment_admin_expenses at Migration 424)

-- ============================================================================
-- 14. دوال الخزينة والحسابات البنكية المحدثة مع دعم حقل الملاحظات (Notes)
-- ============================================================================

-- 1. deposit_treasury
DROP FUNCTION IF EXISTS public.deposit_treasury(p_treasury_id integer, p_currency text, p_amount numeric, p_description text, p_revenue_account_id integer, p_reference_type text, p_reference_id text);
DROP FUNCTION IF EXISTS public.deposit_treasury(p_treasury_id integer, p_currency text, p_amount numeric, p_description text, p_revenue_account_id integer, p_reference_type text, p_reference_id text, p_notes text);

CREATE OR REPLACE FUNCTION public.deposit_treasury(
    p_treasury_id integer,
    p_currency text,
    p_amount numeric,
    p_description text DEFAULT NULL::text,
    p_revenue_account_id integer DEFAULT NULL::integer,
    p_reference_type text DEFAULT NULL::text,
    p_reference_id text DEFAULT NULL::text,
    p_notes text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_current_balance NUMERIC := 0;
    v_current_cost_base NUMERIC := 0;
    v_current_book_rate NUMERIC := 1.0;
    v_new_balance NUMERIC := 0;
    v_new_cost_base NUMERIC := 0;
    v_new_book_rate NUMERIC := 1.0;
    v_tx_id BIGINT;
    v_company_id UUID;
    v_treasury_acct BIGINT;
    v_revenue_acct BIGINT;
    v_desc TEXT;
    v_je_id BIGINT;
    v_source_type TEXT;
    v_rate NUMERIC := 1.0;
    v_base_amount NUMERIC;
    v_snapshot JSONB;
BEGIN
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'المبلغ يجب أن يكون أكبر من صفر';
    END IF;

    -- 1. Lock treasury balance row & retrieve current cost_base and book_rate
    SELECT COALESCE(balance, 0), COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_current_balance, v_current_cost_base, v_current_book_rate
    FROM public.treasury_balances
    WHERE treasury_id::TEXT = p_treasury_id::TEXT AND currency = p_currency
    FOR UPDATE;

    SELECT company_id INTO v_company_id FROM public.treasuries WHERE id = p_treasury_id;
    IF v_company_id IS NULL THEN
        SELECT id INTO v_company_id FROM public.sys_companies LIMIT 1;
    END IF;

    -- 2. Calculate spot exchange rate & base amount
    IF p_currency = 'EGP' THEN
        v_rate := 1.0;
        v_base_amount := p_amount;
        v_new_cost_base := COALESCE(v_current_cost_base, 0) + p_amount;
        v_new_book_rate := 1.0;
    ELSE
        v_rate := public.fn_get_exchange_rate(p_currency);
        v_base_amount := ROUND(p_amount * v_rate, 2);
        v_new_cost_base := COALESCE(v_current_cost_base, 0) + v_base_amount;
    END IF;

    v_new_balance := v_current_balance + p_amount;

    IF v_new_balance > 0 AND p_currency != 'EGP' THEN
        v_new_book_rate := ROUND(v_new_cost_base / v_new_balance, 4);
    ELSIF p_currency = 'EGP' THEN
        v_new_book_rate := 1.0;
    ELSE
        v_new_book_rate := v_rate;
    END IF;

    -- 3. Resolve GL accounts
    v_source_type := CASE WHEN p_revenue_account_id IS NOT NULL THEN 'revenue' ELSE 'opening_balance' END;
    v_desc := COALESCE(NULLIF(p_description, ''), 'إيداع في الخزينة');

    v_treasury_acct := public.resolve_treasury_account(p_treasury_id, p_currency, v_company_id);

    IF p_revenue_account_id IS NOT NULL THEN
        v_revenue_acct := p_revenue_account_id;
    ELSE
        v_revenue_acct := public.resolve_opening_balance_equity_account(p_currency, v_company_id);
    END IF;

    -- 4. Post Journal Entry
    v_je_id := public.post_journal_entry(
        'treasury_deposit',
        v_desc,
        CURRENT_DATE,
        v_company_id,
        auth.uid(),
        jsonb_build_array(
            jsonb_build_object('account_id', v_treasury_acct, 'debit', p_amount, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', p_currency, 'description', v_desc),
            jsonb_build_object('account_id', v_revenue_acct,  'debit', 0, 'credit', p_amount, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', p_currency, 'description', v_desc)
        )
    );

    -- 5. Update / Upsert treasury_balances
    INSERT INTO public.treasury_balances (treasury_id, currency, balance, cost_base, book_rate, account_id, updated_at)
    VALUES (p_treasury_id, p_currency, v_new_balance, v_new_cost_base, v_new_book_rate, v_treasury_acct, NOW())
    ON CONFLICT (treasury_id, currency) DO UPDATE
    SET balance = v_new_balance,
        cost_base = v_new_cost_base,
        book_rate = v_new_book_rate,
        updated_at = NOW();

    -- 6. Insert transaction with notes mapped to p_notes
    v_snapshot := jsonb_build_object(
        'currency', p_currency,
        'exchange_rate', v_rate,
        'book_rate', v_new_book_rate,
        'amount', p_amount,
        'amount_in_base_currency', v_base_amount,
        'rate_date', CURRENT_DATE,
        'rate_source', 'exchange_rates_table'
    );

    INSERT INTO public.treasury_transactions (
        treasury_id, type, currency, amount,
        balance_before, balance_after, description, source_type, journal_entry_id, created_by,
        revenue_account_id, reference_type, reference_id, notes, exchange_rate, amount_in_base_currency, currency_snapshot
    ) VALUES (
        p_treasury_id, 'deposit', p_currency, p_amount,
        v_current_balance, v_new_balance, v_desc, v_source_type, v_je_id, auth.uid(),
        CASE WHEN p_revenue_account_id IS NOT NULL THEN p_revenue_account_id ELSE NULL END,
        p_reference_type, p_reference_id, p_notes,
        v_rate, v_base_amount, v_snapshot
    ) RETURNING id INTO v_tx_id;

    RETURN jsonb_build_object(
        'success', true,
        'tx_id', v_tx_id,
        'journal_entry_id', v_je_id,
        'new_balance', v_new_balance,
        'cost_base', v_new_cost_base,
        'book_rate', v_new_book_rate
    );
END;
$function$;

-- 2. withdraw_treasury
DROP FUNCTION IF EXISTS public.withdraw_treasury(p_treasury_id integer, p_currency text, p_amount numeric, p_description text);
DROP FUNCTION IF EXISTS public.withdraw_treasury(p_treasury_id integer, p_currency text, p_amount numeric, p_description text, p_notes text);

CREATE OR REPLACE FUNCTION public.withdraw_treasury(
    p_treasury_id integer,
    p_currency text,
    p_amount numeric,
    p_description text DEFAULT ''::text,
    p_notes text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_current_balance NUMERIC;
    v_current_cost_base NUMERIC;
    v_current_book_rate NUMERIC;
    v_new_balance     NUMERIC;
    v_new_cost_base   NUMERIC;
    v_new_book_rate   NUMERIC;
    v_tx_id           INTEGER;
    v_company_id      UUID;
    v_treasury_acct   BIGINT;
    v_equity_acct     BIGINT;
    v_je_id           BIGINT;
    v_entry_number    TEXT;
    v_desc            TEXT;
    v_treasury_name   TEXT;
    v_base_amount     NUMERIC;
BEGIN
    IF NOT public._is_admin() THEN
        RAISE EXCEPTION 'غير مصرح بهذه العملية';
    END IF;

    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'المبلغ يجب أن يكون أكبر من صفر';
    END IF;

    SELECT t.company_id INTO v_company_id FROM treasuries t WHERE t.id = p_treasury_id;

    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'Treasury % not found', p_treasury_id;
    END IF;

    -- Current balance check & fetch rates
    SELECT COALESCE(balance, 0), COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_current_balance, v_current_cost_base, v_current_book_rate
    FROM treasury_balances
    WHERE treasury_id = p_treasury_id AND currency = p_currency;

    IF v_current_balance < p_amount THEN
        RAISE EXCEPTION 'الرصيد غير كاف (الرصيد الحالي: % %)', v_current_balance, p_currency;
    END IF;

    -- IAS 21 Multi-Currency FX Engine Logic
    IF p_currency = 'EGP' THEN
        v_base_amount := p_amount;
        v_new_book_rate := 1.0;
        v_new_cost_base := GREATEST(0, COALESCE(v_current_cost_base, 0) - p_amount);
    ELSE
        v_new_book_rate := COALESCE(NULLIF(v_current_book_rate, 0), public.fn_get_exchange_rate(p_currency));
        v_base_amount := ROUND(p_amount * v_new_book_rate, 2);
        v_new_cost_base := GREATEST(0, COALESCE(v_current_cost_base, 0) - v_base_amount);
    END IF;

    v_new_balance := v_current_balance - p_amount;

    SELECT name INTO v_treasury_name FROM treasuries WHERE id = p_treasury_id;
    v_desc := COALESCE(
        NULLIF(p_description, ''),
        'سحب من ' || COALESCE(v_treasury_name, 'الخزينة الرئيسية')
    );

    -- GL accounts
    v_treasury_acct := public.resolve_treasury_account(p_treasury_id, p_currency, v_company_id);
    v_equity_acct := public.resolve_gl_account('3000', v_company_id);

    -- Journal entry: Dr.Owner Equity / Cr.Treasury
    v_je_id := public.post_journal_entry(
        'opening_balance',
        v_desc,
        CURRENT_DATE,
        v_company_id,
        auth.uid(),
        jsonb_build_array(
            jsonb_build_object('account_id', v_equity_acct, 'debit', p_amount, 'credit', 0, 'currency', p_currency, 'description', v_desc, 'base_debit', v_base_amount, 'base_credit', 0),
            jsonb_build_object('account_id', v_treasury_acct, 'debit', 0, 'credit', p_amount, 'currency', p_currency, 'description', v_desc, 'base_debit', 0, 'base_credit', v_base_amount)
        )
    );

    -- Update treasury balance
    UPDATE treasury_balances 
    SET balance = v_new_balance,
        cost_base = v_new_cost_base,
        book_rate = v_new_book_rate,
        updated_at = NOW()
    WHERE treasury_id = p_treasury_id AND currency = p_currency;

    -- Treasury transaction record
    INSERT INTO treasury_transactions (
        treasury_id, type, currency, amount,
        balance_before, balance_after, description, source_type,
        journal_entry_id, expense_account_id, notes, created_by
    ) VALUES (
        p_treasury_id, 'withdrawal', p_currency, p_amount,
        v_current_balance, v_new_balance, v_desc, 'opening_balance',
        v_je_id, v_equity_acct, p_notes, auth.uid()
    )
    RETURNING id INTO v_tx_id;

    SELECT entry_number INTO v_entry_number FROM journal_entries WHERE id = v_je_id;

    RETURN jsonb_build_object('treasury_tx_id', v_tx_id, 'journal_entry_id', v_je_id, 'entry_number', v_entry_number);
END;
$function$;


-- 3. spend_with_category
DROP FUNCTION IF EXISTS public.spend_with_category(p_treasury_id bigint, p_currency text, p_amount numeric, p_description text, p_category_id integer, p_customer_id integer, p_supplier_id uuid, p_clearing_agent_id bigint, p_shipping_company_id bigint, p_shareholder_id uuid, p_expense_account_id integer, p_reference_type text, p_reference_id text);
DROP FUNCTION IF EXISTS public.spend_with_category(p_treasury_id bigint, p_currency text, p_amount numeric, p_description text, p_category_id integer, p_customer_id integer, p_supplier_id uuid, p_clearing_agent_id bigint, p_shipping_company_id bigint, p_shareholder_id uuid, p_expense_account_id integer, p_reference_type text, p_reference_id text, p_notes text);

CREATE OR REPLACE FUNCTION public.spend_with_category(
    p_treasury_id bigint,
    p_currency text,
    p_amount numeric,
    p_description text DEFAULT ''::text,
    p_category_id integer DEFAULT NULL::integer,
    p_customer_id integer DEFAULT NULL::integer,
    p_supplier_id uuid DEFAULT NULL::uuid,
    p_clearing_agent_id bigint DEFAULT NULL::bigint,
    p_shipping_company_id bigint DEFAULT NULL::bigint,
    p_shareholder_id uuid DEFAULT NULL::uuid,
    p_expense_account_id integer DEFAULT NULL::integer,
    p_reference_type text DEFAULT NULL::text,
    p_reference_id text DEFAULT NULL::text,
    p_notes text DEFAULT NULL::text
)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_current_balance NUMERIC;
    v_current_cost_base NUMERIC;
    v_current_book_rate NUMERIC;
    v_new_balance     NUMERIC;
    v_new_cost_base   NUMERIC;
    v_new_book_rate   NUMERIC;
    v_base_amount     NUMERIC;
    v_tx_id           BIGINT;
    v_company_id      UUID;
    v_treasury_acct   BIGINT;
    v_expense_acct    BIGINT;
    v_je_id           BIGINT;
    v_desc            TEXT;
    v_tx_type         TEXT;
    v_supplier_leaf   INTEGER;
BEGIN
    IF p_expense_account_id IS NOT NULL THEN
        SELECT id INTO v_expense_acct FROM accounts
        WHERE id = p_expense_account_id AND is_leaf = true AND is_active = true AND account_type = 'expense';
        IF v_expense_acct IS NULL THEN
            RAISE EXCEPTION 'الحساب المحدد غير صالح — يجب أن يكون حساب مصروفات ورقي ونشط';
        END IF;
        v_tx_type := 'expense';
    ELSIF p_supplier_id IS NOT NULL THEN
        SELECT s.account_id INTO v_supplier_leaf
        FROM suppliers s WHERE s.id = p_supplier_id;
        IF v_supplier_leaf IS NULL THEN
            RAISE EXCEPTION 'المورد لا يمتلك حساب في شجرة الحسابات';
        END IF;
        SELECT id INTO v_expense_acct FROM accounts
        WHERE id = v_supplier_leaf AND is_leaf = true AND is_active = true;
        IF v_expense_acct IS NULL THEN
            RAISE EXCEPTION 'حساب المورد غير موجود أو غير نشط في شجرة الحسابات';
        END IF;
        v_tx_type := 'supplier_payment';
    ELSE
        RAISE EXCEPTION 'يجب اختيار حساب مصروفات من شجرة الحسابات أو تحديد مورد';
    END IF;

    SELECT COALESCE(balance, 0), COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_current_balance, v_current_cost_base, v_current_book_rate
    FROM public.treasury_balances
    WHERE treasury_id = p_treasury_id AND currency = p_currency;

    IF v_current_balance IS NULL OR v_current_balance < p_amount THEN
        RAISE EXCEPTION 'الرصيد غير كاف في % (المتوفر: %)', p_currency, COALESCE(v_current_balance, 0);
    END IF;

    -- IAS 21 Multi-Currency FX Engine Logic
    IF p_currency = 'EGP' THEN
        v_base_amount := p_amount;
        v_new_book_rate := 1.0;
        v_new_cost_base := GREATEST(0, COALESCE(v_current_cost_base, 0) - p_amount);
    ELSE
        v_new_book_rate := COALESCE(NULLIF(v_current_book_rate, 0), public.fn_get_exchange_rate(p_currency));
        v_base_amount := ROUND(p_amount * v_new_book_rate, 2);
        v_new_cost_base := GREATEST(0, COALESCE(v_current_cost_base, 0) - v_base_amount);
    END IF;

    v_new_balance := v_current_balance - p_amount;

    UPDATE public.treasury_balances
    SET balance = v_new_balance,
        cost_base = v_new_cost_base,
        book_rate = v_new_book_rate,
        updated_at = NOW()
    WHERE treasury_id = p_treasury_id AND currency = p_currency;

    SELECT t.company_id INTO v_company_id FROM treasuries t WHERE t.id = p_treasury_id;

    v_desc := COALESCE(NULLIF(p_description, ''), 'مصروف خزينة');

    INSERT INTO public.treasury_transactions (
        treasury_id, type, amount, currency, description, category_id,
        expense_account_id,
        customer_id, supplier_id, clearing_agent_id, shipping_company_id, shareholder_id,
        balance_before, balance_after,
        reference_type, reference_id, notes,
        created_by
    ) VALUES (
        p_treasury_id, v_tx_type, p_amount, p_currency, v_desc, p_category_id,
        p_expense_account_id,
        p_customer_id, p_supplier_id, p_clearing_agent_id, p_shipping_company_id, p_shareholder_id,
        v_current_balance, v_new_balance,
        p_reference_type, p_reference_id, p_notes,
        auth.uid()
    ) RETURNING id INTO v_tx_id;

    IF p_customer_id IS NOT NULL THEN
        UPDATE public.customers SET balance = balance + p_amount WHERE id = p_customer_id;
        INSERT INTO public.ledger_entries (entity_type, entity_id, entry_type, amount, currency, reference_type, reference_id, description, created_by)
        VALUES ('customer', p_customer_id::TEXT, 'debit', p_amount, p_currency, v_tx_type, v_tx_id, v_desc, auth.uid());
    END IF;
    IF p_supplier_id IS NOT NULL THEN
        UPDATE public.suppliers SET outstanding_balance = outstanding_balance - p_amount WHERE id = p_supplier_id;
        INSERT INTO public.ledger_entries (entity_type, entity_id, entry_type, amount, currency, reference_type, reference_id, description, created_by)
        VALUES ('supplier', p_supplier_id::TEXT, 'credit', p_amount, p_currency, v_tx_type, v_tx_id, v_desc, auth.uid());
    END IF;
    IF p_clearing_agent_id IS NOT NULL THEN
        UPDATE public.clearing_agents SET balance = balance - p_amount WHERE id = p_clearing_agent_id;
        INSERT INTO public.ledger_entries (entity_type, entity_id, entry_type, amount, currency, reference_type, reference_id, description, created_by)
        VALUES ('clearing_agent', p_clearing_agent_id::TEXT, 'debit', p_amount, p_currency, v_tx_type, v_tx_id, v_desc, auth.uid());
    END IF;
    IF p_shipping_company_id IS NOT NULL THEN
        UPDATE public.shipping_companies SET balance = balance - p_amount WHERE id = p_shipping_company_id;
        INSERT INTO public.ledger_entries (entity_type, entity_id, entry_type, amount, currency, reference_type, reference_id, description, created_by)
        VALUES ('shipping_company', p_shipping_company_id::TEXT, 'debit', p_amount, p_currency, v_tx_type, v_tx_id, v_desc, auth.uid());
    END IF;
    IF p_shareholder_id IS NOT NULL THEN
        IF p_currency = 'EGP' THEN UPDATE public.shareholders SET current_balance_egp = current_balance_egp - p_amount WHERE id = p_shareholder_id;
        ELSIF p_currency = 'USD' THEN UPDATE public.shareholders SET current_balance_usd = current_balance_usd - p_amount WHERE id = p_shareholder_id;
        ELSIF p_currency = 'EUR' THEN UPDATE public.shareholders SET current_balance_eur = current_balance_eur - p_amount WHERE id = p_shareholder_id;
        ELSIF p_currency = 'GBP' THEN UPDATE public.shareholders SET current_balance_gbp = current_balance_gbp - p_amount WHERE id = p_shareholder_id;
        END IF;
        INSERT INTO public.ledger_entries (entity_type, entity_id, entry_type, amount, currency, reference_type, reference_id, description, created_by)
        VALUES ('shareholder', p_shareholder_id::TEXT, 'debit', p_amount, p_currency, v_tx_type, v_tx_id, v_desc, auth.uid());
    END IF;

    IF p_reference_type = 'purchase_invoice' AND p_reference_id IS NOT NULL THEN
        UPDATE public.purchase_invoices
        SET paid_amount = COALESCE(paid_amount, 0) + p_amount,
            remaining_amount = GREATEST(0, (COALESCE(total_amount, 0) - COALESCE(discount_amount, 0)) - (COALESCE(paid_amount, 0) + p_amount)),
            payment_status = CASE 
                WHEN GREATEST(0, (COALESCE(total_amount, 0) - COALESCE(discount_amount, 0)) - (COALESCE(paid_amount, 0) + p_amount)) <= 0.001 THEN 'paid'
                ELSE 'partial'
            END,
            updated_at = NOW()
        WHERE id::TEXT = p_reference_id OR invoice_number = p_reference_id;
    END IF;

    v_treasury_acct := public.resolve_gl_account(
        CASE p_currency WHEN 'EGP' THEN '11101' WHEN 'USD' THEN '11102' WHEN 'EUR' THEN '11103' WHEN 'GBP' THEN '11104' END,
        v_company_id
    );

    v_je_id := public.post_journal_entry(
        CASE v_tx_type WHEN 'supplier_payment' THEN 'purchase_payment' ELSE 'expense_payment' END,
        v_desc, CURRENT_DATE, v_company_id, auth.uid(),
        jsonb_build_array(
            jsonb_build_object('account_id', v_expense_acct, 'debit', p_amount, 'credit', 0, 'currency', p_currency, 'description', v_desc, 'base_debit', v_base_amount, 'base_credit', 0),
            jsonb_build_object('account_id', v_treasury_acct, 'debit', 0, 'credit', p_amount, 'currency', p_currency, 'description', v_desc, 'base_debit', 0, 'base_credit', v_base_amount)
        )
    );

    UPDATE public.treasury_transactions SET journal_entry_id = v_je_id WHERE id = v_tx_id;

    RETURN v_tx_id;
END;
$function$;


-- 4. disburse_custody
DROP FUNCTION IF EXISTS public.disburse_custody(p_from_treasury_id integer, p_to_treasury_id integer, p_currency text, p_amount numeric, p_description text);
DROP FUNCTION IF EXISTS public.disburse_custody(p_from_treasury_id integer, p_to_treasury_id integer, p_currency text, p_amount numeric, p_description text, p_notes text);

CREATE OR REPLACE FUNCTION public.disburse_custody(
    p_from_treasury_id integer,
    p_to_treasury_id integer,
    p_currency text,
    p_amount numeric,
    p_description text DEFAULT ''::text,
    p_notes text DEFAULT NULL::text
)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_from_balance NUMERIC;
    v_to_balance   NUMERIC;
    v_from_cost_base NUMERIC;
    v_to_cost_base NUMERIC;
    v_from_book_rate NUMERIC;
    v_to_book_rate NUMERIC;
    v_base_amount  NUMERIC;
    v_tx_id        BIGINT;
    v_je_id        BIGINT;
    v_company_id   UUID;
    v_from_acct    BIGINT;
    v_to_acct      BIGINT;
    v_desc         TEXT;
    v_user_id      UUID;
    v_to_name      TEXT;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        SELECT id INTO v_user_id FROM public.users LIMIT 1;
    END IF;

    SELECT COALESCE(balance, 0), COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_from_balance, v_from_cost_base, v_from_book_rate
    FROM treasury_balances 
    WHERE treasury_id = p_from_treasury_id AND currency = p_currency
    FOR UPDATE;

    IF v_from_balance IS NULL OR v_from_balance < p_amount THEN
        RAISE EXCEPTION 'الرصيد غير كاف في الخزينة المصدرة';
    END IF;

    -- IAS 21 Outbound from Source Treasury
    IF p_currency = 'EGP' THEN
        v_base_amount := p_amount;
    ELSE
        v_base_amount := ROUND(p_amount * COALESCE(NULLIF(v_from_book_rate, 0), public.fn_get_exchange_rate(p_currency)), 2);
    END IF;

    -- Update Source Treasury
    UPDATE treasury_balances 
    SET balance = balance - p_amount,
        cost_base = GREATEST(0, COALESCE(cost_base, 0) - v_base_amount),
        updated_at = NOW()
    WHERE treasury_id = p_from_treasury_id AND currency = p_currency;

    -- Update/Upsert Destination Treasury
    SELECT COALESCE(balance, 0), COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_to_balance, v_to_cost_base, v_to_book_rate
    FROM treasury_balances 
    WHERE treasury_id = p_to_treasury_id AND currency = p_currency
    FOR UPDATE;

    IF NOT FOUND THEN
        v_to_balance := 0;
        v_to_cost_base := 0;
        v_to_book_rate := 1.0;
        INSERT INTO treasury_balances (treasury_id, currency, balance, cost_base, book_rate, account_id)
        VALUES (p_to_treasury_id, p_currency, 0, 0, 1.0, public.resolve_treasury_account(p_to_treasury_id, p_currency, (SELECT company_id FROM treasuries WHERE id = p_to_treasury_id)));
    END IF;

    -- IAS 21 Inbound to Destination Treasury
    IF p_currency = 'EGP' THEN
        v_to_book_rate := 1.0;
    ELSE
        IF (v_to_balance + p_amount) > 0 THEN
            v_to_book_rate := ROUND((v_to_cost_base + v_base_amount) / (v_to_balance + p_amount), 4);
        END IF;
    END IF;

    UPDATE treasury_balances
    SET balance = balance + p_amount,
        cost_base = COALESCE(cost_base, 0) + v_base_amount,
        book_rate = v_to_book_rate,
        updated_at = NOW()
    WHERE treasury_id = p_to_treasury_id AND currency = p_currency;

    SELECT name INTO v_to_name FROM treasuries WHERE id = p_to_treasury_id;
    v_desc := COALESCE(NULLIF(p_description, ''), 'صرف عهدة إلى ' || COALESCE(v_to_name, 'موظف'));

    -- GL Posting
    SELECT company_id INTO v_company_id FROM treasuries WHERE id = p_from_treasury_id;
    v_from_acct := public.resolve_treasury_account(p_from_treasury_id, p_currency, v_company_id);
    v_to_acct   := public.resolve_treasury_account(p_to_treasury_id, p_currency, v_company_id);

    IF v_to_acct IS NULL THEN
        SELECT id INTO v_to_acct FROM public.accounts WHERE (account_code = '12612' OR code = '12612') AND is_active = true LIMIT 1;
    END IF;
    IF v_from_acct IS NULL THEN
        SELECT id INTO v_from_acct FROM public.accounts WHERE (account_code = '12211' OR code = '12211') AND is_active = true LIMIT 1;
    END IF;

    v_je_id := public.post_journal_entry(
        'custody_disbursement', v_desc, CURRENT_DATE, v_company_id, v_user_id,
        jsonb_build_array(
            jsonb_build_object('account_id', v_to_acct, 'debit', p_amount, 'credit', 0, 'currency', p_currency, 'description', v_desc || ' (استلام عهدة)', 'base_debit', v_base_amount, 'base_credit', 0),
            jsonb_build_object('account_id', v_from_acct, 'debit', 0, 'credit', p_amount, 'currency', p_currency, 'description', v_desc || ' (صرف عهدة)', 'base_debit', 0, 'base_credit', v_base_amount)
        )
    );

    -- Transaction Record (Sender)
    INSERT INTO treasury_transactions (
        treasury_id, type, amount, currency, description,
        balance_before, balance_after,
        reference_type, reference_id, notes, created_by, journal_entry_id
    ) VALUES (
        p_from_treasury_id, 'disbursement_out', p_amount, p_currency, v_desc,
        v_from_balance, v_from_balance - p_amount,
        'treasury', p_to_treasury_id::TEXT, p_notes, v_user_id, v_je_id
    ) RETURNING id INTO v_tx_id;

    -- Transaction Record (Receiver)
    INSERT INTO treasury_transactions (
        treasury_id, type, amount, currency, description,
        balance_before, balance_after,
        reference_type, reference_id, notes, created_by, journal_entry_id
    ) VALUES (
        p_to_treasury_id, 'disbursement', p_amount, p_currency, v_desc,
        v_to_balance, v_to_balance + p_amount,
        'treasury', p_from_treasury_id::TEXT, p_notes, v_user_id, v_je_id
    );

    RETURN v_tx_id;
END;
$function$;


-- 5. transfer_custody
DROP FUNCTION IF EXISTS public.transfer_custody(p_from_treasury_id integer, p_to_treasury_id integer, p_currency text, p_amount numeric, p_description text);
DROP FUNCTION IF EXISTS public.transfer_custody(p_from_treasury_id integer, p_to_treasury_id integer, p_currency text, p_amount numeric, p_description text, p_notes text);

CREATE OR REPLACE FUNCTION public.transfer_custody(
    p_from_treasury_id integer,
    p_to_treasury_id integer,
    p_currency text,
    p_amount numeric,
    p_description text DEFAULT ''::text,
    p_notes text DEFAULT NULL::text
)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_from_balance NUMERIC;
    v_to_balance   NUMERIC;
    v_from_cost_base NUMERIC;
    v_to_cost_base NUMERIC;
    v_from_book_rate NUMERIC;
    v_to_book_rate NUMERIC;
    v_base_amount  NUMERIC;
    v_tx_id        BIGINT;
    v_je_id        BIGINT;
    v_company_id   UUID;
    v_from_acct    BIGINT;
    v_to_acct      BIGINT;
    v_desc         TEXT;
    v_user_id      UUID;
    v_from_name    TEXT;
    v_to_name      TEXT;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        SELECT id INTO v_user_id FROM public.users LIMIT 1;
    END IF;

    SELECT COALESCE(balance, 0), COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_from_balance, v_from_cost_base, v_from_book_rate
    FROM treasury_balances 
    WHERE treasury_id = p_from_treasury_id AND currency = p_currency
    FOR UPDATE;

    IF v_from_balance IS NULL OR v_from_balance < p_amount THEN
        RAISE EXCEPTION 'الرصيد غير كاف للتحويل';
    END IF;

    IF p_currency = 'EGP' THEN
        v_base_amount := p_amount;
    ELSE
        v_base_amount := ROUND(p_amount * COALESCE(NULLIF(v_from_book_rate, 0), public.fn_get_exchange_rate(p_currency)), 2);
    END IF;

    UPDATE treasury_balances 
    SET balance = balance - p_amount,
        cost_base = GREATEST(0, COALESCE(cost_base, 0) - v_base_amount),
        updated_at = NOW()
    WHERE treasury_id = p_from_treasury_id AND currency = p_currency;

    SELECT COALESCE(balance, 0), COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_to_balance, v_to_cost_base, v_to_book_rate
    FROM treasury_balances 
    WHERE treasury_id = p_to_treasury_id AND currency = p_currency
    FOR UPDATE;

    IF NOT FOUND THEN
        v_to_balance := 0;
        v_to_cost_base := 0;
        v_to_book_rate := 1.0;
        INSERT INTO treasury_balances (treasury_id, currency, balance, cost_base, book_rate, account_id)
        VALUES (p_to_treasury_id, p_currency, 0, 0, 1.0, public.resolve_treasury_account(p_to_treasury_id, p_currency, (SELECT company_id FROM treasuries WHERE id = p_to_treasury_id)));
    END IF;

    IF p_currency = 'EGP' THEN
        v_to_book_rate := 1.0;
    ELSE
        IF (v_to_balance + p_amount) > 0 THEN
            v_to_book_rate := ROUND((v_to_cost_base + v_base_amount) / (v_to_balance + p_amount), 4);
        END IF;
    END IF;

    UPDATE treasury_balances
    SET balance = balance + p_amount,
        cost_base = COALESCE(cost_base, 0) + v_base_amount,
        book_rate = v_to_book_rate,
        updated_at = NOW()
    WHERE treasury_id = p_to_treasury_id AND currency = p_currency;

    SELECT name INTO v_from_name FROM treasuries WHERE id = p_from_treasury_id;
    SELECT name INTO v_to_name FROM treasuries WHERE id = p_to_treasury_id;
    v_desc := COALESCE(NULLIF(p_description, ''), 'تحويل عهدة من ' || COALESCE(v_from_name, '') || ' إلى ' || COALESCE(v_to_name, ''));

    SELECT company_id INTO v_company_id FROM treasuries WHERE id = p_from_treasury_id;
    v_from_acct := public.resolve_treasury_account(p_from_treasury_id, p_currency, v_company_id);
    v_to_acct   := public.resolve_treasury_account(p_to_treasury_id, p_currency, v_company_id);

    IF v_to_acct IS NULL THEN
        SELECT id INTO v_to_acct FROM public.accounts WHERE (account_code = '12612' OR code = '12612') AND is_active = true LIMIT 1;
    END IF;
    IF v_from_acct IS NULL THEN
        SELECT id INTO v_from_acct FROM public.accounts WHERE (account_code = '12612' OR code = '12612') AND is_active = true LIMIT 1;
    END IF;

    v_je_id := public.post_journal_entry(
        'custody_transfer', v_desc, CURRENT_DATE, v_company_id, v_user_id,
        jsonb_build_array(
            jsonb_build_object('account_id', v_to_acct, 'debit', p_amount, 'credit', 0, 'currency', p_currency, 'description', v_desc || ' (استلام تحويل)', 'base_debit', v_base_amount, 'base_credit', 0),
            jsonb_build_object('account_id', v_from_acct, 'debit', 0, 'credit', p_amount, 'currency', p_currency, 'description', v_desc || ' (إرسال تحويل)', 'base_debit', 0, 'base_credit', v_base_amount)
        )
    );

    INSERT INTO treasury_transactions (
        treasury_id, type, amount, currency, description,
        balance_before, balance_after,
        reference_type, reference_id, notes, created_by, journal_entry_id
    ) VALUES (
        p_from_treasury_id, 'transfer_out', p_amount, p_currency, v_desc,
        v_from_balance, v_from_balance - p_amount,
        'treasury', p_to_treasury_id::TEXT, p_notes, v_user_id, v_je_id
    ) RETURNING id INTO v_tx_id;

    INSERT INTO treasury_transactions (
        treasury_id, type, amount, currency, description,
        balance_before, balance_after,
        reference_type, reference_id, notes, created_by, journal_entry_id
    ) VALUES (
        p_to_treasury_id, 'transfer_in', p_amount, p_currency, v_desc,
        v_to_balance, v_to_balance + p_amount,
        'treasury', p_from_treasury_id::TEXT, p_notes, v_user_id, v_je_id
    );

    RETURN v_tx_id;
END;
$function$;


-- 6. return_custody
DROP FUNCTION IF EXISTS public.return_custody(p_from_treasury_id integer, p_to_treasury_id integer, p_currency text, p_amount numeric, p_description text);
DROP FUNCTION IF EXISTS public.return_custody(p_from_treasury_id integer, p_to_treasury_id integer, p_currency text, p_amount numeric, p_description text, p_notes text);

CREATE OR REPLACE FUNCTION public.return_custody(
    p_from_treasury_id integer,
    p_to_treasury_id integer,
    p_currency text,
    p_amount numeric,
    p_description text DEFAULT ''::text,
    p_notes text DEFAULT NULL::text
)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_from_balance NUMERIC;
    v_to_balance   NUMERIC;
    v_from_cost_base NUMERIC;
    v_to_cost_base NUMERIC;
    v_from_book_rate NUMERIC;
    v_to_book_rate NUMERIC;
    v_base_amount  NUMERIC;
    v_tx_id        BIGINT;
    v_je_id        BIGINT;
    v_company_id   UUID;
    v_from_acct    BIGINT;
    v_to_acct      BIGINT;
    v_desc         TEXT;
    v_user_id      UUID;
    v_from_name    TEXT;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        SELECT id INTO v_user_id FROM public.users LIMIT 1;
    END IF;

    SELECT COALESCE(balance, 0), COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_from_balance, v_from_cost_base, v_from_book_rate
    FROM treasury_balances 
    WHERE treasury_id = p_from_treasury_id AND currency = p_currency
    FOR UPDATE;

    IF v_from_balance IS NULL OR v_from_balance < p_amount THEN
        RAISE EXCEPTION 'الرصيد غير كاف لرد العهدة';
    END IF;

    IF p_currency = 'EGP' THEN
        v_base_amount := p_amount;
    ELSE
        v_base_amount := ROUND(p_amount * COALESCE(NULLIF(v_from_book_rate, 0), public.fn_get_exchange_rate(p_currency)), 2);
    END IF;

    UPDATE treasury_balances 
    SET balance = balance - p_amount,
        cost_base = GREATEST(0, COALESCE(cost_base, 0) - v_base_amount),
        updated_at = NOW()
    WHERE treasury_id = p_from_treasury_id AND currency = p_currency;

    SELECT COALESCE(balance, 0), COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_to_balance, v_to_cost_base, v_to_book_rate
    FROM treasury_balances 
    WHERE treasury_id = p_to_treasury_id AND currency = p_currency
    FOR UPDATE;

    IF NOT FOUND THEN
        v_to_balance := 0;
        v_to_cost_base := 0;
        v_to_book_rate := 1.0;
        INSERT INTO treasury_balances (treasury_id, currency, balance, cost_base, book_rate, account_id)
        VALUES (p_to_treasury_id, p_currency, 0, 0, 1.0, public.resolve_treasury_account(p_to_treasury_id, p_currency, (SELECT company_id FROM treasuries WHERE id = p_to_treasury_id)));
    END IF;

    IF p_currency = 'EGP' THEN
        v_to_book_rate := 1.0;
    ELSE
        IF (v_to_balance + p_amount) > 0 THEN
            v_to_book_rate := ROUND((v_to_cost_base + v_base_amount) / (v_to_balance + p_amount), 4);
        END IF;
    END IF;

    UPDATE treasury_balances
    SET balance = balance + p_amount,
        cost_base = COALESCE(cost_base, 0) + v_base_amount,
        book_rate = v_to_book_rate,
        updated_at = NOW()
    WHERE treasury_id = p_to_treasury_id AND currency = p_currency;

    SELECT name INTO v_from_name FROM treasuries WHERE id = p_from_treasury_id;
    v_desc := COALESCE(NULLIF(p_description, ''), 'إرجاع عهدة من ' || COALESCE(v_from_name, 'موظف'));

    SELECT company_id INTO v_company_id FROM treasuries WHERE id = p_from_treasury_id;
    v_from_acct := public.resolve_treasury_account(p_from_treasury_id, p_currency, v_company_id);
    v_to_acct   := public.resolve_treasury_account(p_to_treasury_id, p_currency, v_company_id);

    IF v_to_acct IS NULL THEN
        SELECT id INTO v_to_acct FROM public.accounts WHERE (account_code = '12211' OR code = '12211') AND is_active = true LIMIT 1;
    END IF;
    IF v_from_acct IS NULL THEN
        SELECT id INTO v_from_acct FROM public.accounts WHERE (account_code = '12612' OR code = '12612') AND is_active = true LIMIT 1;
    END IF;

    v_je_id := public.post_journal_entry(
        'return_custody', v_desc, CURRENT_DATE, v_company_id, v_user_id,
        jsonb_build_array(
            jsonb_build_object('account_id', v_to_acct, 'debit', p_amount, 'credit', 0, 'currency', p_currency, 'description', v_desc || ' (استلام مرتجع عهدة)', 'base_debit', v_base_amount, 'base_credit', 0),
            jsonb_build_object('account_id', v_from_acct, 'debit', 0, 'credit', p_amount, 'currency', p_currency, 'description', v_desc || ' (إرجاع عهدة)', 'base_debit', 0, 'base_credit', v_base_amount)
        )
    );

    INSERT INTO treasury_transactions (
        treasury_id, type, amount, currency, description,
        balance_before, balance_after,
        reference_type, reference_id, notes, created_by, journal_entry_id
    ) VALUES (
        p_from_treasury_id, 'return_out', p_amount, p_currency, v_desc,
        v_from_balance, v_from_balance - p_amount,
        'treasury', p_to_treasury_id::TEXT, p_notes, v_user_id, v_je_id
    ) RETURNING id INTO v_tx_id;

    INSERT INTO treasury_transactions (
        treasury_id, type, amount, currency, description,
        balance_before, balance_after,
        reference_type, reference_id, notes, created_by, journal_entry_id
    ) VALUES (
        p_to_treasury_id, 'return_in', p_amount, p_currency, v_desc,
        v_to_balance, v_to_balance + p_amount,
        'treasury', p_from_treasury_id::TEXT, p_notes, v_user_id, v_je_id
    );

    RETURN v_tx_id;
END;
$function$;


-- 7. bank_transfer
DROP FUNCTION IF EXISTS public.bank_transfer(p_from_account_id integer, p_to_account_id integer, p_amount numeric, p_description text);
DROP FUNCTION IF EXISTS public.bank_transfer(p_from_account_id integer, p_to_account_id integer, p_amount numeric, p_description text, p_bank_fee numeric);
DROP FUNCTION IF EXISTS public.bank_transfer(p_from_account_id integer, p_to_account_id integer, p_amount numeric, p_description text, p_bank_fee numeric, p_notes text);

CREATE OR REPLACE FUNCTION public.bank_transfer(p_from_account_id integer, p_to_account_id integer, p_amount numeric, p_description text DEFAULT NULL::text, p_bank_fee numeric DEFAULT 0.0, p_notes text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_from_balance NUMERIC;
    v_to_balance   NUMERIC;
    v_from_currency TEXT;
    v_to_currency  TEXT;
    v_cost_base_from NUMERIC;
    v_cost_base_to NUMERIC;
    v_book_rate_from NUMERIC;
    v_transfer_cost NUMERIC;
    v_company_id   UUID;
    v_from_acct    BIGINT;
    v_to_acct      BIGINT;
    v_je_id        BIGINT;
    v_desc         TEXT;
    v_lines        JSONB := '[]'::jsonb;
BEGIN
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'المبلغ يجب أن يكون أكبر من صفر';
    END IF;

    IF p_from_account_id = p_to_account_id THEN
        RAISE EXCEPTION 'لا يمكن التحويل للحساب نفسه';
    END IF;

    -- Lock and check source
    SELECT COALESCE(balance, 0), currency, COALESCE(cost_base, 0), COALESCE(book_rate, 1.0), company_id 
    INTO v_from_balance, v_from_currency, v_cost_base_from, v_book_rate_from, v_company_id
    FROM public.bank_accounts WHERE id = p_from_account_id FOR UPDATE;

    IF v_from_balance < p_amount THEN
        RAISE EXCEPTION 'الرصيد غير كافٍ في الحساب المصدر (المتوفر: %)', v_from_balance;
    END IF;

    -- Check destination
    SELECT COALESCE(balance, 0), currency, COALESCE(cost_base, 0)
    INTO v_to_balance, v_to_currency, v_cost_base_to
    FROM public.bank_accounts WHERE id = p_to_account_id FOR UPDATE;

    IF v_from_currency != v_to_currency THEN
        RAISE EXCEPTION 'التحويل البنكي المباشر مخصص للحسابات من نفس العملة. للتحويل بين عملات مختلفة استخدم صرف العملة البنكي.';
    END IF;

    v_desc := COALESCE(NULLIF(p_description, ''), 'تحويل بنكي داخلي (' || v_from_currency || ')');

    IF v_from_currency = 'EGP' THEN
        v_transfer_cost := p_amount;
    ELSE
        v_transfer_cost := ROUND(p_amount * v_book_rate_from, 2);
    END IF;

    -- Update balances & cost bases
    UPDATE public.bank_accounts 
    SET balance = balance - p_amount,
        cost_base = GREATEST(0.00, v_cost_base_from - v_transfer_cost),
        updated_at = NOW()
    WHERE id = p_from_account_id;

    UPDATE public.bank_accounts 
    SET balance = balance + p_amount,
        cost_base = v_cost_base_to + v_transfer_cost,
        book_rate = CASE WHEN (balance + p_amount) > 0 THEN ROUND((v_cost_base_to + v_transfer_cost) / (balance + p_amount), 4) ELSE v_book_rate_from END,
        updated_at = NOW()
    WHERE id = p_to_account_id;

    -- Resolve GL accounts
    v_from_acct := public.resolve_gl_account(
        CASE v_from_currency WHEN 'EGP' THEN '11201' WHEN 'USD' THEN '11202' WHEN 'EUR' THEN '11203' WHEN 'GBP' THEN '11204' ELSE '11201' END,
        v_company_id
    );
    v_to_acct := public.resolve_gl_account(
        CASE v_to_currency WHEN 'EGP' THEN '11201' WHEN 'USD' THEN '11202' WHEN 'EUR' THEN '11203' WHEN 'GBP' THEN '11204' ELSE '11201' END,
        v_company_id
    );

    v_lines := jsonb_build_array(
        jsonb_build_object('account_id', v_to_acct, 'debit', p_amount, 'credit', 0, 'base_debit', v_transfer_cost, 'base_credit', 0, 'currency', v_from_currency, 'description', v_desc || ' (وارد)'),
        jsonb_build_object('account_id', v_from_acct, 'debit', 0, 'credit', p_amount, 'base_debit', 0, 'base_credit', v_transfer_cost, 'currency', v_from_currency, 'description', v_desc || ' (صادر)')
    );

    -- GL: Dr.Destination Bank / Cr.Source Bank (Zero Net Effect)
    v_je_id := public.post_journal_entry(
        'bank_transfer', v_desc, CURRENT_DATE, v_company_id, auth.uid(),
        v_lines
    );

    -- Record transactions with notes mapped to p_notes
    INSERT INTO public.bank_account_transactions (
        bank_account_id, type, amount, balance_before, balance_after, description, 
        created_by, journal_entry_id, amount_in_base_currency, cost_base_released, bank_fee, transfer_mode, notes
    ) VALUES (
        p_from_account_id, 'transfer_out', p_amount, v_from_balance, v_from_balance - p_amount, 
        v_desc, auth.uid(), v_je_id, v_transfer_cost, v_transfer_cost, 0, 'internal_transfer', p_notes
    );

    INSERT INTO public.bank_account_transactions (
        bank_account_id, type, amount, balance_before, balance_after, description, 
        created_by, journal_entry_id, amount_in_base_currency, cost_base_released, transfer_mode, notes
    ) VALUES (
        p_to_account_id, 'transfer_in', p_amount, v_to_balance, v_to_balance + p_amount, 
        v_desc, auth.uid(), v_je_id, v_transfer_cost, 0, 'internal_transfer', p_notes
    );

    RETURN jsonb_build_object('success', true, 'journal_entry_id', v_je_id, 'cost_base', v_transfer_cost);
END;
$function$;

GRANT EXECUTE ON FUNCTION public.deposit_treasury(integer, text, numeric, text, integer, text, text, text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.withdraw_treasury(integer, text, numeric, text, text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.spend_with_category(bigint, text, numeric, text, integer, integer, uuid, bigint, bigint, uuid, integer, text, text, text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.disburse_custody(integer, integer, text, numeric, text, text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.transfer_custody(integer, integer, text, numeric, text, text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.return_custody(integer, integer, text, numeric, text, text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.bank_transfer(integer, integer, numeric, text, numeric, text) TO authenticated, service_role;

-- ============================================================================
-- المرحلة 8: تهيئة المساهمين وإعدادات توزيع الأرباح (Migration 354 Mirror)
-- ============================================================================
DO $$
DECLARE
  v_p1_id UUID;
  v_p2_id UUID;
  v_p3_id UUID;
  v_company_id UUID;
  v_acct_islam BIGINT;
  v_acct_abdelbatin BIGINT;
  v_acct_emad BIGINT;
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'sys_companies') THEN
    SELECT id INTO v_company_id FROM public.sys_companies WHERE deleted_at IS NULL ORDER BY created_at ASC LIMIT 1;
  END IF;

  -- جلب حسابات المساهمين المعتمدة الثلاثة (23211, 23212, 23213)
  SELECT id INTO v_acct_islam FROM public.accounts WHERE account_code = '23213' LIMIT 1;
  SELECT id INTO v_acct_abdelbatin FROM public.accounts WHERE account_code = '23212' LIMIT 1;
  SELECT id INTO v_acct_emad FROM public.accounts WHERE account_code = '23211' LIMIT 1;

  -- 1. إسلام
  IF NOT EXISTS (SELECT 1 FROM public.shareholders WHERE name = 'إسلام') THEN
    INSERT INTO public.shareholders (code, name, company_id, initial_balance_egp, current_balance_egp, initial_balance_direction_egp, account_id)
    VALUES ('00001', 'إسلام', v_company_id, 0, 0, 'CREDIT', v_acct_islam);
  END IF;

  -- 2. عبدالباطن
  IF NOT EXISTS (SELECT 1 FROM public.shareholders WHERE name = 'عبدالباطن') THEN
    INSERT INTO public.shareholders (code, name, company_id, initial_balance_egp, current_balance_egp, initial_balance_direction_egp, account_id)
    VALUES ('00002', 'عبدالباطن', v_company_id, 0, 0, 'CREDIT', v_acct_abdelbatin);
  END IF;

  -- 3. عماد
  IF NOT EXISTS (SELECT 1 FROM public.shareholders WHERE name = 'عماد') THEN
    INSERT INTO public.shareholders (code, name, company_id, initial_balance_egp, current_balance_egp, initial_balance_direction_egp, account_id)
    VALUES ('00003', 'عماد', v_company_id, 0, 0, 'CREDIT', v_acct_emad);
  END IF;

  -- Fetch their IDs
  SELECT id INTO v_p1_id FROM public.shareholders WHERE name = 'إسلام' LIMIT 1;
  SELECT id INTO v_p2_id FROM public.shareholders WHERE name = 'عبدالباطن' LIMIT 1;
  SELECT id INTO v_p3_id FROM public.shareholders WHERE name = 'عماد' LIMIT 1;

  -- 3. Ensure profit_distribution_settings default row exists
  IF EXISTS (SELECT 1 FROM public.profit_distribution_settings LIMIT 1) THEN
    UPDATE public.profit_distribution_settings
    SET person1_id = v_p1_id,
        person1_name = 'إسلام',
        person2_id = v_p2_id,
        person2_name = 'عبدالباطن',
        person3_id = v_p3_id,
        person3_name = 'عماد',
        updated_at = NOW()
    WHERE id = (SELECT id FROM public.profit_distribution_settings ORDER BY updated_at DESC LIMIT 1);
  ELSE
    INSERT INTO public.profit_distribution_settings (
      person1_id, person1_name,
      person2_id, person2_name,
      person3_id, person3_name,
      percentages, person4_for_shipment, currency_conversions,
      user_id
    ) VALUES (
      v_p1_id, 'إسلام',
      v_p2_id, 'عبدالباطن',
      v_p3_id, 'عماد',
      '{}'::jsonb, '{}'::jsonb, '{}'::jsonb,
      COALESCE((SELECT id FROM auth.users LIMIT 1), '00000000-0000-0000-0000-000000000000'::uuid)
    );
  END IF;

  -- مزامنة حسابات المساهمين مع الحساب الأب 2321 وإعادة بناء مسارات الشجرة بالكامل
  UPDATE public.shareholders s
  SET account_id = a.id
  FROM public.accounts a
  WHERE (s.account_id IS NULL OR s.account_id != a.id)
    AND (
      a.account_name = 'جارى أ / ' || s.name
      OR a.account_name = 'مساهم - ' || s.name
      OR a.name = 'Shareholder - ' || s.name
      OR (s.name LIKE '%عماد%' AND a.account_code = '23211')
      OR (s.name LIKE '%عبدالباطن%' AND a.account_code = '23212')
      OR (s.name LIKE '%إسلام%' AND a.account_code = '23213')
      OR (s.name LIKE '%اسلام%' AND a.account_code = '23213')
    );

  PERFORM public.rebuild_chart_of_accounts_hierarchy();

  -- ضمان حذف الحسابات الزائدة غير المستخدمة نهائياً (مع الحفاظ على أي حساب مساهم نشط أو به حركات)
  DELETE FROM public.accounts a 
  WHERE a.account_code IN ('232101', '232102', '232103')
    AND NOT EXISTS (SELECT 1 FROM public.shareholders sh WHERE sh.account_id = a.id)
    AND NOT EXISTS (SELECT 1 FROM public.account_ledger_entries ale WHERE ale.account_id = a.id);
END $$;

-- ============================================================================
-- ── Treasury Draft & Confirm Workflow Support ──
-- ============================================================================

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'treasury_transactions' AND column_name = 'status'
    ) THEN
        ALTER TABLE public.treasury_transactions 
        ADD COLUMN status TEXT NOT NULL DEFAULT 'confirmed';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'treasury_transactions' AND column_name = 'payload'
    ) THEN
        ALTER TABLE public.treasury_transactions 
        ADD COLUMN payload JSONB DEFAULT '{}'::jsonb;
    END IF;

    ALTER TABLE public.treasury_transactions 
        DROP CONSTRAINT IF EXISTS treasury_transactions_type_check;

    ALTER TABLE public.treasury_transactions 
        ADD CONSTRAINT treasury_transactions_type_check 
        CHECK (type = ANY (ARRAY[
            'deposit',
            'expense',
            'withdrawal',
            'withdraw',
            'disbursement',
            'disbursement_out',
            'transfer_in',
            'transfer_out',
            'transfer',
            'return_in',
            'return_out',
            'currency_exchange_out',
            'currency_exchange_in',
            'currency_exchange',
            'exchange',
            'exchange_out',
            'exchange_in',
            'supplier_payment',
            'customer_payment',
            'clearing_agent_payment',
            'shipping_company_payment',
            'shareholder_payment',
            'shareholder_withdrawal',
            'customer_refund',
            'revenue',
            'multi_payment',
            'receipt'
        ]));

    ALTER TABLE public.bank_account_transactions 
        DROP CONSTRAINT IF EXISTS bank_account_transactions_type_check;

    ALTER TABLE public.bank_account_transactions 
        ADD CONSTRAINT bank_account_transactions_type_check 
        CHECK (type = ANY (ARRAY[
            'deposit',
            'withdraw',
            'withdrawal',
            'exchange_in',
            'exchange_out',
            'currency_exchange_in',
            'currency_exchange_out',
            'currency_exchange',
            'exchange',
            'transfer_in',
            'transfer_out',
            'transfer',
            'supplier_payment',
            'customer_payment',
            'clearing_agent_payment',
            'shipping_company_payment',
            'shareholder_payment',
            'shareholder_withdrawal',
            'customer_refund',
            'revenue',
            'multi_payment',
            'receipt',
            'expense'
        ]));
END $$;

CREATE OR REPLACE FUNCTION public.fn_require_expense_account_treasury()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
    IF NEW.status = 'draft' THEN
        RETURN NEW;
    END IF;

    IF NEW.type = 'expense' 
       AND NEW.expense_account_id IS NULL 
       AND NEW.supplier_id IS NULL 
       AND NEW.customer_id IS NULL 
       AND NEW.clearing_agent_id IS NULL 
       AND NEW.shipping_company_id IS NULL 
       AND NEW.shareholder_id IS NULL THEN
        RAISE EXCEPTION 'يجب اختيار حساب مصروفات من شجرة الحسابات — لا يسمح بالقيود الافتراضية';
    END IF;

    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.fn_require_revenue_account_treasury()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
    IF NEW.status = 'draft' THEN
        RETURN NEW;
    END IF;

    -- Skip revenue account check for internal transfers, cheque feedings, custody settlements, and opening balances
    IF NEW.source_type IN ('cheque', 'transfer', 'bank_transfer', 'treasury_transfer', 'opening_balance', 'custody_settlement')
       OR NEW.reference_type IN ('cheque', 'transfer', 'bank_transfer', 'custody_settlement') THEN
        RETURN NEW;
    END IF;

    IF NEW.type = 'deposit' 
       AND NEW.revenue_account_id IS NULL 
       AND NEW.customer_id IS NULL 
       AND NEW.supplier_id IS NULL 
       AND NEW.clearing_agent_id IS NULL 
       AND NEW.shipping_company_id IS NULL 
       AND NEW.shareholder_id IS NULL THEN
        RAISE EXCEPTION 'يجب اختيار حساب إيرادات من شجرة الحسابات — لا يسمح بالقيود الافتراضية';
    END IF;

    RETURN NEW;
END;
$$;
-- ── rpc_save_treasury_draft & rpc_update_treasury_draft ─────────────────────
ALTER TABLE public.treasury_transactions
  ADD COLUMN IF NOT EXISTS cost_center_id TEXT,
  ADD COLUMN IF NOT EXISTS branch_id BIGINT,
  ADD COLUMN IF NOT EXISTS to_branch_id BIGINT,
  ADD COLUMN IF NOT EXISTS to_cost_center_id TEXT;

DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT oid::regprocedure AS func_sig 
             FROM pg_proc 
             WHERE proname IN ('rpc_save_treasury_draft', 'rpc_update_treasury_draft')
               AND pronamespace = 'public'::regnamespace
    LOOP
        EXECUTE 'DROP FUNCTION ' || r.func_sig || ' CASCADE';
    END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.rpc_save_treasury_draft(
    p_treasury_id BIGINT,
    p_type TEXT,
    p_amount NUMERIC,
    p_currency TEXT,
    p_description TEXT DEFAULT NULL,
    p_notes TEXT DEFAULT NULL,
    p_category_id BIGINT DEFAULT NULL,
    p_expense_account_id BIGINT DEFAULT NULL,
    p_revenue_account_id BIGINT DEFAULT NULL,
    p_customer_id BIGINT DEFAULT NULL,
    p_supplier_id UUID DEFAULT NULL,
    p_clearing_agent_id BIGINT DEFAULT NULL,
    p_shipping_company_id BIGINT DEFAULT NULL,
    p_shareholder_id UUID DEFAULT NULL,
    p_payload JSONB DEFAULT '{}'::jsonb,
    p_cost_center_id TEXT DEFAULT NULL,
    p_branch_id BIGINT DEFAULT NULL,
    p_to_branch_id BIGINT DEFAULT NULL,
    p_to_cost_center_id TEXT DEFAULT NULL
)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_tx_id BIGINT;
    v_payload JSONB;
    v_cc_id TEXT;
    v_branch_id BIGINT;
    v_cat_id BIGINT := p_category_id;
BEGIN
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'المبلغ يجب أن يكون أكبر من صفر';
    END IF;

    -- Safety check: ensure category_id actually exists in expense_categories to prevent FK 23503
    IF v_cat_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.expense_categories WHERE id = v_cat_id) THEN
        v_cat_id := NULL;
    END IF;

    v_cc_id := COALESCE(p_cost_center_id, p_payload->>'cost_center_id');
    v_branch_id := COALESCE(p_branch_id, CASE WHEN (p_payload->>'branch_id') ~ '^[0-9]+$' THEN (p_payload->>'branch_id')::BIGINT ELSE NULL END);

    v_payload := COALESCE(p_payload, '{}'::jsonb);
    IF v_cc_id IS NOT NULL THEN
        v_payload := jsonb_set(v_payload, '{cost_center_id}', to_jsonb(v_cc_id));
    END IF;
    IF v_branch_id IS NOT NULL THEN
        v_payload := jsonb_set(v_payload, '{branch_id}', to_jsonb(v_branch_id));
    END IF;
    IF p_to_branch_id IS NOT NULL THEN
        v_payload := jsonb_set(v_payload, '{to_branch_id}', to_jsonb(p_to_branch_id));
    END IF;
    IF p_to_cost_center_id IS NOT NULL THEN
        v_payload := jsonb_set(v_payload, '{to_cost_center_id}', to_jsonb(p_to_cost_center_id));
    END IF;

    INSERT INTO public.treasury_transactions (
        treasury_id,
        type,
        amount,
        currency,
        description,
        notes,
        category_id,
        expense_account_id,
        revenue_account_id,
        customer_id,
        supplier_id,
        clearing_agent_id,
        shipping_company_id,
        shareholder_id,
        status,
        payload,
        cost_center_id,
        branch_id,
        to_branch_id,
        to_cost_center_id,
        created_by,
        created_at
    ) VALUES (
        p_treasury_id,
        p_type,
        p_amount,
        p_currency,
        p_description,
        p_notes,
        v_cat_id,
        p_expense_account_id,
        p_revenue_account_id,
        p_customer_id,
        p_supplier_id,
        p_clearing_agent_id,
        p_shipping_company_id,
        p_shareholder_id,
        'draft',
        v_payload,
        v_cc_id,
        v_branch_id,
        p_to_branch_id,
        p_to_cost_center_id,
        auth.uid(),
        NOW()
    )
    RETURNING id INTO v_tx_id;

    RETURN v_tx_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_save_treasury_draft(BIGINT, TEXT, NUMERIC, TEXT, TEXT, TEXT, BIGINT, BIGINT, BIGINT, BIGINT, UUID, BIGINT, BIGINT, UUID, JSONB, TEXT, BIGINT, BIGINT, TEXT) TO authenticated, service_role, anon;

CREATE OR REPLACE FUNCTION public.rpc_update_treasury_draft(
    p_transaction_id BIGINT,
    p_treasury_id BIGINT DEFAULT NULL,
    p_amount NUMERIC DEFAULT NULL,
    p_currency TEXT DEFAULT NULL,
    p_description TEXT DEFAULT NULL,
    p_notes TEXT DEFAULT NULL,
    p_category_id BIGINT DEFAULT NULL,
    p_expense_account_id BIGINT DEFAULT NULL,
    p_revenue_account_id BIGINT DEFAULT NULL,
    p_customer_id BIGINT DEFAULT NULL,
    p_supplier_id UUID DEFAULT NULL,
    p_clearing_agent_id BIGINT DEFAULT NULL,
    p_shipping_company_id BIGINT DEFAULT NULL,
    p_shareholder_id UUID DEFAULT NULL,
    p_payload JSONB DEFAULT NULL,
    p_cost_center_id TEXT DEFAULT NULL,
    p_branch_id BIGINT DEFAULT NULL,
    p_to_branch_id BIGINT DEFAULT NULL,
    p_to_cost_center_id TEXT DEFAULT NULL
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_cc_id TEXT;
    v_branch_id BIGINT;
    v_payload JSONB;
    v_cat_id BIGINT := p_category_id;
BEGIN
    -- Safety check: ensure category_id actually exists in expense_categories to prevent FK 23503
    IF v_cat_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.expense_categories WHERE id = v_cat_id) THEN
        v_cat_id := NULL;
    END IF;

    v_cc_id := COALESCE(p_cost_center_id, p_payload->>'cost_center_id');
    v_branch_id := COALESCE(p_branch_id, CASE WHEN (p_payload->>'branch_id') ~ '^[0-9]+$' THEN (p_payload->>'branch_id')::BIGINT ELSE NULL END);

    UPDATE public.treasury_transactions
    SET
        treasury_id = COALESCE(p_treasury_id, treasury_id),
        amount = COALESCE(p_amount, amount),
        currency = COALESCE(p_currency, currency),
        description = COALESCE(p_description, description),
        notes = p_notes,
        category_id = v_cat_id,
        expense_account_id = p_expense_account_id,
        revenue_account_id = p_revenue_account_id,
        customer_id = p_customer_id,
        supplier_id = p_supplier_id,
        clearing_agent_id = p_clearing_agent_id,
        shipping_company_id = p_shipping_company_id,
        shareholder_id = p_shareholder_id,
        cost_center_id = COALESCE(v_cc_id, cost_center_id),
        branch_id = COALESCE(v_branch_id, branch_id),
        to_branch_id = COALESCE(p_to_branch_id, to_branch_id),
        to_cost_center_id = COALESCE(p_to_cost_center_id, to_cost_center_id),
        payload = CASE 
            WHEN p_payload IS NOT NULL THEN p_payload
            ELSE payload 
        END
    WHERE id = p_transaction_id AND status = 'draft';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'لم يتم العثور على المسودة أو أنها مؤكدة بالفعل';
    END IF;

    RETURN TRUE;
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_update_treasury_draft(BIGINT, BIGINT, NUMERIC, TEXT, TEXT, TEXT, BIGINT, BIGINT, BIGINT, BIGINT, UUID, BIGINT, BIGINT, UUID, JSONB, TEXT, BIGINT, BIGINT, TEXT) TO authenticated, service_role, anon;



CREATE OR REPLACE FUNCTION public.rpc_delete_treasury_draft(
    p_transaction_id BIGINT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_deleted_count INT;
BEGIN
    DELETE FROM public.treasury_transactions
    WHERE id = p_transaction_id AND status = 'draft';

    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    IF v_deleted_count = 0 THEN
        RAISE EXCEPTION 'لم يتم العثور على المسودة أو تم تأكيدها مسبقاً';
    END IF;

    RETURN TRUE;
END;
$$;

CREATE OR REPLACE FUNCTION public.rpc_confirm_treasury_draft(
    p_transaction_id BIGINT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_tx RECORD;
    v_res JSONB;
    v_receipt_type TEXT;
    v_counterparty_type TEXT;
    v_mp_source_type TEXT;
    v_mp_source_id BIGINT;
BEGIN
    SELECT * INTO v_tx
    FROM public.treasury_transactions
    WHERE id = p_transaction_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'الحركة غير موجودة';
    END IF;

    IF v_tx.status != 'draft' THEN
        RAISE EXCEPTION 'هذه الحركة مؤكدة بالفعل وليست مسودة';
    END IF;

    IF v_tx.type = 'deposit' OR v_tx.type = 'receipt' THEN
        v_receipt_type := COALESCE(v_tx.payload->>'receipt_type', 'cash');
        v_counterparty_type := v_tx.payload->>'counterparty_type';

        v_res := public.receive_payment(
            p_receipt_type      := v_receipt_type,
            p_amount            := v_tx.amount,
            p_currency          := v_tx.currency,
            p_counterparty_type := v_counterparty_type,
            p_counterparty_id   := v_tx.customer_id,
            p_supplier_id       := v_tx.supplier_id,
            p_shareholder_id    := v_tx.shareholder_id,
            p_description       := v_tx.description,
            p_notes             := v_tx.notes,
            p_treasury_id       := v_tx.treasury_id
        );

        DELETE FROM public.treasury_transactions WHERE id = p_transaction_id;

        RETURN jsonb_build_object('success', true, 'message', 'تم تأكيد الاستلام وترحيل القيد بنجاح', 'result', v_res);

    ELSIF v_tx.type = 'multi_payment' OR COALESCE((v_tx.payload->>'is_multi_payment')::boolean, false) = true THEN
        -- Read source_type and source_id from payload (fixes bank account multi-payment)
        v_mp_source_type := COALESCE(v_tx.payload->>'source_type', 'treasury');
        v_mp_source_id   := COALESCE(
            (v_tx.payload->>'source_id')::bigint,
            v_tx.treasury_id::bigint
        );

        v_res := public.rpc_entity_multi_payment(
            p_source_type        := v_mp_source_type,
            p_source_id          := v_mp_source_id,
            p_currency           := v_tx.currency,
            p_amount             := v_tx.amount,
            p_entity_type        := LOWER(COALESCE(v_tx.payload->>'entity_type', 'supplier')),
            p_entity_id          := COALESCE(v_tx.payload->>'entity_id', v_tx.supplier_id::text),
            p_description        := COALESCE(v_tx.description, 'سداد متعدد'),
            p_notes              := v_tx.notes,
            p_expense_account_id := v_tx.expense_account_id
        );

        DELETE FROM public.treasury_transactions WHERE id = p_transaction_id;

        RETURN jsonb_build_object('success', true, 'message', 'تم تأكيد السداد المتعدد بنجاح', 'result', v_res);

    ELSIF v_tx.type = 'exchange' OR v_tx.type = 'currency_exchange' THEN
        PERFORM public.exchange_currency(
            p_treasury_id   := v_tx.treasury_id::text,
            p_from_currency := COALESCE(v_tx.payload->>'from_currency', v_tx.currency),
            p_to_currency   := (v_tx.payload->>'to_currency')::text,
            p_amount_from   := COALESCE((v_tx.payload->>'amount_from')::numeric, v_tx.amount),
            p_amount_to     := (v_tx.payload->>'amount_to')::numeric,
            p_exchange_rate := (v_tx.payload->>'exchange_rate')::numeric,
            p_user_id       := v_tx.created_by,
            p_transfer_mode := COALESCE(v_tx.payload->>'transfer_mode', 'exchange')
        );

        DELETE FROM public.treasury_transactions WHERE id = p_transaction_id;

        RETURN jsonb_build_object('success', true, 'message', 'تم تأكيد تحويل العملة وترحيل القيد بنجاح');

    ELSE
        IF v_tx.category_id IS NOT NULL AND v_tx.category_id > 0 THEN
            PERFORM public.spend_with_category(
                p_treasury_id          := v_tx.treasury_id,
                p_currency             := v_tx.currency,
                p_amount               := v_tx.amount,
                p_description          := COALESCE(v_tx.description, ''),
                p_category_id          := v_tx.category_id::integer,
                p_customer_id          := v_tx.customer_id::integer,
                p_supplier_id          := v_tx.supplier_id,
                p_clearing_agent_id    := v_tx.clearing_agent_id,
                p_shipping_company_id  := v_tx.shipping_company_id,
                p_shareholder_id       := v_tx.shareholder_id,
                p_expense_account_id   := v_tx.expense_account_id::integer,
                p_reference_type       := v_tx.payload->>'reference_type',
                p_reference_id         := v_tx.payload->>'reference_id',
                p_notes                := v_tx.notes
            );
        ELSE
            PERFORM public.spend_custody(
                p_treasury_id          := v_tx.treasury_id,
                p_currency             := v_tx.currency,
                p_amount               := v_tx.amount,
                p_description          := COALESCE(v_tx.description, ''),
                p_expense_account_id   := v_tx.expense_account_id::integer,
                p_customer_id          := v_tx.customer_id::integer,
                p_supplier_id          := v_tx.supplier_id,
                p_clearing_agent_id    := v_tx.clearing_agent_id,
                p_shipping_company_id  := v_tx.shipping_company_id,
                p_shareholder_id       := v_tx.shareholder_id,
                p_reference_type       := v_tx.payload->>'reference_type',
                p_reference_id         := v_tx.payload->>'reference_id',
                p_notes                := v_tx.notes
            );
        END IF;

        DELETE FROM public.treasury_transactions WHERE id = p_transaction_id;

        RETURN jsonb_build_object('success', true, 'message', 'تم تأكيد صرف المصروف وترحيل القيد بنجاح');
    END IF;
END;
$$;

-- ============================================================================
-- ── Treasury Multi-Currency Cost Base & Exchange Engine (IAS 21) ──
-- ============================================================================

CREATE OR REPLACE FUNCTION public.receive_payment(
    p_receipt_type character varying,
    p_amount numeric,
    p_currency character varying,
    p_counterparty_type character varying DEFAULT NULL::character varying,
    p_counterparty_id bigint DEFAULT NULL::bigint,
    p_supplier_id uuid DEFAULT NULL::uuid,
    p_shareholder_id uuid DEFAULT NULL::uuid,
    p_description text DEFAULT NULL::text,
    p_notes text DEFAULT NULL::text,
    p_treasury_id bigint DEFAULT NULL::bigint
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_treasury_id       BIGINT;
    v_current_balance   NUMERIC := 0;
    v_current_cost_base NUMERIC := 0;
    v_current_book_rate NUMERIC := 1.0;
    v_new_balance       NUMERIC := 0;
    v_new_cost_base     NUMERIC := 0;
    v_new_book_rate     NUMERIC := 1.0;
    v_tx_id             BIGINT;
    v_company_id        UUID;
    v_treasury_acct     BIGINT;
    v_ar_acct           BIGINT;
    v_je_id             BIGINT;
    v_desc              TEXT;
    v_counterparty_name TEXT;
    v_source_type       TEXT;
    v_treasury_name     TEXT;
    v_je_source         TEXT;
    v_credit_acct       BIGINT;
    v_rate              NUMERIC := 1.0;
    v_base_amount       NUMERIC;
    v_snapshot          JSONB;
BEGIN
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'المبلغ يجب أن يكون أكبر من صفر';
    END IF;

    IF p_treasury_id IS NOT NULL THEN
        v_treasury_id := p_treasury_id;
    ELSE
        SELECT id INTO v_treasury_id
        FROM public.treasuries
        WHERE type = 'main' AND user_id = auth.uid()
        LIMIT 1;
        IF v_treasury_id IS NULL THEN
            SELECT id INTO v_treasury_id FROM public.treasuries WHERE type = 'main' LIMIT 1;
        END IF;
        IF v_treasury_id IS NULL THEN
            RAISE EXCEPTION 'لم يتم العثور على الخزينة الرئيسية.';
        END IF;
    END IF;

    SELECT t.company_id INTO v_company_id FROM public.treasuries t WHERE t.id = v_treasury_id;

    -- 1. Lock treasury balance row & retrieve current cost_base and book_rate
    SELECT COALESCE(balance, 0), COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_current_balance, v_current_cost_base, v_current_book_rate
    FROM public.treasury_balances
    WHERE treasury_id::TEXT = v_treasury_id::TEXT AND currency = p_currency
    FOR UPDATE;

    -- 2. Calculate spot exchange rate & base amount
    IF p_currency = 'EGP' THEN
        v_rate := 1.0;
        v_base_amount := p_amount;
        v_new_cost_base := COALESCE(v_current_cost_base, 0) + p_amount;
        v_new_book_rate := 1.0;
    ELSE
        v_rate := public.fn_get_exchange_rate(p_currency);
        v_base_amount := ROUND(p_amount * v_rate, 2);
        v_new_cost_base := COALESCE(v_current_cost_base, 0) + v_base_amount;
    END IF;

    v_new_balance := COALESCE(v_current_balance, 0) + p_amount;

    IF v_new_balance > 0 AND p_currency != 'EGP' THEN
        v_new_book_rate := ROUND(v_new_cost_base / v_new_balance, 4);
    ELSIF p_currency = 'EGP' THEN
        v_new_book_rate := 1.0;
    ELSE
        v_new_book_rate := v_rate;
    END IF;

    IF p_counterparty_type IS NULL OR p_counterparty_type = 'opening' THEN
        v_source_type := 'opening_balance';
        SELECT name INTO v_treasury_name FROM public.treasuries WHERE id = v_treasury_id;
        v_desc := COALESCE(
            NULLIF(p_description, ''),
            'الرصيد الافتتاحي لل' || COALESCE(v_treasury_name, 'الخزينة الرئيسية')
        );
    ELSE
        v_source_type := p_counterparty_type;
        v_desc := COALESCE(NULLIF(p_description, ''), 'استلام ' || p_receipt_type);
    END IF;

    v_treasury_acct := public.resolve_treasury_account(v_treasury_id, p_currency, v_company_id);

    IF p_counterparty_type = 'customer' THEN
        SELECT c.account_id, c.name INTO v_credit_acct, v_counterparty_name FROM public.customers c WHERE c.id = p_counterparty_id;
        IF v_counterparty_name IS NOT NULL AND v_counterparty_name != '' THEN
            IF p_description IS NOT NULL AND p_description != '' AND p_description NOT LIKE '%' || v_counterparty_name || '%' THEN
                v_desc := p_description || ' - العميل: ' || v_counterparty_name || ' (سداد حساب العميل)';
            ELSIF p_description IS NULL OR p_description = '' OR p_description = 'استلام ' || p_receipt_type THEN
                v_desc := 'استلام نقدية من العميل ' || v_counterparty_name || ' (سداد حساب العميل)';
            END IF;
        END IF;
        IF v_credit_acct IS NOT NULL THEN
            SELECT id INTO v_credit_acct FROM public.accounts WHERE id = v_credit_acct AND is_leaf = true AND is_active = true;
        END IF;
        IF v_credit_acct IS NULL THEN
            v_credit_acct := public.resolve_gl_account('12511', v_company_id);
        END IF;
    ELSIF p_counterparty_type = 'supplier' THEN
        SELECT s.account_id, s.name INTO v_credit_acct, v_counterparty_name FROM public.suppliers s WHERE s.id = p_supplier_id;
        IF v_counterparty_name IS NOT NULL AND v_counterparty_name != '' THEN
            IF p_description IS NOT NULL AND p_description != '' AND p_description NOT LIKE '%' || v_counterparty_name || '%' THEN
                v_desc := p_description || ' - المورد: ' || v_counterparty_name || ' (إيداع نقدي / دفعة مقدمة)';
            ELSIF p_description IS NULL OR p_description = '' OR p_description = 'استلام ' || p_receipt_type OR p_description LIKE 'استلام % من ' || v_counterparty_name THEN
                v_desc := 'إيداع نقدي / دفعة مقدمة من المورد ' || v_counterparty_name;
            END IF;
        END IF;
        IF v_credit_acct IS NOT NULL THEN
            SELECT id INTO v_credit_acct FROM public.accounts WHERE id = v_credit_acct AND is_leaf = true AND is_active = true;
        END IF;
        IF v_credit_acct IS NULL THEN
            v_credit_acct := public.resolve_gl_account('21113', v_company_id);
        END IF;
        IF v_credit_acct IS NULL THEN
            v_credit_acct := public.resolve_gl_account('2000', v_company_id);
        END IF;
    ELSIF p_counterparty_type = 'clearing_agent' THEN
        SELECT ca.account_id INTO v_credit_acct FROM public.clearing_agents ca WHERE ca.id = p_counterparty_id;
        IF v_credit_acct IS NOT NULL THEN
            SELECT id INTO v_credit_acct FROM public.accounts WHERE id = v_credit_acct AND is_leaf = true AND is_active = true;
        END IF;
        IF v_credit_acct IS NULL THEN
            v_credit_acct := public.resolve_gl_account('2000', v_company_id);
        END IF;
    ELSIF p_counterparty_type = 'shipping_company' THEN
        SELECT sc.account_id INTO v_credit_acct FROM public.shipping_companies sc WHERE sc.id = p_counterparty_id;
        IF v_credit_acct IS NOT NULL THEN
            SELECT id INTO v_credit_acct FROM public.accounts WHERE id = v_credit_acct AND is_leaf = true AND is_active = true;
        END IF;
        IF v_credit_acct IS NULL THEN
            v_credit_acct := public.resolve_gl_account('2000', v_company_id);
        END IF;
    ELSIF p_counterparty_type = 'shareholder' THEN
        SELECT account_id INTO v_credit_acct FROM public.shareholders WHERE id = p_shareholder_id;
        IF v_credit_acct IS NOT NULL THEN
            SELECT id INTO v_credit_acct FROM public.accounts WHERE id = v_credit_acct AND is_leaf = true AND is_active = true;
        END IF;
        IF v_credit_acct IS NULL THEN
            v_credit_acct := public.resolve_equity_account(p_currency, v_company_id);
        END IF;
    ELSE
        v_credit_acct := public.resolve_opening_balance_equity_account(p_currency, v_company_id);
    END IF;

    v_snapshot := jsonb_build_object(
        'currency', p_currency,
        'exchange_rate', v_rate,
        'book_rate', v_new_book_rate,
        'amount', p_amount,
        'amount_in_base_currency', v_base_amount,
        'rate_date', CURRENT_DATE,
        'rate_source', 'exchange_rates_table'
    );

    INSERT INTO public.treasury_transactions (
        treasury_id, type, amount, currency, description, source_type,
        customer_id, supplier_id, clearing_agent_id, shipping_company_id, shareholder_id,
        balance_before, balance_after,
        created_by, revenue_account_id, notes,
        exchange_rate, amount_in_base_currency, currency_snapshot
    ) VALUES (
        v_treasury_id, 'deposit', p_amount, p_currency, v_desc, v_source_type,
        CASE WHEN p_counterparty_type = 'customer' THEN p_counterparty_id ELSE NULL END,
        CASE WHEN p_counterparty_type = 'supplier' THEN p_supplier_id ELSE NULL END,
        CASE WHEN p_counterparty_type = 'clearing_agent' THEN p_counterparty_id ELSE NULL END,
        CASE WHEN p_counterparty_type = 'shipping_company' THEN p_counterparty_id ELSE NULL END,
        CASE WHEN p_counterparty_type = 'shareholder' THEN p_shareholder_id ELSE NULL END,
        v_current_balance, v_new_balance,
        auth.uid(),
        v_credit_acct, p_notes,
        v_rate, v_base_amount, v_snapshot
    ) RETURNING id INTO v_tx_id;

    IF p_counterparty_type = 'customer' AND p_counterparty_id IS NOT NULL THEN
        UPDATE public.customers SET balance = balance - p_amount WHERE id = p_counterparty_id;
        INSERT INTO public.ledger_entries (entity_type, entity_id, entry_type, amount, currency, reference_type, reference_id, description, created_by)
        VALUES ('customer', p_counterparty_id::TEXT, 'credit', p_amount, p_currency, 'receive', v_tx_id, v_desc, auth.uid());

        v_ar_acct := v_credit_acct;
        v_je_id := public.post_journal_entry(
            'customer_payment', v_desc, CURRENT_DATE, v_company_id, auth.uid(),
            jsonb_build_array(
                jsonb_build_object('account_id', v_treasury_acct, 'debit', p_amount, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', p_currency, 'description', v_desc),
                jsonb_build_object('account_id', v_ar_acct, 'debit', 0, 'credit', p_amount, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', p_currency, 'description', v_desc)
            )
        );

    ELSIF p_counterparty_type = 'supplier' AND p_supplier_id IS NOT NULL THEN
        UPDATE public.suppliers 
        SET outstanding_balance = outstanding_balance + p_amount 
        WHERE id = p_supplier_id;

        INSERT INTO public.ledger_entries (entity_type, entity_id, entry_type, amount, currency, reference_type, reference_id, description, created_by)
        VALUES ('supplier', p_supplier_id::TEXT, 'credit', p_amount, p_currency, 'supplier_deposit', v_tx_id, v_desc, auth.uid());

        v_ar_acct := v_credit_acct;
        v_je_id := public.post_journal_entry(
            'supplier_advance_deposit', v_desc, CURRENT_DATE, v_company_id, auth.uid(),
            jsonb_build_array(
                jsonb_build_object('account_id', v_treasury_acct, 'debit', p_amount, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', p_currency, 'description', v_desc),
                jsonb_build_object('account_id', v_ar_acct, 'debit', 0, 'credit', p_amount, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', p_currency, 'description', v_desc)
            )
        );

        IF to_regproc('public.sync_supplier_balances') IS NOT NULL THEN
            PERFORM public.sync_supplier_balances(p_supplier_id);
        END IF;

    ELSIF p_counterparty_type = 'clearing_agent' AND p_counterparty_id IS NOT NULL THEN
        UPDATE public.clearing_agents
        SET manual_adjustment = COALESCE(manual_adjustment, 0) + p_amount,
            balance = COALESCE(balance, 0) + p_amount
        WHERE id = p_counterparty_id;

        INSERT INTO public.ledger_entries (entity_type, entity_id, entry_type, amount, currency, reference_type, reference_id, description, created_by)
        VALUES ('clearing_agent', p_counterparty_id::TEXT, 'credit', p_amount, p_currency, 'receive', v_tx_id, v_desc, auth.uid());

        v_ar_acct := v_credit_acct;
        v_je_id := public.post_journal_entry(
            'clearing_agent_payment_received', v_desc, CURRENT_DATE, v_company_id, auth.uid(),
            jsonb_build_array(
                jsonb_build_object('account_id', v_treasury_acct, 'debit', p_amount, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', p_currency, 'description', v_desc),
                jsonb_build_object('account_id', v_ar_acct, 'debit', 0, 'credit', p_amount, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', p_currency, 'description', v_desc)
            )
        );

    ELSIF p_counterparty_type = 'shipping_company' AND p_counterparty_id IS NOT NULL THEN
        UPDATE public.shipping_companies
        SET manual_adjustment = COALESCE(manual_adjustment, 0) + p_amount,
            balance = COALESCE(balance, 0) + p_amount
        WHERE id = p_counterparty_id;

        INSERT INTO public.ledger_entries (entity_type, entity_id, entry_type, amount, currency, reference_type, reference_id, description, created_by)
        VALUES ('shipping_company', p_counterparty_id::TEXT, 'credit', p_amount, p_currency, 'receive', v_tx_id, v_desc, auth.uid());

        v_ar_acct := v_credit_acct;
        v_je_id := public.post_journal_entry(
            'shipping_company_payment_received', v_desc, CURRENT_DATE, v_company_id, auth.uid(),
            jsonb_build_array(
                jsonb_build_object('account_id', v_treasury_acct, 'debit', p_amount, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', p_currency, 'description', v_desc),
                jsonb_build_object('account_id', v_ar_acct, 'debit', 0, 'credit', p_amount, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', p_currency, 'description', v_desc)
            )
        );

    ELSIF p_counterparty_type = 'shareholder' AND p_shareholder_id IS NOT NULL THEN
        IF p_currency = 'EGP' THEN
            UPDATE public.shareholders SET current_balance_egp = current_balance_egp + p_amount WHERE id = p_shareholder_id;
        ELSIF p_currency = 'USD' THEN
            UPDATE public.shareholders SET current_balance_usd = current_balance_usd + p_amount WHERE id = p_shareholder_id;
        ELSIF p_currency = 'EUR' THEN
            UPDATE public.shareholders SET current_balance_eur = current_balance_eur + p_amount WHERE id = p_shareholder_id;
        ELSIF p_currency = 'GBP' THEN
            UPDATE public.shareholders SET current_balance_gbp = current_balance_gbp + p_amount WHERE id = p_shareholder_id;
        END IF;

        INSERT INTO public.ledger_entries (entity_type, entity_id, entry_type, amount, currency, reference_type, reference_id, description, created_by)
        VALUES ('shareholder', p_shareholder_id::TEXT, 'credit', p_amount, p_currency, 'receive', v_tx_id, v_desc, auth.uid());

        v_ar_acct := v_credit_acct;
        v_je_id := public.post_journal_entry(
            'shareholder_payment_received', v_desc, CURRENT_DATE, v_company_id, auth.uid(),
            jsonb_build_array(
                jsonb_build_object('account_id', v_treasury_acct, 'debit', p_amount, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', p_currency, 'description', v_desc),
                jsonb_build_object('account_id', v_ar_acct, 'debit', 0, 'credit', p_amount, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', p_currency, 'description', v_desc)
            )
        );

    ELSE
        v_je_source := 'opening_balance';
        v_je_id := public.post_journal_entry(
            v_je_source, v_desc, CURRENT_DATE, v_company_id, auth.uid(),
            jsonb_build_array(
                jsonb_build_object('account_id', v_treasury_acct, 'debit', p_amount, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', p_currency, 'description', v_desc),
                jsonb_build_object('account_id', v_credit_acct, 'debit', 0, 'credit', p_amount, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', p_currency, 'description', v_desc)
            )
        );
    END IF;

    UPDATE public.treasury_transactions SET journal_entry_id = v_je_id WHERE id = v_tx_id;

    -- Sync treasury_balances with full cost_base and book_rate
    INSERT INTO public.treasury_balances (treasury_id, currency, balance, cost_base, book_rate, account_id, updated_at)
    VALUES (v_treasury_id, p_currency, v_new_balance, v_new_cost_base, v_new_book_rate, v_treasury_acct, NOW())
    ON CONFLICT (treasury_id, currency) DO UPDATE
    SET balance = v_new_balance,
        cost_base = v_new_cost_base,
        book_rate = v_new_book_rate,
        updated_at = NOW();

    RETURN jsonb_build_object('success', true, 'treasury_tx_id', v_tx_id, 'journal_entry_id', v_je_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.exchange_currency(
    p_treasury_id text,
    p_from_currency text,
    p_to_currency text,
    p_amount_from numeric,
    p_amount_to numeric,
    p_exchange_rate numeric,
    p_user_id uuid DEFAULT auth.uid(),
    p_transfer_mode text DEFAULT 'exchange',
    p_description text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_treasury_id         BIGINT;
    v_balance_before_from DECIMAL(15,2);
    v_balance_after_from  DECIMAL(15,2);
    v_cost_before_from    DECIMAL(15,2);
    v_rate_before_from    DECIMAL(15,4);
    v_new_cost_from       DECIMAL(15,2);
    v_new_rate_from       DECIMAL(15,4);

    v_balance_before_to   DECIMAL(15,2);
    v_balance_after_to    DECIMAL(15,2);
    v_cost_before_to      DECIMAL(15,2);
    v_rate_before_to      DECIMAL(15,4);
    v_new_cost_to         DECIMAL(15,2);
    v_new_rate_to         DECIMAL(15,4);

    v_company_id          UUID;
    v_from_acct           BIGINT;
    v_to_acct             BIGINT;
    v_fx_gain_loss_acct   BIGINT;
    v_je_id               BIGINT;
    v_desc                TEXT;
    v_base_amount         NUMERIC;
    v_cost_base_released  NUMERIC;
    v_realized_fx_diff    NUMERIC;
    v_user_id             UUID := COALESCE(p_user_id, auth.uid());
BEGIN
    IF p_amount_from <= 0 OR p_amount_to <= 0 THEN
        RAISE EXCEPTION 'المبالغ يجب أن تكون أكبر من صفر';
    END IF;

    IF UPPER(p_from_currency) = UPPER(p_to_currency) THEN
        RAISE EXCEPTION 'لا يمكن التحويل لنفس العملة';
    END IF;

    -- Clean treasury ID
    v_treasury_id := p_treasury_id::BIGINT;

    -- Description handling
    v_desc := COALESCE(
        NULLIF(TRIM(p_description), ''),
        'تحويل عملة من (' || p_amount_from || ' ' || UPPER(p_from_currency) || ') إلى (' || p_amount_to || ' ' || UPPER(p_to_currency) || ') بسعر ' || p_exchange_rate
    );

    -- 1. Lock from_currency row in treasury_balances
    SELECT balance, COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_balance_before_from, v_cost_before_from, v_rate_before_from
    FROM public.treasury_balances
    WHERE treasury_id = v_treasury_id AND UPPER(currency) = UPPER(p_from_currency)
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'لا يوجد رصيد بعملة % في هذه الخزينة', p_from_currency;
    END IF;

    IF v_balance_before_from < p_amount_from THEN
        RAISE EXCEPTION 'الرصيد غير كافٍ. المتوفر: %، المطلوب: %', v_balance_before_from, p_amount_from;
    END IF;

    -- Ensure to_currency balance row exists
    INSERT INTO public.treasury_balances (treasury_id, currency, balance, cost_base, book_rate)
    VALUES (v_treasury_id, UPPER(p_to_currency), 0.00, 0.00, 1.0000)
    ON CONFLICT (treasury_id, currency) DO NOTHING;

    SELECT balance, COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_balance_before_to, v_cost_before_to, v_rate_before_to
    FROM public.treasury_balances
    WHERE treasury_id = v_treasury_id AND UPPER(currency) = UPPER(p_to_currency)
    FOR UPDATE;

    SELECT t.company_id INTO v_company_id FROM public.treasuries t WHERE t.id = v_treasury_id;
    IF v_company_id IS NULL THEN
        SELECT id INTO v_company_id FROM public.sys_companies LIMIT 1;
    END IF;

    -- Resolve GL Accounts for from_currency and to_currency
    v_from_acct := public.resolve_treasury_account(v_treasury_id, p_from_currency, v_company_id);
    IF v_from_acct IS NULL THEN
        v_from_acct := public.resolve_gl_account(
            CASE UPPER(p_from_currency) 
                WHEN 'EGP' THEN '12111' 
                WHEN 'USD' THEN '12122' 
                WHEN 'EUR' THEN '12123' 
                WHEN 'GBP' THEN '12124' 
                ELSE '12111' 
            END,
            v_company_id
        );
    END IF;
    IF v_from_acct IS NULL THEN
        v_from_acct := public.resolve_gl_account(
            CASE UPPER(p_from_currency) 
                WHEN 'EGP' THEN '11101' 
                WHEN 'USD' THEN '11102' 
                WHEN 'EUR' THEN '11103' 
                WHEN 'GBP' THEN '11104' 
                ELSE '11101' 
            END,
            v_company_id
        );
    END IF;

    v_to_acct := public.resolve_treasury_account(v_treasury_id, p_to_currency, v_company_id);
    IF v_to_acct IS NULL THEN
        v_to_acct := public.resolve_gl_account(
            CASE UPPER(p_to_currency) 
                WHEN 'EGP' THEN '12111' 
                WHEN 'USD' THEN '12122' 
                WHEN 'EUR' THEN '12123' 
                WHEN 'GBP' THEN '12124' 
                ELSE '12111' 
            END,
            v_company_id
        );
    END IF;
    IF v_to_acct IS NULL THEN
        v_to_acct := public.resolve_gl_account(
            CASE UPPER(p_to_currency) 
                WHEN 'EGP' THEN '11101' 
                WHEN 'USD' THEN '11102' 
                WHEN 'EUR' THEN '11103' 
                WHEN 'GBP' THEN '11104' 
                ELSE '11101' 
            END,
            v_company_id
        );
    END IF;

    -- Calculate balances and cost base
    v_balance_after_from := v_balance_before_from - p_amount_from;
    v_balance_after_to   := v_balance_before_to + p_amount_to;

    IF UPPER(p_from_currency) != 'EGP' THEN
        -- Selling foreign currency -> release cost base
        v_cost_base_released := ROUND(p_amount_from * v_rate_before_from, 2);
        v_new_cost_from      := GREATEST(0, v_cost_before_from - v_cost_base_released);
        v_new_rate_from      := CASE WHEN v_balance_after_from > 0 THEN ROUND(v_new_cost_from / v_balance_after_from, 4) ELSE v_rate_before_from END;

        v_new_cost_to        := v_balance_after_to;
        v_new_rate_to        := 1.0;
        v_realized_fx_diff   := p_amount_to - v_cost_base_released;
    ELSE
        -- Buying foreign currency with EGP
        v_new_cost_from      := v_balance_after_from;
        v_new_rate_from      := 1.0;

        v_new_cost_to        := v_cost_before_to + p_amount_from;
        v_new_rate_to        := CASE WHEN v_balance_after_to > 0 THEN ROUND(v_new_cost_to / v_balance_after_to, 4) ELSE p_exchange_rate END;
        v_realized_fx_diff   := 0;
        v_cost_base_released := p_amount_from;
    END IF;

    -- Update treasury balances
    UPDATE public.treasury_balances
    SET balance    = v_balance_after_from,
        cost_base  = v_new_cost_from,
        book_rate  = v_new_rate_from,
        updated_at = NOW()
    WHERE treasury_id = v_treasury_id AND UPPER(currency) = UPPER(p_from_currency);

    UPDATE public.treasury_balances
    SET balance    = v_balance_after_to,
        cost_base  = v_new_cost_to,
        book_rate  = v_new_rate_to,
        updated_at = NOW()
    WHERE treasury_id = v_treasury_id AND UPPER(currency) = UPPER(p_to_currency);

    -- Base amount calculation
    IF UPPER(p_from_currency) = 'EGP' THEN
        v_base_amount := p_amount_from;
    ELSE
        v_base_amount := p_amount_to;
    END IF;

    -- Post balanced Journal Entry
    IF v_realized_fx_diff != 0 THEN
        IF v_realized_fx_diff > 0 THEN
            v_fx_gain_loss_acct := public.resolve_realized_fx_gain_account(v_company_id);
            IF v_fx_gain_loss_acct IS NULL THEN
                v_fx_gain_loss_acct := public.resolve_gl_account('4310', v_company_id);
            END IF;
            IF v_fx_gain_loss_acct IS NULL THEN
                v_fx_gain_loss_acct := public.resolve_gl_account('4220', v_company_id);
            END IF;

            v_je_id := public.post_journal_entry(
                'currency_exchange', v_desc, CURRENT_DATE, v_company_id, v_user_id,
                jsonb_build_array(
                    jsonb_build_object('account_id', v_to_acct, 'debit', p_amount_to, 'credit', 0, 'base_debit', p_amount_to, 'base_credit', 0, 'currency', UPPER(p_to_currency), 'description', v_desc),
                    jsonb_build_object('account_id', v_from_acct, 'debit', 0, 'credit', p_amount_from, 'base_debit', 0, 'base_credit', v_cost_base_released, 'currency', UPPER(p_from_currency), 'description', v_desc),
                    jsonb_build_object('account_id', v_fx_gain_loss_acct, 'debit', 0, 'credit', v_realized_fx_diff, 'base_debit', 0, 'base_credit', v_realized_fx_diff, 'currency', 'EGP', 'description', 'أرباح فروق عملة محققة')
                )
            );
        ELSE
            v_fx_gain_loss_acct := public.resolve_realized_fx_loss_account(v_company_id);
            IF v_fx_gain_loss_acct IS NULL THEN
                v_fx_gain_loss_acct := public.resolve_gl_account('6151', v_company_id);
            END IF;
            IF v_fx_gain_loss_acct IS NULL THEN
                v_fx_gain_loss_acct := public.resolve_gl_account('5220', v_company_id);
            END IF;

            v_je_id := public.post_journal_entry(
                'currency_exchange', v_desc, CURRENT_DATE, v_company_id, v_user_id,
                jsonb_build_array(
                    jsonb_build_object('account_id', v_to_acct, 'debit', p_amount_to, 'credit', 0, 'base_debit', p_amount_to, 'base_credit', 0, 'currency', UPPER(p_to_currency), 'description', v_desc),
                    jsonb_build_object('account_id', v_fx_gain_loss_acct, 'debit', ABS(v_realized_fx_diff), 'credit', 0, 'base_debit', ABS(v_realized_fx_diff), 'base_credit', 0, 'currency', 'EGP', 'description', 'خسائر فروق عملة محققة'),
                    jsonb_build_object('account_id', v_from_acct, 'debit', 0, 'credit', p_amount_from, 'base_debit', 0, 'base_credit', v_cost_base_released, 'currency', UPPER(p_from_currency), 'description', v_desc)
                )
            );
        END IF;
    ELSE
        v_je_id := public.post_journal_entry(
            'currency_exchange', v_desc, CURRENT_DATE, v_company_id, v_user_id,
            jsonb_build_array(
                jsonb_build_object('account_id', v_to_acct, 'debit', p_amount_to, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', UPPER(p_to_currency), 'description', v_desc),
                jsonb_build_object('account_id', v_from_acct, 'debit', 0, 'credit', p_amount_from, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', UPPER(p_from_currency), 'description', v_desc)
            )
        );
    END IF;

    -- Record outgoing transaction
    INSERT INTO public.treasury_transactions (
        treasury_id, type, amount, currency, description,
        balance_before, balance_after,
        created_by, exchange_rate, amount_in_base_currency, journal_entry_id
    ) VALUES (
        v_treasury_id, 'currency_exchange_out', p_amount_from, UPPER(p_from_currency),
        v_desc || ' (صادر)', v_balance_before_from, v_balance_after_from,
        v_user_id, p_exchange_rate, v_base_amount, v_je_id
    );

    -- Record incoming transaction
    INSERT INTO public.treasury_transactions (
        treasury_id, type, amount, currency, description,
        balance_before, balance_after,
        created_by, exchange_rate, amount_in_base_currency, journal_entry_id
    ) VALUES (
        v_treasury_id, 'currency_exchange_in', p_amount_to, UPPER(p_to_currency),
        v_desc || ' (وارد)', v_balance_before_to, v_balance_after_to,
        v_user_id, p_exchange_rate, v_base_amount, v_je_id
    );

    RETURN jsonb_build_object(
        'success', true,
        'journal_entry_id', v_je_id,
        'amount_from', p_amount_from,
        'from_currency', UPPER(p_from_currency),
        'amount_to', p_amount_to,
        'to_currency', UPPER(p_to_currency),
        'exchange_rate', p_exchange_rate
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.exchange_currency(text, text, text, numeric, numeric, numeric, uuid, text, text) TO authenticated, service_role, anon;

-- Overload for bigint treasury_id
CREATE OR REPLACE FUNCTION public.exchange_currency(
    p_treasury_id bigint,
    p_from_currency text,
    p_to_currency text,
    p_amount_from numeric,
    p_amount_to numeric,
    p_exchange_rate numeric,
    p_user_id uuid DEFAULT auth.uid(),
    p_transfer_mode text DEFAULT 'exchange',
    p_description text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    RETURN public.exchange_currency(
        p_treasury_id   := p_treasury_id::text,
        p_from_currency := p_from_currency,
        p_to_currency   := p_to_currency,
        p_amount_from   := p_amount_from,
        p_amount_to     := p_amount_to,
        p_exchange_rate := p_exchange_rate,
        p_user_id       := p_user_id,
        p_transfer_mode := p_transfer_mode,
        p_description   := p_description
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.exchange_currency(bigint, text, text, numeric, numeric, numeric, uuid, text, text) TO authenticated, service_role, anon;


-- ============================================================================
-- ── Bank Account Draft & Confirm Workflow Support ──
-- ============================================================================

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'status'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN status TEXT NOT NULL DEFAULT 'confirmed';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'payload'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN payload JSONB DEFAULT '{}'::jsonb;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'source_type'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN source_type TEXT;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'revenue_account_id'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN revenue_account_id BIGINT REFERENCES public.accounts(id) ON DELETE SET NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'expense_account_id'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN expense_account_id BIGINT REFERENCES public.accounts(id) ON DELETE SET NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'source_id'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN source_id TEXT;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'category_id'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN category_id TEXT;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'cost_center_id'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN cost_center_id TEXT;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'reference_type'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN reference_type TEXT;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'reference_id'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN reference_id TEXT;
    END IF;

    -- 3. Fix foreign currency bank accounts default book_rate
    UPDATE public.bank_accounts ba
    SET book_rate = COALESCE(
        (SELECT rate_to_egp FROM public.exchange_rates er WHERE er.currency_code = ba.currency LIMIT 1),
        CASE ba.currency WHEN 'USD' THEN 50.0 WHEN 'EUR' THEN 54.0 WHEN 'GBP' THEN 63.0 ELSE 50.0 END
    )
    WHERE ba.currency != 'EGP' AND (ba.book_rate <= 1.0 OR ba.book_rate IS NULL);
END $$;

-- ── Soften fiscal-year trigger for 'draft' transactions (Treasury & Bank) ──
CREATE OR REPLACE FUNCTION public.check_fiscal_year_allows_financial()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  _fy_status text;
BEGIN
  IF TG_TABLE_NAME IN ('bank_account_transactions', 'treasury_transactions')
     AND NEW.status = 'draft' THEN
    RETURN NEW;
  END IF;

  SELECT fy.status INTO _fy_status
  FROM public.fiscal_years fy
  WHERE fy.is_current = true
    AND fy.deleted_at IS NULL
  LIMIT 1;

  IF _fy_status IN ('CLOSING', 'CLOSED') THEN
    RAISE EXCEPTION 'لا يمكن إنشاء مستندات مالية في سنة مالية %', _fy_status;
  END IF;

  RETURN NEW;
END;
$$;

-- ── RPC: Save Bank Draft ──
CREATE OR REPLACE FUNCTION public.rpc_save_bank_draft(
    p_bank_account_id BIGINT,
    p_type TEXT,
    p_amount NUMERIC,
    p_description TEXT DEFAULT NULL,
    p_notes TEXT DEFAULT NULL,
    p_entity_type TEXT DEFAULT NULL,
    p_entity_id TEXT DEFAULT NULL,
    p_counterparty_name TEXT DEFAULT NULL,
    p_payload JSONB DEFAULT '{}'::jsonb
)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_tx_id BIGINT;
BEGIN
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'المبلغ يجب أن يكون أكبر من صفر';
    END IF;

    INSERT INTO public.bank_account_transactions (
        bank_account_id,
        type,
        amount,
        balance_before,
        balance_after,
        description,
        notes,
        entity_type,
        entity_id,
        counterparty_name,
        status,
        payload,
        created_by,
        created_at
    ) VALUES (
        p_bank_account_id,
        p_type,
        p_amount,
        0,
        0,
        p_description,
        p_notes,
        p_entity_type,
        p_entity_id,
        p_counterparty_name,
        'draft',
        COALESCE(p_payload, '{}'::jsonb),
        auth.uid(),
        NOW()
    )
    RETURNING id INTO v_tx_id;

    RETURN v_tx_id;
END;
$$;

-- ── RPC: Update Bank Draft ──
CREATE OR REPLACE FUNCTION public.rpc_update_bank_draft(
    p_transaction_id BIGINT,
    p_bank_account_id BIGINT DEFAULT NULL,
    p_type TEXT DEFAULT NULL,
    p_amount NUMERIC DEFAULT NULL,
    p_description TEXT DEFAULT NULL,
    p_notes TEXT DEFAULT NULL,
    p_entity_type TEXT DEFAULT NULL,
    p_entity_id TEXT DEFAULT NULL,
    p_counterparty_name TEXT DEFAULT NULL,
    p_payload JSONB DEFAULT NULL
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
    UPDATE public.bank_account_transactions
    SET
        bank_account_id = COALESCE(p_bank_account_id, bank_account_id),
        type = COALESCE(p_type, type),
        amount = COALESCE(p_amount, amount),
        description = COALESCE(p_description, description),
        notes = p_notes,
        entity_type = p_entity_type,
        entity_id = p_entity_id,
        counterparty_name = p_counterparty_name,
        payload = CASE WHEN p_payload IS NOT NULL THEN p_payload ELSE payload END
    WHERE id = p_transaction_id AND status = 'draft';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'لم يتم العثور على المسودة أو أنها مؤكدة بالفعل';
    END IF;

    RETURN TRUE;
END;
$$;

-- ── RPC: Delete Bank Draft ──
CREATE OR REPLACE FUNCTION public.rpc_delete_bank_draft(
    p_transaction_id BIGINT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_deleted_count INT;
BEGIN
    DELETE FROM public.bank_account_transactions
    WHERE id = p_transaction_id AND status = 'draft';

    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    IF v_deleted_count = 0 THEN
        RAISE EXCEPTION 'لم يتم العثور على المسودة أو تم تأكيدها مسبقاً';
    END IF;

    RETURN TRUE;
END;
$$;

-- ── Drop all existing overloads of exchange_bank_currency (Migration 377) ──
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN (
        SELECT p.proname, pg_get_function_identity_arguments(p.oid) as args
        FROM pg_proc p
        JOIN pg_namespace n ON p.pronamespace = n.oid
        WHERE n.nspname = 'public' AND p.proname = 'exchange_bank_currency'
    ) LOOP
        EXECUTE 'DROP FUNCTION IF EXISTS public.' || quote_ident(r.proname) || '(' || r.args || ') CASCADE;';
    END LOOP;
END $$;

-- ── Single Unified exchange_bank_currency (Migration 377) ──
CREATE OR REPLACE FUNCTION public.exchange_bank_currency(
    p_from_account_id integer,
    p_to_account_id integer,
    p_amount_from numeric,
    p_amount_to numeric,
    p_exchange_rate numeric
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_from_currency       TEXT;
    v_to_currency         TEXT;
    v_balance_before_from NUMERIC;
    v_balance_before_to   NUMERIC;
    v_balance_after_from  NUMERIC;
    v_balance_after_to    NUMERIC;
    
    v_cost_before_from    NUMERIC;
    v_rate_before_from    NUMERIC;
    v_cost_before_to      NUMERIC;
    v_rate_before_to      NUMERIC;
    
    v_new_cost_from       NUMERIC;
    v_new_rate_from       NUMERIC;
    v_new_cost_to         NUMERIC;
    v_new_rate_to         NUMERIC;
    
    v_cost_base_released  NUMERIC := 0;
    v_realized_fx_diff    NUMERIC := 0;
    v_base_amount         NUMERIC;
    
    v_from_acct           BIGINT;
    v_to_acct             BIGINT;
    v_fx_gain_loss_acct   BIGINT;
    v_je_id               BIGINT;
    v_desc                TEXT;
    v_company_id          UUID;
    v_user_id             UUID;
    v_transaction_id      BIGINT;
    v_result              JSONB;
BEGIN
    v_user_id := auth.uid();

    IF p_amount_from <= 0 OR p_amount_to <= 0 OR p_exchange_rate <= 0 THEN
        RAISE EXCEPTION 'المبالغ وسعر الصرف يجب أن تكون أكبر من صفر';
    END IF;

    -- 1. Lock from_account and fetch balances & cost base
    SELECT currency, COALESCE(balance, 0), COALESCE(cost_base, 0), COALESCE(book_rate, 1.0), company_id
    INTO v_from_currency, v_balance_before_from, v_cost_before_from, v_rate_before_from, v_company_id
    FROM public.bank_accounts
    WHERE id = p_from_account_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'الحساب البنكي المصدر غير موجود';
    END IF;

    IF v_balance_before_from < p_amount_from THEN
        RAISE EXCEPTION 'الرصيد غير كافٍ في الحساب البنكي المصدر. المتوفر: %، المطلوب: %', v_balance_before_from, p_amount_from;
    END IF;

    -- 2. Lock to_account and fetch balances & cost base
    SELECT currency, COALESCE(balance, 0), COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_to_currency, v_balance_before_to, v_cost_before_to, v_rate_before_to
    FROM public.bank_accounts
    WHERE id = p_to_account_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'الحساب البنكي المحول إليه غير موجود';
    END IF;

    IF v_company_id IS NULL THEN
        SELECT company_id INTO v_company_id FROM public.bank_accounts WHERE id = p_to_account_id;
        IF v_company_id IS NULL THEN
            SELECT id INTO v_company_id FROM public.sys_companies LIMIT 1;
        END IF;
    END IF;

    -- Strict Rule: One of the currencies MUST be EGP
    IF v_from_currency != 'EGP' AND v_to_currency != 'EGP' THEN
        RAISE EXCEPTION 'التحويل المباشر بين عملتين أجنبيتين غير مسموح. يجب التحويل عبر الجنيه المصري كخطوتين منفصلتين.';
    END IF;

    -- Fallback for uninitialized cost base
    IF v_from_currency != 'EGP' AND (v_cost_before_from <= 0 OR v_rate_before_from <= 0) THEN
        v_rate_before_from := COALESCE(NULLIF(v_rate_before_from, 0), public.fn_get_exchange_rate(v_from_currency));
        IF v_rate_before_from <= 0 THEN v_rate_before_from := p_exchange_rate; END IF;
        v_cost_before_from := ROUND(v_balance_before_from * v_rate_before_from, 2);
    END IF;

    v_desc := 'تحويل بنكي من ' || v_from_currency || ' إلى ' || v_to_currency || ' بسعر صرف ' || p_exchange_rate;

    v_from_acct := public.resolve_gl_account(
        CASE v_from_currency WHEN 'EGP' THEN '11201' WHEN 'USD' THEN '11202' WHEN 'EUR' THEN '11203' WHEN 'GBP' THEN '11204' ELSE '11201' END,
        v_company_id
    );
    v_to_acct := public.resolve_gl_account(
        CASE v_to_currency WHEN 'EGP' THEN '11201' WHEN 'USD' THEN '11202' WHEN 'EUR' THEN '11203' WHEN 'GBP' THEN '11204' ELSE '11201' END,
        v_company_id
    );

    v_balance_after_from := v_balance_before_from - p_amount_from;
    v_balance_after_to := v_balance_before_to + p_amount_to;

    -- 3. IAS 21 Multi-Currency Cost Base & Realized FX Calculation
    IF v_from_currency != 'EGP' THEN
        -- Case A: Selling foreign currency (e.g. USD -> EGP)
        v_cost_base_released := ROUND(p_amount_from * v_rate_before_from, 2);
        v_new_cost_from := GREATEST(0, v_cost_before_from - v_cost_base_released);
        v_new_rate_from := CASE WHEN v_balance_after_from > 0 THEN ROUND(v_new_cost_from / v_balance_after_from, 4) ELSE v_rate_before_from END;

        v_new_cost_to := v_balance_after_to;
        v_new_rate_to := 1.0;
        v_realized_fx_diff := p_amount_to - v_cost_base_released;
    ELSE
        -- Case B: Buying foreign currency (e.g. EGP -> USD)
        v_new_cost_from := v_balance_after_from;
        v_new_rate_from := 1.0;

        v_new_cost_to := v_cost_before_to + p_amount_from;
        v_new_rate_to := CASE WHEN v_balance_after_to > 0 THEN ROUND(v_new_cost_to / v_balance_after_to, 4) ELSE p_exchange_rate END;
        v_realized_fx_diff := 0;
    END IF;

    -- Update Bank Accounts balances, cost_base, and book_rate
    UPDATE public.bank_accounts
    SET balance = v_balance_after_from,
        cost_base = v_new_cost_from,
        book_rate = v_new_rate_from,
        updated_at = NOW()
    WHERE id = p_from_account_id;

    UPDATE public.bank_accounts
    SET balance = v_balance_after_to,
        cost_base = v_new_cost_to,
        book_rate = v_new_rate_to,
        updated_at = NOW()
    WHERE id = p_to_account_id;

    -- Base Amount is the EGP amount
    IF v_from_currency = 'EGP' THEN
        v_base_amount := p_amount_from;
    ELSE
        v_base_amount := p_amount_to;
    END IF;

    -- 4. Post Balanced Journal Entry with Realized FX Gain/Loss
    IF v_realized_fx_diff != 0 THEN
        IF v_realized_fx_diff > 0 THEN
            v_fx_gain_loss_acct := public.resolve_gl_account('4310', v_company_id);
            v_je_id := public.post_journal_entry(
                'currency_exchange', v_desc, CURRENT_DATE, v_company_id, v_user_id,
                jsonb_build_array(
                    jsonb_build_object('account_id', v_to_acct, 'debit', p_amount_to, 'credit', 0, 'base_debit', p_amount_to, 'base_credit', 0, 'currency', v_to_currency, 'description', v_desc || ' (وارد)'),
                    jsonb_build_object('account_id', v_from_acct, 'debit', 0, 'credit', p_amount_from, 'base_debit', 0, 'base_credit', v_cost_base_released, 'currency', v_from_currency, 'description', v_desc || ' (صادر بالتكلفة الدفترية)'),
                    jsonb_build_object('account_id', v_fx_gain_loss_acct, 'debit', 0, 'credit', v_realized_fx_diff, 'base_debit', 0, 'base_credit', v_realized_fx_diff, 'currency', 'EGP', 'description', 'أرباح فروق عملة محققة')
                )
            );
        ELSE
            v_fx_gain_loss_acct := public.resolve_gl_account('6151', v_company_id);
            v_je_id := public.post_journal_entry(
                'currency_exchange', v_desc, CURRENT_DATE, v_company_id, v_user_id,
                jsonb_build_array(
                    jsonb_build_object('account_id', v_to_acct, 'debit', p_amount_to, 'credit', 0, 'base_debit', p_amount_to, 'base_credit', 0, 'currency', v_to_currency, 'description', v_desc || ' (وارد)'),
                    jsonb_build_object('account_id', v_fx_gain_loss_acct, 'debit', ABS(v_realized_fx_diff), 'credit', 0, 'base_debit', ABS(v_realized_fx_diff), 'base_credit', 0, 'currency', 'EGP', 'description', 'خسائر فروق عملة محققة'),
                    jsonb_build_object('account_id', v_from_acct, 'debit', 0, 'credit', p_amount_from, 'base_debit', 0, 'base_credit', v_cost_base_released, 'currency', v_from_currency, 'description', v_desc || ' (صادر بالتكلفة الدفترية)')
                )
            );
        END IF;
    ELSE
        v_je_id := public.post_journal_entry(
            'currency_exchange', v_desc, CURRENT_DATE, v_company_id, v_user_id,
            jsonb_build_array(
                jsonb_build_object('account_id', v_to_acct, 'debit', p_amount_to, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', v_to_currency, 'description', v_desc || ' (وارد)'),
                jsonb_build_object('account_id', v_from_acct, 'debit', 0, 'credit', p_amount_from, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', v_from_currency, 'description', v_desc || ' (صادر)')
            )
        );
    END IF;

    -- 5. Insert Transaction Records
    INSERT INTO public.bank_account_transactions (
        bank_account_id, type, amount, balance_before, balance_after,
        description, entity_type, journal_entry_id,
        exchange_rate, amount_in_base_currency, currency_snapshot, status
    ) VALUES (
        p_from_account_id, 'currency_exchange_out', p_amount_from, v_balance_before_from, v_balance_after_from,
        v_desc || ' (صادر)', 'exchange', v_je_id,
        p_exchange_rate, CASE WHEN v_from_currency != 'EGP' THEN v_cost_base_released ELSE v_base_amount END,
        jsonb_build_object('currency', v_from_currency, 'exchange_rate', p_exchange_rate, 'book_rate', v_new_rate_from, 'amount', p_amount_from, 'amount_in_base_currency', CASE WHEN v_from_currency != 'EGP' THEN v_cost_base_released ELSE v_base_amount END),
        'confirmed'
    ) RETURNING id INTO v_transaction_id;

    INSERT INTO public.bank_account_transactions (
        bank_account_id, type, amount, balance_before, balance_after,
        description, entity_type, journal_entry_id,
        exchange_rate, amount_in_base_currency, currency_snapshot, status
    ) VALUES (
        p_to_account_id, 'currency_exchange_in', p_amount_to, v_balance_before_to, v_balance_after_to,
        v_desc || ' (وارد)', 'exchange', v_je_id,
        p_exchange_rate, v_base_amount,
        jsonb_build_object('currency', v_to_currency, 'exchange_rate', p_exchange_rate, 'book_rate', v_new_rate_to, 'amount', p_amount_to, 'amount_in_base_currency', v_base_amount),
        'confirmed'
    );

    v_result := jsonb_build_object(
        'success', true,
        'transaction_id', v_transaction_id,
        'journal_entry_id', v_je_id,
        'realized_fx_diff', v_realized_fx_diff
    );

    RETURN v_result;
END;
$$;

GRANT EXECUTE ON FUNCTION public.exchange_bank_currency(integer, integer, numeric, numeric, numeric) TO authenticated, anon, service_role;

-- ── RPC: Confirm Bank Draft ──
CREATE OR REPLACE FUNCTION public.rpc_confirm_bank_draft(
    p_transaction_id BIGINT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_tx RECORD;
    v_res JSONB;
BEGIN
    SELECT * INTO v_tx
    FROM public.bank_account_transactions
    WHERE id = p_transaction_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'الحركة غير موجودة';
    END IF;

    IF v_tx.status != 'draft' THEN
        RAISE EXCEPTION 'هذه الحركة مؤكدة بالفعل وليست مسودة';
    END IF;

    IF v_tx.type = 'deposit' THEN
        v_res := public.deposit_bank_account(
            p_account_id        := v_tx.bank_account_id::bigint,
            p_amount            := v_tx.amount,
            p_description       := v_tx.description,
            p_revenue_account_id := COALESCE((v_tx.payload->>'revenue_account_id')::bigint, NULL),
            p_entity_type       := v_tx.entity_type,
            p_entity_id         := v_tx.entity_id,
            p_counterparty_name := v_tx.counterparty_name,
            p_source_type       := COALESCE(v_tx.payload->>'source_type', 'deposit'),
            p_notes             := v_tx.notes
        );

        DELETE FROM public.bank_account_transactions WHERE id = p_transaction_id;

        RETURN jsonb_build_object('success', true, 'message', 'تم تأكيد الإيداع وترحيل القيد بنجاح', 'result', v_res);

    ELSIF v_tx.type = 'withdraw' THEN
        v_res := public.withdraw_bank_account(
            p_account_id        := v_tx.bank_account_id,
            p_amount            := v_tx.amount,
            p_description       := v_tx.description,
            p_entity_type       := v_tx.entity_type,
            p_entity_id         := v_tx.entity_id,
            p_counterparty_name := v_tx.counterparty_name,
            p_expense_account_id := COALESCE((v_tx.payload->>'expense_account_id')::integer, NULL),
            p_notes             := v_tx.notes,
            p_reference_type    := v_tx.payload->>'reference_type',
            p_reference_id      := v_tx.payload->>'reference_id'
        );

        DELETE FROM public.bank_account_transactions WHERE id = p_transaction_id;

        RETURN jsonb_build_object('success', true, 'message', 'تم تأكيد الصرف وترحيل القيد بنجاح', 'result', v_res);

    ELSIF v_tx.type IN ('currency_exchange_out', 'currency_exchange_in', 'exchange') THEN
        v_res := public.exchange_bank_currency(
            p_from_account_id := v_tx.bank_account_id::integer,
            p_to_account_id   := (v_tx.payload->>'to_account_id')::integer,
            p_amount_from     := COALESCE((v_tx.payload->>'amount_from')::numeric, v_tx.amount),
            p_amount_to       := (v_tx.payload->>'amount_to')::numeric,
            p_exchange_rate   := (v_tx.payload->>'exchange_rate')::numeric
        );

        DELETE FROM public.bank_account_transactions WHERE id = p_transaction_id;

        RETURN jsonb_build_object('success', true, 'message', 'تم تأكيد تحويل العملة وترحيل القيد بنجاح', 'result', v_res);

    ELSIF v_tx.type = 'transfer' THEN
        PERFORM public.bank_transfer(
            p_from_account_id := v_tx.bank_account_id::integer,
            p_to_account_id   := (v_tx.payload->>'to_account_id')::integer,
            p_amount          := v_tx.amount,
            p_description     := v_tx.description,
            p_bank_fee        := COALESCE((v_tx.payload->>'bank_fee')::numeric, 0),
            p_notes           := v_tx.notes
        );

        DELETE FROM public.bank_account_transactions WHERE id = p_transaction_id;

        RETURN jsonb_build_object('success', true, 'message', 'تم تأكيد التحويل البنكي وترحيل القيد بنجاح');

    ELSE
        RAISE EXCEPTION 'نوع الحركة غير مدعوم: %', v_tx.type;
    END IF;
END;
$$;

-- ── 7.5 Ensure all required columns exist on public.cheques ──
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'cheques' AND column_name = 'bank_account_id'
    ) THEN
        ALTER TABLE public.cheques ADD COLUMN bank_account_id INTEGER REFERENCES public.bank_accounts(id) ON DELETE SET NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'cheques' AND column_name = 'journal_entry_id'
    ) THEN
        ALTER TABLE public.cheques ADD COLUMN journal_entry_id BIGINT REFERENCES public.journal_entries(id) ON DELETE SET NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'cheques' AND column_name = 'expense_account_id'
    ) THEN
        ALTER TABLE public.cheques ADD COLUMN expense_account_id BIGINT REFERENCES public.accounts(id) ON DELETE SET NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'cheques' AND column_name = 'exchange_rate'
    ) THEN
        ALTER TABLE public.cheques ADD COLUMN exchange_rate NUMERIC(15,6) DEFAULT 1.0;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'cheques' AND column_name = 'amount_in_base_currency'
    ) THEN
        ALTER TABLE public.cheques ADD COLUMN amount_in_base_currency NUMERIC(15,2);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'cheques' AND column_name = 'treasury_id'
    ) THEN
        ALTER TABLE public.cheques ADD COLUMN treasury_id BIGINT REFERENCES public.treasuries(id) ON DELETE SET NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'cheques' AND column_name = 'bank_transaction_id'
    ) THEN
        ALTER TABLE public.cheques ADD COLUMN bank_transaction_id BIGINT;
    END IF;
END $$;

-- ── 7.4 Create Cheque RPC (Fixed shareholder_id UUID type) ──
DROP FUNCTION IF EXISTS public.create_cheque(text, text, numeric, text, date, date, text, bigint, text, uuid, bigint, bigint, bigint, integer);
DROP FUNCTION IF EXISTS public.create_cheque(character varying, character varying, numeric, character varying, date, character varying, bigint, uuid, bigint, bigint, uuid, text);
DROP FUNCTION IF EXISTS public.create_cheque(text, text, numeric, text, date, date, text, bigint, text, uuid, bigint, bigint, uuid, integer);
DROP FUNCTION IF EXISTS public.create_cheque(text, text, numeric, text, date, date, text, bigint, text, uuid, bigint, bigint, uuid, integer, bigint);
DROP FUNCTION IF EXISTS public.create_cheque(text, text, numeric, text, date, date, text, bigint, text, uuid, bigint, bigint, uuid, integer, bigint, boolean);

CREATE OR REPLACE FUNCTION public.create_cheque(
    p_cheque_number text,
    p_type text,
    p_amount numeric,
    p_currency text,
    p_issue_date date,
    p_due_date date,
    p_counterparty_type text DEFAULT NULL::text,
    p_counterparty_id bigint DEFAULT NULL::bigint,
    p_notes text DEFAULT NULL::text,
    p_supplier_id uuid DEFAULT NULL::uuid,
    p_clearing_agent_id bigint DEFAULT NULL::bigint,
    p_shipping_company_id bigint DEFAULT NULL::bigint,
    p_shareholder_id uuid DEFAULT NULL::uuid,
    p_category_id integer DEFAULT NULL::integer,
    p_expense_account_id bigint DEFAULT NULL::bigint,
    p_post_ledger boolean DEFAULT true
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_id BIGINT;
    v_je_id BIGINT := NULL;
    v_company_id UUID;
    v_rate NUMERIC;
    v_base_amount NUMERIC;
    v_norm_counterparty_type TEXT;
    v_counterparty_acct BIGINT;
    v_holding_acct BIGINT;
    v_je_lines JSONB := '[]'::jsonb;
    v_desc TEXT;
    v_counterparty_name TEXT;
BEGIN
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'المبلغ يجب أن يكون أكبر من صفر';
    END IF;

    IF p_due_date < p_issue_date THEN
        RAISE EXCEPTION 'تاريخ الاستحقاق يجب أن يكون بعد تاريخ التحرير';
    END IF;

    -- Optional immediate Stage-1 ledger posting if requested
    IF p_post_ledger THEN
        SELECT id INTO v_company_id FROM public.sys_companies WHERE deleted_at IS NULL ORDER BY created_at ASC LIMIT 1;
        v_rate := public.fn_get_exchange_rate(p_currency);
        v_base_amount := ROUND(p_amount * v_rate, 2);
        v_norm_counterparty_type := LOWER(COALESCE(p_counterparty_type, ''));

        IF p_type = 'incoming' THEN
            v_holding_acct := public.resolve_gl_account('12121', v_company_id);

            IF v_norm_counterparty_type = 'customer' AND p_counterparty_id IS NOT NULL THEN
                SELECT account_id, name INTO v_counterparty_acct, v_counterparty_name FROM public.customers WHERE id = p_counterparty_id;
            ELSIF v_norm_counterparty_type = 'shareholder' AND p_shareholder_id IS NOT NULL THEN
                SELECT account_id, name INTO v_counterparty_acct, v_counterparty_name FROM public.shareholders WHERE id = p_shareholder_id;
            END IF;

            IF v_counterparty_acct IS NULL THEN
                v_counterparty_acct := public.resolve_gl_account('12511', v_company_id);
            END IF;

            IF v_norm_counterparty_type = 'customer' AND v_counterparty_name IS NOT NULL AND v_counterparty_name != '' THEN
                v_desc := 'استلام شيك برسم التحصيل رقم ' || p_cheque_number || ' من العميل ' || v_counterparty_name || ' (سداد حساب العميل)';
            ELSE
                v_desc := 'استلام شيك برسم التحصيل رقم: ' || p_cheque_number;
            END IF;

            v_je_lines := jsonb_build_array(
                jsonb_build_object(
                    'account_id', v_holding_acct,
                    'debit', p_amount,
                    'credit', 0,
                    'base_debit', v_base_amount,
                    'base_credit', 0,
                    'currency', p_currency,
                    'description', v_desc
                ),
                jsonb_build_object(
                    'account_id', v_counterparty_acct,
                    'debit', 0,
                    'credit', p_amount,
                    'base_debit', 0,
                    'base_credit', v_base_amount,
                    'currency', p_currency,
                    'description', v_desc
                )
            );

            v_je_id := public.post_journal_entry(
                'cheque_receipt',
                v_desc,
                p_issue_date,
                v_company_id,
                auth.uid(),
                v_je_lines,
                p_cheque_number
            );
        ELSIF p_type = 'outgoing' THEN
            v_desc := 'إصدار شيك أوراق دفع رقم: ' || p_cheque_number;
            v_holding_acct := public.resolve_gl_account('21121', v_company_id);

            IF v_norm_counterparty_type = 'supplier' AND p_supplier_id IS NOT NULL THEN
                SELECT account_id INTO v_counterparty_acct FROM public.suppliers WHERE id = p_supplier_id;
            ELSIF v_norm_counterparty_type = 'shipping_company' AND (p_shipping_company_id IS NOT NULL OR p_counterparty_id IS NOT NULL) THEN
                SELECT account_id INTO v_counterparty_acct FROM public.shipping_companies WHERE id = COALESCE(p_shipping_company_id, p_counterparty_id);
            ELSIF v_norm_counterparty_type = 'clearing_agent' AND (p_clearing_agent_id IS NOT NULL OR p_counterparty_id IS NOT NULL) THEN
                SELECT account_id INTO v_counterparty_acct FROM public.clearing_agents WHERE id = COALESCE(p_clearing_agent_id, p_counterparty_id);
            ELSIF v_norm_counterparty_type = 'shareholder' AND p_shareholder_id IS NOT NULL THEN
                SELECT account_id INTO v_counterparty_acct FROM public.shareholders WHERE id = p_shareholder_id;
            ELSIF p_expense_account_id IS NOT NULL THEN
                v_counterparty_acct := p_expense_account_id;
            END IF;

            IF v_counterparty_acct IS NULL THEN
                v_counterparty_acct := public.resolve_gl_account('21113', v_company_id);
            END IF;

            v_je_lines := jsonb_build_array(
                jsonb_build_object(
                    'account_id', v_counterparty_acct,
                    'debit', p_amount,
                    'credit', 0,
                    'base_debit', v_base_amount,
                    'base_credit', 0,
                    'currency', p_currency,
                    'description', v_desc || ' (تسوية مستحقات)'
                ),
                jsonb_build_object(
                    'account_id', v_holding_acct,
                    'debit', 0,
                    'credit', p_amount,
                    'base_debit', 0,
                    'base_credit', v_base_amount,
                    'currency', p_currency,
                    'description', v_desc
                )
            );

            v_je_id := public.post_journal_entry(
                'cheque_issued',
                v_desc,
                p_issue_date,
                v_company_id,
                auth.uid(),
                v_je_lines,
                p_cheque_number
            );
        END IF;
    END IF;

    INSERT INTO public.cheques (
        cheque_number, type, status, amount, currency,
        issue_date, due_date, counterparty_type, counterparty_id,
        supplier_id, clearing_agent_id, shipping_company_id, shareholder_id, notes, created_by, category_id,
        expense_account_id, journal_entry_id
    ) VALUES (
        p_cheque_number, p_type, 'pending', p_amount, p_currency,
        p_issue_date, p_due_date, p_counterparty_type, p_counterparty_id,
        p_supplier_id, p_clearing_agent_id, p_shipping_company_id, p_shareholder_id, p_notes, auth.uid(), p_category_id,
        p_expense_account_id, v_je_id
    ) RETURNING id INTO v_id;

    RETURN jsonb_build_object('id', v_id, 'journal_entry_id', v_je_id);
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_cheque TO authenticated, anon, service_role;

-- ── 7.4b Cancel Cheque RPC ──
CREATE OR REPLACE FUNCTION public.cancel_cheque(p_cheque_id bigint)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_cheque RECORD;
    v_rev_lines JSONB := '[]'::jsonb;
    v_rev_je_id BIGINT;
    v_holding_acct BIGINT;
    v_counterparty_acct BIGINT;
    v_norm_counterparty_type TEXT;
    v_rate NUMERIC;
    v_base_amount NUMERIC;
BEGIN
    SELECT * INTO v_cheque
    FROM public.cheques
    WHERE id = p_cheque_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'الشيك غير موجود';
    END IF;

    IF v_cheque.status != 'pending' THEN
        RAISE EXCEPTION 'لا يمكن إلغاء شيك بحالة %', v_cheque.status;
    END IF;

    -- If a journal entry was previously posted while pending, reverse it
    IF v_cheque.journal_entry_id IS NOT NULL THEN
        v_rate := public.fn_get_exchange_rate(v_cheque.currency);
        v_base_amount := ROUND(v_cheque.amount * v_rate, 2);
        v_norm_counterparty_type := LOWER(COALESCE(v_cheque.counterparty_type, ''));

        IF v_cheque.type = 'incoming' THEN
            v_holding_acct := public.resolve_gl_account('12121', v_cheque.company_id);

            IF v_norm_counterparty_type = 'customer' AND v_cheque.counterparty_id IS NOT NULL THEN
                SELECT account_id INTO v_counterparty_acct FROM public.customers WHERE id = v_cheque.counterparty_id;
            ELSIF v_norm_counterparty_type = 'shareholder' AND v_cheque.shareholder_id IS NOT NULL THEN
                SELECT account_id INTO v_counterparty_acct FROM public.shareholders WHERE id = v_cheque.shareholder_id;
            END IF;

            IF v_counterparty_acct IS NULL THEN
                v_counterparty_acct := public.resolve_gl_account('12511', v_cheque.company_id);
            END IF;

            -- Reversal: Dr Customer / Cr 12121
            v_rev_lines := jsonb_build_array(
                jsonb_build_object(
                    'account_id', v_counterparty_acct,
                    'debit', v_cheque.amount,
                    'credit', 0,
                    'base_debit', v_base_amount,
                    'base_credit', 0,
                    'currency', v_cheque.currency,
                    'description', 'إلغاء شيك وارد برسم التحصيل رقم: ' || v_cheque.cheque_number
                ),
                jsonb_build_object(
                    'account_id', v_holding_acct,
                    'debit', 0,
                    'credit', v_cheque.amount,
                    'base_debit', 0,
                    'base_credit', v_base_amount,
                    'currency', v_cheque.currency,
                    'description', 'إلغاء شيك وارد برسم التحصيل رقم: ' || v_cheque.cheque_number
                )
            );
        ELSE
            v_holding_acct := public.resolve_gl_account('21121', v_cheque.company_id);

            IF v_norm_counterparty_type = 'supplier' AND v_cheque.supplier_id IS NOT NULL THEN
                SELECT account_id INTO v_counterparty_acct FROM public.suppliers WHERE id = v_cheque.supplier_id;
            ELSIF v_norm_counterparty_type = 'shipping_company' AND COALESCE(v_cheque.shipping_company_id, v_cheque.counterparty_id) IS NOT NULL THEN
                SELECT account_id INTO v_counterparty_acct FROM public.shipping_companies WHERE id = COALESCE(v_cheque.shipping_company_id, v_cheque.counterparty_id)::bigint;
            ELSIF v_norm_counterparty_type = 'clearing_agent' AND COALESCE(v_cheque.clearing_agent_id, v_cheque.counterparty_id) IS NOT NULL THEN
                SELECT account_id INTO v_counterparty_acct FROM public.clearing_agents WHERE id = COALESCE(v_cheque.clearing_agent_id, v_cheque.counterparty_id)::bigint;
            ELSIF v_norm_counterparty_type = 'shareholder' AND v_cheque.shareholder_id IS NOT NULL THEN
                SELECT account_id INTO v_counterparty_acct FROM public.shareholders WHERE id = v_cheque.shareholder_id;
            ELSIF v_cheque.expense_account_id IS NOT NULL THEN
                v_counterparty_acct := v_cheque.expense_account_id;
            END IF;

            IF v_counterparty_acct IS NULL THEN
                v_counterparty_acct := public.resolve_gl_account('21113', v_cheque.company_id);
            END IF;

            -- Reversal: Dr 21121 / Cr Supplier
            v_rev_lines := jsonb_build_array(
                jsonb_build_object(
                    'account_id', v_holding_acct,
                    'debit', v_cheque.amount,
                    'credit', 0,
                    'base_debit', v_base_amount,
                    'base_credit', 0,
                    'currency', v_cheque.currency,
                    'description', 'إلغاء شيك أوراق دفع رقم: ' || v_cheque.cheque_number
                ),
                jsonb_build_object(
                    'account_id', v_counterparty_acct,
                    'debit', 0,
                    'credit', v_cheque.amount,
                    'base_debit', 0,
                    'base_credit', v_base_amount,
                    'currency', v_cheque.currency,
                    'description', 'إلغاء شيك أوراق دفع رقم: ' || v_cheque.cheque_number
                )
            );
        END IF;

        v_rev_je_id := public.post_journal_entry(
            'cheque_cancelled',
            'إلغاء شيك رقم: ' || v_cheque.cheque_number,
            CURRENT_DATE,
            v_cheque.company_id,
            auth.uid(),
            v_rev_lines,
            p_cheque_id::TEXT
        );
    END IF;

    UPDATE public.cheques
    SET status = 'cancelled', cancelled_at = NOW()
    WHERE id = p_cheque_id;

    RETURN jsonb_build_object('success', true);
END;
$$;

GRANT EXECUTE ON FUNCTION public.cancel_cheque(bigint) TO authenticated, anon, service_role;

-- ── 7.5 Unified clear_cheque with Cheques Under Collection (12121) & Notes Payable (21121) ──
CREATE OR REPLACE FUNCTION public.clear_cheque(p_cheque_id bigint)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_cheque RECORD;
    v_desc TEXT;
    v_bank_id INTEGER;
    v_bank_bal NUMERIC;
    v_current_cost_base NUMERIC := 0;
    v_current_book_rate NUMERIC := 1.0;
    v_new_cost_base NUMERIC := 0;
    v_new_book_rate NUMERIC := 1.0;
    v_cost_released NUMERIC := 0;
    v_currency TEXT;
    v_company_id UUID;
    v_new_bank_bal NUMERIC;
    v_bank_acct BIGINT;
    v_counterparty_acct BIGINT;
    v_realized_gain_acct BIGINT;
    v_realized_loss_acct BIGINT;
    v_je_id BIGINT;
    v_stage1_je_id BIGINT;
    v_stage1_je_lines JSONB := '[]'::jsonb;
    v_bank_tx_id BIGINT;
    v_rate NUMERIC := 1.0;
    v_counterparty_name TEXT;
    v_base_amount NUMERIC;
    v_book_rate NUMERIC := 1.0;
    v_snapshot JSONB;
    v_entity_id TEXT;
    v_norm_counterparty_type TEXT;
    v_je_lines JSONB := '[]'::jsonb;
    v_treasury_id BIGINT;
    v_tr_bal NUMERIC := 0;
    v_tr_cost_base NUMERIC := 0;
    v_tr_book_rate NUMERIC := 1.0;
    v_new_tr_bal NUMERIC := 0;
    v_new_tr_cost_base NUMERIC := 0;
    v_new_tr_book_rate NUMERIC := 1.0;
    v_cheques_under_collection_acct BIGINT;
    v_notes_payable_acct BIGINT;

    -- Liability matching & FX calculation variables
    v_total_ap_base   NUMERIC := 0.0;
    v_total_gain      NUMERIC := 0.0;
    v_total_loss      NUMERIC := 0.0;
    v_remaining_alloc NUMERIC;
    v_alloc           NUMERIC;
    v_inv_rate        NUMERIC;
    v_inv_base        NUMERIC;
    v_paid_base       NUMERIC;
    v_diff            NUMERIC;
    v_liab            RECORD;
    v_shipment        RECORD;
    v_spec_shipment   RECORD;
    v_total_cust_base NUMERIC;
    v_alloc_bank_base NUMERIC;
    v_alloc_cust_base NUMERIC;
BEGIN
    SELECT * INTO v_cheque
    FROM public.cheques
    WHERE id = p_cheque_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'الشيك غير موجود';
    END IF;

    IF v_cheque.status != 'pending' THEN
        RAISE EXCEPTION 'لا يمكن تسوية شيك بحالة %', v_cheque.status;
    END IF;

    v_currency := v_cheque.currency;
    v_rate := public.fn_get_exchange_rate(v_currency);
    v_base_amount := ROUND(v_cheque.amount * v_rate, 2);
    v_norm_counterparty_type := LOWER(COALESCE(v_cheque.counterparty_type, ''));

    IF v_norm_counterparty_type = 'customer' AND v_cheque.counterparty_id IS NOT NULL THEN
        SELECT name INTO v_counterparty_name FROM public.customers WHERE id = v_cheque.counterparty_id;
    END IF;

    IF v_cheque.type = 'outgoing' THEN
        v_desc := 'صرف شيك رقم: ' || v_cheque.cheque_number;
    ELSE
        IF v_norm_counterparty_type = 'customer' AND v_counterparty_name IS NOT NULL AND v_counterparty_name != '' THEN
            v_desc := 'تحصيل شيك رقم ' || v_cheque.cheque_number || ' من العميل ' || v_counterparty_name || ' (سداد حساب العميل)';
        ELSE
            v_desc := 'تحصيل شيك رقم: ' || v_cheque.cheque_number;
        END IF;
    END IF;

    -- Get bank account (use cheque's assigned bank if present, otherwise match currency)
    IF v_cheque.bank_account_id IS NOT NULL THEN
        SELECT id, balance, COALESCE(cost_base, 0), COALESCE(book_rate, 1.0), ba.company_id, ba.account_id
        INTO v_bank_id, v_bank_bal, v_current_cost_base, v_current_book_rate, v_company_id, v_bank_acct
        FROM public.bank_accounts ba
        WHERE ba.id = v_cheque.bank_account_id
        FOR UPDATE;
    ELSE
        SELECT id, balance, COALESCE(cost_base, 0), COALESCE(book_rate, 1.0), ba.company_id, ba.account_id
        INTO v_bank_id, v_bank_bal, v_current_cost_base, v_current_book_rate, v_company_id, v_bank_acct
        FROM public.bank_accounts ba
        WHERE ba.currency = v_currency AND ba.deleted_at IS NULL
        ORDER BY ba.id ASC
        LIMIT 1
        FOR UPDATE;
    END IF;

    IF v_bank_id IS NULL THEN
        RAISE EXCEPTION 'لم يتم العثور على حساب بنكي بعملة %', v_currency;
    END IF;

    IF v_company_id IS NULL THEN
        SELECT id INTO v_company_id FROM public.sys_companies LIMIT 1;
    END IF;

    -- Resolve Bank GL Account if ba.account_id is null
    IF v_bank_acct IS NULL THEN
        v_bank_acct := public.resolve_gl_account(
            CASE v_currency WHEN 'EGP' THEN '12111' WHEN 'USD' THEN '12112' WHEN 'EUR' THEN '12113' WHEN 'GBP' THEN '12114' ELSE '12111' END,
            v_company_id
        );
    END IF;

    -- Resolve Cheques Under Collection (12121) and Notes Payable (21121)
    v_cheques_under_collection_acct := public.resolve_gl_account('12121', v_company_id);
    v_notes_payable_acct := public.resolve_gl_account('21121', v_company_id);

    -- ================================================================
    -- 1. OUTGOING CHEQUE: Notes Payable (21121) Transition & Bank Withdrawal
    -- ================================================================
    IF v_cheque.type = 'outgoing' THEN
        IF v_bank_bal < v_cheque.amount THEN
            RAISE EXCEPTION 'رصيد الحساب البنكي غير كافٍ. الرصيد الحالي: %', v_bank_bal;
        END IF;

        IF v_currency = 'EGP' THEN
            v_book_rate := 1.0;
            v_cost_released := v_cheque.amount;
            v_new_cost_base := GREATEST(0, v_current_cost_base - v_cheque.amount);
            v_new_book_rate := 1.0;
        ELSE
            v_book_rate := COALESCE(NULLIF(v_current_book_rate, 0), v_rate);
            v_cost_released := ROUND(v_cheque.amount * v_book_rate, 2);
            v_new_cost_base := GREATEST(0, v_current_cost_base - v_cost_released);
        END IF;

        v_new_bank_bal := v_bank_bal - v_cheque.amount;

        IF v_new_bank_bal > 0 AND v_currency != 'EGP' THEN
            v_new_book_rate := ROUND(v_new_cost_base / v_new_bank_bal, 4);
        ELSIF v_currency = 'EGP' THEN
            v_new_book_rate := 1.0;
        ELSE
            v_new_book_rate := v_book_rate;
            v_new_cost_base := 0;
        END IF;

        v_counterparty_acct := NULL;
        v_entity_id := NULL;
        v_treasury_id := NULL;

        IF v_norm_counterparty_type = 'supplier' AND v_cheque.supplier_id IS NOT NULL THEN
            v_entity_id := v_cheque.supplier_id::text;
            SELECT account_id INTO v_counterparty_acct FROM public.suppliers WHERE id = v_cheque.supplier_id;
        ELSIF v_norm_counterparty_type = 'shipping_company' AND COALESCE(v_cheque.shipping_company_id, v_cheque.counterparty_id) IS NOT NULL THEN
            v_entity_id := COALESCE(v_cheque.shipping_company_id, v_cheque.counterparty_id)::text;
            SELECT account_id INTO v_counterparty_acct FROM public.shipping_companies WHERE id = v_entity_id::bigint;
        ELSIF v_norm_counterparty_type = 'clearing_agent' AND COALESCE(v_cheque.clearing_agent_id, v_cheque.counterparty_id) IS NOT NULL THEN
            v_entity_id := COALESCE(v_cheque.clearing_agent_id, v_cheque.counterparty_id)::text;
            SELECT account_id INTO v_counterparty_acct FROM public.clearing_agents WHERE id = v_entity_id::bigint;
        ELSIF v_norm_counterparty_type = 'customer' AND v_cheque.counterparty_id IS NOT NULL THEN
            v_entity_id := v_cheque.counterparty_id::text;
            SELECT account_id INTO v_counterparty_acct FROM public.customers WHERE id = v_cheque.counterparty_id;
        ELSIF v_norm_counterparty_type = 'shareholder' AND v_cheque.shareholder_id IS NOT NULL THEN
            v_entity_id := v_cheque.shareholder_id::text;
            SELECT account_id INTO v_counterparty_acct FROM public.shareholders WHERE id = v_cheque.shareholder_id;
        ELSIF v_norm_counterparty_type = 'treasury' OR v_cheque.treasury_id IS NOT NULL THEN
            v_treasury_id := COALESCE(v_cheque.treasury_id, v_cheque.counterparty_id::bigint);
            v_entity_id := v_treasury_id::text;
            v_counterparty_acct := public.resolve_treasury_account(v_treasury_id::integer, v_currency, v_company_id);
        ELSIF v_cheque.expense_account_id IS NOT NULL THEN
            v_counterparty_acct := v_cheque.expense_account_id;
        END IF;

        IF v_counterparty_acct IS NULL THEN
            IF v_norm_counterparty_type = 'supplier' THEN
                v_counterparty_acct := public.resolve_gl_account('21113', v_company_id);
            ELSIF v_norm_counterparty_type = 'shipping_company' THEN
                v_counterparty_acct := public.resolve_gl_account('21115', v_company_id);
            ELSIF v_norm_counterparty_type = 'clearing_agent' THEN
                v_counterparty_acct := public.resolve_gl_account('21116', v_company_id);
            ELSE
                v_counterparty_acct := public.resolve_gl_account('21121', v_company_id);
            END IF;
        END IF;

        -- Multi-liability allocation and FX Calculation for Supplier / Shipping Company / Clearing Agent
        v_remaining_alloc := v_cheque.amount;
        v_total_ap_base := 0.0;
        v_total_gain := 0.0;
        v_total_loss := 0.0;

        IF v_norm_counterparty_type IN ('supplier', 'shipping_company', 'clearing_agent') AND v_entity_id IS NOT NULL THEN
            FOR v_liab IN 
                SELECT liability_type, liability_id, reference_number, currency, currency_snapshot, due_amount
                FROM public.vw_unpaid_liabilities
                WHERE LOWER(entity_type) = v_norm_counterparty_type
                  AND entity_id = v_entity_id
                  AND currency = v_currency
                ORDER BY liability_date ASC, liability_id ASC
            LOOP
                EXIT WHEN v_remaining_alloc <= 0;

                IF v_remaining_alloc >= v_liab.due_amount THEN
                    v_alloc := v_liab.due_amount;
                ELSE
                    v_alloc := v_remaining_alloc;
                END IF;

                v_inv_rate := COALESCE(
                    (v_liab.currency_snapshot->>'exchange_rate')::NUMERIC,
                    v_rate
                );

                v_inv_base  := ROUND(v_alloc * v_inv_rate, 2);
                v_paid_base := ROUND(v_alloc * v_book_rate, 2);
                v_diff      := v_paid_base - v_inv_base;

                v_total_ap_base := v_total_ap_base + v_inv_base;

                IF v_diff < 0 THEN
                    v_total_gain := v_total_gain + ABS(v_diff);
                ELSIF v_diff > 0 THEN
                    v_total_loss := v_total_loss + v_diff;
                END IF;

                -- Update individual liability records
                IF v_liab.liability_type = 'purchase_invoice' THEN
                    IF v_norm_counterparty_type = 'supplier' THEN
                        INSERT INTO public.supplier_payment_allocations (
                            source_type, source_id, purchase_invoice_id, supplier_id, allocation_type, amount
                        ) VALUES (
                            'bank', p_cheque_id, v_liab.liability_id::integer, v_cheque.supplier_id, 'invoice', v_alloc
                        );
                    END IF;
                    UPDATE public.purchase_invoices
                    SET paid_amount = COALESCE(paid_amount, 0) + v_alloc,
                        payment_status = CASE WHEN (COALESCE(paid_amount, 0) + v_alloc) >= (COALESCE(total_amount, 0) - COALESCE(discount_amount, 0) - 0.001) THEN 'paid' ELSE 'partial' END,
                        payment_bank_account_id = v_bank_id,
                        payment_source_type = 'bank'
                    WHERE id::text = v_liab.liability_id;
                    
                ELSIF v_liab.liability_type = 'lot_receipt' THEN
                    IF v_norm_counterparty_type = 'supplier' THEN
                        INSERT INTO public.supplier_payment_allocations (
                            source_type, source_id, lot_receipt_id, supplier_id, allocation_type, amount
                        ) VALUES (
                            'bank', p_cheque_id, v_liab.liability_id::bigint, v_cheque.supplier_id, 'lot_receipt', v_alloc
                        );
                    END IF;
                    UPDATE public.lot_receipts
                    SET paid_amount = COALESCE(paid_amount, 0) + v_alloc,
                        payment_status = CASE WHEN (COALESCE(paid_amount, 0) + v_alloc) >= (COALESCE(total_fruit_cost, 0) - 0.001) THEN 'paid' ELSE 'partial' END,
                        payment_bank_account_id = v_bank_id,
                        payment_source_type = 'bank',
                        updated_at = NOW()
                    WHERE id::text = v_liab.liability_id;
                    
                ELSIF v_liab.liability_type = 'packing_cost_item' THEN
                    IF v_norm_counterparty_type = 'supplier' THEN
                        INSERT INTO public.supplier_payment_allocations (
                            source_type, source_id, packing_order_cost_item_id, supplier_id, allocation_type, amount
                        ) VALUES (
                            'bank', p_cheque_id, v_liab.liability_id::bigint, v_cheque.supplier_id, 'packing_cost', v_alloc
                        );
                    END IF;
                    UPDATE public.packing_order_cost_items
                    SET paid_amount = COALESCE(paid_amount, 0) + v_alloc,
                        payment_status = CASE WHEN (COALESCE(paid_amount, 0) + v_alloc) >= (COALESCE(original_amount, 0) - 0.001) THEN 'paid' ELSE 'partial' END,
                        payment_bank_account_id = v_bank_id,
                        payment_source_type = 'bank'
                    WHERE id::text = v_liab.liability_id;
                    
                ELSIF v_liab.liability_type = 'shipment_cost_item' THEN
                    IF v_norm_counterparty_type = 'supplier' THEN
                        INSERT INTO public.supplier_payment_allocations (
                            source_type, source_id, shipment_cost_item_id, supplier_id, allocation_type, amount
                        ) VALUES (
                            'bank', p_cheque_id, v_liab.liability_id::bigint, v_cheque.supplier_id, 'shipment_cost', v_alloc
                        );
                    END IF;
                    UPDATE public.shipment_cost_items
                    SET paid_amount = COALESCE(paid_amount, 0) + v_alloc,
                        payment_status = CASE WHEN (COALESCE(paid_amount, 0) + v_alloc) >= (ROUND(COALESCE(NULLIF(total_price, 0), quantity * unit_price, 0) / COALESCE(NULLIF(exchange_rate, 0), 1.0), 2) - 0.001) THEN 'paid' ELSE 'partial' END,
                        payment_bank_account_id = v_bank_id,
                        payment_source_type = 'bank'
                    WHERE id::text = v_liab.liability_id;
                END IF;

                v_remaining_alloc := v_remaining_alloc - v_alloc;
            END LOOP;

            IF v_remaining_alloc > 0 THEN
                v_total_ap_base := v_total_ap_base + ROUND(v_remaining_alloc * v_book_rate, 2);
            END IF;
        ELSE
            v_total_ap_base := v_cost_released;
        END IF;

        -- Stage 1: If pending cheque had not generated a ledger entry, post Stage 1 (Dr Supplier / Cr Notes Payable 21121)
        IF v_cheque.journal_entry_id IS NULL THEN
            v_stage1_je_lines := jsonb_build_array(
                jsonb_build_object(
                    'account_id', v_counterparty_acct,
                    'debit', v_cheque.amount,
                    'credit', 0,
                    'base_debit', v_total_ap_base,
                    'base_credit', 0,
                    'currency', v_currency,
                    'description', v_desc || ' (تسجيل إصدار شيك أوراق دفع)'
                ),
                jsonb_build_object(
                    'account_id', v_notes_payable_acct,
                    'debit', 0,
                    'credit', v_cheque.amount,
                    'base_debit', 0,
                    'base_credit', v_total_ap_base,
                    'currency', v_currency,
                    'description', v_desc || ' (أوراق دفع مستحقة)'
                )
            );

            v_stage1_je_id := public.post_journal_entry(
                'cheque_issued',
                v_desc || ' (إصدار شيك أوراق دفع)',
                COALESCE(v_cheque.issue_date, CURRENT_DATE),
                v_company_id,
                auth.uid(),
                v_stage1_je_lines,
                p_cheque_id::TEXT
            );
        END IF;

        -- Stage 2: Post Bank Withdrawal against Notes Payable (Dr 21121 / Cr Bank)
        v_je_lines := jsonb_build_array(
            jsonb_build_object(
                'account_id', v_notes_payable_acct,
                'debit', v_cheque.amount,
                'credit', 0,
                'base_debit', v_total_ap_base,
                'base_credit', 0,
                'currency', v_currency,
                'description', v_desc || ' (تسوية أوراق الدفع بالبنك)'
            )
        );

        IF v_total_loss > 0 THEN
            v_realized_loss_acct := public.resolve_realized_fx_loss_account(v_company_id);
            v_je_lines := v_je_lines || jsonb_build_array(
                jsonb_build_object(
                    'account_id', v_realized_loss_acct,
                    'debit', v_total_loss,
                    'credit', 0,
                    'base_debit', v_total_loss,
                    'base_credit', 0,
                    'currency', 'EGP',
                    'description', 'خسائر فروق أسعار عملة محققة - ' || v_desc
                )
            );
        END IF;

        v_je_lines := v_je_lines || jsonb_build_array(
            jsonb_build_object(
                'account_id', v_bank_acct,
                'debit', 0,
                'credit', v_cheque.amount,
                'base_debit', 0,
                'base_credit', v_cost_released,
                'currency', v_currency,
                'description', v_desc || ' (صرف شيك من حساب البنك)'
            )
        );

        IF v_total_gain > 0 THEN
            v_realized_gain_acct := public.resolve_realized_fx_gain_account(v_company_id);
            v_je_lines := v_je_lines || jsonb_build_array(
                jsonb_build_object(
                    'account_id', v_realized_gain_acct,
                    'debit', 0,
                    'credit', v_total_gain,
                    'base_debit', 0,
                    'base_credit', v_total_gain,
                    'currency', 'EGP',
                    'description', 'أرباح فروق أسعار عملة محققة - ' || v_desc
                )
            );
        END IF;

        v_je_id := public.post_journal_entry(
            'bank_withdrawal',
            v_desc,
            CURRENT_DATE,
            v_company_id,
            auth.uid(),
            v_je_lines,
            p_cheque_id::TEXT
        );

        UPDATE public.bank_accounts
        SET balance = v_new_bank_bal,
            cost_base = v_new_cost_base,
            book_rate = v_new_book_rate,
            updated_at = now()
        WHERE id = v_bank_id;

        INSERT INTO public.bank_account_transactions
            (bank_account_id, type, amount, balance_before, balance_after,
             description, created_by, journal_entry_id, entity_type, entity_id, source_type,
             exchange_rate, amount_in_base_currency, currency_snapshot)
        VALUES
            (v_bank_id, 'withdraw', v_cheque.amount, v_bank_bal, v_new_bank_bal,
             v_desc, auth.uid(), v_je_id, 'cheque', p_cheque_id::TEXT, 'cheque',
             v_book_rate, v_cost_released, jsonb_build_object(
                'currency', v_currency,
                'exchange_rate', v_book_rate,
                'book_rate', v_new_book_rate,
                'cost_base', v_new_cost_base,
                'amount', v_cheque.amount,
                'amount_in_base_currency', v_cost_released,
                'rate_date', CURRENT_DATE,
                'rate_source', 'bank_book_rate',
                'realized_fx_gain', v_total_gain,
                'realized_fx_loss', v_total_loss
             ))
        RETURNING id INTO v_bank_tx_id;

        -- If outgoing cheque feeds a treasury
        IF v_treasury_id IS NOT NULL THEN
            SELECT COALESCE(balance, 0), COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
            INTO v_tr_bal, v_tr_cost_base, v_tr_book_rate
            FROM public.treasury_balances
            WHERE treasury_id = v_treasury_id AND currency = v_currency
            FOR UPDATE;

            IF NOT FOUND THEN
                v_tr_bal := 0;
                v_tr_cost_base := 0;
                v_tr_book_rate := 1.0;
            END IF;

            v_new_tr_bal := v_tr_bal + v_cheque.amount;
            v_new_tr_cost_base := v_tr_cost_base + v_cost_released;

            IF v_currency = 'EGP' THEN
                v_new_tr_book_rate := 1.0;
            ELSIF v_new_tr_bal > 0 THEN
                v_new_tr_book_rate := ROUND(v_new_tr_cost_base / v_new_tr_bal, 4);
            ELSE
                v_new_tr_book_rate := v_book_rate;
            END IF;

            INSERT INTO public.treasury_balances (treasury_id, currency, balance, cost_base, book_rate, account_id, updated_at)
            VALUES (v_treasury_id, v_currency, v_new_tr_bal, v_new_tr_cost_base, v_new_tr_book_rate, v_counterparty_acct, NOW())
            ON CONFLICT (treasury_id, currency) DO UPDATE
            SET balance = v_new_tr_bal,
                cost_base = v_new_tr_cost_base,
                book_rate = v_new_tr_book_rate,
                updated_at = NOW();

            INSERT INTO public.treasury_transactions (
                treasury_id, type, currency, amount,
                balance_before, balance_after, description, source_type, journal_entry_id, created_by,
                reference_type, reference_id, exchange_rate, amount_in_base_currency, currency_snapshot
            ) VALUES (
                v_treasury_id, 'deposit', v_currency, v_cheque.amount,
                v_tr_bal, v_new_tr_bal, 'تغذية الخزينة من صرف شيك رقم: ' || COALESCE(v_cheque.cheque_number, ''), 'cheque', v_je_id, auth.uid(),
                'cheque', p_cheque_id::text, v_book_rate, v_cost_released,
                jsonb_build_object(
                    'currency', v_currency,
                    'exchange_rate', v_book_rate,
                    'book_rate', v_new_tr_book_rate,
                    'cost_base', v_new_tr_cost_base,
                    'amount', v_cheque.amount,
                    'amount_in_base_currency', v_cost_released,
                    'rate_date', CURRENT_DATE,
                    'rate_source', 'bank_book_rate'
                )
            );
        END IF;

        -- Sync Entity True Balance
        IF v_norm_counterparty_type = 'supplier' AND v_cheque.supplier_id IS NOT NULL THEN
            UPDATE public.suppliers
            SET outstanding_balance = (SELECT true_balance FROM public.get_supplier_true_balances() WHERE supplier_id = v_cheque.supplier_id)
            WHERE id = v_cheque.supplier_id;
        ELSIF v_norm_counterparty_type = 'shipping_company' AND v_entity_id IS NOT NULL THEN
            UPDATE public.shipping_companies
            SET balance = (SELECT true_balance FROM public.get_shipping_company_true_balances() WHERE shipping_company_id = v_entity_id::bigint)
            WHERE id = v_entity_id::bigint;
        ELSIF v_norm_counterparty_type = 'clearing_agent' AND v_entity_id IS NOT NULL THEN
            UPDATE public.clearing_agents
            SET balance = (SELECT true_balance FROM public.get_clearing_agent_true_balances() WHERE clearing_agent_id = v_entity_id::bigint)
            WHERE id = v_entity_id::bigint;
        END IF;

    -- ================================================================
    -- 2. INCOMING CHEQUE: Cheques Under Collection (12121) & Bank Clearance
    -- ================================================================
    ELSIF v_cheque.type = 'incoming' THEN
        IF v_currency = 'EGP' THEN
            v_new_cost_base := v_current_cost_base + v_cheque.amount;
            v_new_book_rate := 1.0;
        ELSE
            v_new_cost_base := v_current_cost_base + v_base_amount;
        END IF;

        v_new_bank_bal := v_bank_bal + v_cheque.amount;

        IF v_new_bank_bal > 0 AND v_currency != 'EGP' THEN
            v_new_book_rate := ROUND(v_new_cost_base / v_new_bank_bal, 4);
        ELSIF v_currency = 'EGP' THEN
            v_new_book_rate := 1.0;
        ELSE
            v_new_book_rate := v_rate;
            v_new_cost_base := v_base_amount;
        END IF;

        v_counterparty_acct := NULL;

        IF v_norm_counterparty_type = 'customer' AND v_cheque.counterparty_id IS NOT NULL THEN
            SELECT account_id INTO v_counterparty_acct FROM public.customers WHERE id = v_cheque.counterparty_id;
        ELSIF v_norm_counterparty_type = 'supplier' AND v_cheque.supplier_id IS NOT NULL THEN
            SELECT account_id INTO v_counterparty_acct FROM public.suppliers WHERE id = v_cheque.supplier_id;
        ELSIF v_norm_counterparty_type = 'clearing_agent' AND v_cheque.clearing_agent_id IS NOT NULL THEN
            SELECT account_id INTO v_counterparty_acct FROM public.clearing_agents WHERE id = v_cheque.clearing_agent_id;
        ELSIF v_norm_counterparty_type = 'shipping_company' AND v_cheque.shipping_company_id IS NOT NULL THEN
            SELECT account_id INTO v_counterparty_acct FROM public.shipping_companies WHERE id = v_cheque.shipping_company_id;
        ELSIF v_norm_counterparty_type = 'shareholder' AND v_cheque.shareholder_id IS NOT NULL THEN
            SELECT account_id INTO v_counterparty_acct FROM public.shareholders WHERE id = v_cheque.shareholder_id;
        ELSIF v_norm_counterparty_type = 'treasury' OR v_cheque.treasury_id IS NOT NULL THEN
            v_counterparty_acct := public.resolve_treasury_account(COALESCE(v_cheque.treasury_id, v_cheque.counterparty_id::bigint)::integer, v_currency, v_company_id);
        END IF;

        IF v_counterparty_acct IS NULL THEN
            IF v_norm_counterparty_type = 'customer' THEN
                v_counterparty_acct := public.resolve_gl_account('12511', v_company_id);
            ELSE
                v_counterparty_acct := public.resolve_gl_account('12615', v_company_id);
            END IF;
        END IF;

        -- Customer Shipment Matching & Realized FX Calculation (if foreign currency)
        v_total_cust_base := v_base_amount;
        v_total_gain := 0;
        v_total_loss := 0;

        IF v_norm_counterparty_type = 'customer' AND v_cheque.counterparty_id IS NOT NULL AND v_currency != 'EGP' THEN
            v_remaining_alloc := v_cheque.amount;
            v_total_cust_base := 0;

            -- Check if a specific shipment is referenced in notes
            SELECT id, shipment_no, COALESCE(exchange_rate, v_rate) as shipment_rate,
                   (total_revenue_foreign - COALESCE(discount_amount, 0) - COALESCE(paid_amount, 0)) as due_foreign
            INTO v_spec_shipment
            FROM public.export_shipments
            WHERE customer_id = v_cheque.counterparty_id
              AND is_confirmed = true
              AND status != 'cancelled'
              AND (
                  (v_cheque.notes IS NOT NULL AND v_cheque.notes LIKE '%' || shipment_no || '%')
                  OR (v_desc IS NOT NULL AND v_desc LIKE '%' || shipment_no || '%')
              )
            ORDER BY id DESC
            LIMIT 1;

            IF v_spec_shipment.id IS NOT NULL AND v_spec_shipment.due_foreign > 0.001 THEN
                v_alloc := LEAST(v_remaining_alloc, v_spec_shipment.due_foreign);
                v_alloc_bank_base := ROUND(v_alloc * v_rate, 2);
                v_alloc_cust_base := ROUND(v_alloc * v_spec_shipment.shipment_rate, 2);
                v_diff := v_alloc_bank_base - v_alloc_cust_base;

                v_total_cust_base := v_total_cust_base + v_alloc_cust_base;

                IF v_diff > 0 THEN
                    v_total_gain := v_total_gain + v_diff;
                ELSIF v_diff < 0 THEN
                    v_total_loss := v_total_loss + ABS(v_diff);
                END IF;

                UPDATE public.export_shipments
                SET paid_amount = COALESCE(paid_amount, 0) + v_alloc,
                    updated_at = NOW()
                WHERE id = v_spec_shipment.id;

                v_remaining_alloc := v_remaining_alloc - v_alloc;
            END IF;

            -- Allocate remaining amount to open shipments in FIFO order
            IF v_remaining_alloc > 0.001 THEN
                FOR v_shipment IN
                    SELECT id, shipment_no, COALESCE(exchange_rate, v_rate) as shipment_rate,
                           (total_revenue_foreign - COALESCE(discount_amount, 0) - COALESCE(paid_amount, 0)) as due_foreign
                    FROM public.export_shipments
                    WHERE customer_id = v_cheque.counterparty_id
                      AND is_confirmed = true
                      AND status != 'cancelled'
                      AND (v_spec_shipment.id IS NULL OR id != v_spec_shipment.id)
                      AND (total_revenue_foreign - COALESCE(discount_amount, 0) - COALESCE(paid_amount, 0)) > 0.001
                    ORDER BY created_at ASC, id ASC
                LOOP
                    EXIT WHEN v_remaining_alloc <= 0.001;

                    v_alloc := LEAST(v_remaining_alloc, v_shipment.due_foreign);
                    v_alloc_bank_base := ROUND(v_alloc * v_rate, 2);
                    v_alloc_cust_base := ROUND(v_alloc * v_shipment.shipment_rate, 2);
                    v_diff := v_alloc_bank_base - v_alloc_cust_base;

                    v_total_cust_base := v_total_cust_base + v_alloc_cust_base;

                    IF v_diff > 0 THEN
                        v_total_gain := v_total_gain + v_diff;
                    ELSIF v_diff < 0 THEN
                        v_total_loss := v_total_loss + ABS(v_diff);
                    END IF;

                    UPDATE public.export_shipments
                    SET paid_amount = COALESCE(paid_amount, 0) + v_alloc,
                        updated_at = NOW()
                    WHERE id = v_shipment.id;

                    v_remaining_alloc := v_remaining_alloc - v_alloc;
                END LOOP;
            END IF;

            -- If any advance amount remains (no open shipments)
            IF v_remaining_alloc > 0.001 THEN
                v_total_cust_base := v_total_cust_base + ROUND(v_remaining_alloc * v_rate, 2);
            END IF;
        END IF;

        -- Stage 1: If pending cheque had not generated a ledger entry, post Stage 1 (Dr 12121 Cheques Under Collection / Cr Customer)
        IF v_cheque.journal_entry_id IS NULL THEN
            v_stage1_je_lines := jsonb_build_array(
                jsonb_build_object(
                    'account_id', v_cheques_under_collection_acct,
                    'debit', v_cheque.amount,
                    'credit', 0,
                    'base_debit', v_base_amount,
                    'base_credit', 0,
                    'currency', v_currency,
                    'description', v_desc || ' (استلام شيك برسم التحصيل)'
                ),
                jsonb_build_object(
                    'account_id', v_counterparty_acct,
                    'debit', 0,
                    'credit', v_cheque.amount,
                    'base_debit', 0,
                    'base_credit', v_base_amount,
                    'currency', v_currency,
                    'description', v_desc || ' (سداد حساب العميل/الجهة بموجب شيك)'
                )
            );

            v_stage1_je_id := public.post_journal_entry(
                'cheque_receipt',
                v_desc || ' (استلام شيك برسم التحصيل)',
                COALESCE(v_cheque.issue_date, CURRENT_DATE),
                v_company_id,
                auth.uid(),
                v_stage1_je_lines,
                p_cheque_id::TEXT
            );
        END IF;

        -- Stage 2: Post Bank Deposit against Cheques Under Collection (Dr Bank / Cr 12121)
        v_je_lines := jsonb_build_array(
            jsonb_build_object(
                'account_id', v_bank_acct,
                'debit', v_cheque.amount,
                'credit', 0,
                'base_debit', v_base_amount,
                'base_credit', 0,
                'currency', v_currency,
                'description', v_desc || ' (إيداع بنكي من تحصيل شيك)'
            )
        );

        IF v_total_loss > 0 THEN
            v_realized_loss_acct := public.resolve_realized_fx_loss_account(v_company_id);
            v_je_lines := v_je_lines || jsonb_build_array(
                jsonb_build_object(
                    'account_id', v_realized_loss_acct,
                    'debit', v_total_loss,
                    'credit', 0,
                    'base_debit', v_total_loss,
                    'base_credit', 0,
                    'currency', 'EGP',
                    'description', 'خسائر فروق أسعار عملة محققة - شيك ' || COALESCE(v_cheque.cheque_number, '')
                )
            );
        END IF;

        v_je_lines := v_je_lines || jsonb_build_array(
            jsonb_build_object(
                'account_id', v_cheques_under_collection_acct,
                'debit', 0,
                'credit', v_cheque.amount,
                'base_debit', 0,
                'base_credit', v_total_cust_base,
                'currency', v_currency,
                'description', v_desc || ' (تسوية شيكات برسم التحصيل بالبنك)'
            )
        );

        IF v_total_gain > 0 THEN
            v_realized_gain_acct := public.resolve_realized_fx_gain_account(v_company_id);
            v_je_lines := v_je_lines || jsonb_build_array(
                jsonb_build_object(
                    'account_id', v_realized_gain_acct,
                    'debit', 0,
                    'credit', v_total_gain,
                    'base_debit', 0,
                    'base_credit', v_total_gain,
                    'currency', 'EGP',
                    'description', 'أرباح فروق أسعار عملة محققة - شيك ' || COALESCE(v_cheque.cheque_number, '')
                )
            );
        END IF;

        -- Post Stage 2 Journal Entry
        v_je_id := public.post_journal_entry(
            'bank_deposit',
            v_desc,
            CURRENT_DATE,
            v_company_id,
            auth.uid(),
            v_je_lines,
            p_cheque_id::TEXT
        );

        -- Update bank balance, cost_base and weighted average book_rate
        UPDATE public.bank_accounts
        SET balance = v_new_bank_bal,
            cost_base = v_new_cost_base,
            book_rate = v_new_book_rate,
            updated_at = now()
        WHERE id = v_bank_id;

        -- Record bank transaction
        INSERT INTO public.bank_account_transactions
            (bank_account_id, type, amount, balance_before, balance_after,
             description, created_by, journal_entry_id, entity_type, entity_id, source_type,
             exchange_rate, amount_in_base_currency, currency_snapshot)
        VALUES
            (v_bank_id, 'deposit', v_cheque.amount, v_bank_bal, v_new_bank_bal,
             v_desc, auth.uid(), v_je_id, 'cheque', p_cheque_id::TEXT, 'cheque',
             v_rate, v_base_amount, jsonb_build_object(
                'currency', v_currency,
                'exchange_rate', v_rate,
                'book_rate', v_new_book_rate,
                'cost_base', v_new_cost_base,
                'amount', v_cheque.amount,
                'amount_in_base_currency', v_base_amount,
                'rate_date', CURRENT_DATE,
                'rate_source', 'exchange_rates_table',
                'realized_fx_gain', v_total_gain,
                'realized_fx_loss', v_total_loss
             ))
        RETURNING id INTO v_bank_tx_id;
    END IF;

    -- Update cheque status + freeze rate and amount_in_base_currency
    UPDATE public.cheques
    SET status = 'cleared',
        cleared_at = NOW(),
        bank_account_id = v_bank_id,
        journal_entry_id = v_je_id,
        bank_transaction_id = v_bank_tx_id,
        exchange_rate = CASE WHEN v_cheque.type = 'outgoing' THEN v_book_rate ELSE v_rate END,
        amount_in_base_currency = CASE WHEN v_cheque.type = 'outgoing' THEN v_cost_released ELSE v_base_amount END,
        currency_snapshot = jsonb_build_object(
            'currency', v_currency,
            'exchange_rate', CASE WHEN v_cheque.type = 'outgoing' THEN v_book_rate ELSE v_rate END,
            'amount', v_cheque.amount,
            'amount_in_base_currency', CASE WHEN v_cheque.type = 'outgoing' THEN v_cost_released ELSE v_base_amount END,
            'rate_date', CURRENT_DATE,
            'rate_source', CASE WHEN v_cheque.type = 'outgoing' THEN 'bank_book_rate' ELSE 'exchange_rates_table' END,
            'realized_fx_gain', v_total_gain,
            'realized_fx_loss', v_total_loss
        )
    WHERE id = p_cheque_id;

    RETURN jsonb_build_object(
        'success', true,
        'cheque_id', p_cheque_id,
        'journal_entry_id', v_je_id,
        'stage1_journal_entry_id', v_stage1_je_id,
        'bank_transaction_id', v_bank_tx_id,
        'realized_fx_gain', v_total_gain,
        'realized_fx_loss', v_total_loss
    );
END;
$function$;

GRANT EXECUTE ON FUNCTION public.clear_cheque(bigint) TO authenticated, anon, service_role;

